// 이미 생성된 회원의 미지정 소속만 유입 서버로 지정하는 함수
function assignUnspecifiedMemberServer(data, user, server) {
    var member = data && data.member ? data.member[user] : null;
    if (!member || member.server || !server) return false;
    member.server = server;
    return true;
}

// 기존 서버 표기를 현재 서버의 최종 명칭으로 맞추는 함수
function normalizeHoiServerLabel(serverName) {
    if (serverName === "호이서버1-2[30]") return "호이서버1[30]";
    if (serverName === "호이서버6[2030]") return "호이서버6[30]";
    return serverName || "";
}

// 서버 전체명을 운영용 약칭으로 변환하는 함수
function getServerShortName(serverName) {
    serverName = normalizeHoiServerLabel(serverName);
    var map = {
        "벨라서버1[2030]": "벨1",
        "벨라서버2[30]": "벨2",
        "호이서버1[30]": "호1",
        "호이서버2[2030]": "호2",
        "호이서버3[3040]": "호3",
        "호이서버4[3040]": "호4",
        "호이서버5[2030]": "호5",
        "호이서버6[30]": "호6",
        "호이서버7[2030]": "호7",
        "호이서버1-2[30]": "호1-2",
        "호이월드 운영진[GM]": "GM",
        "호이월드[서버장]": "서버장"
    };
    return map[serverName] || serverName || "미확인";
}

// 미가입 출첵 목록의 서버 표시 순서를 반환하는 함수
function getAttendanceServerSortOrder(serverName) {
    var shortName = getServerShortName(serverName);
    var match = shortName.match(/^호(\d+)$/);
    if (match) return parseInt(match[1], 10);
    if (shortName.indexOf("벨") === 0) return 8;
    if (shortName === "GM") return 9;
    if (shortName === "서버장") return 10;
    return 99;
}

