                        var beforeBattle = Number(mini.battleExp) || 0;
                        var beforeCastle = Number(mini.castleExp) || 0;
                        var beforeRaid = Number(mini.raidExp) || 0;
                        // 원본 객체 직접 갱신
                        mini.upgrade = nextLvAfter;
