                    if (lordGuildInfo.error) {
                        replier.reply("❌ 길드 데이터 오류.");
                        return;
                    }

                    var g = lordGuildInfo.guild;

                    var itemName = "길드창고패키지🧳(/길드창고패키지오픈)";

