// 영지전 공격 순서표 빌드
function buildGuildTerritoryOrderMessage(data, petData, guildData) {
    var war = guildData.territoryWar;
    var out = "📜 길드 영지전 공격 순서표 📜\n" + allsee;

    if (!war.turnOrder || war.turnOrder.length === 0) {
        return out + "참여 공격자가 없습니다.";
    }

    var orderIndex = 1;

    for (var i = 0; i < war.turnOrder.length; i++) {
        var row = war.turnOrder[i];

        // 탈락 길드/유저는 순서표에서 제외
        if (war.eliminatedGuilds && war.eliminatedGuilds[row.guildId]) continue;
        if (war.eliminatedUsers && war.eliminatedUsers[row.user]) continue;

        var g = getGuildByIdSafe(guildData, row.guildId);
        if (!g) continue;

        out += orderIndex + ". [" + checkRank(data, petData, guildData, row.user) + "] [" + formatGuildDisplay(g) + "]\n";
        orderIndex++;
    }

    if (orderIndex === 1) {
        out += "남은 공격 대상이 없습니다.";
    }

    return out;
}

// 영지전 현재 공격자 정보 가져오기
function getGuildTerritoryTurnRow(data, guildData) {
    var war = guildData.territoryWar;//
    if (!war || !war.active || !war.turnOrder || war.turnOrder.length === 0) return null;

    if (!war.eliminatedGuilds) war.eliminatedGuilds = {}; // 탈락한 길드 ID를 키로 저장하는 객체
    if (!war.eliminatedUsers) war.eliminatedUsers = {};// 탈락한 유저 ID를 키로 저장하는 객체
    if (!war.guildAttackCounts) war.guildAttackCounts = {};// 길드별 공격 횟수를 저장하는 객체

    for (var i = 0; i < war.turnOrder.length; i++) {
        var idx = ((war.currentTurnIndex || 0) + i) % war.turnOrder.length;// 현재 턴부터 순회하면서 공격 가능한 소드마스터 찾기
        var row = war.turnOrder[idx];// 안전성 체크는 아래에서 길드 정보 가져올 때 같이 하도록 수정

        if (!row) continue;// 안전성 체크
        if (war.eliminatedGuilds[row.guildId]) continue; // 탈락한 길드의 공격자는 모두 제외
        if (war.eliminatedUsers[row.user]) continue;// 탈락한 유저는 공격자에서 제외

        var g = getGuildByIdSafe(guildData, row.guildId); // 길드 정보 가져오기, 탈락 여부 체크도 같이
        if (!g) continue;

        var attackCount = war.guildAttackCounts[row.guildId] || 0; // 해당 길드의 현재 공격 횟수 가져오기
        if (attackCount >= getGuildTerritoryAttackLimitForWar(war, g, row.guildId)) continue; // 공격 횟수 초과한 길드는 공격자에서 제외

        war.currentTurnIndex = idx; // 현재 턴 인덱스 업데이트
        return row;
    }

    return null;
}

// 해당 길드에 공격 가능한 소드마스터가 있는지 체크
function hasGuildTerritoryEligibleAttacker(data, guildData, gid) {
    var war = guildData.territoryWar;
    if (!war || !war.turnOrder || war.turnOrder.length === 0) return false;
    if (war.eliminatedGuilds && war.eliminatedGuilds[gid]) return false;
    for (var i = 0; i < war.turnOrder.length; i++) {
        var row = war.turnOrder[i];
        if (!row || row.guildId !== gid) continue;
        if (!war.eliminatedUsers[row.user]) return true;
    }
    return false;
}
// 모든 길드가 공격 횟수를 다 채웠거나 공격할 수 있는 소드마스터가 없는지 체크
function isGuildTerritoryAllDone(data, guildData) {
    var war = guildData.territoryWar;
    if (!war || !war.active) return true;
    var ready = Object.keys(war.readyGuilds || {});
    if (ready.length === 0) return true;
    for (var i = 0; i < ready.length; i++) {
        var gid = ready[i];
        var g = getGuildByIdSafe(guildData, gid);
        if (!g || (war.eliminatedGuilds && war.eliminatedGuilds[gid])) continue;
        if ((war.guildAttackCounts[gid] || 0) < getGuildTerritoryAttackLimitForWar(war, g, gid) && hasGuildTerritoryEligibleAttacker(data, guildData, gid)) {
            return false;
        }
    }
    return true;
}

// 영지전 턴 진행, 다음 공격자 선택
function advanceGuildTerritoryTurn(data, guildData) {
    var war = guildData.territoryWar;
    if (!war || !war.turnOrder || war.turnOrder.length === 0) return null;
    war.currentTurnIndex = ((war.currentTurnIndex || 0) + 1) % war.turnOrder.length;
    return getGuildTerritoryTurnRow(data, guildData);
}

// 영지전 현재 공격 차례 한 줄 빌드
function buildGuildTerritoryCurrentTurnLine(data, petData, guildData, isAutoAttackScheduled) {
    var row = getGuildTerritoryTurnRow(data, guildData);
    if (!row) return "";
    if (isAutoAttackScheduled) {
        return "[" + checkRank(data, petData, guildData, row.user) + "] 님이 자동공격을 진행합니다.";
    }
    return "[" + checkRank(data, petData, guildData, row.user) + "] 님의 공격 차례입니다.";
}

// 영지전 턴 메시지 빌드
function buildGuildTerritoryTurnMessage(data, petData, guildData, autoTerritoryNo) {
    var war = guildData.territoryWar;
    var row = getGuildTerritoryTurnRow(data, guildData);
    if (!row) return ["⚠️ 다음 공격 가능한 소드마스터가 없습니다."];
    var g = getGuildByIdSafe(guildData, row.guildId);
    var used = war.guildAttackCounts[row.guildId] || 0;
    var attackLimit = getGuildTerritoryAttackLimitForWar(war, g, row.guildId);
    var remain = Math.max(0, attackLimit - used);
    var status = buildGuildTerritoryStatusMessage(data, guildData, false);

    var isAutoAttackScheduled = autoTerritoryNo >= 1 && autoTerritoryNo <= 7; // 예약된 자동공격 영지가 있는 턴인지 여부
    var turnLine = buildGuildTerritoryCurrentTurnLine(data, petData, guildData, isAutoAttackScheduled);
    var turnDetail = "";
    if (isAutoAttackScheduled) {
        var autoTerritory = getGuildTerritoryByNo(autoTerritoryNo);
        turnDetail += "자동공격 영지: [" + autoTerritoryNo + "] " + (autoTerritory ? autoTerritory.name : "") + "\n";
    }

    var msg =
        turnLine + "\n" +
        "━━━━━━━━━━━━\n" +
        turnDetail +
        "[" +
        formatGuildDisplay(g) +
        "] 남은 턴(" +
        remain +
        "/" +
        attackLimit +
        "⚔)\n" +
        buildGuildTerritoryRiftUi(war) +
        "\n" +
        "━━━━━━━━━━━━\n" +
        status +
        "\n━━━━━━━━━━━━\n" +
        turnLine;

    return [msg];
}

// DEV 영지공격의 응답 공통 처리와 단계별 소요 시간을 출력하는 메시지 생성
function buildGuildTerritoryAttackTimeCheckMessage(responseStartMs, branchStartMs, responseTimingRows, attackTimingRows) {
    var message = "🏰 DEV 영지공격 속도체크 🏰\n";
    message += "━━━━━━━━━━━━\n";
    message += "전체(응답진입): " + (Date.now() - responseStartMs) + "ms\n";
    message += "영지공격 분기: " + (Date.now() - branchStartMs) + "ms\n";
    message += "\n응답 공통 처리📋\n";
    for (var commonIndex = 0; commonIndex < responseTimingRows.length; commonIndex++) {
        message += responseTimingRows[commonIndex].label + ": " + responseTimingRows[commonIndex].ms + "ms\n";
    }
    message += "\n영지공격 처리📋\n";
    for (var attackIndex = 0; attackIndex < attackTimingRows.length; attackIndex++) {
        message += attackTimingRows[attackIndex].label + ": " + attackTimingRows[attackIndex].ms + "ms\n";
    }
    message += "※ dev/영지공격에서만 표시됩니다.";
    return message;
}

// 영지전 공격 턴 보상 적용: 길드 자금 보상, 공헌 메달 보상 확률 계산 및 적용, 보상 메시지 반환
function applyGuildTerritoryTurnReward(data, guildData, guildId, user) {
    var g = getGuildByIdSafe(guildData, guildId);
    if (!g || !data.member[user]) return "";

    ensureGuildWarehouseObj(g);
    var war = ensureGuildTerritoryWar(data, guildData);
    var ownedTerritoryCount = getGuildTerritoryOwnedCount(war, guildId); // 공격 시점 길드 점령지 수
    var hasMaxTerritoryBonus = ownedTerritoryCount >= GLOBAL_CONFIG.guildTerritory.limits.maxOwnedTerritories;
    var turnFundMultiplier = hasMaxTerritoryBonus ? GLOBAL_CONFIG.guildTerritory.rewards.maxTerritoryTurnFundMultiplier : 1;
    var turnFundBaseReward = GLOBAL_CONFIG.guildTerritory.rewards.turnFundReward; // 큐브 보너스 계산 기준 기본 포인트
    var territoryPointPercent = getGuildContributionCubeMemberPercent(data, guildData, user, "territoryPoint");
    var turnFundReward = turnFundBaseReward * turnFundMultiplier + Math.floor(turnFundBaseReward * territoryPointPercent / 100);
    g.warehouse.fund += turnFundReward;

    var medalSuccess = Math.random() < GLOBAL_CONFIG.guildTerritory.rates.medalRewardRate;
    if (medalSuccess) {
        addItem(data, user, GLOBAL_CONFIG.guildTerritory.items.contributionMedalName, 1);
    }

    return "길드 보상🤑: 🅟" + formatGuildTerritoryRewardAmount(turnFundReward) +
        (hasMaxTerritoryBonus ? "\n점령 3개 추가보너스 획득" : "") +
        "\n확률 보상🎊: " + (medalSuccess ? "[💎]다이아+1 획득" : "[🥺]보상실패");
}

// 영지전 균열 이벤트 보상 금액 포맷 함수 (억, 만 단위로 콤마와 함께 포맷)
function formatGuildTerritoryRewardAmount(amount) {
    if (amount % 100000000 === 0) return numberWithCommas(amount / 100000000) + "억";
    if (amount % 10000 === 0) return numberWithCommas(amount / 10000) + "만";
    return numberWithCommas(amount);
}

// 영지전 균열 이벤트 가이드 메시지 빌드
function buildGuildTerritoryRiftCommandGuide() {
    return (
        "🌋 대균열 유도권(/대균열) -> 대균열\n" +
        "🌌 균열 유도권(/균열) -> 균열\n" +
        "🌪️ 전쟁불안정 증폭권(/불안정) -> 불안정\n" +
        "🚑 전쟁불안정 감소권(/안정) -> 안정\n\n" +
        "정리:\n" +
        "- /대균열\n" +
        "- /균열\n" +
        "- /불안정\n" +
        "- /안정"
    );
}

// 영지전 균열 이벤트 처리: 불안정도 증가, 균열/대균열 발생 여부 판단 및 적용, 안정화 판단
function processGuildTerritoryRiftEvent(data, guildData) {
    var war = ensureGuildTerritoryWar(data, guildData);
    if (!war.active) {

        return ""
    };

    if (war.riftEventStatus === "stable" || isGuildTerritoryRiftEventLimitReached(war)) {

        return "";
    }

    war.turnCount = (war.turnCount || 0) + 1;

    var instabilityRate = getGuildTerritoryInstabilityRate(war);
    var rates = getGuildTerritoryRiftRates(war);
    var instabilityRoll = Math.random() * 100;
    var riftRoll = null;

    if (instabilityRoll < instabilityRate) {
        riftRoll = Math.random() * 100;
        if (riftRoll < rates.rift) {
            return applyGuildTerritoryRift(data, guildData);
        }
        return applyGuildTerritoryGreatRift(data, guildData);
    }

    if (war.turnCount >= GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn) {
        war.riftEventStatus = "stable";
        war.riftEventAt = formatDateTime(new Date());
        return (
            "🌪️ 전쟁불안정도 안정화\n\n" +
            GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn +
            "턴까지 🌌균열/🌋대균열이 발생하지 않았습니다.\n\n" +
            "전장의 불안정한 기운이 사라지며,\n이번 영지전에서는 더 이상 균열 이벤트가 발생하지 않습니다."
        );
    }
    return "";
}

// 균열 이벤트 적용: 모든 영지 점령 초기화, 호월킹덤 초기화, 균열 이벤트 상태 설정
function applyGuildTerritoryRift(data, guildData) {
    var war = resetGuildTerritoryOccupation(data, guildData);
    resetGuildTerritoryInstability(war);
    var limitText = markGuildTerritoryRiftEvent(war, "rift");

    return (
        "🌌 균열 발생!\n\n" +
        "전장의 균형이 무너지며\n점령 중이던 길드영지에 균열이 발생했습니다.\n\n" +
        "🏰 길드영지의 점령 상태가 초기화됩니다.\n해당 영지는 다시 쟁탈 가능한 중립 상태가 되었습니다.\n" +
        "🌪️ 누적 전쟁불안정도는 0으로 초기화됩니다.\n\n" +
        limitText
    );
}

// 영지전 균열 이벤트 발생 시 점령 상태 초기화 및 호월킹덤 초기화
function resetGuildTerritoryOccupation(data, guildData) {
    var war = ensureGuildTerritoryWar(data, guildData);
    var list = getGuildTerritoryList();

    for (var i = 0; i < list.length; i++) {
        var ter = war.territories[String(list[i].no)];
        if (!ter) continue;
        ter.ownerGuildId = null;
        ter.ownerUser = null;
    }

    if (!guildData.war24 && data.HoiCastle) {
        data.HoiCastle.lord = "";
        data.HoiCastle.earnings = 0;
        data.HoiCastle.defenseCount = 0;
    }

    return war;
}

// 대균열 이벤트 적용: 랜덤한 준비된 길드 하나를 영지전에서 제거, 대균열 이벤트 상태 설정
function applyGuildTerritoryGreatRift(data, guildData) {
    var war = ensureGuildTerritoryWar(data, guildData);
    var readyGuildIds = Object.keys(war.readyGuilds || {}).filter(function (gid) {
        return !war.eliminatedGuilds[gid] && !!getGuildByIdSafe(guildData, gid);
    });

    // ✅ 빈 문자열 반환 금지
    if (readyGuildIds.length === 0) {
        war.riftEventStatus = "stable";
        war.riftEventAt = formatDateTime(new Date());

        return (
            "🌪️ 전쟁불안정도 안정화\n\n" +
            "대균열이 발생하려 했으나,\n" +
            "영향을 받을 참여 길드가 없어 전장이 안정화되었습니다.\n\n" +
            "※ 이번 영지전에서는 더 이상 균열 이벤트가 발생하지 않습니다."
        );
    }

    var targetGuildId = readyGuildIds[Math.floor(Math.random() * readyGuildIds.length)];
    var targetGuild = getGuildByIdSafe(guildData, targetGuildId);

    war.eliminatedGuilds[targetGuildId] = {
        reason: "GREAT_RIFT",
        at: formatDateTime(new Date())
    };
    resetGuildTerritoryInstability(war);

    var limitText = markGuildTerritoryRiftEvent(war, "greatRift", targetGuildId);

    return (
        "🌋 대균열 발생!\n\n" +
        "전장의 균열이 걷잡을 수 없이 확산됩니다.\n\n" +
        "거대한 균열이 전장을 집어삼키며,\n[" +
        formatGuildDisplay(targetGuild) +
        "] 길드가 겁에 질려 영지전에서 후다닥 도망갑니다.\n\n" +
        "해당 길드는 이번 길드영지전에서\n더 이상 공격 및 점령에 참여할 수 없습니다.\n\n" +
        "🌪️ 누적 전쟁불안정도는 0으로 초기화됩니다.\n\n" +
        limitText
    );
}

// 영지전 균열 아이템 사용 가능 여부 체크, 사용 불가 시 이유 메시지 반환
function canUseGuildTerritoryRiftItem(war) {
    if (!war || !war.active) return "현재 진행 중인 길드 영지전이 없습니다.";
    if (war.riftEventStatus === "stable" || isGuildTerritoryRiftEventLimitReached(war)) return "균열 이벤트가 최대 " + GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount + "회 발생하여 사용할 수 없습니다.\n\n이번 영지전에서는 더 이상\n균열/대균열 확률을 변경할 수 없습니다.";
    if ((war.turnCount || 0) >= GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn) return GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn + "턴이 지나 전장이 안정화되었습니다.\n\n이번 영지전에서는 더 이상\n균열 유도권을 사용할 수 없습니다.";
    return "";
}

// 영지전 균열 아이템 사용 횟수 계산
function getGuildTerritoryUseCount(store, guildId, type) {
    var gStore = store[guildId] || {};
    var tStore = gStore[type] || {};
    var total = 0;
    var users = Object.keys(tStore);
    for (var i = 0; i < users.length; i++) total += tStore[users[i]] || 0;
    return total;
}

// 영지전 균열 아이템 사용 기록 저장
function markGuildTerritoryItemUse(store, guildId, type, user) {
    if (!store[guildId]) store[guildId] = {};
    if (!store[guildId][type]) store[guildId][type] = {};
    store[guildId][type][user] = (store[guildId][type][user] || 0) + 1;
}

// 영지전 균열 명령의 길드별 1회 사용 여부 확인
function hasGuildTerritoryCommandBeenUsed(store, guildId, type) {
    return !!(store && store[guildId] && store[guildId][type] && store[guildId][type].used);
}

// 영지전 균열 명령의 길드별 1회 사용 기록 저장
function markGuildTerritoryCommandUsed(store, guildId, type, user, count) {
    if (!store[guildId]) store[guildId] = {};
    store[guildId][type] = {
        used: true,
        user: user,
        count: count,
        at: formatDateTime(new Date())
    };
}

// 영지전 균열 명령 재사용 거부 메시지
function buildGuildTerritoryCommandReuseBlockedMessage(guild, command) {
    return (
        "❌ [" + formatGuildDisplay(guild) + "]\n\n" +
        "[" + command + "]은 이번 영지전에서\n" +
        "이미 사용하셨습니다.\n\n" +
        "각 명령어는 영지전당 1회만\n" +
        "사용 가능합니다."
    );
}

// 영지전 균열 아이템 사용 명령 처리
function handleGuildTerritoryRiftControlCommand(data, petData, guildData, petSkillData, sender, msg) {
    if (!isGuildTerritoryRiftControlCommandMessage(msg)) return null;

    var parts = msg.trim().split(/\s+/);
    var command = parts[0];

    var config = null;
    if (command === "/불안정") {
        config = { type: "instabilityUp", item: GLOBAL_CONFIG.guildTerritory.items.instabilityUpName, deltaAdjust: GLOBAL_CONFIG.guildTerritory.rates.instabilityItemStep };
    } else if (command === "/안정") {
        config = { type: "instabilityDown", item: GLOBAL_CONFIG.guildTerritory.items.instabilityDownName, deltaAdjust: -GLOBAL_CONFIG.guildTerritory.rates.instabilityItemStep };
    } else if (command === "/균열") {
        config = { type: "riftGuide", item: GLOBAL_CONFIG.guildTerritory.items.riftGuideName, deltaBias: GLOBAL_CONFIG.guildTerritory.rates.riftItemStep };
    } else if (command === "/대균열") {
        config = { type: "greatRiftGuide", item: GLOBAL_CONFIG.guildTerritory.items.greatRiftGuideName, deltaBias: -GLOBAL_CONFIG.guildTerritory.rates.riftItemStep };
    } else {
        return null;
    }
    var bagItemName = config.item;

    var count = parts.length === 2 ? parseInt(parts[1], 10) : 1;
    if (isNaN(count) || count <= 0) {
        return { message: "사용법: " + command + " 숫자\n예) " + command + " 1" };
    }
    if (count > GLOBAL_CONFIG.command.batchUseMax) {
        return { message: "❌ " + command + "은 한 번에 최대 " + GLOBAL_CONFIG.command.batchUseMax + "회까지만 사용할 수 있습니다." };
    }

    // 영지전 데이터 보장 및 초기화
    var war = ensureGuildTerritoryWar(data, guildData);
    var blocked = canUseGuildTerritoryRiftItem(war);
    if (blocked) return { message: blocked };

    var guildInfo = getMyGuildInfo(data, guildData, sender);
    if (!guildInfo || guildInfo.error || !guildInfo.guild) {
        return { message: "❌ 길드에 속하지 않아 사용할 수 없습니다." };
    }
    if (!war.readyGuilds[guildInfo.guildId]) {
        return { message: "❌ 길드영지전에 참여하지 않은 길드는 사용할 수 없습니다." };
    }
    if (hasGuildTerritoryCommandBeenUsed(war.riftCommandUses, guildInfo.guildId, config.type)) {
        return { message: buildGuildTerritoryCommandReuseBlockedMessage(guildInfo.guild, command) };
    }
    if (!isGuildTerritoryAttacker(guildInfo.guild, petSkillData, sender)) {
        return { message: "❌ [" + checkRank(data, petData, guildData, sender) + "] 님은 소드마스터🤺 또는 전투형 지휘관📙 권한이 없어 사용할 수 없습니다." };
    }
    if (war.eliminatedGuilds[guildInfo.guildId] || war.eliminatedUsers[sender]) {
        return { message: "❌ 탈락한 길드 또는 유저는 사용할 수 없습니다." };
    }
    if (!hasItem(data, sender, config.item, 1)) {
        return { message: "보유 중인 " + config.item + "이 없습니다.\n\n아이템을 보유한 상태에서 다시 시도해 주세요." };
    }
    var bagItemCount = data.member[sender].bag[bagItemName] || 0;

    // 불안정도 조정 아이템인 경우, 입력 수량과 조정치 한도 안에서 적용
    if (config.deltaAdjust) {
        var adjustRemain = config.deltaAdjust > 0
            ? Math.max(0, GLOBAL_CONFIG.guildTerritory.limits.instabilityAdjustLimit - (war.instabilityAdjust || 0))
            : Math.max(0, GLOBAL_CONFIG.guildTerritory.limits.instabilityAdjustLimit + (war.instabilityAdjust || 0));
        var maxUseByAdjust = Math.floor(adjustRemain / Math.abs(config.deltaAdjust));
        var useCount = Math.min(count, bagItemCount, maxUseByAdjust);
        if (useCount <= 0) {
            return { message: "❌ 이번 영지전에서 더 이상 " + config.item + "을 사용할 수 없습니다." };
        }

        removeItem(data, sender, bagItemName, useCount);
        for (var i = 0; i < useCount; i++) markGuildTerritoryItemUse(war.instabilityUses, guildInfo.guildId, config.type, sender);
        markGuildTerritoryCommandUsed(war.riftCommandUses, guildInfo.guildId, config.type, sender, useCount);
        war.instabilityAdjust += config.deltaAdjust * useCount;

        var currentRate = getGuildTerritoryInstabilityRate(war);
        var appliedDelta = Math.abs(config.deltaAdjust * useCount);
        var out = "[" + formatGuildDisplay(guildInfo.guild) + "]\n\n";
        out += config.item + " 사용!\n\n";
        out += config.deltaAdjust > 0 ? "전장의 기운이 흔들리기 시작합니다.\n" : "전장의 기운이 차분히 가라앉습니다.\n";
        out += "🌪️ 전쟁불안정도 " + (config.deltaAdjust > 0 ? "+" : "-") + formatPercent1(appliedDelta) + "%\n";
        out += "[ 🌪️ 누적 전쟁불안정도: " + formatPercent1(currentRate) + "%]\n";
        out += config.deltaAdjust > 0 ? "🌌균열/🌋대균열 발생할 가능성이 조금 증가했습니다." : "🌌균열/🌋대균열 발생할 가능성이 조금 감소했습니다.";
        return { message: out, changed: true };
    }

    // 균열 유도 아이템인 경우, 입력 수량과 편향 한도 안에서 적용
    var guideStore = war.riftGuideUses;
    var biasRemain = config.deltaBias > 0
        ? Math.floor((30 - (war.riftBias || 0)) / config.deltaBias)
        : Math.floor(((war.riftBias || 0) + 70) / Math.abs(config.deltaBias));
    var guideUseCount = Math.min(count, bagItemCount, Math.max(0, biasRemain));
    if (guideUseCount <= 0) {
        return { message: "❌ 이번 영지전에서 더 이상 " + config.item + "을 사용할 수 없습니다." };
    }

    // 균열 유도 아이템 적용: 사용 횟수만큼 리프트 편향 조정, 균열 발생 확률 변화 계산, 결과 메시지 빌드 및 반환
    var beforeRates = getGuildTerritoryRiftRates(war);
    removeItem(data, sender, bagItemName, guideUseCount);
    for (var gu = 0; gu < guideUseCount; gu++) markGuildTerritoryItemUse(guideStore, guildInfo.guildId, config.type, sender);
    markGuildTerritoryCommandUsed(war.riftCommandUses, guildInfo.guildId, config.type, sender, guideUseCount);
    war.riftBias += config.deltaBias * guideUseCount;
    war.riftBias = Math.max(-70, Math.min(30, war.riftBias));
    var afterRates = getGuildTerritoryRiftRates(war);

    var guideOut = "[" + formatGuildDisplay(guildInfo.guild) + "]\n\n";
    guideOut += config.item + " 사용!\n\n";
    guideOut += config.deltaBias > 0 ? "전장의 흐름이 균열 쪽으로 기울기 시작합니다.\n\n" : "전장의 흐름이 대균열 쪽으로 기울기 시작합니다.\n\n";
    guideOut += config.deltaBias > 0 ? "🌌 균열의 기운이 강해지고\n🌋 대균열의 기운이 약해졌습니다.\n\n" : "🌋 대균열의 기운이 강해지고\n🌌 균열의 기운이 약해졌습니다.\n\n";
    guideOut += "🌌 균열: " + beforeRates.rift + "% → " + afterRates.rift + "%\n";
    guideOut += "🌋 대균열: " + beforeRates.greatRift + "% → " + afterRates.greatRift + "%";
    return { message: guideOut, changed: true };
}

// 영지전 공격 제한 시간 초과 시 미공격 처리: 누적된 미공격 횟수에 따른 경고 및 탈락 처리, 결과 메시지 반환
function applyGuildTerritoryTimeoutMiss(guildData, guildId) {
    var war = ensureGuildTerritoryWar({}, guildData);
    var g = getGuildByIdSafe(guildData, guildId);
    if (!g) return "⏳ 시간초과 미공격 발생\n\n길드 정보를 찾지 못했습니다.\n다음 공격 차례로 넘어갑니다.";

    war.timeoutMissCounts[guildId] = (war.timeoutMissCounts[guildId] || 0) + 1;
    var missCount = war.timeoutMissCounts[guildId];
    var guildName = formatGuildDisplay(g);

    if (missCount >= GLOBAL_CONFIG.guildTerritory.limits.timeoutMissLimit) {
        war.eliminatedGuilds[guildId] = {
            reason: "TIMEOUT_MISS",
            at: formatDateTime(new Date()),
            timeoutMissCount: missCount
        };
        return (
            "🚫 시간초과 미공격 " +
            GLOBAL_CONFIG.guildTerritory.limits.timeoutMissLimit +
            "회 누적\n\n[" +
            guildName +
            "] 길드가\n영지공격 미진행 " +
            GLOBAL_CONFIG.guildTerritory.limits.timeoutMissLimit +
            "회를 누적했습니다.\n\n해당 길드는 길드영지전에서 탈락됩니다.\n\n탈락 길드: " +
            guildName
        );
    }

    if (missCount === 1) {
        return (
            "⏳ 시간초과 미공격 발생\n\n[" +
            guildName +
            "] 길드가 제한 시간 내\n영지공격을 진행하지 않았습니다.\n\n미공격 경고: " +
            missCount +
            "/" +
            GLOBAL_CONFIG.guildTerritory.limits.timeoutMissLimit +
            "\n\n다음 공격 차례로 넘어갑니다."
        );
    }

    return (
        "⚠️ 시간초과 미공격 누적\n\n[" +
        guildName +
        "] 길드가 다시 제한 시간 내\n영지공격을 진행하지 않았습니다.\n\n미공격 경고: " +
        missCount +
        "/" +
        GLOBAL_CONFIG.guildTerritory.limits.timeoutMissLimit +
        "\n\n한 번 더 시간초과 미공격 시\n해당 길드는 길드영지전에서 탈락됩니다."
    );
}

// 길드 영지전 턴 타이머 또는 현재 공격자의 자동 공격 예약을 시작하는 함수
function startGuildTerritoryTurnTimer(data, petData, guildData, petSkillData, replier, isGroupChat) {
    if (GLOBAL_CONFIG.guildWar.legacyPaused) return;
    var war = guildData.territoryWar;
    if (!war || !war.active) return;

    // 기존 타이머가 있으면 초기화
    clearGuildTerritoryWarTimer();

    // 현재 공격자 정보 가져오기
    var row = getGuildTerritoryTurnRow(data, guildData);
    if (!row) {
        finishGuildTerritoryWar(data, guildData, "자동 종료", petSkillData);
        withGuildTerritoryDataMode(guildData, function () {
            saveJsonFile(guildData, guildPath);
        });
        return;
    }

    // 턴 타이머 식별 토큰 생성 (현재 시간 + 랜덤값)
    war.turnToken = String(new Date().getTime()) + "_" + String(Math.random());
    var token = war.turnToken;
    var turnGuildId = row.guildId;
    var turnUser = row.user;
    var autoAttackScheduled = false; // 현재 턴 사용자의 자동 공격 예약 여부
    var scheduledAutoTerritoryNo = 0; // 턴 안내와 실제 자동공격에 함께 사용할 영지 번호
    if (data.member[turnUser] && data.member[turnUser].guildTerritoryAutoAttackEnabled === true) {
        var scheduleValidation = validateGuildTerritoryAutoAttack(data, guildData, petSkillData, turnUser);
        if (scheduleValidation.ok) {
            scheduledAutoTerritoryNo = getGuildTerritoryAutoAttackTargetNo(war, turnGuildId);
            autoAttackScheduled = scheduledAutoTerritoryNo > 0;
            if (!autoAttackScheduled) {
                data.member[turnUser].guildTerritoryAutoAttackEnabled = false;
                appendGuildTerritoryAutomationLog(war, {
                    type: "AUTO_ATTACK_OFF",
                    roundId: war.roundId,
                    user: turnUser,
                    reason: "공격 가능한 타 길드 영지가 없음",
                    processedAt: formatDateTime(new Date())
                });
                appendGuildTerritoryAutomationDataLog(data, {
                    type: "AUTO_ATTACK_OFF",
                    user: turnUser,
                    reason: "공격 가능한 타 길드 영지가 없음",
                    processedAt: formatDateTime(new Date())
                });
                saveJsonFile(data, filePath);
            }
        } else {
            data.member[turnUser].guildTerritoryAutoAttackEnabled = false;
            appendGuildTerritoryAutomationLog(war, {
                type: "AUTO_ATTACK_OFF",
                roundId: war.roundId,
                user: turnUser,
                reason: scheduleValidation.reason,
                processedAt: formatDateTime(new Date())
            });
            appendGuildTerritoryAutomationDataLog(data, {
                type: "AUTO_ATTACK_OFF",
                user: turnUser,
                reason: scheduleValidation.reason,
                processedAt: formatDateTime(new Date())
            });
            saveJsonFile(data, filePath);
        }
    }
    var timerCtx = getCurrentContext();
    var timerCtxKey = timerCtx.key();
    saveJsonFile(guildData, guildPath);

    guildTerritoryWarTimers[timerCtxKey] = setTimeout(function () {
        var prevCtx = enterCommandContext(timerCtx);
        var timerTransactionAcquired = false;
        var timerTransactionEntered = false;
        try {
            dataTransactionLock.lock();
            timerTransactionAcquired = true;
            beginDataSaveTransaction();
            timerTransactionEntered = true;
            delete guildTerritoryWarTimers[timerCtxKey];
            var latestData = loadJsonFile(filePath);
            var latestPetData = loadJsonFile(memberPetPath);
            var latestPetSkillData = loadJsonFile(petSkillDataPath);
            var latestGuildData = loadJsonFile(guildPath);
            ensureGuildTerritoryWar(latestData, latestGuildData);
            var latestWar = latestGuildData ? latestGuildData.territoryWar : null;
            if (!latestWar || !latestWar.active) return;
            if (latestWar.turnToken !== token) return;

            if (autoAttackScheduled) {
                var latestTurn = getGuildTerritoryTurnRow(latestData, latestGuildData);
                var latestMember = latestData.member && latestData.member[turnUser] ? latestData.member[turnUser] : null;
                var executionValidation = validateGuildTerritoryAutoAttack(latestData, latestGuildData, latestPetSkillData, turnUser);
                var autoAttackLimit = getGuildTerritoryAttackLimitForWar(latestWar, executionValidation.guildInfo ? executionValidation.guildInfo.guild : null, turnGuildId);
                var personalAttackLimit = GLOBAL_CONFIG.guildTerritory.limits.personalAttackLimit;
                var canExecuteAutoAttack = !!(
                    latestTurn && latestTurn.guildId === turnGuildId && latestTurn.user === turnUser &&
                    latestMember && latestMember.guildTerritoryAutoAttackEnabled === true &&
                    executionValidation.ok && executionValidation.guildInfo && executionValidation.guildInfo.guildId === turnGuildId &&
                    (latestWar.guildAttackCounts[turnGuildId] || 0) < autoAttackLimit &&
                    getGuildTerritoryUserAttackCount(latestWar, turnUser) < personalAttackLimit
                );
                if (!canExecuteAutoAttack) {
                    if (latestMember) latestMember.guildTerritoryAutoAttackEnabled = false;
                    appendGuildTerritoryAutomationLog(latestWar, {
                        type: "AUTO_ATTACK_OFF",
                        roundId: latestWar.roundId,
                        user: turnUser,
                        reason: executionValidation.ok ? "공격 차례·횟수 조건 불충족" : executionValidation.reason,
                        processedAt: formatDateTime(new Date())
                    });
                    appendGuildTerritoryAutomationDataLog(latestData, {
                        type: "AUTO_ATTACK_OFF",
                        user: turnUser,
                        reason: executionValidation.ok ? "공격 차례·횟수 조건 불충족" : executionValidation.reason,
                        processedAt: formatDateTime(new Date())
                    });
                    saveJsonFile(latestData, filePath);
                    saveJsonFile(latestGuildData, guildPath);
                    startGuildTerritoryTurnTimer(latestData, latestPetData, latestGuildData, latestPetSkillData, replier, isGroupChat);
                    return;
                }
                var autoHomeData = null;
                if (getGuildTerritoryMissingCastleExpUsers(latestData, latestPetData, latestGuildData, turnUser, scheduledAutoTerritoryNo).length > 0) {
                    autoHomeData = loadJsonFile(homeDataFile);
                }
                var autoExecutionResult = executeGuildTerritoryNormalAttack(latestData, latestPetData, autoHomeData, latestGuildData, latestPetSkillData, turnUser, scheduledAutoTerritoryNo, replier, isGroupChat, true, null);
                if (!autoExecutionResult.ok && latestGuildData.territoryWar && latestGuildData.territoryWar.active) {
                    latestData.member[turnUser].guildTerritoryAutoAttackEnabled = false;
                    appendGuildTerritoryAutomationDataLog(latestData, {
                        type: "AUTO_ATTACK_OFF",
                        user: turnUser,
                        reason: autoExecutionResult.message,
                        processedAt: formatDateTime(new Date())
                    });
                    saveJsonFile(latestData, filePath);
                    saveJsonFile(latestGuildData, guildPath);
                    startGuildTerritoryTurnTimer(latestData, latestPetData, latestGuildData, latestPetSkillData, replier, isGroupChat);
                }
                return;
            }

            // 현재 공격자 길드의 미공격 처리 및 누적 횟수 증가
            latestWar.guildAttackCounts[turnGuildId] = (latestWar.guildAttackCounts[turnGuildId] || 0) + 1;
            latestWar.turnToken = null;

            // 미공격 처리 결과 메시지 빌드
            var timeoutMessage = applyGuildTerritoryTimeoutMiss(latestGuildData, turnGuildId);
            var riftMessage = processGuildTerritoryRiftEvent(latestData, latestGuildData);
            if (riftMessage) {
                withGuildTerritoryDataMode(latestGuildData, function () {
                    saveJsonFile(latestData, filePath);
                });
            }

            Api.replyRoom(room8, timerCtx.header(timeoutMessage));
            if (riftMessage) {
                Api.replyRoom(room8, timerCtx.header(riftMessage));
            }

            // 모든 길드가 공격 횟수를 다 채웠거나 공격할 수 있는 소드마스터가 없는 경우 영지전 종료 처리
            if (isGuildTerritoryAllDone(latestData, latestGuildData)) {
                finishGuildTerritoryWar(latestData, latestGuildData, "자동 종료", latestPetSkillData);
                withGuildTerritoryDataMode(latestGuildData, function () {
                    saveJsonFile(latestGuildData, guildPath);
                    saveJsonFile(latestData, filePath);
                });
                return;
            }

            // 다음 공격자 선택 및 턴 메시지 발송
            advanceGuildTerritoryTurn(latestData, latestGuildData);
            withGuildTerritoryDataMode(latestGuildData, function () {
                saveJsonFile(latestGuildData, guildPath);
            });

            // 다음 공격자 정보로 턴 메시지 빌드 및 발송
            var timeoutAutoTerritoryNo = startGuildTerritoryTurnTimer(latestData, latestPetData, latestGuildData, latestPetSkillData, replier, isGroupChat);
            var turnMsgs = buildGuildTerritoryTurnMessage(latestData, latestPetData, latestGuildData, timeoutAutoTerritoryNo);
            turnMsgs.forEach(function (m) {
                castleMsg(m, replier, isGroupChat);
            });
        } finally {
            if (timerTransactionEntered) endDataSaveTransaction();
            if (timerTransactionAcquired) dataTransactionLock.unlock();
            exitCommandContext(prevCtx);
        }
    }, autoAttackScheduled ? GLOBAL_CONFIG.guildTerritory.timers.autoAttackDelayMs : GLOBAL_CONFIG.guildTerritory.timers.turnTimeoutMs);
    return scheduledAutoTerritoryNo;
}

// 영지전 공격 시 특수 아이템 체크
function getGuildTerritorySpecialItem(userBag, candidates) {
    for (var i = 0; i < candidates.length; i++) {
        if (userBag && userBag[candidates[i].name] && userBag[candidates[i].name] > 0) {
            return candidates[i];
        }
    }
    return null;
}

// 영지전 아이템 사용 후 감소 처리
function decreaseGuildTerritoryItem(data, user, itemName) {
    if (!data.member[user] || !data.member[user].bag || !data.member[user].bag[itemName]) return;
    data.member[user].bag[itemName] -= 1;
    if (data.member[user].bag[itemName] <= 0) delete data.member[user].bag[itemName];
}

// 영지전 공격자와 방어자의 크리티컬을 한 번씩 판정하고 최종 캐슬매력을 반환
function resolveGuildTerritoryCastleBattle(war, data, petData, attackerName, defenderName) {
    var attackerSnapshot = war.castleBattleSnapshots[attackerName] || createGuildTerritoryCastleBattleSnapshot(data, petData, attackerName, war.castleExpSnapshots[attackerName]);
    var defenderSnapshot = war.castleBattleSnapshots[defenderName] || createGuildTerritoryCastleBattleSnapshot(data, petData, defenderName, war.castleExpSnapshots[defenderName]);
    var isAttackerCritical = Math.random() < attackerSnapshot.critChance;
    var isDefenderCritical = Math.random() < defenderSnapshot.critChance;
    var attackerFinalExp = isAttackerCritical ? Math.round(attackerSnapshot.baseExp * attackerSnapshot.critMultiplier) : attackerSnapshot.baseExp;
    var defenderFinalExp = isDefenderCritical ? Math.round(defenderSnapshot.baseExp * defenderSnapshot.critMultiplier) : defenderSnapshot.baseExp;

    war.castleBattleSnapshots[attackerName] = attackerSnapshot;
    war.castleBattleSnapshots[defenderName] = defenderSnapshot;
    return {
        attacker: { name: attackerName, petName: attackerSnapshot.petName, baseExp: attackerSnapshot.baseExp, finalExp: attackerFinalExp, isCritical: isAttackerCritical },
        defender: { name: defenderName, petName: defenderSnapshot.petName, baseExp: defenderSnapshot.baseExp, finalExp: defenderFinalExp, isCritical: isDefenderCritical }
    };
}

// 영지전 공격·방어 유저의 길드와 캐슬매력 상세 블록 생성
function formatGuildTerritoryCastleBattleUserBlock(data, petData, guildData, guild, battleUser, roleLabel) {
    var message = roleLabel + " · " + formatGuildDisplay(guild) + "\n";
    message += "유저: " + checkRank(data, petData, guildData, battleUser.name) + "\n";
    message += "펫: " + battleUser.petName + "\n";
    message += "기본: " + numberWithCommas(battleUser.baseExp) + "💕\n";
    message += "최종: " + numberWithCommas(battleUser.finalExp) + "💕" + (battleUser.isCritical ? " 💥크리티컬" : "");
    return message;
}

// 영지전 상세보기에 공격·방어 카드와 최종 매력 판정 결과 생성
function buildGuildTerritoryCastleBattleDetailMessage(data, petData, guildData, attackerGuild, defenderGuild, territory, territoryNo, battleResult, isAttackerWin) {
    var compareSymbol = battleResult.attacker.finalExp > battleResult.defender.finalExp ? ">" : battleResult.attacker.finalExp < battleResult.defender.finalExp ? "<" : "=";
    var message = "\n🏰 [" + territoryNo + "] " + territory.name + "\n";
    message += "━━━━━━━━━━━━\n\n";
    message += formatGuildTerritoryCastleBattleUserBlock(data, petData, guildData, attackerGuild, battleResult.attacker, "⚔️ 공격") + "\n\n";
    message += "              🆚\n\n";
    message += formatGuildTerritoryCastleBattleUserBlock(data, petData, guildData, defenderGuild, battleResult.defender, "🛡️ 방어") + "\n\n";
    message += "━━━━━━━━━━━━\n";
    message += "📊 최종 매력 비교\n";
    message += numberWithCommas(battleResult.attacker.finalExp) + " " + compareSymbol + " " + numberWithCommas(battleResult.defender.finalExp) + "\n\n";
    if (isAttackerWin) {
        message += "⚔️ 공격 성공\n";
        message += "[" + formatGuildDisplay(attackerGuild) + "] 길드가\n";
        message += "[" + territoryNo + "] " + territory.name + " 점령에 성공했습니다!";
    } else {
        message += "🛡️ 방어 성공\n";
        message += "[" + formatGuildDisplay(defenderGuild) + "] 길드가\n";
        message += "[" + territoryNo + "] " + territory.name + "을 지켜냈습니다!";
    }
    return message;
}

// 차원의 문 이벤트 결과 처리
function resolveGuildTerritoryDimensionGate(data, petData, guildData, sender, attackInfo) {
    var war = ensureGuildTerritoryWar(data, guildData);
    var rank = checkRank(data, petData, guildData, sender);
    var success = Math.random() < GLOBAL_CONFIG.guildTerritory.rates.dimensionGateSuccessRate;
    var messages = success ? GLOBAL_CONFIG.guildTerritory.dimensionGate.successMessages : GLOBAL_CONFIG.guildTerritory.dimensionGate.failMessages;
    var message = messages[Math.floor(Math.random() * messages.length)].replace("{{rank}}", rank);
    var attackLimit = getGuildTerritoryAttackLimitForWar(war, attackInfo.guild, attackInfo.guildId);

    if (success) {
        war.guildAttackLimits[attackInfo.guildId] = attackLimit + GLOBAL_CONFIG.guildTerritory.dimensionGate.bonusTurns;
        return "🎖️길드 영지전 결과🎖️\n\n[차원의 문 통과🌀]\n" +
            message + "\n\n" +
            "[" + formatGuildDisplay(attackInfo.guild) + "] 남은 턴(" +
            Math.max(0, war.guildAttackLimits[attackInfo.guildId] - (war.guildAttackCounts[attackInfo.guildId] || 0)) +
            "/" +
            war.guildAttackLimits[attackInfo.guildId] +
            "⚔)";
    }

    war.eliminatedUsers[sender] = {
        guildId: attackInfo.guildId,
        reason: "DIMENSION_GATE_FAIL",
        at: formatDateTime(new Date()),
        penaltyTurns: GLOBAL_CONFIG.guildTerritory.dimensionGate.failPenaltyTurns
    };
    war.guildAttackCounts[attackInfo.guildId] =
        (war.guildAttackCounts[attackInfo.guildId] || 0) + GLOBAL_CONFIG.guildTerritory.dimensionGate.failPenaltyTurns;
    return "🎖️길드 영지전 결과🎖️\n\n[차원의 문 실패🌀]\n" +
        message + "\n\n" +
        "※ 차원의 문 탈락으로 공격 가능 횟수 " + GLOBAL_CONFIG.guildTerritory.dimensionGate.failPenaltyTurns + "회가 차감됩니다.\n" +
        "[" + formatGuildDisplay(attackInfo.guild) + "] 남은 턴 " +
        Math.max(0, attackLimit - (war.guildAttackCounts[attackInfo.guildId] || 0)) +
        "/" +
        attackLimit +
        "회";
}

// 날 기억해줘 이벤트를 판정하고 성공 시 점령지 한 곳을 해제
function resolveGuildTerritoryRememberMe(data, petData, guildData, sender, attackInfo) {
    var war = ensureGuildTerritoryWar(data, guildData);
    var rank = checkRank(data, petData, guildData, sender);
    var occupiedTerritories = []; // 현재 실제 길드가 점령 중인 1~7번 영지 후보
    var territoryList = getGuildTerritoryList();

    for (var i = 0; i < territoryList.length; i++) {
        var territory = territoryList[i];
        var territoryState = war.territories[String(territory.no)];
        var ownerGuild = getGuildByIdSafe(guildData, territoryState ? territoryState.ownerGuildId : null);
        if (territoryState && ownerGuild) {
            occupiedTerritories.push({ territory: territory, state: territoryState, ownerGuild: ownerGuild });
        }
    }

    var success = occupiedTerritories.length > 0 && Math.random() < GLOBAL_CONFIG.guildTerritory.rememberMe.successRate;
    var messages = success ? GLOBAL_CONFIG.guildTerritory.rememberMe.successMessages : GLOBAL_CONFIG.guildTerritory.rememberMe.failMessages;
    var message = messages[Math.floor(Math.random() * messages.length)].replace("{{rank}}", rank);

    if (!success) {
        return "🎖️길드 영지전 결과🎖️\n\n[날 기억해줘 실패😭]\n" +
            message + "\n\n" +
            "※ 점령지에는 아무런 변화도 일어나지 않았습니다.";
    }

    var selected = occupiedTerritories[Math.floor(Math.random() * occupiedTerritories.length)];
    selected.state.ownerGuildId = null;
    selected.state.ownerUser = null;
    if (selected.territory.no === 1 && data.HoiCastle) {
        data.HoiCastle.lord = "";
        data.HoiCastle.earnings = 0;
        data.HoiCastle.defenseCount = 0;
    }

    return "🎖️길드 영지전 결과🎖️\n\n[날 기억해줘 성공😭]\n" +
        message + "\n\n" +
        "※ [" + formatGuildDisplay(selected.ownerGuild) + "]의 점령지인 " + selected.territory.name + "(이)가\n" +
        "미점령 상태로 변경됩니다.";
}

// 디버깅 모드에서 영지 방어권과 기습방어 큐브 확률의 합산 내역 생성
function buildGuildTerritoryAmbushDefenseDebugMessage(data, petData, guildData, defenderName, defenseItem, guildCubeAmbushDefensePercent) {
    var defenseItemPercent = defenseItem ? defenseItem.successRate * 100 : 0; // 보유 중인 최우선 영지절대방어권 확률
    var combinedPercent = Math.min(100, defenseItemPercent + guildCubeAmbushDefensePercent); // 방어권과 큐브의 단순 합산 확인값
    var defenderDisplay = defenderName ? checkRank(data, petData, guildData, defenderName) : "방어자 없음";
    var defenseItemDisplay = defenseItem ? defenseItem.label : "미보유";

    return "🛡️ 영지공격 기습방어 디버깅\n" +
        "━━━━━━━━━━━━━━━\n" +
        "방어자: [" + defenderDisplay + "]\n" +
        "영지절대방어권: " + defenseItemDisplay + " = " + defenseItemPercent.toFixed(1) + "%\n" +
        "기습방어 큐브: +" + guildCubeAmbushDefensePercent.toFixed(1) + "%\n" +
        "단순 합산: " + defenseItemPercent.toFixed(1) + "% + " + guildCubeAmbushDefensePercent.toFixed(1) + "% = " + combinedPercent.toFixed(1) + "%\n" +
        "※ 실제 전투에서는 절대방어권을 먼저 판정하고, 기습공격이 발동하면 큐브를 별도로 판정합니다.";
}

// 영지전 공격 결과 처리
function resolveGuildTerritoryAttack(data, petData, guildData, petSkillData, sender, territoryNo) {
    if (territoryNo === 1) return "❌ 호월킹덤은 /길드전쟁에서 점령할 수 있습니다.";
    var war = guildData.territoryWar;
    var ter = war.territories[String(territoryNo)];
    var attackerGuildInfo = getMyGuildInfo(data, guildData, sender);
    var attackerGuild = attackerGuildInfo.guild;
    var defenderGuild = getGuildByIdSafe(guildData, ter.ownerGuildId);
    var defenderName = getGuildTerritoryDefenderName(guildData, ter);
    var territory = getGuildTerritoryByNo(territoryNo);
    var used = war.guildAttackCounts[attackerGuildInfo.guildId] || 0;
    //	var baseInfo = "(길드영지전 총 공격횟수⚔ " + used + "/" + getGuildTerritoryAttackLimitForWar(war, attackerGuild, attackerGuildInfo.guildId) + ")\n\n";
    var out = "";

    if (defenderGuild && defenderGuild.name === attackerGuild.name) {
        out = "🎖️길드 영지전 결과🎖️[공격 불가⚠️]\n";
        //		out += baseInfo;
        out += "[" + checkRank(data, petData, guildData, sender) + "] [" + formatGuildDisplay(attackerGuild) + "]\n";
        out += "[" + territoryNo + "] " + territory.name + "을(를) 이미 점령 중입니다.";
        return out;
    }

    var ownedTerritoryCount = getGuildTerritoryOwnedCount(war, attackerGuildInfo.guildId); // 현재 길드 점령지 수
    if (ownedTerritoryCount >= GLOBAL_CONFIG.guildTerritory.limits.maxOwnedTerritories) {
        var occupationLimit = getGuildTerritoryAttackLimitForWar(war, attackerGuild, attackerGuildInfo.guildId);
        var occupationRemain = Math.max(0, occupationLimit - used); // 이번 공격 턴 차감 후 남은 횟수
        out = "🎖️길드 영지전 결과🎖️[공격 불가⚠️]\n";
        out += "[🤣점령제한]\n";
        out += "[" + formatGuildDisplay(attackerGuild) + "] 길드는\n";
        out += "현재 최대 점령지 " + GLOBAL_CONFIG.guildTerritory.limits.maxOwnedTerritories + "개에 도달했습니다.\n";
        out += "턴 -1개가 차감됩니다.\n\n";
        out += "※ [" + formatGuildDisplay(attackerGuild) + "] 남은 턴 " + occupationRemain + "/" + occupationLimit + "회";
        return out;
    }

    var defenseItems = [
        { name: "영지절대방어권🛡(50%)", successRate: 0.5, label: "절대🛡(50%)" },
        { name: "영지절대방어권🛡(50%)", successRate: 0.5, label: "절대🛡(50%)" },
        { name: "영지절대방어권🛡(20%)", successRate: 0.2, label: "절대🛡(20%)" },
        { name: "영지절대방어권🛡(20%)", successRate: 0.2, label: "절대🛡(20%)" }
    ];
    var offenseItems = [
        { name: "영지기습공격권🔥(40%)", successRate: 0.4, label: "기습🔥(40%)" },
        { name: "영지기습공격권🔥(40%)", successRate: 0.4, label: "기습🔥(40%)" },
        { name: "영지기습공격권🔥(10%)", successRate: 0.1, label: "기습🔥(10%)" },
        { name: "영지기습공격권🔥(10%)", successRate: 0.1, label: "기습🔥(10%)" }
    ];
    var defenseItem = defenderName && data.member[defenderName] ? getGuildTerritorySpecialItem(data.member[defenderName].bag, defenseItems) : null;
    var guildCubeAmbushDefensePercent = defenderName ? getGuildContributionCubeMemberPercent(data, guildData, defenderName, "ambushDefense") : 0;
    if (isDebuggerFlag) {
        debuggerLog(buildGuildTerritoryAmbushDefenseDebugMessage(data, petData, guildData, defenderName, defenseItem, guildCubeAmbushDefensePercent));
    }
    if (defenderName && data.member[defenderName]) {
        // 방어 아이템
        if (defenseItem && Math.random() <= defenseItem.successRate) {
            decreaseGuildTerritoryItem(data, defenderName, defenseItem.name);

            out = "🎖️길드 영지전 결과🎖️[공격 실패❌]\n";
            //		out += baseInfo;
            out += "[" + territoryNo + "] " + territory.name + " 방어 [" + defenseItem.label + "] 발동!\n";
            out += "공격/방어/보상 상세보기" + allsee;
            out += "[" + formatGuildDisplay(attackerGuild) + "] 길드의 [" + checkRank(data, petData, guildData, sender) + "] 이(가)\n";
            out += "[" + territoryNo + "] " + territory.name + " 공격에 실패합니다!\n🆚\n";
            out += "[" + formatGuildDisplay(defenderGuild) + "] 길드의 [" + checkRank(data, petData, guildData, defenderName) + "]\n";
            return out;
        }
    }

    var offenseItem = getGuildTerritorySpecialItem(data.member[sender].bag, offenseItems);
    if (offenseItem && Math.random() <= offenseItem.successRate) {
        // 공격 아이템
        decreaseGuildTerritoryItem(data, sender, offenseItem.name);
        if (guildCubeAmbushDefensePercent > 0 && Math.random() < guildCubeAmbushDefensePercent / 100) {
            out = "🎖️길드 영지전 결과🎖️[공격 실패❌]\n";
            out += "[💠 길드공헌 큐브] 기습방어 +" + guildCubeAmbushDefensePercent.toFixed(1) + "% 발동!\n";
            out += "공격/방어/보상 상세보기" + allsee;
            out += "[" + formatGuildDisplay(attackerGuild) + "] 길드의 [" + checkRank(data, petData, guildData, sender) + "] 이(가)\n";
            out += "[" + territoryNo + "] " + territory.name + " 기습 공격에 실패합니다!\n🆚\n";
            out += "[" + formatGuildDisplay(defenderGuild) + "] 길드의 [" + checkRank(data, petData, guildData, defenderName) + "]\n";
            return out;
        }
        ter.ownerGuildId = attackerGuildInfo.guildId;
        ter.ownerUser = sender;
        if (territoryNo === 1 && data.HoiCastle) {
            data.HoiCastle.lord = sender;
            data.HoiCastle.earnings = 0;
            data.HoiCastle.defenseCount = 0;
        }
        out = "🎖️길드 영지전 결과🎖️[공격 성공✅]\n";
        //	out += baseInfo;
        out += "🔥 공격 성공! [" + offenseItem.label + "] 발동\n";
        out += "공격/방어/보상 상세보기" + allsee;
        out += "[" + formatGuildDisplay(attackerGuild) + "] 길드의 [" + checkRank(data, petData, guildData, sender) + "] 이(가)\n";
        out += "[" + territoryNo + "] " + territory.name + " 공격하였습니다.\n\n";
        return out;
    }

    if (!defenderName || !petData[defenderName] || !petData[sender]) {
        // 방어자 또는 공격자 정보가 없는 경우 자동으로 공격 성공 처리
        ter.ownerGuildId = attackerGuildInfo.guildId;
        ter.ownerUser = sender;
        if (territoryNo === 1 && data.HoiCastle) data.HoiCastle.lord = sender;

        out = "🎖️길드 영지전 결과🎖️[공격 성공✅]\n";
        //out += baseInfo;
        out += "공격/방어/보상 상세보기" + allsee;
        out += "[" + formatGuildDisplay(attackerGuild) + "] 길드의 [" + checkRank(data, petData, guildData, sender) + "] 이(가)\n";
        out += "[" + territoryNo + "] " + territory.name + " 점령에 성공합니다!";
        return out;
    }

    var castleBattleResult = resolveGuildTerritoryCastleBattle(war, data, petData, sender, defenderName);
    var isAttackerWin = castleBattleResult.attacker.finalExp > castleBattleResult.defender.finalExp; // 크리 적용 후 공격자 캐슬매력이 높을 때만 승리
    var castleBattleDetailMessage = buildGuildTerritoryCastleBattleDetailMessage(data, petData, guildData, attackerGuild, defenderGuild, territory, territoryNo, castleBattleResult, isAttackerWin);

    if (isAttackerWin) {
        //공격자 승리
        ter.ownerGuildId = attackerGuildInfo.guildId;
        ter.ownerUser = sender;
        if (territoryNo === 1 && data.HoiCastle) {
            data.HoiCastle.lord = sender;
            data.HoiCastle.earnings = 0;
            data.HoiCastle.defenseCount = 0;
        }
        out = "🎖️길드 영지전 결과🎖️[공격 성공✅]\n";
        //out += baseInfo;
        out += "공격/방어/보상 상세보기" + allsee + castleBattleDetailMessage;
    } else {
        //방어자 승리
        out = "🎖️길드 영지전 결과🎖️[공격 실패❌]\n";
        //	out += baseInfo;
        out += "공격/방어/보상 상세보기" + allsee + castleBattleDetailMessage;
    }
    return out;
}

// 종료된 영지전 참가 길드 중 권한·직책을 충족한 길드를 다음 회차에 자동 준비하는 함수
function prepareNextGuildTerritoryWarAutomatically(data, guildData, petSkillData, war, finishedReadyGuildIds) {
    var nextReadyGuilds = {};
    var messages = [];
    var nextRoundId = "READY_" + String(new Date().getTime());
    for (var guildIndex = 0; guildIndex < finishedReadyGuildIds.length; guildIndex++) {
        var guildId = finishedReadyGuildIds[guildIndex];
        var guild = getGuildByIdSafe(guildData, guildId);
        if (!guild) continue;
        var candidates = [];
        if (guild.master) candidates.push(guild.master);
        var subMasters = ensureGuildSubMasters(guild);
        for (var subIndex = 0; subIndex < subMasters.length; subIndex++) {
            if (candidates.indexOf(subMasters[subIndex]) === -1) candidates.push(subMasters[subIndex]);
        }
        var basisUser = "";
        for (var candidateIndex = 0; candidateIndex < candidates.length; candidateIndex++) {
            var candidate = candidates[candidateIndex];
            if (!guild.members || !guild.members[candidate]) continue;
            if (!hasGuildTerritoryAutoReadyEntitlement(data, candidate)) continue;
            basisUser = candidate;
            break;
        }
        if (!basisUser) continue;
        nextReadyGuilds[guildId] = {
            guildId: guildId,
            guildName: guild.name,
            preparedBy: basisUser,
            preparedAt: formatDateTime(new Date()),
            automatic: true,
            roundId: nextRoundId
        };
        appendGuildTerritoryAutomationLog(war, {
            type: "AUTO_READY",
            roundId: war.roundId,
            nextRoundId: nextRoundId,
            guildId: guildId,
            basisUser: basisUser,
            entitlement: hasGuildTerritoryAutomationItem(data, basisUser, GLOBAL_CONFIG.guildTerritory.automation.autoReadyItemName) ? "ITEM" : "TERRITORY_PASS",
            processedAt: formatDateTime(new Date())
        });
        messages.push("✅ 길드영지 자동 준비 완료\n[" + formatGuildDisplay(guild) + "] 길드가 다음 길드영지전 준비를 완료했습니다.");
    }
    return { readyGuilds: nextReadyGuilds, messages: messages, nextRoundId: nextRoundId };
}

// 현재 영지전 턴의 자동·수동 공격 중복 방지 키를 반환하는 함수
function getGuildTerritoryAttackActionKey(war, user) {
    var turnId = war.turnToken || ("TURN_" + String(war.currentTurnIndex || 0) + "_" + String(war.turnCount || 0));
    return (war.roundId || war.startedAt || "ROUND") + "_" + turnId + "_" + user;
}

// 영지전 수동·자동 공격 결과의 상단 요약과 접힌 상세 내용을 생성
function buildGuildTerritoryAttackResultMessage(data, petData, guildData, sender, territoryNo, isAutoAttack, resultMessage, rewardMessage, triggerMessages) {
    var territory = getGuildTerritoryByNo(territoryNo); // 요약에 표시할 실제 공격 영지
    var headerEnd = resultMessage.indexOf("\n");
    var header = headerEnd === -1 ? resultMessage : resultMessage.slice(0, headerEnd); // 공격 성공·실패 결과 제목
    var detailBody = headerEnd === -1 ? "" : resultMessage.slice(headerEnd + 1); // 접힌 상세보기로 이동할 기존 결과 본문
    var detailMarker = "공격/방어/보상 상세보기" + allsee;
    var detailMarkerIndex = detailBody.indexOf(detailMarker); // 기존 상세보기 표기의 시작 위치
    if (detailMarkerIndex !== -1) {
        detailBody = detailBody.slice(0, detailMarkerIndex) + detailBody.slice(detailMarkerIndex + detailMarker.length);
    }
    detailBody = detailBody.replace(/^\n+|\n+$/g, "");
    if (triggerMessages && triggerMessages.length > 0) {
        detailBody = triggerMessages.join("\n") + (detailBody ? "\n" + detailBody : "");
    }

    var out = header + "\n";
    out += "⚔️ [" + checkRank(data, petData, guildData, sender) + "] 님의 상세 결과" + (isAutoAttack ? "(자동)" : "") + "\n\n";
    out += (isAutoAttack ? "자동공격 영지: " : "공격 영지: ") + "[" + territoryNo + "] " + (territory ? territory.name : "") + "\n";
    if (rewardMessage) out += rewardMessage + "\n";
    out += "\n공격/방어/보상 상세보기" + allsee;
    if (detailBody) out += "\n" + detailBody;
    return out;
}

// 1~7번 길드영지의 공통 공격·보상·저장·다음 턴 처리를 실행하는 함수
function executeGuildTerritoryNormalAttack(data, petData, homeData, guildData, petSkillData, sender, territoryNo, replier, isGroupChat, isAutoAttack, timingRows) {
    if (territoryNo === 1) return { ok: false, message: "❌ 호월킹덤은 /길드전쟁에서 점령할 수 있습니다." };
    var war = ensureGuildTerritoryWar(data, guildData);
    var attackInfo = getMyGuildInfo(data, guildData, sender);
    if (!war.active || !war.startReady || !attackInfo || attackInfo.error || !attackInfo.guild) {
        return { ok: false, message: "❌ 영지공격 실행 조건이 유효하지 않습니다." };
    }
    var currentTurn = getGuildTerritoryTurnRow(data, guildData);
    if (!currentTurn || currentTurn.guildId !== attackInfo.guildId || (isAutoAttack && currentTurn.user !== sender)) {
        return { ok: false, message: "❌ 현재 공격 차례가 아닙니다." };
    }
    var missingCastleExpUsers = getGuildTerritoryMissingCastleExpUsers(data, petData, guildData, sender, territoryNo);
    if (missingCastleExpUsers.length > 0 && !homeData) {
        return { ok: false, message: "❌ 영지공격 스냅샷 데이터를 확인할 수 없습니다." };
    }
    var actionKey = getGuildTerritoryAttackActionKey(war, sender);
    if (war.autoAttackProcessedKeys[actionKey]) {
        return { ok: false, duplicate: true, message: "⚠️ 이미 처리된 영지공격 차례입니다." };
    }
    war.autoAttackProcessedKeys[actionKey] = {
        user: sender,
        territoryNo: territoryNo,
        automatic: isAutoAttack === true,
        processedAt: formatDateTime(new Date())
    };

    var attackPrepareStartMs = timingRows ? Date.now() : 0;
    clearGuildTerritoryWarTimer();
    war.turnToken = null;
    war.guildAttackCounts[attackInfo.guildId] = (war.guildAttackCounts[attackInfo.guildId] || 0) + 1;
    increaseGuildTerritoryUserAttackCount(war, sender); // 본인·대리 공격을 실제 실행자 기준으로 1회 누적
    var rewardMessage = applyGuildTerritoryTurnReward(data, guildData, attackInfo.guildId, sender);
    if (timingRows) timingRows.push({ label: "공격 준비/턴 보상", ms: Date.now() - attackPrepareStartMs });

    var snapshotPrepareStartMs = timingRows ? Date.now() : 0;
    if (missingCastleExpUsers.length > 0) {
        fillGuildTerritoryCastleExpSnapshots(data, petData, homeData, petSkillData, guildData, missingCastleExpUsers);
    }
    if (timingRows) timingRows.push({ label: "캐슬매력 스냅샷 준비", ms: Date.now() - snapshotPrepareStartMs });

    var attackResolveStartMs = timingRows ? Date.now() : 0;
    var resultMessage = resolveGuildTerritoryAttack(data, petData, guildData, petSkillData, sender, territoryNo);
    if (timingRows) timingRows.push({ label: "전투 판정", ms: Date.now() - attackResolveStartMs });
    var attackPostProcessStartMs = timingRows ? Date.now() : 0;
    var isAttackBlocked = resultMessage.indexOf("[공격 불가⚠️]") !== -1;
    var riftMessage = isAttackBlocked ? "" : processGuildTerritoryRiftEvent(data, guildData);
    var triggerMessages = [];
    if (shouldShowGuildTerritoryCommanderTrigger(attackInfo.guild, petSkillData, sender)) {
        triggerMessages.push(buildPetSkillMsg(data, petData, guildData, sender, "전투형 지휘관"));
    }
    resultMessage = buildGuildTerritoryAttackResultMessage(data, petData, guildData, sender, territoryNo, isAutoAttack, resultMessage, rewardMessage, triggerMessages);
    appendGuildTerritoryAutomationLog(war, {
        type: isAutoAttack ? "AUTO_ATTACK" : "MANUAL_ATTACK",
        roundId: war.roundId,
        actionKey: actionKey,
        user: sender,
        guildId: attackInfo.guildId,
        territoryNo: territoryNo,
        blocked: isAttackBlocked,
        result: isAttackBlocked ? "BLOCKED" : (resultMessage.indexOf("[공격 성공✅]") !== -1 ? "SUCCESS" : "FAIL"),
        processedAt: formatDateTime(new Date())
    });
    if (timingRows) timingRows.push({ label: "균열/보상 후처리", ms: Date.now() - attackPostProcessStartMs });

    if (isGuildTerritoryAllDone(data, guildData)) {
        castleMsg(resultMessage, replier, isGroupChat);
        if (riftMessage) castleMsg(riftMessage, replier, isGroupChat);
        finishGuildTerritoryWar(data, guildData, "전체 공격 횟수 소진", petSkillData);
        withGuildTerritoryDataMode(guildData, function () {
            saveJsonFile(guildData, guildPath);
            saveJsonFile(data, filePath);
        });
        return { ok: true, ended: true, actionKey: actionKey };
    }

    advanceGuildTerritoryTurn(data, guildData);
    var nextTurnLine = buildGuildTerritoryCurrentTurnLine(data, petData, guildData);
    if (nextTurnLine) resultMessage = nextTurnLine + "\n━━━━━━━━━━━━\n" + resultMessage;
    castleMsg(resultMessage, replier, isGroupChat);
    if (riftMessage) castleMsg(riftMessage, replier, isGroupChat);
    saveJsonFile(guildData, guildPath);
    saveJsonFile(data, filePath);
    var nextAutoTerritoryNo = startGuildTerritoryTurnTimer(data, petData, guildData, petSkillData, replier, isGroupChat);
    var turnMsgs = buildGuildTerritoryTurnMessage(data, petData, guildData, nextAutoTerritoryNo);
    turnMsgs.forEach(function (turnMessage) {
        castleMsg(turnMessage, replier, isGroupChat);
    });
    return { ok: true, ended: false, actionKey: actionKey };
}

// 영지전 종료 처리
function finishGuildTerritoryWar(data, guildData, reason, petSkillData) {
    return withGuildTerritoryDataMode(guildData, function () {
        var war = ensureGuildTerritoryWar(data, guildData);
        if (GLOBAL_CONFIG.guildWar.legacyPaused) {
            war.active = false; war.pendingStart = false; war.startReady = false; war.turnToken = null;
            guildData.castleSiegeFlag = false;
            clearGuildTerritoryWarTimer(); clearGuildTerritoryPendingStartTimer(); clearGuildTerritoryOpeningTimer();
            return;
        }
        if (!war.active && war.finishProcessed) return;
        var finishedReadyGuildIds = Object.keys(war.readyGuilds || {}); // 종료 회차에 참가한 길드 ID
        clearGuildTerritoryWarTimer();
        clearGuildTerritoryPendingStartTimer();
        clearGuildTerritoryOpeningTimer();
        war.active = false;
        war.endedAt = formatDateTime(new Date());
        war.turnToken = null;
        war.startReady = false;
        war.openingToken = null;
        war.castleSiegeFlag = false;
        clearGuildTerritoryPendingStartState(war);
        if (!getCurrentContext().isDev) {
            guildData.castleSiegeFlag = false;
        }

        var list = getGuildTerritoryList();
        var rewardRowsByGuild = {};
        for (var i = 0; i < list.length; i++) {
            var territory = list[i];
            if (territory.rewardType === "castle") continue;
            var ter = war.territories[String(territory.no)];
            var g = getGuildByIdSafe(guildData, ter ? ter.ownerGuildId : null);
            if (!g) continue;
            addGuildWarehouseReward(g, territory.rewardType, territory.rewardAmount);
            if (territory.boosterReward === false) continue;
            if (!rewardRowsByGuild[ter.ownerGuildId]) rewardRowsByGuild[ter.ownerGuildId] = [];
            rewardRowsByGuild[ter.ownerGuildId].push({ guild: g, territory: territory, baseAmount: territory.rewardAmount });
        }

        var boosterLogs = [];
        for (var gid in rewardRowsByGuild) {
            if (!rewardRowsByGuild.hasOwnProperty(gid)) continue;
            var rows = rewardRowsByGuild[gid];
            if (!rows || rows.length === 0) continue;
            var guild = rows[0].guild;
            var availableBooster = ensureGuildTerritoryBoosterCount(guild);
            if (availableBooster <= 0) continue;

            var boosterResult = calculateGuildTerritoryBoosterBonuses(rows, availableBooster);
            for (var bonusIdx = 0; bonusIdx < rows.length; bonusIdx++) {
                var bonusAmount = boosterResult.bonuses[bonusIdx] || 0;
                if (bonusAmount <= 0) continue;
                addGuildWarehouseReward(guild, rows[bonusIdx].territory.rewardType, bonusAmount);
                boosterLogs.push(formatGuildDisplay(guild) + " " + rows[bonusIdx].territory.name + " " + numberWithCommas(rows[bonusIdx].baseAmount) + "+" + numberWithCommas(bonusAmount) + "🔮");
            }

            guild.guildTerritoryBooster = Math.max(0, availableBooster - boosterResult.used);
        }

        var scoreLogs = applyGuildTerritoryScores(guildData, list, war);
        var autoReadyResult = prepareNextGuildTerritoryWarAutomatically(data, guildData, petSkillData, war, finishedReadyGuildIds);

        var out = "[🎖️길드 영지전 종료🎖️]\n";
        if (reason) out += reason + "\n";
        out += "최종 영지전 결과✌\n\n";
        for (var j = 0; j < list.length; j++) {
            var t = war.territories[String(list[j].no)];
            var owner = getGuildByIdSafe(guildData, t ? t.ownerGuildId : null);
            out += "[" + list[j].no + "] " + list[j].name + ": " + (owner ? formatGuildDisplay(owner) : "점령 길드 없음") + "\n";
        }
        if (autoReadyResult.messages.length > 0) out += "\n" + autoReadyResult.messages.join("\n\n") + "\n";
        out += "\n💥영지종료보상 및 영지순위 보상 확인하기..";
        if (typeof allsee !== "undefined") out += allsee;
        else out += "\n";
        if (boosterLogs.length > 0) {
            out += "\n[길드영지 종료 보상🏅+부스터🔮 적용]\n" + boosterLogs.join("\n") + "\n";
        }
        if (scoreLogs.length > 0) {
            out += "\n[🏅길드영지 포인트 획득🏅+ 부스터🔮 적용]\n" + scoreLogs.join("\n") + "\n";
            out += "\n획득한 점수는 길드영지순위에\n자동으로 누적됩니다.\n";
        }
        out += "\n영지순위 확인: /길드영지순위\n영지순위 보상: /영지순위보상\n영지점령 보상: /영지종료보상";
        war.finishProcessed = true;
        war.readyGuilds = autoReadyResult.readyGuilds;
        war.riftCommandUses = {};
        noticeMsg(out);
    });
}
// 한국시간 날짜를 출석·채팅 경험치의 일일 판정 키로 반환하는 함수
function getAttendanceKstDateKey() {
    var kst = new Date(Date.now() + GLOBAL_CONFIG.attendance.kstOffsetMs);
    var month = kst.getUTCMonth() + 1;
    var day = kst.getUTCDate();
    return String(kst.getUTCFullYear()) + (month < 10 ? "0" : "") + month + (day < 10 ? "0" : "") + day;
}

// 회원이 마지막 /리셋 이후 출석했는지 확인하는 함수
function hasAttendedToday(data, user) {
    var member = data && data.member ? data.member[user] : null;
    return !!member && (parseInt(member.today, 10) || 0) > 0;
}

// 출석 알림 등록 명령의 기존 이름 또는 단축 이름을 반환하는 함수
function getAttendanceNoticeCommandPrefix(msg) {
    if (msg === "/출석알림" || /^\/출석알림\s+[\s\S]*$/.test(msg)) return "/출석알림";
    if (msg === "/출첵알림" || /^\/출첵알림\s+[\s\S]*$/.test(msg)) return "/출첵알림";
    return "";
}

// 대상 회원의 오늘 채팅 경험치 조회 명령에서 닉네임을 추출하는 함수
function getChatExperienceQueryTarget(msg) {
    if (msg === "/채팅경험치확인") return "";
    var match = String(msg || "").match(/^\/채팅경험치확인\s+([^\r\n]+)$/);
    return match ? match[1].trim() : null;
}

// 관리자용 채팅 경험치 조회 명령의 권한과 대상을 확인해 결과를 응답하는 함수
function handleDailyChatExperienceQuery(data, msg, sender, replier) {
    var target = getChatExperienceQueryTarget(msg);
    if (target === null) return false;
    if (!(isAdminIdentity(sender) || isMasterIdentity(sender))) {
        replier.reply("❌ 관리자 또는 MASTER만 사용할 수 있습니다.");
        return true;
    }
    if (!target) {
        replier.reply("사용법: /채팅경험치확인 대상닉네임");
        return true;
    }
    if (!data.member || !data.member[target]) {
        replier.reply("❌ 대상 계정을 찾을 수 없습니다: " + target);
        return true;
    }
    replier.reply(buildDailyChatExperienceStatusMessage(data, target));
    return true;
}

// 출석 전에도 이용할 수 있는 안내·운영 명령인지 확인하는 함수
function isAttendanceFreeCommand(msg, sender) {
    if (sender === "오픈채팅봇") return true;
    if (msg === "ㅊㅊ" || msg === "호월 봇 이용약관") return true;
    if (msg === "/도움말" || msg === "/명령어" || msg === "/공지" || msg === "/소식" || msg === "/문의" || msg === "/호이봇버전" || msg === "/모험시작") return true;
    if (getAttendanceNoticeCommandPrefix(msg) && isMasterIdentity(sender)) return true;
    if (isGlobalOperatorCommandAllowed(sender, msg)) return true;
    return (isAdmin(sender) || isMaster(sender)) && msg !== "/호여" && !/^\/호여\s+\d+$/.test(msg) && isMatzangOperatorCommandMessage(msg);
}

// 슬래시 명령과 기존 비슬래시 게임 트리거를 출석 제한 대상으로 확인하는 함수
function isAttendanceGameCommand(msg) {
    if (msg.charAt(0) === "/") return true;
    if (msg === "ㅊㄹ") return true;
    var plainCommands = ["ㅊㅇ", "ㅁㅁ", "ㅈㅈ", "ㅅㅅ", "ㅈㅈㅈ", "ㅍㅍㅍ", "ㅁㅁㅁ", "ㅇㅇㅇ", "ㄹㄹㄹ", "ㅇㅋㅋ", "ㅎㅎㅎ", "ㄴㄴㄴ", "ㄱㄱㄱ", "ㅎㄹ", "쫄아뜸", "승급할거임", "쫄았음", "진행시켜", "생각해볼게", "장착할래", "입양할래", "집뚝딱", "생각해본다", "등록한다", "등록안한다", "홈뱃지취소", "홈뱃지교체", "홈뱃지해제확정", "등록", "ㄴㄴ", "가입한다", "영지종료보상", "해방열쇠조합", "자유시장거래", "자유시장거래취소", "이쁘다"];
    return plainCommands.indexOf(msg) !== -1;
}

// 출석 전 게임 명령에 보낼 고정 안내를 만드는 함수
function buildAttendanceRequiredMessage(data, petData, guildData, user) {
    return getHoiPassPremiumHeader(data, user) + "[" + checkRank(data, petData, guildData, user) + "]님, 출석체크부터 해주세요! ✅\n" +
        "━━━━━━━━━━━━\n오늘의 출석체크가 아직 완료되지 않았습니다.\n출석체크를 완료하면 게임을 이용할 수 있어요.\n\n👉 채팅창에 ㅊㅊ을 입력해주세요.";
}

// 실제 출석 보상 결과와 운영 알림을 한 메시지로 조합하는 함수
function buildAttendanceCompleteMessage(data, petData, guildData, user, result) {
    var exp = result.experienceResult;
    var booster = exp.boosterResult;
    var boosterState = booster.usedBooster > 0 ? (booster.usedBooster < booster.requiredBooster ? "일부 적용" : "적용") : "미적용";
    var lines = [];
    var authorityBadge = getAuthorityTitleBadge(data, user);
    if (authorityBadge) lines.push(authorityBadge);
    if (isHoiPassPremiumActive(data, user)) lines.push("[👑호이패스 프리미엄👑]");
    lines.push("[" + checkRank(data, petData, guildData, user) + "]님, 출석체크 완료! ✅", "이 게임물은 게임물관리위원회로부터", "전체이용가 등급을 받았습니다.", GLOBAL_CONFIG.attendance.resultLink, "━━━━━━━━━━━━", "💰 총 획득 포인트 🅟" + numberWithCommas(result.totalPointReward), "📊 총 획득 경험치: +" + numberWithCommas(exp.total) + "exp", "├ 📘 기본: +" + numberWithCommas(exp.base) + "exp");
    if (exp.bonus > 0) lines.push("├ 🎟️ 티어 보너스: +" + numberWithCommas(exp.bonus) + "exp");
    if (booster.extraExperience > 0) lines.push("└ ✨ 가호 추가: +" + numberWithCommas(booster.extraExperience) + "exp");
    lines.push("✨ 호월신의 가호 " + boosterState + (booster.usedBooster > 0 ? " (" + numberWithCommas(booster.usedBooster) + "개 사용)" : ""));
    if (result.dicePoint > 0) lines.push("🎲 출첵보너스 " + result.multiplier + "배 당첨: 🅟" + numberWithCommas(result.dicePoint));
    if (result.rankBonusPoint > 0) lines.push("🎊 추가 보너스: 🅟" + numberWithCommas(result.rankBonusPoint));
    if (data.attendanceNotice) lines.push("━━━━━━━━━━━━", "(알림)", String(data.attendanceNotice));
    if (result.openRunRewardGranted) lines.push("", "[" + checkRank(data, petData, guildData, user) + "] : 오늘도 1등 출석 성공!", "오픈런의 기세로 펫먹이🍼 1,000개를 획득합니다!", "[" + checkRank(data, petData, guildData, user) + "] : 누구보다 빠르게, 남들과는 다르게!");
    if (result.boosterDepletionMessage) lines.push("", result.boosterDepletionMessage);
    if (result.levelUps.length > 0) lines.push("", buildAdventureLevelUpMessage(data, petData, guildData, user, result.levelUps));
    return lines.join("\n");
}

// 수동·자동 출석이 함께 사용하는 출석 판정과 보상 처리 함수
function processAttendanceForUser(data, petData, petSkillData, guildData, user) {
    if (!data || !data.member || !data.member[user]) return { ok: false, message: "❌ 존재하지 않거나 비정상적인 회원 데이터입니다." };
    if (!(data.attend_list instanceof Array)) data.attend_list = [];
    var member = data.member[user];
    var todayText = getAttendanceKstDateKey();
    var alreadyAttended = (parseInt(member.today, 10) || 0) > 0;
    var rankText = checkRank(data, petData, guildData, user);
    if (alreadyAttended) return { ok: false, already: true, message: "[" + rankText + "] 님 이미 출첵 하셨습니다." };

    if (!member.bag || typeof member.bag !== "object") member.bag = {};
    data.attend_list.push(user);
    member.cnt = (parseInt(member.cnt, 10) || 0) + 1;
    member.today = (parseInt(member.today, 10) || 0) + 1;
    member.recent = todayText;
    member.point = (Number(member.point) || 0) + GLOBAL_CONFIG.attendance.bonusPoint;
    var attendanceExpResult = addMemberExperienceWithTierBonus(data, user, GLOBAL_CONFIG.attendance.bonusExp);
    var attendanceBoosterResult = attendanceExpResult.boosterResult; // 출석 경험치 가호 적용·소모 결과

    var messages = [];
    var attendanceRewardMessage = "[" + rankText + "] 님 출첵👏\n\n💰포인트 🅟" + GLOBAL_CONFIG.attendance.bonusPoint + " 획득\n" + buildBattleExperienceRewardMessage(attendanceExpResult);
    messages.push(attendanceRewardMessage);
    if (attendanceExpResult.levelUps.length > 0) messages.push(buildAdventureLevelUpMessage(data, petData, guildData, user, attendanceExpResult.levelUps));
    var attendanceBoosterDepletionMessage = buildAdventureBoosterDepletionMessage(data, petData, guildData, user, attendanceBoosterResult);
    if (attendanceBoosterDepletionMessage) messages.push(attendanceBoosterDepletionMessage);
    var multiplier = rollAndCalculateMultiplier(); // 출석 응모 주사위 배율
    var dicePoint = parseInt((GLOBAL_CONFIG.attendance.bonusPoint * multiplier).toFixed(0), 10); // 주사위 추가 포인트
    member.point += dicePoint;
    messages.push("[" + rankText + "]님의 출첵 응모가 굴러갑니다!\n" + multiplier + "배 당첨!💸\n🅟" + numberWithCommas(dicePoint) + " 추가적립 되었습니다.\nhttps://ibb.co/jkbgrzHt\n이 게임물은 게임물관리위원회로부터 전체이용가 등급을 받았습니다.");

    var rankBonus = RankBonus(data, user) || {}; // 랭크별 출석 추가 보너스
    var rankBonusMultiplier = Number(rankBonus.BonusM) || 0; // 유효한 랭크 보너스 배율
    var rankBonusPoint = parseInt((GLOBAL_CONFIG.attendance.bonusPoint * rankBonusMultiplier).toFixed(0), 10); // 랭크 추가 포인트
    if (rankBonusMultiplier !== 0) {
        member.point += rankBonusPoint;
        messages.push(String(rankBonus.Bonusmsg || "") + "🎊\n🅟" + numberWithCommas(rankBonusPoint) + " 추가적립 되었습니다.");
    }

    var openRunRewardGranted = false; // 출석 1등 오픈런 보상 지급 여부
    if (data.attend_list[0] === user && hasPetSkill(petSkillData, user, "오픈런") && !member.openRunRewardClaimed) {
        member.bag["펫먹이🍼"] = (member.bag["펫먹이🍼"] || 0) + 1000;
        member.openRunRewardClaimed = true;
        openRunRewardGranted = true;
        messages.push("[" + rankText + "] : 오늘도 1등 출석 성공!");
        messages.push("오픈런의 기세로 펫먹이🍼 1,000개를 획득합니다!");
        messages.push("[" + rankText + "] : 누구보다 빠르게, 남들과는 다르게!");
    }

    var totalPointReward = GLOBAL_CONFIG.attendance.bonusPoint + dicePoint + rankBonusPoint; // 이번 출석의 총 포인트 보상
    var attendanceNoticeMessage = "[" + rankText + "] 님 자동출첵이 완료되어 보상을 받았습니다.\n💰포인트: 🅟" + numberWithCommas(totalPointReward) + "\n" + buildBattleExperienceRewardMessage(attendanceExpResult);
    if (openRunRewardGranted) attendanceNoticeMessage += "\n펫먹이🍼 1,000개 추가 획득";
    if (attendanceBoosterDepletionMessage) attendanceNoticeMessage += "\n\n" + attendanceBoosterDepletionMessage;
    if (attendanceExpResult.levelUps.length > 0) attendanceNoticeMessage += "\n\n" + buildAdventureLevelUpMessage(data, petData, guildData, user, attendanceExpResult.levelUps);
    return {
        ok: true,
        messages: messages,
        totalPointReward: totalPointReward,
        experienceResult: attendanceExpResult,
        dicePoint: dicePoint,
        rankBonusPoint: rankBonusPoint,
        rankBonusMessage: rankBonusMultiplier !== 0 ? String(rankBonus.Bonusmsg || "") : "",
        multiplier: multiplier,
        boosterDepletionMessage: attendanceBoosterDepletionMessage,
        expReward: GLOBAL_CONFIG.attendance.bonusExp,
        boosterUsed: attendanceBoosterResult.usedBooster,
        boosterExperience: attendanceBoosterResult.extraExperience,
        levelUps: attendanceExpResult.levelUps,
        openRunRewardGranted: openRunRewardGranted,
        noticeMessage: attendanceNoticeMessage
    };
}

// 출석 /리셋 함수
function resetAttendance(petData, data, replier) {
    var resetDateKey = getAttendanceKstDateKey(); // 리셋 시작 시점의 한국시간 날짜
    for (let user in data.member) {
        var chatDaily = data.member[user].chatExperienceDaily;
        if (chatDaily && typeof chatDaily.date === "string" && chatDaily.date.length === 8 && /^\d{8}$/.test(chatDaily.date) && chatDaily.date < resetDateKey) {
            var chatYear = Number(chatDaily.date.substring(0, 4)), chatMonth = Number(chatDaily.date.substring(4, 6)), chatDay = Number(chatDaily.date.substring(6, 8));
            var chatDate = new Date(Date.UTC(chatYear, chatMonth - 1, chatDay)); // 형식만 맞는 잘못된 날짜는 보존
            if (chatDate.getUTCFullYear() === chatYear && chatDate.getUTCMonth() === chatMonth - 1 && chatDate.getUTCDate() === chatDay) delete data.member[user].chatExperienceDaily;
        }
        data.member[user].today = 0; // /리셋마다 모든 회원의 새 출석 회차 시작
        if (petData[user]) {
            petData[user].petraid = 0;
            petData[user].raidItemCount = 0;
            if (!petData[user].miniPetBattle) {
                petData[user].miniPetBattle = {
                    win: 0,
                    lose: 0,
                    count: 0
                };
            }
            petData[user].miniPetBattle.count = 0; // 미니펫 전투 횟수 초기화
        }
        if (data.member[user].noticeItemCount !== undefined) {
            delete data.member[user].noticeItemCount;
        }
        if (data.member[user].noticeYahoCount !== undefined) {
            delete data.member[user].noticeYahoCount;
        }
        if (data.member[user].noticePremiumCount !== undefined) {
            delete data.member[user].noticePremiumCount;
        }
        if (data.member[user].carrotBuyCount !== undefined) {
            delete data.member[user].carrotBuyCount;
        }
        if (data.member[user].diamondBoxBuyCount !== undefined) {
            delete data.member[user].diamondBoxBuyCount;
        }
        if (data.member[user].legendaryPickpocket !== undefined) {
            delete data.member[user].legendaryPickpocket;
        }
        if (data.member[user].diamondTycoon !== undefined) {
            delete data.member[user].diamondTycoon;
        }
        if (data.member[user].worldNewsLotteryPlayed !== undefined) {
            delete data.member[user].worldNewsLotteryPlayed;
        }
        data.member[user].battle.ticket = 0;
        data.member[user].battle.count = 0;
        for (var counterIndex = 0; counterIndex < GLOBAL_CONFIG.dataCleanup.zeroDailyCounterKeys.length; counterIndex++) delete data.member[user][GLOBAL_CONFIG.dataCleanup.zeroDailyCounterKeys[counterIndex]];
        if (data.member[user].exploreCnt !== undefined) {
            delete data.member[user].exploreCnt;
        }

        // 길드 관련 "하루 1회 구매 제한" 초기화
        if (data.member[user].gMedalBuyCnt !== undefined) {
            delete data.member[user].gMedalBuyCnt;
        }
        if (data.member[user].gContribCnt !== undefined) {
            delete data.member[user].gContribCnt;
        }
        if (data.member[user].gBoosterContribCnt !== undefined) {
            delete data.member[user].gBoosterContribCnt;
        }
        if (data.member[user].dailyQuestCnt !== undefined) {
            delete data.member[user].dailyQuestCnt;
        }
        if (data.member[user].passDailyQuestCnt !== undefined) {
            delete data.member[user].passDailyQuestCnt;
        }
        if (data.member[user].premiumDailyQuestCnt !== undefined) {
            delete data.member[user].premiumDailyQuestCnt;
        }
        if (data.member[user][GLOBAL_CONFIG.petSkill.prayer.dailyFlagKey] !== undefined) {
            delete data.member[user][GLOBAL_CONFIG.petSkill.prayer.dailyFlagKey];
        }
        if (data.member[user].openRunRewardClaimed !== undefined) {
            delete data.member[user].openRunRewardClaimed;
        }
        if (data.member[user].coincount) {
            //슬롯코인
            delete data.member[user].coincount;
        }
        if (data.member[user].guildJoinTicketBuyCount) {
            // 길드가입권🍭 일일 구매 횟수 초기화
            delete data.member[user].guildJoinTicketBuyCount;
        }
        if (data.member[user].guildLeaveTicketBuyCount) {
            // 길드탈퇴권🚪 일일 구매 횟수 초기화
            delete data.member[user].guildLeaveTicketBuyCount;
        }

        if (data.member[user].guildDistributeItemBuyCount) {
            // 길드자원분배🫂 일일 구매 횟수 초기화
            delete data.member[user].guildDistributeItemBuyCount;
        }

        if (data.member[user].guildContributeMedalBuyCount) {
            // 길드공헌훈장🌟 일일 구매 횟수 초기화
            delete data.member[user].guildContributeMedalBuyCount;
        }
        if (data.member[user].guildMarkChangeBuyCount) {
            // 길드마크변경권🔖 일일 구매 횟수 초기화
            delete data.member[user].guildMarkChangeBuyCount;
        }

        if (data.member[user].bag["자동대깨호😝(1일)"]) {
            delete data.member[user].bag["자동대깨호😝(1일)"];
        }
        if (data.member[user].bag["자동대깨봇🤖(1일)"]) {
            delete data.member[user].bag["자동대깨봇🤖(1일)"];
        }
        if (data.member[user].bag["자동배팅😝🤖(1일)"]) {
            delete data.member[user].bag["자동배팅😝🤖(1일)"];
        }
    }
    // 여기서 data.attend_list에 있는 유저가 data.member에 있는지 확인
    for (let user of data.attend_list) {
        if (data.member.hasOwnProperty(user)) {
            data.member[user].today = 0; // 오늘 출석 초기화
        }
    }
    data.attend_list = []; // 오늘 출석 목록 초기화
    replier.reply("출첵시작! 리셋 완료");
    const rooms = [room1, room2, room3, testRoom, room5, room6, room7, room10, room11, room12, room15];
    const checkinMessage = "출석체크가 시작 되었습니다!\nㅊㅊ 가즈아!!";
    rooms.forEach((room) => Api.replyRoom(room, checkinMessage));
}

// 캐슬대전 랜덤점수
function getRandomScore(isWinFlag, castleBattleData) {
    let min = null;
    let max = null;
    if (isWinFlag) {
        max = castleBattleData.score.win.max || null;
        min = castleBattleData.score.win.min || null;
    } else {
        max = castleBattleData.score.lose.max || null;
        min = castleBattleData.score.lose.min || null;
    }
    if (min !== null && max !== null) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    } else if (min !== null) {
        return min;
    } else if (max !== null) {
        return max;
    }
    return 0;
}
// 캐슬대전 랜덤점수 new-쌍팔
function getRandomScore2(isWinFlag, position, matchPoint, castleBattleData) {
    let min = null;
    let max = null;
    if (isWinFlag) {
        if (matchPoint == 3) {
            if (position) {
                max = 20;
                min = 17;
            } else {
                max = 9;
                min = 7;
            }
        } else if (matchPoint == 2) {
            max = 13;
            min = 11;
        } else if (matchPoint == 1) {
            if (position) {
                max = 9;
                min = 7;
            } else {
                max = 20;
                min = 17;
            }
        }
    } else {
        max = 5;
        min = 4;
    }
    if (min !== null && max !== null) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    } else if (min !== null) {
        return min;
    } else if (max !== null) {
        return max;
    }
    return 0;
}
// 이름입력 시 등수 리턴
function getCastleBattleRank(memberName, data) {
    let sortedMembers = sortCastleBattle(data);
    for (let i = 0; i < sortedMembers.length; i++) {
        if (sortedMembers[i].name === memberName) {
            return i + 1;
        }
    }
    return null;
}
// 점수 별 등급 이름+이모지 리턴
function getCastleBattleRankEmoji(score, castleBattleData) {
    let ranks = castleBattleData.rank;
    for (let rankKey in ranks) {
        if (score >= ranks[rankKey].scoreRequirement) {
            return ranks[rankKey].name;
        }
    }
}
// 새로운 점수 별 등급 이름+이모지 리턴+티어조정 상팔
function getCastleBattleRankEmoji2(score, castleBattleData) {
    let ranks = castleBattleData.rank;
    let rankName;
    for (let rankKey in ranks) {
        if (score >= ranks[rankKey].scoreRequirement) {
            rankName = ranks[rankKey].name;
        }
    }
    return rankName;
}
// 캐슬대전 전적 필드를 숫자 기본값으로 보정하는 함수
function ensureCastleBattleRecord(data, userName) {
    if (!data || !data.member || !data.member[userName]) return null;
    if (!data.member[userName].battle) data.member[userName].battle = {};
    var battle = data.member[userName].battle;
    battle.win = parseInt(battle.win, 10) || 0;
    battle.lose = parseInt(battle.lose, 10) || 0;
    battle.score = parseInt(battle.score, 10) || 0;
    battle.ticket = parseInt(battle.ticket, 10) || 0;
    battle.count = parseInt(battle.count, 10) || 0;
    battle.tierPoint = parseInt(battle.tierPoint, 10) || 1;
    return battle;
}
// 전투후 스코어로 티어 조정
function setCastleBattleTier(atkScore, defScore, castleBattleData) {
    let ranks = castleBattleData.rank;
    let atkTier;
    let defTier;
    for (let rankKey in ranks) {
        if (atkScore >= ranks[rankKey].scoreRequirement) {
            atkTier = ranks[rankKey].tierPoint;
        }
        if (defScore >= ranks[rankKey].scoreRequirement) {
            defTier = ranks[rankKey].tierPoint;
        }
    }
    return [atkTier, defTier];
}
// 사용자의 점수와 최근 전투 날짜를 기준으로 정렬
function sortCastleBattle(data) {
    let memberData = data.member;
    let sortedMembers = Object.keys(memberData)
        .filter((memberName) => memberData[memberName].battle.lastBattleDateTime)
        .map((memberName) => ({
            name: memberName,
            score: memberData[memberName].battle.score,
            lastBattleDateTime: memberData[memberName].battle.lastBattleDateTime
        }));
    sortedMembers.sort((a, b) => {
        // 점수(score)가 높은 순서로 정렬, 동일한 경우 최근 전투 날짜(lastBattleDateTime)가 더 최근인 순서로 정렬
        if (a.score !== b.score) {
            return b.score - a.score;
        } else {
            return new Date(b.lastBattleDateTime) - new Date(a.lastBattleDateTime);
        }
    });
    return sortedMembers;
}
