/**
 * 301강 이상에서도 치명타 확률은 "동일"해야 하므로
 * 치확 계산에 사용하는 강화레벨은 300으로 캡
 */
function getCappedUpgradeForCrit(upgradeLevel) {
    var u = parseInt(upgradeLevel || 0, 10);
    if (u > 300) return 300;
    if (u < 0) return 0;
    return u;
}

/**
 * 펫의 강화 레벨에 따른 치명타 확률(%) 계산 함수
 * @param {number} upgradeLevel - 펫의 현재 강화 레벨
 * @returns {string} - 계산된 치명타 확률 (소수점 2자리, % 기호 제외)
 */
function getCritChance(upgradeLevel) {
    upgradeLevel = getCappedUpgradeForCrit(upgradeLevel);

    var critChance = 0;
    if (upgradeLevel <= 100) {
        critChance = upgradeLevel * 0.5;
    } else if (upgradeLevel <= 200) {
        critChance = 100 * 0.5 + (upgradeLevel - 100) * 0.3;
    } else {
        // <= 300
        critChance = 100 * 0.5 + 100 * 0.3 + (upgradeLevel - 200) * 0.1;
    }
    return critChance.toFixed(2);
}

/**
 * 치명타 확률을 0~1 범위(rate)로 반환
 * - 301강 이상은 300강 확률과 동일(캡)
 * @param {number} upgradeLevel
 * @returns {number} - 0.0 ~ 1.0
 */
function calculateCritChance(upgradeLevel) {
    var capped = getCappedUpgradeForCrit(upgradeLevel);
    var pctStr = getCritChance(capped); // "15.00" 같은 문자열
    var pct = parseFloat(pctStr);
    if (isNaN(pct)) pct = 0;

    var rate = pct / 100;
    if (rate > 1) rate = 1;
    if (rate < 0) rate = 0;
    return rate;
}

/**
 * 301강부터 치명타 배수(계수) 증가
 * 0~300강: 1.70 고정
 * 301강: 1.71, 302강: 1.72 ... (0.01씩 증가)
 * @param {number} upgradeLevel
 * @returns {number} - 배수(소수 2자리)
 */
function getCritMultiplier(upgradeLevel) {
    var u = parseInt(upgradeLevel || 0, 10);
    if (u <= 300) return BASE_CRIT_DAMAGE_MULTIPLIER; // 1.7

    var mul = BASE_CRIT_DAMAGE_MULTIPLIER + (u - 300) * 0.01;
    return parseFloat(mul.toFixed(2));
}

/**
 * 크리티컬 데미지 계산 함수
 * @param {object} petObj - 유저 펫 정보
 * @param {number} damage - 기본 데미지
 * @param {object} result - 선택 항목. 실제 치명타 판정값을 함께 받을 객체
 * @returns {number} - 크리티컬이 적용된 최종 데미지
 */
function calculateCriticalDamage(petObj, damage, effectiveUpgradeLevel, result) {
    var upgradeLevel = typeof effectiveUpgradeLevel === "number" ? effectiveUpgradeLevel : ((petObj && petObj.upgrade) || 0);
    var critChance = calculateCritChance(upgradeLevel);
    var isCritical = Math.random() < critChance;
    if (result) result.critical = isCritical; // 선택한 호출에서 실제 치명타 판정값을 함께 사용

    if (isCritical) {
        return Math.round(damage * getCritMultiplier(upgradeLevel)); //  301+ 배수 반영
    }
    return damage;
}

/**
 * 크리티컬 데미지 계산 함수
 * @param {object} pet - 펫 정보
 * @param {number} damage - 기본 데미지
 * @returns {number} - 크리티컬이 적용된 최종 데미지
 */
function calculateCriticalDamageWithPet(pet, damage) {
    var upgradeLevel = (pet && pet.upgrade) || 0;
    var critChance = calculateCritChance(upgradeLevel);
    var isCritical = Math.random() < critChance;

    if (isCritical) {
        return Math.round(damage * getCritMultiplier(upgradeLevel)); //  301+ 배수 반영
    }
    return damage;
}

/**
 * 모든 방 공지 함수
 * @param {String} msg - 공지 메시지
 */
function noticeMsg(msg, targetRooms) {
    msg = formatNicknameRankMessage(msg);
    var ctx = getCurrentContext();
    var rooms = targetRooms || getNoticeTargetRooms(ctx);
    var successful = true;
    for (var i = 0; i < rooms.length; i++) if (Api.replyRoom(rooms[i], ctx.isDev ? ctx.header(msg) : msg) === false) successful = false;
    return successful;
}

// 대승급 공지를 원래 대화방과 중복되지 않게 전체 방에 전송하는 함수
function noticeMsgExceptRoom(msg, originRoom) {
    msg = formatNicknameRankMessage(msg);
    var ctx = getCurrentContext();
    if (ctx.isDev) {
        var devRoom = isDebuggerFlag ? testRoom : room8;
        if (devRoom !== originRoom) Api.replyRoom(devRoom, ctx.header(msg));
        return;
    }
    var rooms = [room1, room2, room3, room5, room6, room7, room8, room10, room11, room12, room13, room15, room90];
    for (var i = 0; i < rooms.length; i++) {
        if (rooms[i] !== originRoom) Api.replyRoom(rooms[i], msg);
    }
}
function debuggerToggle() {
    if (isDebuggerFlag) {
        isDebuggerFlag = false;
    } else {
        isDebuggerFlag = true;
    }
    return isDebuggerFlag;
}
/**
 * 일부 방 함수
 * @param {String} msg - 공지 메시지
 */
function castleMsg(msg, replier, isGroupChat) {
    if (!isGroupChat) {
        replier.reply(msg);
        return;
    }

    var ctx = getCurrentContext();
    if (ctx.isDev) {
        Api.replyRoom(isDebuggerFlag ? testRoom : room8, ctx.header(msg));
        return;
    }
    if (isDebuggerFlag) {
        Api.replyRoom(testRoom, msg);
    } else {
        Api.replyRoom(room8, msg);
        // Api.replyRoom(room5, msg);
        // Api.replyRoom(room6, msg);
    }
}
/**
 * 세율을 적용하고 성주에게 포인트를 추가하는 함수
 * @param {number} point - 세율이 적용될 포인트
 * @returns {number} - 세금이 적용된 후의 포인트
 */
function applyTax(point, data, guildData, taxAmountOverride) {
    // 세율과 성주 정보가 있는지 확인
    if (data.HoiCastle && data.HoiCastle.taxRate && data.HoiCastle.lord) {
        var taxRate = data.HoiCastle.taxRate; // 세율
        var lord = data.HoiCastle.lord; // 성주

        // 세금 계산
        var taxAmount = typeof taxAmountOverride === "number" ? Math.round(taxAmountOverride) : Math.round(point * (taxRate / 100));
        var taxedPoint = point + taxAmount;

        // 실제 길드자금으로 들어갈 금액
        var guildFundAmount = Math.round(taxAmount * 0.15); // 세금의 15%가 길드자금으로 들어감
        var foundationAmount = taxAmount - guildFundAmount; // 세금의 나머지 85%는 호이행복재단 장부에 적립

        // 성주의 길드 찾기
        var myGuildInfo = getMyGuildInfo(data, guildData, lord);

        if (myGuildInfo && !myGuildInfo.error && myGuildInfo.guild) {
            var g = myGuildInfo.guild;

            ensureGuildWarehouseObj(g);

            g.warehouse.fund += guildFundAmount;
        }

        // 호월킹덤 누적 수익
        if (typeof data.HoiCastle.earnings !== "number") {
            data.HoiCastle.earnings = 0;
        }
        data.HoiCastle.earnings += guildFundAmount;
        addHappyFoundationLedgerAmount(data, foundationAmount);

        // 세금이 적용된 금액 반환
        saveJsonFile(guildData, guildPath);
        return taxedPoint;
    } else {
        return point;
    }
}

function debuggerLog(msg) {
    if (isDebuggerFlag && msg) {
        if (msg) {
            if (typeof msg == "Object") {
                msg = JSON.stringify(msg);
            }
            Api.replyRoom(testRoom, msg);
        }
    }
}
// 펜던트 전환 중 기존 반지 강화석은 자동 변환하지 않고 보존
function normalizePendantTransitionItemName(itemName) {
    return itemName;
}

// 컬렉션 만능열쇠와 스킬 슬롯 확장권의 기존 이름·현재 이름 대응을 반환하는 함수
function getUniversalCollectionKeyBagMappings() {
    var config = GLOBAL_CONFIG.universalBox;
    return [
        { oldName: config.legacyPetSkillKeyItemName, newName: config.petSkillKeyItemName },
        { oldName: config.legacyMiniPetKeyItemName, newName: config.miniPetKeyItemName },
        { oldName: config.oldPetSkillKeyItemName, newName: config.petSkillKeyItemName },
        { oldName: config.oldMiniPetKeyItemName, newName: config.miniPetKeyItemName },
        { oldName: GLOBAL_CONFIG.petSkill.slots.legacyExpansionItemName, newName: GLOBAL_CONFIG.petSkill.slots.expansionItemName }
    ];
}

// 기존 컬렉션 만능열쇠·펫스킬 슬롯 확장권을 사용 명령어가 포함된 정식 이름으로 병합하는 함수
function normalizeUniversalCollectionKeyBagItems(bag) {
    if (!bag) return false;
    var mappings = getUniversalCollectionKeyBagMappings();
    var changed = false;
    for (var i = 0; i < mappings.length; i++) {
        var mapping = mappings[i];
        if (typeof bag[mapping.oldName] === "undefined") continue;
        var oldCount = parseInt(bag[mapping.oldName], 10) || 0;
        var newCount = parseInt(bag[mapping.newName], 10) || 0;
        if (oldCount > 0) bag[mapping.newName] = newCount + oldCount;
        delete bag[mapping.oldName];
        changed = true;
    }
    return changed;
}

// 아이템명 전환 훅
function normalizePendantTransitionBagItem(bag, itemName) {
    itemName = normalizePendantTransitionItemName(itemName);
    normalizeUniversalCollectionKeyBagItems(bag);
    if (itemName === GLOBAL_CONFIG.petSkill.slots.legacyExpansionItemName) return GLOBAL_CONFIG.petSkill.slots.expansionItemName;
    if (itemName === GLOBAL_CONFIG.universalBox.legacyPetSkillKeyItemName) return GLOBAL_CONFIG.universalBox.petSkillKeyItemName;
    if (itemName === GLOBAL_CONFIG.universalBox.legacyMiniPetKeyItemName) return GLOBAL_CONFIG.universalBox.miniPetKeyItemName;
    if (itemName === GLOBAL_CONFIG.universalBox.oldPetSkillKeyItemName) return GLOBAL_CONFIG.universalBox.petSkillKeyItemName;
    if (itemName === GLOBAL_CONFIG.universalBox.oldMiniPetKeyItemName) return GLOBAL_CONFIG.universalBox.miniPetKeyItemName;
    return itemName;
}

// 상자 오픈과 관련된 아이템들을 사용자의 가방에 추가하는 함수
function addItemToBag(bag, item, quantity) {
    if (item === GLOBAL_CONFIG.spiritRetirement.removedItem || item === GLOBAL_CONFIG.items.carrotName) return;
    item = normalizePendantTransitionBagItem(bag, item);
    if (bag[item]) {
        bag[item] += quantity;
    } else {
        bag[item] = quantity;
    }
}
// 상자를 사용하는 함수
function openBox(data, memberName, boxType) {
    if (data.member[memberName].bag[boxType] > 0) {
        data.member[memberName].bag[boxType] -= 1; // 상자 하나를 사용합니다
        if (data.member[memberName].bag[boxType] === 0) {
            delete data.member[memberName].bag[boxType]; // 상자가 0개면 삭제
        }
        if (boxType === "캐슬벨라상자🦄(/벨라오픈)") {
            addItemToBag(data.member[memberName].bag, "캐슬벨라유닛🦄(+250💕)", 1);
            addItemToBag(data.member[memberName].bag, "캐슬뽑기권♟", 30);
            addItemToBag(data.member[memberName].bag, "펫먹이상자📦(/상자오픈)", 20);
            addItemToBag(data.member[memberName].bag, "슬롯코인🪙", 100);
        }
        return true;
    }
    return false;
}
// 가방에 편지가 있는지 확인하는 함수 추가
function hasLetterInBag(data, memberName) {
    return data.member[memberName] && data.member[memberName].bag && data.member[memberName].bag["우표💌"];
}
// 우표를 사용하고 가방에서 하나 줄이거나 삭제하는 함수 추가
function useLetterInBag(data, memberName) {
    if (hasLetterInBag(data, memberName)) {
        let currentCount = data.member[memberName].bag["우표💌"];
        if (currentCount > 1) {
            data.member[memberName].bag["우표💌"] -= 1;
        } else {
            delete data.member[memberName].bag["우표💌"];
        }
        return true;
    }
    return false;
}

// 호이패스 프리미엄 자동화 설정 객체를 회원 데이터에 보장하는 함수
function ensureHoiPassPremiumAutomationSettings(member) {
    if (!member.premiumAutomation || typeof member.premiumAutomation !== "object" || member.premiumAutomation instanceof Array) {
        member.premiumAutomation = {};
    }
    if (typeof member.premiumAutomation.petMusouAutoReady !== "boolean") member.premiumAutomation.petMusouAutoReady = false;
    if (typeof member.premiumAutomation.autoAttendance !== "boolean") member.premiumAutomation.autoAttendance = false;
    return member.premiumAutomation;
}

// 프리미엄 자동화 처리 내역을 로드된 운영 로그에 제한 개수로 기록하는 함수
function appendPetMusouAutomationLog(data, log) {
    if (!Array.isArray(data.petMusouAutomationLogs)) data.petMusouAutomationLogs = [];
    data.petMusouAutomationLogs.push(log);
    var logMax = GLOBAL_CONFIG.petMusou.automationLogMax;
    if (data.petMusouAutomationLogs.length > logMax) data.petMusouAutomationLogs.splice(0, data.petMusouAutomationLogs.length - logMax);
}

// 프리미엄 자동 준비·자동 출석 설정 명령인지 확인하는 함수
function isHoiPassPremiumAutomationCommand(msg) {
    return msg === "/무쌍온" || msg === "/무쌍오프" || msg === "/출첵온" || msg === "/출첵오프";
}

// 프리미엄 자동 준비·자동 출석 ON/OFF 명령을 처리하는 함수
function processHoiPassPremiumAutomationCommand(msg, data, petData, petSkillData, guildData, sender) {
    var rankText = checkRank(data, petData, guildData, sender);
    if (!isHoiPassPremiumActive(data, sender)) {
        return {
            changed: false,
            message: "[" + rankText + "] 님 해당 기능은 호이패스 프리미엄 전용 기능입니다.\n호이패스 프리미엄 이용 상태를 확인해 주세요."
        };
    }
    var settings = ensureHoiPassPremiumAutomationSettings(data.member[sender]);
    var nowText = formatDateTime(new Date());
    if (msg === "/무쌍온") {
        if (settings.petMusouAutoReady === true) {
            return {
                changed: false,
                message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 이미 무쌍온 상태입니다."
            };
        }
        settings.petMusouAutoReady = true;
        var joinResult = joinPetMusou(data, petData, petSkillData, guildData, sender);
        var registeredNow = joinResult.ok === true; // 현재 준비 회차 즉시 자동 등록 여부
        appendPetMusouAutomationLog(data, {
            feature: "PET_MUSOU_AUTO_READY",
            action: "ON",
            user: sender,
            result: registeredNow ? "REGISTERED" : "PENDING",
            reason: registeredNow ? "" : String(joinResult.message || "").substring(0, 200),
            processedAt: nowText
        });
        return {
            changed: true,
            message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 펫무쌍 대회 자동 준비 기능을 켰습니다.\n" + (registeredNow ? "현재 준비 중인 펫무쌍 대회에 자동 등록되었습니다." : "다음 펫무쌍 준비 시 자동으로 참가 등록됩니다.")
        };
    }
    if (msg === "/무쌍오프") {
        settings.petMusouAutoReady = false;
        appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "OFF", user: sender, result: "SAVED", reason: "", processedAt: nowText });
        return {
            changed: true,
            message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 펫무쌍 대회 자동 준비 기능을 껐습니다.\n이미 등록된 현재 회차의 참가는 유지됩니다."
        };
    }
    if (msg === "/출첵온") {
        if (settings.autoAttendance === true) {
            return {
                changed: false,
                message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 이미 출첵온 상태입니다."
            };
        }
        settings.autoAttendance = true;
        appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "ON", user: sender, result: "SAVED", reason: "", processedAt: nowText });
        return {
            changed: true,
            message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 자동 출석체크 기능을 켰습니다.\n매일 00:01에 자동출첵 처리가 되며 전체공지로 안내합니다."
        };
    }
    settings.autoAttendance = false;
    appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "OFF", user: sender, result: "SAVED", reason: "", processedAt: nowText });
    return {
        changed: true,
        message: getHoiPassPremiumHeader(data, sender) + "[" + rankText + "] 님 자동 출석체크 기능을 껐습니다.\n이후 자동 출석 대상에서 제외됩니다."
    };
}

// 프리미엄 자동 준비 ON 이용자를 현재 펫무쌍 준비 회차에 일괄 등록하는 함수
function autoRegisterHoiPassPremiumPetMusouUsers(data, petData, petSkillData, guildData, excludedUser) {
    var result = { changed: false, registeredCount: 0, skippedCount: 0, failedCount: 0 };
    if (!data || !data.member) return result;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || user === excludedUser) continue;
        var member = data.member[user];
        if (!member || typeof member !== "object" || member instanceof Array) {
            result.changed = true;
            result.failedCount++;
            appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "AUTO_REGISTER", user: user, result: "FAILED", reason: "존재하지 않거나 비정상적인 회원 데이터", processedAt: formatDateTime(new Date()) });
            continue;
        }
        var settings = member.premiumAutomation;
        if (!settings || settings.petMusouAutoReady !== true) continue;
        try {
            if (!isHoiPassPremiumActive(data, user)) {
                result.changed = true;
                result.skippedCount++;
                appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "AUTO_REGISTER", user: user, result: "SKIPPED", reason: "호이패스 프리미엄 비활성 또는 만료", processedAt: formatDateTime(new Date()) });
                continue;
            }
            var joinResult = joinPetMusou(data, petData, petSkillData, guildData, user);
            if (joinResult.ok) {
                result.changed = true;
                result.registeredCount++;
                appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "AUTO_REGISTER", user: user, result: "REGISTERED", reason: "", processedAt: formatDateTime(new Date()) });
            } else {
                result.changed = true;
                result.skippedCount++;
                appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "AUTO_REGISTER", user: user, result: "SKIPPED", reason: String(joinResult.message || "").substring(0, 200), processedAt: formatDateTime(new Date()) });
            }
        } catch (autoReadyError) {
            result.changed = true;
            result.failedCount++;
            appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_AUTO_READY", action: "AUTO_REGISTER", user: user, result: "ERROR", reason: String(autoReadyError).substring(0, 200), processedAt: formatDateTime(new Date()) });
        }
    }
    return result;
}

// 출첵 초기화 뒤 프리미엄 자동 출석 대상자를 처리하는 함수
function runHoiPassPremiumAutoAttendance(data, petData, petSkillData, guildData, operator) {
    var changed = false;
    var successCount = 0;
    var alreadyCount = 0;
    var inactiveCount = 0;
    var failedCount = 0;
    var noticeMessages = [];
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || !data.member[user]) continue;
        var settings = data.member[user].premiumAutomation;
        if (!settings || settings.autoAttendance !== true) continue;
        if (!isHoiPassPremiumActive(data, user)) {
            inactiveCount++;
            continue;
        }
        try {
            var attendanceResult = processAttendanceForUser(data, petData, petSkillData, guildData, user);
            if (attendanceResult.ok) {
                changed = true;
                successCount++;
                noticeMessages.push(attendanceResult.noticeMessage);
                appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "RUN", user: user, result: "SUCCESS", reason: "", processedAt: formatDateTime(new Date()) });
            } else if (attendanceResult.already) {
                alreadyCount++;
            } else {
                failedCount++;
                changed = true;
                appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "RUN", user: user, result: "FAILED", reason: attendanceResult.message, processedAt: formatDateTime(new Date()) });
            }
        } catch (attendanceError) {
            failedCount++;
            changed = true;
            appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "RUN", user: user, result: "ERROR", reason: String(attendanceError), processedAt: formatDateTime(new Date()) });
        }
    }
    appendPetMusouAutomationLog(data, { feature: "AUTO_ATTENDANCE", action: "SUMMARY", operator: operator, result: failedCount > 0 ? "PARTIAL" : "SUCCESS", successCount: successCount, alreadyCount: alreadyCount, inactiveCount: inactiveCount, failedCount: failedCount, processedAt: formatDateTime(new Date()) });
    changed = true;
    var noticeMessage = "";
    if (noticeMessages.length > 0) {
        noticeMessage = "[👑호이패스 프리미엄 자동출첵 기능👑]\n[자동출첵 유저 리스트]" + allsee + "\n\n" + noticeMessages.join("\n\n") + "\n\n==========";
    }
    var lines = ["🐺 호이패스 프리미엄 자동출첵", "━━━━━━━━━━━━━━━", "출석 완료: " + successCount + "명", "당일 출석 완료로 제외: " + alreadyCount + "명", "프리미엄 비활성으로 제외: " + inactiveCount + "명", "처리 실패: " + failedCount + "명"];
    return { changed: changed, noticeMessage: noticeMessage, noticeMessages: noticeMessages, message: lines.join("\n") };
}

// 펫무쌍 티켓 이벤트 저장 구조를 member.json 안에 보장하는 함수
function ensurePetMusouTicketEventData(data) {
    if (!data.petMusouTicketEvent || typeof data.petMusouTicketEvent !== "object" || data.petMusouTicketEvent instanceof Array) data.petMusouTicketEvent = {};
    var eventData = data.petMusouTicketEvent;
    if (typeof eventData.enabled !== "boolean") eventData.enabled = false;
    if (!(eventData.logs instanceof Array)) eventData.logs = [];
    return eventData;
}

// 펫무쌍 티켓 이벤트 운영·지급 로그를 제한 개수로 기록하는 함수
function appendPetMusouTicketEventLog(data, log) {
    var eventData = ensurePetMusouTicketEventData(data);
    eventData.logs.push(log);
    var logMax = GLOBAL_CONFIG.petMusou.automationLogMax;
    if (eventData.logs.length > logMax) eventData.logs.splice(0, eventData.logs.length - logMax);
}

// 입력 시각을 한국 표준시 기준 펫무쌍 일정 값으로 변환하는 함수
function getPetMusouKstDateTime(now) {
    var source = now instanceof Date ? now : new Date();
    var kst = new Date(source.getTime() + 9 * 60 * 60 * 1000);
    var year = kst.getUTCFullYear();
    var month = kst.getUTCMonth() + 1;
    var day = kst.getUTCDate();
    return {
        year: year,
        month: month,
        day: day,
        hour: kst.getUTCHours(),
        minute: kst.getUTCMinutes()
    };
}

// 펫무쌍 티켓 이벤트가 운영 상태인지 확인하는 함수
function isPetMusouTicketEventActive(data) {
    return !!(data && data.petMusouTicketEvent && data.petMusouTicketEvent.enabled === true);
}

// 티켓 이벤트 관리자 명령인지 확인하는 함수
function isPetMusouTicketEventAdminCommand(msg) {
    return msg === "/티켓이벤트시작" || msg === "/티켓이벤트종료" || msg === "/티켓전체회수";
}

// 티켓 이벤트 시작·종료·쿠폰 전체 회수 명령을 처리하는 함수
function processPetMusouTicketEventAdminCommand(msg, data, operator) {
    var eventData = ensurePetMusouTicketEventData(data);
    var nowText = formatDateTime(new Date());
    if (msg === "/티켓이벤트시작") {
        if (eventData.enabled) return { changed: false, noticeMessage: "", message: "이미 티켓이벤트가 진행 중입니다." };
        eventData.enabled = true;
        eventData.startedAt = nowText;
        eventData.startedBy = operator;
        appendPetMusouTicketEventLog(data, { action: "START", operator: operator, processedAt: nowText });
        return {
            changed: true,
            message: "✅ 티켓이벤트를 시작했습니다.\n펫무쌍 시작 시각: 12:30, 20:30",
            noticeMessage: "[🎟️호이월드 티켓 이벤트 시작🎟️]\n티켓이벤트가 시작되었습니다.\n펫무쌍대회에 참여하셔서 티켓할인쿠폰을\n획득해보세요! 참여방법 채팅창에 \"펫무쌍 컨텐츠\"를 입력해보세요"
        };
    }
    if (msg === "/티켓이벤트종료") {
        if (!eventData.enabled) return { changed: false, noticeMessage: "", message: "현재 티켓이벤트가 진행 중이 아닙니다." };
        eventData.enabled = false;
        eventData.endedAt = nowText;
        eventData.endedBy = operator;
        appendPetMusouTicketEventLog(data, { action: "END", operator: operator, processedAt: nowText });
        return {
            changed: true,
            message: "✅ 티켓이벤트를 종료했습니다.\n기존 보유 쿠폰은 유지됩니다.",
            noticeMessage: "[🎟️호이월드 티켓 이벤트 종료🎟️]\n티켓이벤트가 종료되었습니다.\n참여해주신 유저분들께 진심으로 감사드리며\n더 좋은 이벤트로 찾아뵙겠습니다. -호이 남-"
        };
    }

    var couponConfig = GLOBAL_CONFIG.petMusou.ticketEvent.coupons.concat(GLOBAL_CONFIG.petMusou.ticketEvent.legacyCoupons);
    var removedCounts = [];
    var totalRemovedCount = 0;
    for (var couponIndex = 0; couponIndex < couponConfig.length; couponIndex++) removedCounts[couponIndex] = 0;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || !data.member[user] || !data.member[user].bag) continue;
        for (var removeIndex = 0; removeIndex < couponConfig.length; removeIndex++) {
            var couponName = couponConfig[removeIndex].name;
            var couponCount = parseInt(data.member[user].bag[couponName], 10) || 0;
            if (couponCount > 0) {
                removedCounts[removeIndex] += couponCount;
                totalRemovedCount += couponCount;
            }
            if (data.member[user].bag[couponName] !== undefined) delete data.member[user].bag[couponName];
        }
    }
    appendPetMusouTicketEventLog(data, { action: "REVOKE_ALL", operator: operator, totalRemovedCount: totalRemovedCount, processedAt: nowText });
    var lines = ["[🎟️티켓 이벤트 쿠폰 전체 회수 완료🎟️]"];
    for (var resultIndex = 0; resultIndex < couponConfig.length; resultIndex++) lines.push(couponConfig[resultIndex].rate + "% 쿠폰: " + numberWithCommas(removedCounts[resultIndex]) + "개");
    lines.push("━━━━━━━━━━━━", "총 회수: " + numberWithCommas(totalRemovedCount) + "개");
    return { changed: true, noticeMessage: "", message: lines.join("\n") };
}

// 이벤트 확률표에 따라 유효한 펫무쌍 공격의 쿠폰 1장을 지급하는 함수
function grantPetMusouTicketEventCoupon(data, user) {
    if (!isPetMusouTicketEventActive(data) || !data.member || !data.member[user]) return null;
    var coupons = GLOBAL_CONFIG.petMusou.ticketEvent.coupons;
    var totalWeight = 0; // 남은 쿠폰의 기존 가중치 비율을 유지하는 추첨 범위
    for (var weightIndex = 0; weightIndex < coupons.length; weightIndex++) totalWeight += coupons[weightIndex].weight;
    var roll = Math.floor(Math.random() * totalWeight) + 1;
    var cumulativeWeight = 0;
    var selectedCoupon = coupons[0];
    for (var i = 0; i < coupons.length; i++) {
        cumulativeWeight += coupons[i].weight;
        if (roll <= cumulativeWeight) {
            selectedCoupon = coupons[i];
            break;
        }
    }
    if (!data.member[user].bag || typeof data.member[user].bag !== "object") data.member[user].bag = {};
    data.member[user].bag[selectedCoupon.name] = (parseInt(data.member[user].bag[selectedCoupon.name], 10) || 0) + 1;
    appendPetMusouTicketEventLog(data, { action: "COUPON_DROP", user: user, coupon: selectedCoupon.name, roll: roll, processedAt: formatDateTime(new Date()) });
    return { name: selectedCoupon.name, rate: selectedCoupon.rate, display: "티켓쿠폰🎟️(" + selectedCoupon.rate + "%) 획득" };
}

// 생략 시 1개인 레이드 인장 조합 수량을 한 번만 숫자로 변환하는 함수
function getRaidSealCraftRequest(msg) {
    if (typeof msg !== "string") return null;
    var match = msg.match(/^\/레이드인장조합(?:\s+(\d+))?$/);
    return match ? { quantity: typeof match[1] === "undefined" ? 1 : Number(match[1]) } : null;
}

// 조합 비용과 최종 보유량을 확인한 뒤 차감·지급을 함께 반영하는 함수
function craftRaidSealItems(data, user, quantity, nickname) {
    var config = GLOBAL_CONFIG.raidSealCraft;
    var requiredMaterials = config.materialCount * quantity; // 전체 조합에 필요한 잡템 수량
    var requiredPoints = config.pointCost * quantity; // 전체 조합에 필요한 포인트
    if (!isPointShopSafeCount(quantity) || quantity < 1 ||
        !isPointShopSafeCount(requiredMaterials) || !isPointShopSafeCount(requiredPoints)) {
        return { changed: false, message: "❌ 정확히 계산할 수 있는 1 이상의 정수 수량을 입력해주세요.\n사용법: /레이드인장조합 [수량]" };
    }
    var member = data && data.member && Object.prototype.hasOwnProperty.call(data.member, user) ? data.member[user] : null;
    var bag = member && member.bag;
    if (!bag || typeof bag !== "object" || bag instanceof Array) {
        return { changed: false, message: "❌ 가방 정보를 확인할 수 없습니다. 관리자에게 문의해주세요." };
    }
    var heldMaterials = typeof bag[config.materialName] === "undefined" ? 0 : bag[config.materialName];
    var heldRewards = typeof bag[config.rewardName] === "undefined" ? 0 : bag[config.rewardName];
    var finalRewards = heldRewards + quantity; // 지급 후 보유할 인장 수량
    if (!isPointShopSafeCount(heldMaterials) || !isPointShopSafeCount(heldRewards) ||
        !isPointShopSafeCount(finalRewards) || !isPointShopSafeAmount(member.point)) {
        return { changed: false, message: "❌ 재료·포인트·인장 보유량을 정확히 계산할 수 없어 조합하지 않았습니다.\n관리자에게 문의해주세요." };
    }
    if (heldMaterials < requiredMaterials || member.point < requiredPoints) {
        return { changed: false, message: "❌ 레이드인장 조합 재료가 부족합니다.\n[" + nickname + "] 님\n━━━━━━━━━━━━\n📦 필요 재료\n" + config.materialName + " x" + numberWithCommas(requiredMaterials) + " + 🅟" + numberWithCommas(requiredPoints) + " 포인트\n\n🎒 현재 보유\n" + config.materialName + " x" + numberWithCommas(heldMaterials) + "\n🅟" + numberWithCommas(member.point) + "\n\n재료와 포인트를 모두 충족한 뒤\n/레이드인장조합 을 입력해 주세요." };
    }
    bag[config.materialName] = heldMaterials - requiredMaterials;
    if (bag[config.materialName] === 0) delete bag[config.materialName];
    member.point -= requiredPoints;
    bag[config.rewardName] = finalRewards;
    return { changed: true, message: "[" + nickname + "] 님, 조합이 완성되었습니다! 👑\n━━━━━━━━━━━━\n📦 소모 재료\n" + config.materialName + " x" + numberWithCommas(requiredMaterials) + "\n🅟" + numberWithCommas(requiredPoints) + " 포인트\n\n🎁 획득\n" + config.rewardName + " ×" + numberWithCommas(quantity) + "개" };
}

// 기존 돌멩이 단가로 두 상자 가격을 계산해 상점에 반영하는 함수
function syncStoneBoxShopItems(data) {
    var config = GLOBAL_CONFIG.stoneBox;
    if (!data || !data.shop || !Object.prototype.hasOwnProperty.call(data.shop, config.stoneItemName)) return false;
    var unitPrice = data.shop[config.stoneItemName];
    if (!isPointShopSafeAmount(unitPrice)) return false;
    var kinds = Object.keys(config.boxes);
    var prices = []; // 전체 가격을 검증한 뒤 적용할 상자별 가격
    for (var i = 0; i < kinds.length; i++) {
        var price = unitPrice * config.boxes[kinds[i]].stoneCount;
        if (!isPointShopSafeAmount(price)) return false;
        prices.push(price);
    }
    var changed = false;
    for (var j = 0; j < kinds.length; j++) {
        var itemName = config.boxes[kinds[j]].itemName;
        if (data.shop[itemName] !== prices[j]) {
            data.shop[itemName] = prices[j];
            changed = true;
        }
    }
    return changed;
}

// 종류와 선택 수량이 명확한 돌멩이 상자 명령을 파싱하는 함수
function getStoneBoxOpenRequest(msg) {
    if (typeof msg !== "string") return null;
    var match = msg.match(/^\/돌멩이상자오픈\s+(1만|10만)(?:\s+(\d+))?$/);
    return match ? { kind: match[1], count: typeof match[2] === "undefined" ? 1 : Number(match[2]) } : null;
}

// 돌멩이 상자와 최종 지급량을 확인해 이미 로드한 가방에 함께 반영하는 함수
function openStoneBoxItems(data, user, kind, count) {
    var config = GLOBAL_CONFIG.stoneBox;
    var box = Object.prototype.hasOwnProperty.call(config.boxes, kind) ? config.boxes[kind] : null;
    if (!box || !isPointShopSafeCount(count) || count < 1 || count > config.maxOpenQuantity) {
        return { changed: false, message: "❌ 돌멩이 상자는 한 번에 1~" + numberWithCommas(config.maxOpenQuantity) + "개까지 열 수 있습니다." };
    }
    var member = data && data.member && Object.prototype.hasOwnProperty.call(data.member, user) ? data.member[user] : null;
    var bag = member && member.bag;
    if (!bag || typeof bag !== "object" || bag instanceof Array) {
        return { changed: false, message: "❌ 가방 정보를 확인할 수 없습니다. 관리자에게 문의해주세요." };
    }
    var heldBoxes = typeof bag[box.itemName] === "undefined" ? 0 : bag[box.itemName];
    var heldStones = typeof bag[config.stoneItemName] === "undefined" ? 0 : bag[config.stoneItemName];
    var rewardCount = box.stoneCount * count; // 이번 개봉으로 지급할 돌멩이 수량
    var finalStoneCount = heldStones + rewardCount; // 기존 보유량까지 합산한 최종 수량
    if (!isPointShopSafeCount(heldBoxes) || !isPointShopSafeCount(heldStones) ||
        !isPointShopSafeCount(rewardCount) || !isPointShopSafeCount(finalStoneCount)) {
        return { changed: false, message: "❌ 상자나 돌멩이 수량을 정확히 계산할 수 없어 개봉하지 않았습니다.\n관리자에게 문의해주세요." };
    }
    if (heldBoxes < count) {
        return { changed: false, message: "❌ 돌멩이 " + kind + "개 상자가 부족합니다.\n필요: " + numberWithCommas(count) + "개\n보유: " + numberWithCommas(heldBoxes) + "개" };
    }
    bag[box.itemName] = heldBoxes - count;
    if (bag[box.itemName] === 0) delete bag[box.itemName];
    bag[config.stoneItemName] = finalStoneCount;
    return { changed: true, message: "✅ 돌멩이 상자 오픈 완료\n━━━━━━━━━━━━\n📦 소모: " + kind + "개 상자 ×" + numberWithCommas(count) + "개\n🪨 획득: 돌멩이 " + numberWithCommas(rewardCount) + "개\n🪨 현재 보유: " + numberWithCommas(finalStoneCount) + "개" };
}

// 포인트 상점의 금액이 유한한 숫자이며 정확한 정수 표현 범위 안인지 확인하는 함수
function isPointShopSafeAmount(value) {
    return typeof value === "number" && isFinite(value) && value >= 0 && value <= GLOBAL_CONFIG.pointShop.limits.maxSafeNumber;
}

// 포인트 상점의 보유·지급 수량이 안전한 0 이상 정수인지 확인하는 함수
function isPointShopSafeCount(value) {
    return isPointShopSafeAmount(value) && Math.floor(value) === value;
}

// 포인트 상점 세금의 성·길드·재단 적립 결과가 안전한지 변경 전에 확인하는 함수
function isPointShopTaxSettlementSafe(data, guildData, taxAmount) {
    var castle = data.HoiCastle;
    if (taxAmount <= 0 || !castle || !castle.taxRate || !castle.lord) return true;
    var guildShare = Math.round(taxAmount * 0.15); // 기존 세금 중 길드 몫
    var foundationShare = taxAmount - guildShare; // 기존 세금 중 재단 몫
    var castleEarnings = typeof castle.earnings === "undefined" ? 0 : castle.earnings;
    var foundationTotal = data.hoiHappyFoundation && typeof data.hoiHappyFoundation.totalAmount !== "undefined" ? data.hoiHappyFoundation.totalAmount : 0;
    if (!isPointShopSafeAmount(castleEarnings) || !isPointShopSafeAmount(castleEarnings + guildShare) ||
        !isPointShopSafeAmount(foundationTotal) || !isPointShopSafeAmount(foundationTotal + foundationShare)) return false;
    var lordGuild = getMyGuildInfo(data, guildData, castle.lord);
    if (lordGuild && !lordGuild.error && lordGuild.guild) {
        var warehouse = lordGuild.guild.warehouse;
        var guildFund = warehouse && typeof warehouse.fund !== "undefined" ? warehouse.fund : 0;
        if (!isPointShopSafeAmount(guildFund) || !isPointShopSafeAmount(guildFund + guildShare)) return false;
    }
    return true;
}

// 티켓 구매 수량에 맞춰 높은 할인율부터 쿠폰 적용 가격과 차감 계획을 계산하는 함수
function buildTicketEventCouponPurchasePlan(data, user, itemName, quantity, unitPrice) {
    if (!isPointShopSafeCount(quantity) || quantity < 1 || !isPointShopSafeAmount(unitPrice) || !isPointShopSafeAmount(unitPrice * quantity)) return null;
    var plan = { itemPrice: unitPrice * quantity, usedCount: 0, usages: [] };
    if (String(itemName || "").indexOf("티켓") === -1) return plan;
    var bag = data && data.member && data.member[user] ? data.member[user].bag : null;
    if (!bag) return plan;
    var remainingQuantity = quantity; // 아직 쿠폰을 적용하지 않은 구매 수량
    var coupons = GLOBAL_CONFIG.petMusou.ticketEvent.coupons.concat(GLOBAL_CONFIG.petMusou.ticketEvent.legacyCoupons);
    coupons.sort(function (a, b) { return b.rate - a.rate; });
    for (var i = 0; i < coupons.length && remainingQuantity > 0; i++) {
        var heldCount = typeof bag[coupons[i].name] === "undefined" ? 0 : bag[coupons[i].name];
        if (!isPointShopSafeCount(heldCount)) return null;
        if (heldCount < 1) continue;
        var useCount = Math.min(heldCount, remainingQuantity); // 이번 할인율에서 실제 적용할 쿠폰 수
        plan.itemPrice -= unitPrice * useCount / 100 * coupons[i].rate;
        plan.usedCount += useCount;
        plan.usages.push({ name: coupons[i].name, rate: coupons[i].rate, count: useCount });
        remainingQuantity -= useCount;
    }
    return isPointShopSafeAmount(plan.itemPrice) ? plan : null;
}

// 포인트 상점의 티어 승급티켓 구매에만 티어 상승론 추가 수량을 계산하는 함수
function getPointShopTierTicketBonusCount(petSkillData, user, itemName, quantity) {
    var benefit = GLOBAL_CONFIG.pointShop.petSkillBenefits.tierTicketBonus;
    var parsedQuantity = quantity;
    if (!isPointShopSafeCount(parsedQuantity)) return 0;
    if (itemName !== benefit.itemName || !hasPetSkill(petSkillData, user, benefit.skillName)) return 0;
    return Math.floor(parsedQuantity * benefit.bonusRate);
}

// 티어 상승론 보너스를 포함해 부족 티켓을 채우는 최소 포인트 상점 구매 수량을 계산하는 함수
function getPointShopTierTicketPurchaseQuantity(petSkillData, user, requiredQuantity) {
    var required = requiredQuantity;
    if (!isPointShopSafeCount(required)) return 0;
    var benefit = GLOBAL_CONFIG.pointShop.petSkillBenefits.tierTicketBonus;
    if (required < 1 || !hasPetSkill(petSkillData, user, benefit.skillName)) return required;
    var low = 1;
    var high = required;
    while (low < high) {
        var middle = low + Math.floor((high - low) / 2); // 안전 범위 안에서 최소 구매량 탐색
        var received = middle + getPointShopTierTicketBonusCount(petSkillData, user, benefit.itemName, middle);
        if (received >= required) high = middle;
        else low = middle + 1;
    }
    return low;
}

// 포인트 상점 구매와 조회 화면이 함께 사용하는 최종 결제 견적을 계산하는 함수
function buildPointShopPurchaseQuote(data, petSkillData, user, itemName, quantity, unitPrice) {
    var parsedQuantity = quantity;
    var parsedUnitPrice = unitPrice;
    if (!data || !data.member || !data.member[user] || !isPointShopSafeCount(parsedQuantity) || parsedQuantity < 1 || !isPointShopSafeAmount(parsedUnitPrice)) {
        return { available: false };
    }
    var basePrice = parsedUnitPrice * parsedQuantity;
    if (!isPointShopSafeAmount(basePrice)) return { available: false };
    var couponPlan = buildTicketEventCouponPurchasePlan(data, user, itemName, parsedQuantity, parsedUnitPrice);
    if (!couponPlan) return { available: false };
    var itemPrice = couponPlan.itemPrice;
    var discountSkill = "";
    if (hasPetSkill(petSkillData, user, "VIP블랙카드")) {
        discountSkill = "VIP블랙카드";
        itemPrice = itemPrice / 100 * (100 - GLOBAL_CONFIG.petSkill.shopDiscounts.vipBlackCardRate * 100);
    } else if (hasPetSkill(petSkillData, user, "쇼핑광")) {
        discountSkill = "쇼핑광";
        itemPrice = itemPrice / 100 * (100 - GLOBAL_CONFIG.petSkill.shopDiscounts.shoppingFanRate * 100);
    }
    var configuredTaxRate = data.HoiCastle && data.HoiCastle.taxRate ? Number(data.HoiCastle.taxRate) : 0;
    if (!isPointShopSafeAmount(configuredTaxRate)) return { available: false };
    var baseTaxRate = Math.floor(configuredTaxRate);
    var taxBenefit = GLOBAL_CONFIG.pointShop.petSkillBenefits.taxRelief;
    var taxExempt = hasPetSkill(petSkillData, user, taxBenefit.skillName);
    var taxRate = taxExempt ? Math.round(baseTaxRate * taxBenefit.payableTaxRate * 10) / 10 : baseTaxRate;
    var taxAmount = Math.round(itemPrice / 100 * taxRate);
    if (!isPointShopSafeAmount(itemPrice) || !isPointShopSafeAmount(taxAmount) || !isPointShopSafeAmount(itemPrice + taxAmount)) return { available: false };
    return {
        available: true,
        quantity: parsedQuantity,
        basePrice: basePrice,
        itemPrice: itemPrice,
        taxRate: taxRate,
        baseTaxRate: baseTaxRate,
        taxAmount: taxAmount,
        totalCost: itemPrice + taxAmount,
        taxExempt: taxExempt,
        discountSkill: discountSkill,
        couponPlan: couponPlan
    };
}

// 구매 성공 뒤 계산된 티켓 이벤트 쿠폰을 할인율별 수량만큼 차감하는 함수
function consumeTicketEventCouponPlan(data, user, plan) {
    var bag = data && data.member && data.member[user] ? data.member[user].bag : null;
    if (!bag || !plan || !(plan.usages instanceof Array)) return 0;
    for (var i = 0; i < plan.usages.length; i++) {
        if (!isPointShopSafeCount(bag[plan.usages[i].name]) ||
            !isPointShopSafeCount(plan.usages[i].count) || bag[plan.usages[i].name] < plan.usages[i].count) return 0;
    }
    var consumedCount = 0; // 모든 할인율에서 실제 차감한 쿠폰 합계
    for (var j = 0; j < plan.usages.length; j++) {
        var usage = plan.usages[j];
        bag[usage.name] -= usage.count;
        consumedCount += usage.count;
        if (bag[usage.name] < 1) delete bag[usage.name];
    }
    return consumedCount;
}

// 티켓 이벤트 쿠폰의 할인율별 사용 수량을 구매 완료 안내로 만드는 함수
function buildTicketEventCouponUsageMessage(plan) {
    var usageTexts = [];
    for (var i = 0; i < plan.usages.length; i++) usageTexts.push(plan.usages[i].rate + "% 쿠폰 " + numberWithCommas(plan.usages[i].count) + "장");
    return "티켓이벤트 할인 적용🎟️: " + usageTexts.join(", ") + "을 사용했습니다.";
}

// 펫무쌍 저장 구조를 기존 member.json 안에서 보장하는 함수
function ensurePetMusouData(data) {
    if (!data.petMusou || typeof data.petMusou !== "object" || data.petMusou instanceof Array) data.petMusou = {};
    var musou = data.petMusou;
    if (typeof musou.signupOpen !== "boolean") musou.signupOpen = true;
    if (!musou.participants || typeof musou.participants !== "object" || musou.participants instanceof Array) musou.participants = {};
    if (!musou.nextParticipants || typeof musou.nextParticipants !== "object" || musou.nextParticipants instanceof Array) {
        musou.nextParticipants = !musou.active && Object.keys(musou.participants).length > 0 ? musou.participants : {};
        if (!musou.active) musou.participants = {};
    }
    if (!musou.players || typeof musou.players !== "object" || musou.players instanceof Array) musou.players = {};
    if (!(musou.turnQueue instanceof Array)) musou.turnQueue = [];
    if (!musou.fakeFlags || typeof musou.fakeFlags !== "object" || musou.fakeFlags instanceof Array) musou.fakeFlags = {};
    if (!musou.processedRounds || typeof musou.processedRounds !== "object" || musou.processedRounds instanceof Array) musou.processedRounds = {};
    if (typeof musou.active !== "boolean") musou.active = false;
    if (typeof musou.lightningRate !== "number") musou.lightningRate = GLOBAL_CONFIG.petMusou.lightningStartRate;
    if (typeof musou.roundNo !== "number") musou.roundNo = 0;
    if (typeof musou.actionSeq !== "number") musou.actionSeq = 0;
    if (typeof musou.turnDeadlineAt !== "number") musou.turnDeadlineAt = 0;
    if (typeof musou.turnToken !== "string") musou.turnToken = "";
    if (typeof musou.startReady !== "boolean") musou.startReady = musou.active;
    if (typeof musou.startGraceDeadlineAt !== "number") musou.startGraceDeadlineAt = 0;
    if (typeof musou.startGraceToken !== "string") musou.startGraceToken = "";
    if (typeof musou.nextRoundId !== "string") musou.nextRoundId = "";
    if (!musou.active && !musou.nextRoundId) musou.nextRoundId = "PREP_" + String(new Date().getTime());
    if (typeof musou.realFlagDiscoveryBonusPaid !== "boolean") musou.realFlagDiscoveryBonusPaid = !!musou.realFlagFound;
    return musou;
}

// 현재 로컬 시각을 펫무쌍 일정 비교용 HH:mm 문자열로 반환하는 함수
function getPetMusouScheduleTimeText(now) {
    var kst = getPetMusouKstDateTime(now);
    var hour = kst.hour;
    var minute = kst.minute;
    return (hour < 10 ? "0" : "") + hour + ":" + (minute < 10 ? "0" : "") + minute;
}

// 펫무쌍 일정의 날짜·회차 중복 방지 키를 반환하는 함수
function getPetMusouScheduleKey(now, timeText) {
    var kst = getPetMusouKstDateTime(now);
    return String(kst.year) + (kst.month < 10 ? "0" : "") + kst.month + (kst.day < 10 ? "0" : "") + kst.day + "_" + timeText;
}

// 일반 일정과 이벤트 추가 일정을 합쳐 현재 활성 시작 시각을 반환하는 함수
function getActivePetMusouStartTimes(data, now) {
    var times = GLOBAL_CONFIG.petMusou.regularStartTimes.slice();
    if (isPetMusouTicketEventActive(data, now)) {
        for (var i = 0; i < GLOBAL_CONFIG.petMusou.ticketEventStartTimes.length; i++) times.push(GLOBAL_CONFIG.petMusou.ticketEventStartTimes[i]);
    }
    return times;
}

// 저장된 일정과 현재 운영 상태를 기준으로 펫무쌍 정시 시작을 한 번 처리하는 함수
function runScheduledPetMusouStart(data, petData, homeData, petSkillData, guildData, now) {
    var timeText = getPetMusouScheduleTimeText(now);
    var activeTimes = getActivePetMusouStartTimes(data, now);
    if (activeTimes.indexOf(timeText) === -1) return { changed: false, started: false, message: "" };
    var musou = ensurePetMusouData(data);
    var scheduleKey = getPetMusouScheduleKey(now, timeText); // 같은 날짜·시각의 중복 시작 방지 키
    if (musou.lastScheduledStartKey === scheduleKey) return { changed: false, started: false, message: "" };
    musou.lastScheduledStartKey = scheduleKey;

    var matzangField = ensureMatzangFieldData(data);
    var territoryWar = ensureGuildTerritoryWar(data, guildData);
    if (musou.active || matzangField.active || territoryWar.active || territoryWar.pendingStart) {
        var blockedReason = musou.active ? "기존 펫무쌍 진행 중" : matzangField.active ? "맞짱필드 진행 중" : "길드 영지전 진행·대기 중";
        appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_SCHEDULE", action: "START", result: "SKIPPED", reason: blockedReason, scheduleKey: scheduleKey, processedAt: formatDateTime(now) });
        return { changed: true, started: false, message: "" };
    }

    autoRegisterHoiPassPremiumPetMusouUsers(data, petData, petSkillData, guildData, "");
    var startResult = beginPetMusou(data, petData, homeData, petSkillData, guildData);
    if (!startResult.ok) {
        appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_SCHEDULE", action: "START", result: "SKIPPED", reason: startResult.message, scheduleKey: scheduleKey, processedAt: formatDateTime(now) });
        return { changed: true, started: false, message: "" };
    }
    appendPetMusouAutomationLog(data, { feature: "PET_MUSOU_SCHEDULE", action: "START", result: "SUCCESS", reason: "", scheduleKey: scheduleKey, processedAt: formatDateTime(now) });
    return { changed: true, started: true, message: startResult.message };
}

// 현재 시각의 펫무쌍 정시 시작을 잠금·저장 단위로 한 번 확인하는 함수
function runPetMusouScheduleTick(timerCtx, replier, now) {
    var timeText = getPetMusouScheduleTimeText(now);
    var isRegularTime = GLOBAL_CONFIG.petMusou.regularStartTimes.indexOf(timeText) !== -1;
    var isEventTime = GLOBAL_CONFIG.petMusou.ticketEventStartTimes.indexOf(timeText) !== -1;
    if (!isRegularTime && !isEventTime) return;

    var prevCtx = enterCommandContext(timerCtx);
    var timerTransactionAcquired = false;
    var timerTransactionEntered = false;
    try {
        dataTransactionLock.lock();
        timerTransactionAcquired = true;
        beginDataSaveTransaction();
        timerTransactionEntered = true;
        var latestData = loadJsonFile(filePath);
        // 이미 처리한 정시 예약과 비활성 이벤트는 전투 자료를 읽기 전에 제외한다.
        if (getActivePetMusouStartTimes(latestData, now).indexOf(timeText) === -1) return;
        var scheduleKey = getPetMusouScheduleKey(now, timeText);
        var latestMusou = ensurePetMusouData(latestData);
        if (latestMusou.lastScheduledStartKey === scheduleKey) return;
        var latestPetData = loadJsonFile(memberPetPath);
        var latestHomeData = loadJsonFile(homeDataFile);
        var latestPetSkillData = loadJsonFile(petSkillDataPath);
        var latestGuildData = loadJsonFile(guildPath);
        var scheduleResult = runScheduledPetMusouStart(latestData, latestPetData, latestHomeData, latestPetSkillData, latestGuildData, now);
        if (!scheduleResult.changed) return;
        saveJsonFile(latestData, filePath);
        if (scheduleResult.started) {
            noticeMsg(scheduleResult.message);
            startPetMusouOpeningTimer(latestData, latestPetData, latestPetSkillData, latestGuildData, replier, true, true);
        }
    } catch (scheduleError) {
        debuggerLog("[펫무쌍 정시 시작 오류] " + scheduleError);
    } finally {
        if (timerTransactionEntered) endDataSaveTransaction();
        if (timerTransactionAcquired) dataTransactionLock.unlock();
        exitCommandContext(prevCtx);
    }
}

// PROD 실행 컨텍스트별 펫무쌍 정시 시작 감시 타이머를 한 번만 생성하는 함수
function ensurePetMusouScheduleTimer(replier) {
    var timerCtx = getCurrentContext();
    var timerCtxKey = timerCtx.key();
    if (petMusouScheduleTimers[timerCtxKey]) return;
    var scheduleTick = function () { runPetMusouScheduleTick(timerCtx, replier, new Date()); };
    petMusouScheduleTimers[timerCtxKey] = setInterval(scheduleTick, GLOBAL_CONFIG.petMusou.scheduleCheckMs);
    scheduleTick();
}

// 길드영지 자동화 권한 아이템을 보유했는지 확인하는 함수
function hasGuildTerritoryAutomationItem(data, user, itemName) {
    var bag = data && data.member && data.member[user] && data.member[user].bag ? data.member[user].bag : null;
    return !!(bag && Number(bag[itemName]) > 0);
}

// 길드영지 자동 준비 권한 보유 여부를 확인하는 함수
function hasGuildTerritoryAutoReadyEntitlement(data, user) {
    return hasGuildTerritoryAutomationItem(data, user, GLOBAL_CONFIG.guildTerritory.automation.autoReadyItemName) ||
        isSupportPassActive(data, user, "territory");
}

// 영지 자동 공격 권한 보유 여부를 확인하는 함수
function hasGuildTerritoryAutoAttackEntitlement(data, user) {
    return isSupportPassActive(data, user, "territory");
}

// 현재 직책과 펫스킬을 기준으로 영지 자동 공격 자격을 확인하는 함수
function hasGuildTerritoryAutoAttackQualification(g, petSkillData, user) {
    if (!g || !user || !g.members || !g.members[user]) return false;
    if (isGuildSwordMaster(g, user, petSkillData)) return true;
    return isGuildMaster(g, user) && hasPetSkill(petSkillData, user, "전투형 지휘관");
}

// 영지 자동 공격 권한과 현재 자격을 함께 검증하는 함수
function validateGuildTerritoryAutoAttack(data, guildData, petSkillData, user) {
    var guildInfo = getMyGuildInfo(data, guildData, user);
    if (!guildInfo || guildInfo.error || !guildInfo.guild) {
        return { ok: false, reason: "길드 미가입", guildInfo: null };
    }
    if (!hasGuildTerritoryAutoAttackEntitlement(data, user)) {
        return { ok: false, reason: "기능 권한 없음", guildInfo: guildInfo };
    }
    if (!hasGuildTerritoryAutoAttackQualification(guildInfo.guild, petSkillData, user)) {
        return { ok: false, reason: "직책·자격 조건 불충족", guildInfo: guildInfo };
    }
    return { ok: true, reason: "", guildInfo: guildInfo };
}

// 길드영지 자동화 처리 로그를 회차 데이터에 추가하는 함수
function appendGuildTerritoryAutomationLog(war, log) {
    if (!war.automationLogs || !(war.automationLogs instanceof Array)) war.automationLogs = [];
    war.automationLogs.push(log);
    var logMax = GLOBAL_CONFIG.guildTerritory.automation.logMax;
    if (war.automationLogs.length > logMax) war.automationLogs.splice(0, war.automationLogs.length - logMax);
}

// 유저별 영지 자동화 설정 변경 내역을 로드된 운영 로그에 추가하는 함수
function appendGuildTerritoryAutomationDataLog(data, log) {
    if (!Array.isArray(data.guildTerritoryAutomationLogs)) data.guildTerritoryAutomationLogs = [];
    data.guildTerritoryAutomationLogs.push(log);
    var logMax = GLOBAL_CONFIG.guildTerritory.automation.logMax;
    if (data.guildTerritoryAutomationLogs.length > logMax) {
        data.guildTerritoryAutomationLogs.splice(0, data.guildTerritoryAutomationLogs.length - logMax);
    }
}

// 만료·삭제된 영지기습패스로 켜 둔 자동 공격을 OFF 처리하는 함수
function disableInvalidGuildTerritoryAutoAttacks(data) {
    var changedUsers = [];
    if (!data || !data.member) return changedUsers;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || !data.member[user]) continue;
        var member = data.member[user];
        if (member.guildTerritoryAutoAttackEnabled !== true) continue;
        if (hasGuildTerritoryAutoAttackEntitlement(data, user)) continue;
        member.guildTerritoryAutoAttackEnabled = false;
        appendGuildTerritoryAutomationDataLog(data, {
            type: "AUTO_ATTACK_OFF",
            user: user,
            reason: "영지기습패스 만료·삭제",
            processedAt: formatDateTime(new Date())
        });
        changedUsers.push(user);
    }
    return changedUsers;
}

// 펫무쌍 운영 명령어 사용 권한을 확인하는 함수
function isPetMusouOperator(sender) {
    return isMaster(sender) || isAdmin(sender) || sender === "오픈채팅봇";
}

// 펫무쌍 시작 명령에 기존 권한과 서버관리자방 Admin·Master 권한을 허용하는 함수
function isPetMusouStartOperator(sender) {
    var permissionRoom = getCurrentContext().permissionRoom;
    return sender === "오픈채팅봇" || isMaster(sender) || (permissionRoom === room8 && Master.includes(sender)) || isServerAdminRoomOperator(sender);
}

// 펫무쌍 진행 중 일반 유저에게 허용할 명령어인지 확인하는 함수
function isPetMusouAllowedDuringTournamentCommand(msg) {
    return msg === "/글자수전체정리" || msg === "/무쌍순위" || /^\/펫무쌍공격\s+(?:10|[1-9])$/.test(msg);
}

// 펫무쌍 누적 벼락 발생확률 운영 명령의 정확한 입력 형식을 확인하는 함수
function isPetMusouLightningRateCommand(msg) {
    return msg === "/벼락확률" || /^\/벼락확률\s+\d{1,3}(?:\.\d)?$/.test(msg);
}

// 펫무쌍 진행 중 일반 유저의 펫무쌍 외 입력 차단 여부를 확인하는 함수
function isPetMusouBlockedDuringTournamentCommand(musou, msg, sender) {
    if (!musou || !musou.active || typeof msg !== "string") return false;
    if (!musou.startReady && musou.signupOpen && msg === "/펫무쌍준비") return false;
    if (isPetMusouOperator(sender) || isGlobalOperatorCommandAllowed(sender, msg)) return false;
    if (msg === "/펫무쌍시작" && isPetMusouStartOperator(sender)) return false;
    return !isPetMusouAllowedDuringTournamentCommand(msg);
}

// 펫무쌍 참가자의 길드 가입 상태를 확인하는 함수
function getPetMusouGuildInfo(data, guildData, user) {
    var guildInfo = getMyGuildInfo(data, guildData, user);
    if (!guildInfo || guildInfo.error || !guildInfo.guild) return null;
    return guildInfo;
}

// 펫무쌍 참가·진행 순서를 무작위로 섞어 반환하는 함수
function shufflePetMusouUsers(users) {
    var shuffled = users.slice();
    for (var i = shuffled.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var temp = shuffled[i];
        shuffled[i] = shuffled[j];
        shuffled[j] = temp;
    }
    return shuffled;
}

// 펫무쌍 깃발 번호에 대응하는 이름을 반환하는 함수
function getPetMusouFlagName(flagNo) {
    var flagNames = ["화염의 깃발🔥", "해일의 깃발🌊", "천둥의 깃발⚡", "폭풍의 깃발🌪️", "빙설의 깃발❄️", "생명의 깃발🌿", "월광의 깃발🌙", "태양의 깃발☀️", "망령의 깃발💀", "천왕의 깃발👑"];
    return flagNames[flagNo - 1] || "알 수 없는 깃발";
}

// 펫무쌍 전투용 종합매력·크리티컬 스냅샷을 생성하는 함수
function createPetMusouBattleSnapshot(user, totalCharm, petData, data) {
    var upgradeLevel = calculateEffectivePetUpgradeLevel(user, data, petData);
    return {
        baseExp: Math.max(0, Math.round(totalCharm || 0)),
        petName: petData[user] && petData[user].petname ? petData[user].petname : "펫 정보 없음",
        upgradeLevel: upgradeLevel,
        critChance: calculateCritChance(upgradeLevel),
        critMultiplier: getCritMultiplier(upgradeLevel)
    };
}

// 다음 펫무쌍 대회 준비자 목록을 표시용 문자열로 생성하는 함수
function buildPetMusouPreparedParticipantList(data, petData, guildData, musou) {
    var preparedUsers = Object.keys(musou.nextParticipants || {});
    var preparedLines = [];
    for (var preparedIndex = 0; preparedIndex < preparedUsers.length; preparedIndex++) {
        preparedLines.push("[" + checkRank(data, petData, guildData, preparedUsers[preparedIndex]) + "] 준비 완료");
    }
    return preparedLines.join("\n");
}

// 펫무쌍 참가 신청을 저장하는 함수
function joinPetMusou(data, petData, petSkillData, guildData, sender) {
    var musou = ensurePetMusouData(data);
    if (!musou.signupOpen || (musou.active && (musou.startReady || new Date().getTime() >= musou.startGraceDeadlineAt))) return { ok: false, message: "❌ 현재 펫무쌍 참가 신청을 받고 있지 않습니다." };
    if (isAccountSuspended(data, sender)) return { ok: false, message: "❌ 계정정지 상태에서는 펫무쌍에 참가할 수 없습니다." };
    var guildInfo = getPetMusouGuildInfo(data, guildData, sender);
    if (!guildInfo) return { ok: false, message: "❌ 길드에 가입된 유저만 펫무쌍에 참가할 수 있습니다." };
    if (!petData[sender]) return { ok: false, message: "❌ 펫 정보가 없어 펫무쌍에 참가할 수 없습니다." };
    if (musou.nextParticipants[sender]) {
        return {
            ok: false,
            message: "⚠️ 이미 다음 펫무쌍 대회 준비를 완료했습니다.\n" +
                "현재 펫무쌍 참여자 목록" + allsee + "\n" + buildPetMusouPreparedParticipantList(data, petData, guildData, musou)
        };
    }
    musou.nextParticipants[sender] = {
        user: sender,
        guildId: guildInfo.guildId,
        guildName: guildInfo.guild.name,
        joinedAt: formatDateTime(new Date()),
        roundId: musou.nextRoundId
    };
    var preparedParticipantList = buildPetMusouPreparedParticipantList(data, petData, guildData, musou); // 방금 준비한 사용자를 포함한 다음 회차 준비자 목록
    return {
        ok: true,
        message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n" +
            "✅ 다음 펫무쌍 대회 준비가 완료되었습니다.\n" +
            "대회 시작 시 자동으로 참가 처리됩니다.\n\n" +
            "펫무쌍 규칙 상세보기 및 참여자 준비 목록\n" + allsee +
            "1. 대회 시작: 매일 12:30 · 이벤트 중 20:30 추가 · 운영자 수동 시작 가능\n" +
            "2. 개인 공격: 기본 " + GLOBAL_CONFIG.petMusou.attackLimit + "회 · " + GLOBAL_CONFIG.petMusou.bonusAttackSkillNames.join("·") + " 각각 장착 시 +" + GLOBAL_CONFIG.petMusou.bonusAttackCount + "회\n" +
            "3. 공격 제한시간: " + Math.floor(GLOBAL_CONFIG.petMusou.turnTimeoutMs / 1000) + "초\n" +
            "4. 처음 발견한 가짜 깃발은 공격권만 1회 차감\n" +
            "5. 공개된 가짜 재공격·시간 초과·벼락 시 탈락\n" +
            "6. 종합매력은 대회 시작 시점 기준\n" +
            "7. 최종 점령자 우승\n" +
            "━━━━━━━━━━━━\n" +
            preparedParticipantList
    };
}

// 펫무쌍 참가자 전원의 시작 시점 종합매력을 저장하고 대회를 시작하는 함수
function beginPetMusou(data, petData, homeData, petSkillData, guildData, finalizeSignup) {
    var musou = ensurePetMusouData(data);
    if (!finalizeSignup) {
        if (musou.active) return { ok: false, message: "❌ 이미 펫무쌍 대회가 진행 중입니다." };
        var signupNow = new Date().getTime(); // 참가 모집 마감시각과 중복 타이머 방지 토큰 기준
        musou.active = true;
        musou.signupOpen = true;
        musou.startReady = false;
        musou.players = {};
        musou.participants = {};
        musou.turnQueue = [];
        musou.currentHolder = "";
        musou.roundId = musou.nextRoundId;
        musou.startGraceToken = String(signupNow) + "_" + String(Math.random());
        musou.startGraceDeadlineAt = signupNow + GLOBAL_CONFIG.petMusou.startGraceMs;
        return {
            ok: true,
            message: "[⚔️전체알림⚔️]\n" +
                "🗡️ 펫무쌍 대회 시작 " + Math.floor(GLOBAL_CONFIG.petMusou.startGraceMs / 1000) + "초 전 🗡️\n" +
                "/펫무쌍준비 를 입력하면 " + Math.floor(GLOBAL_CONFIG.petMusou.startGraceMs / 1000) + "초 안에 대회에 참여할 수 있습니다.\n\n" +
                "이미 준비한 참가자는 그대로 참여합니다.\n" +
                "모집이 끝나면 참가자 명단과 함께 시작합니다.\n" +
                "https://open.kakao.com/o/gaP4Xybh"
        };
    }
    if (!musou.active || musou.startReady || !musou.signupOpen) return { ok: false, message: "❌ 참가 모집 중인 대회가 없습니다." };
    var preparedParticipants = musou.nextParticipants;
    var participantNames = Object.keys(preparedParticipants);
    var validUsers = [];
    var excludedUsers = [];
    var players = {};
    for (var i = 0; i < participantNames.length; i++) {
        var user = participantNames[i];
        var guildInfo = getPetMusouGuildInfo(data, guildData, user);
        if (!data.member[user] || !petData[user] || !guildInfo || isAccountSuspended(data, user)) {
            excludedUsers.push(user);
            continue;
        }
        var totalCharm = calculateTotalExp(user, data, petData, homeData, petSkillData, guildData);
        var equippedBonusAttackSkillNames = []; // 대회 시작 시 장착 중인 펫무쌍 공격 보너스 스킬 스냅샷
        for (var skillIndex = 0; skillIndex < GLOBAL_CONFIG.petMusou.bonusAttackSkillNames.length; skillIndex++) {
            var candidateSkillName = GLOBAL_CONFIG.petMusou.bonusAttackSkillNames[skillIndex];
            if (hasPetSkill(petSkillData, user, candidateSkillName)) {
                equippedBonusAttackSkillNames.push(candidateSkillName);
            }
        }
        var maxAttacks = GLOBAL_CONFIG.petMusou.attackLimit + (equippedBonusAttackSkillNames.length * GLOBAL_CONFIG.petMusou.bonusAttackCount); // 대회 시작 시 장착 스킬을 반영한 개인 공격 한도
        players[user] = {
            alive: true,
            attacksLeft: maxAttacks,
            maxAttacks: maxAttacks,
            bonusAttackSkillNames: equippedBonusAttackSkillNames,
            guildId: guildInfo.guildId,
            totalCharmSnapshot: createPetMusouBattleSnapshot(user, totalCharm, petData, data)
        };
        validUsers.push(user);
    }
    if (validUsers.length < 1) return { ok: false, message: "❌ 참가 조건을 충족한 펫무쌍 참가자가 없습니다." };

    var activeParticipants = {}; // 조건 재확인을 통과해 현재 회차에 확정된 참가자 목록
    for (var activeParticipantIndex = 0; activeParticipantIndex < validUsers.length; activeParticipantIndex++) {
        activeParticipants[validUsers[activeParticipantIndex]] = preparedParticipants[validUsers[activeParticipantIndex]];
    }
    musou.participants = activeParticipants;
    musou.nextParticipants = {};
    musou.active = true;
    musou.signupOpen = false;
    musou.roundId = musou.nextRoundId || (String(getTodaySupportPassDateValue()) + "_" + String(new Date().getTime()));
    musou.nextRoundId = "";
    musou.startedAt = formatDateTime(new Date());
    musou.endedAt = "";
    musou.realFlagNo = Math.floor(Math.random() * GLOBAL_CONFIG.petMusou.flagCount) + 1;
    musou.realFlagFound = false;
    musou.realFlagDiscoveryBonusPaid = false;
    musou.realFlagDiscovery = null;
    musou.fakeFlags = {};
    musou.currentHolder = "";
    musou.players = players;
    musou.turnQueue = shufflePetMusouUsers(validUsers);
    musou.roundNo = 1;
    musou.actionSeq = 0;
    musou.lightningRate = GLOBAL_CONFIG.petMusou.lightningStartRate;
    musou.turnToken = "";
    musou.turnDeadlineAt = 0;
    var startGraceNow = new Date().getTime(); // 참가 확정 시각
    musou.startReady = false;
    musou.startGraceToken = String(startGraceNow) + "_" + String(Math.random());
    musou.startGraceDeadlineAt = startGraceNow + GLOBAL_CONFIG.petMusou.startGraceMs;
    musou.lastActionId = "";
    return {
        ok: true,
        excludedUsers: excludedUsers,
        message: "🗡️ 펫 무쌍 대회 시작 🗡️\n" +
            "━━━━━━━━━━━━━━━━\n" +
            "참가자: " + validUsers.length + "명\n" +
            "개인 공격권: 기본 " + GLOBAL_CONFIG.petMusou.attackLimit + "회 · " + GLOBAL_CONFIG.petMusou.bonusAttackSkillNames.join("·") + " 각각 장착 시 +" + GLOBAL_CONFIG.petMusou.bonusAttackCount + "회\n" +
            "공격 제한시간: " + Math.floor(GLOBAL_CONFIG.petMusou.turnTimeoutMs / 1000) + "초\n\n" +
            "참가 모집이 끝났습니다. 첫 공격을 시작합니다.\n\n" +
            "10개의 깃발 중 진짜 깃발은 단 1개!\n" +
            "처음 발견한 가짜 깃발은 공격권만 차감됩니다.\n" +
            "공개된 가짜를 다시 공격하면 즉시 탈락합니다.\n\n" +
            "⚡ 최초 누적 벼락발생확률: 1.0%\n" +
            "━━━━━━━━━━━━━━━━\n" +
            "펫무쌍 공격은 공성전 방에서만 가능합니다.\n" +
            "https://open.kakao.com/o/gaP4Xybh" +
            (excludedUsers.length > 0 ? "\n\n참가 조건 재확인 제외: " + excludedUsers.join(", ") : "") +
            "\n\n" + buildPetMusouAliveParticipantList(data, petData, guildData, musou)
    };
}

// 펫무쌍 현재 공격자를 반환하는 함수
function getPetMusouCurrentAttacker(musou) {
    return musou && musou.turnQueue && musou.turnQueue.length > 0 ? musou.turnQueue[0] : "";
}

// 펫무쌍에서 다음 라운드 공격 순서를 구성하는 함수
function preparePetMusouNextRound(musou) {
    var candidates = [];
    for (var user in musou.players) {
        if (!musou.players.hasOwnProperty(user)) continue;
        var player = musou.players[user];
        if (player.alive && player.attacksLeft > 0 && user !== musou.currentHolder) candidates.push(user);
    }
    musou.turnQueue = shufflePetMusouUsers(candidates);
    if (candidates.length > 0) musou.roundNo++;
    return candidates.length;
}

// 펫무쌍 종료 조건을 확인하는 함수
function shouldFinishPetMusou(musou) {
    var attackableCount = 0;
    for (var user in musou.players) {
        if (!musou.players.hasOwnProperty(user)) continue;
        var player = musou.players[user];
        if (player.alive && player.attacksLeft > 0 && user !== musou.currentHolder) attackableCount++;
    }
    return attackableCount === 0;
}

// 펫무쌍 우승 보상과 누적 순위를 회차당 한 번만 확정하는 함수
function finishPetMusou(data, petData, petSkillData, guildData, reason) {
    var musou = ensurePetMusouData(data);
    if (!musou.active) return { ended: false, message: "❌ 현재 진행 중인 펫무쌍 대회가 없습니다." };
    var roundId = musou.roundId;
    var winner = musou.currentHolder && musou.players[musou.currentHolder] && musou.players[musou.currentHolder].alive ? musou.currentHolder : "";
    var alreadyProcessed = !!musou.processedRounds[roundId];
    clearPetMusouOpeningTimer();
    clearPetMusouTurnTimer();
    musou.active = false;
    musou.signupOpen = true;
    musou.endedAt = formatDateTime(new Date());
    musou.turnToken = "";
    musou.turnDeadlineAt = 0;
    musou.startReady = false;
    musou.startGraceToken = "";
    musou.startGraceDeadlineAt = 0;
    musou.turnQueue = [];
    musou.participants = {};
    if (!musou.nextRoundId) musou.nextRoundId = "PREP_" + String(new Date().getTime());
    if (!alreadyProcessed) {
        musou.processedRounds[roundId] = { winner: winner, endedAt: musou.endedAt, reason: reason || "자동 종료" };
        if (winner && data.member[winner]) {
            data.member[winner].point = (data.member[winner].point || 0) + GLOBAL_CONFIG.petMusou.winnerRewardPoint;
            data.member[winner].musouWinCount = (data.member[winner].musouWinCount || 0) + 1;
            data.member[winner].musouLastWinAt = musou.endedAt;
            musou.currentChampion = {
                user: winner,
                roundId: roundId,
                wonAt: musou.endedAt,
                expiresAt: new Date().getTime() + GLOBAL_CONFIG.petMusou.titleDurationMs
            };
        }
    }
    var nextAutoReadyResult = autoRegisterHoiPassPremiumPetMusouUsers(data, petData, petSkillData, guildData, "");
    var nextAutoReadyMessage = "\n\n🤖 다음 회차 자동 준비: " + nextAutoReadyResult.registeredCount + "명";
    if (nextAutoReadyResult.skippedCount > 0 || nextAutoReadyResult.failedCount > 0) {
        nextAutoReadyMessage += " (제외 " + nextAutoReadyResult.skippedCount + "명 · 실패 " + nextAutoReadyResult.failedCount + "명)";
    }
    if (!winner) {
        return {
            ended: true,
            winner: "",
            message: "🏆 펫 무쌍 대회 종료 🏆\n" +
                "━━━━━━━━━━━━━━━━\n" +
                "최종 점령자가 없어 우승자 없이 종료됩니다.\n" +
                "공격 보상은 회수하지 않습니다." + nextAutoReadyMessage
        };
    }
    var guildInfo = getPetMusouGuildInfo(data, guildData, winner);
    return {
        ended: true,
        winner: winner,
        message: "🏆 펫 무쌍 대회 종료 🏆\n" +
            "━━━━━━━━━━━━━━━━\n" +
            "🚩 최종 점령자: [" + checkRank(data, petData, guildData, winner).replace(/^\[무쌍⚔️\]/, "") + "]\n" +
            "🏳️ 소속길드: " + (guildInfo ? formatGuildDisplay(guildInfo.guild) : "길드 정보 없음") + "\n\n" +
            "우승 상금🤑: 🅟" + (GLOBAL_CONFIG.petMusou.winnerRewardPoint / 100000000) + "억\n" +
            "전용 칭호⚔️: [무쌍⚔️]\n" +
            "적용 기간⏰: 24시간\n" +
            "누적 무쌍⚔️: " + (data.member[winner].musouWinCount || 0) + "회\n\n" +
            "[무쌍⚔️][" + checkRank(data, petData, guildData, winner).replace(/^\[무쌍⚔️\]/, "") + "] 님이\n" +
            "펫 무쌍 대회의 최종 우승자가 되었습니다!" + nextAutoReadyMessage
    };
}

// 펫무쌍 진행 상태와 전 유저의 참가·누적 전적을 초기화하는 함수
function resetAllPetMusouData(data) {
    clearPetMusouOpeningTimer();
    clearPetMusouTurnTimer();
    var signupUserCount = 0; // 당일 참가 표시가 제거된 유저 수
    var rankingUserCount = 0; // 누적 무쌍 기록이 제거된 유저 수
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || !data.member[user]) continue;
        var member = data.member[user];
        if (member.petMusouLastSignupDate !== undefined) {
            delete member.petMusouLastSignupDate;
            signupUserCount++;
        }
        if (member.musouWinCount !== undefined || member.musouLastWinAt !== undefined) {
            delete member.musouWinCount;
            delete member.musouLastWinAt;
            rankingUserCount++;
        }
    }
    data.petMusou = {};
    ensurePetMusouData(data);
    return { signupUserCount: signupUserCount, rankingUserCount: rankingUserCount };
}

// 펫무쌍 생존자에게 누적 확률로 벼락을 판정하는 함수
function processPetMusouLightning(musou, data, petData, guildData) {
    var currentRate = Math.max(0, Math.min(1, musou.lightningRate));
    if (Math.random() >= currentRate) {
        musou.lightningRate = Math.min(1, currentRate + GLOBAL_CONFIG.petMusou.lightningStepRate);
        musou.lastLightningResult = {
            triggered: false,
            checkedAt: formatDateTime(new Date()),
            checkedRate: currentRate,
            nextRate: musou.lightningRate
        };
        return { triggered: false, message: "⚡ 벼락 미발생 · 다음 확률 " + (musou.lightningRate * 100).toFixed(1) + "%" };
    }
    var aliveUsers = [];
    for (var user in musou.players) {
        if (musou.players.hasOwnProperty(user) && musou.players[user].alive) aliveUsers.push(user);
    }
    var targetCount = Math.floor(Math.random() * 3) + 1;
    var targets = shufflePetMusouUsers(aliveUsers).slice(0, Math.min(targetCount, aliveUsers.length));
    var eliminatedTargets = []; // 피뢰침 방어 후 실제 벼락으로 탈락한 유저
    var protectedTargets = []; // 피뢰침 1개를 자동 소모하고 생존한 유저
    var failedRodTargets = []; // 피뢰침 방어 판정에 실패한 유저
    var holderExceptionTargets = []; // 진짜 깃발 점령으로 피뢰침이 적용되지 않은 유저
    for (var targetIndex = 0; targetIndex < targets.length; targetIndex++) {
        var target = targets[targetIndex];
        var targetBag = data.member[target] && data.member[target].bag ? data.member[target].bag : null;
        var lightningRodName = GLOBAL_CONFIG.petMusou.items.lightningRod;
        var hasLightningRod = targetBag && Number(targetBag[lightningRodName]) > 0;
        if (hasLightningRod && musou.currentHolder === target) {
            holderExceptionTargets.push(target);
        } else if (hasLightningRod && Math.random() < GLOBAL_CONFIG.petMusou.lightningRodSuccessRate) {
            decreaseGuildTerritoryItem(data, target, lightningRodName);
            protectedTargets.push(target);
            continue;
        } else if (hasLightningRod) {
            failedRodTargets.push(target);
        }
        musou.players[target].alive = false;
        musou.players[target].attacksLeft = 0;
        if (musou.currentHolder === target) musou.currentHolder = "";
        eliminatedTargets.push(target);
    }
    var lines = ["🗡️펫 무쌍 대회 결과🗡️[벼락 발생⚡]", "우루루⚡ 캉캉캉⚡ 뿌라찌랴쨖쨖⚡", "━━━━━━━━━━━━", "벼락 판정⚡: [⚡]벼락 발생!", "━━━━━━━━━━━━", "└ 벼락 탈락 인원: " + eliminatedTargets.length + "명"];
    for (var eliminatedIndex = 0; eliminatedIndex < eliminatedTargets.length; eliminatedIndex++) {
        lines.push("  └[" + checkRank(data, petData, guildData, eliminatedTargets[eliminatedIndex]) + "] 님이 객사(탈락)");
    }
    if (protectedTargets.length > 0) {
        lines.push("━━━━━━━━━━━━", "└ 피뢰침⚡(" + (GLOBAL_CONFIG.petMusou.lightningRodSuccessRate * 100).toFixed(0) + "%) 발동: " + protectedTargets.length + "명");
        for (var protectedIndex = 0; protectedIndex < protectedTargets.length; protectedIndex++) {
            lines.push("  └[" + checkRank(data, petData, guildData, protectedTargets[protectedIndex]) + "] 피뢰침 1개 소모 · 생존");
        }
    }
    if (failedRodTargets.length > 0) {
        lines.push("━━━━━━━━━━━━", "└ 피뢰침⚡(" + (GLOBAL_CONFIG.petMusou.lightningRodSuccessRate * 100).toFixed(0) + "%) 미발동: " + failedRodTargets.length + "명");
        for (var failedRodIndex = 0; failedRodIndex < failedRodTargets.length; failedRodIndex++) {
            lines.push("  └[" + checkRank(data, petData, guildData, failedRodTargets[failedRodIndex]) + "] 피뢰침 미소모 · 탈락");
        }
    }
    if (holderExceptionTargets.length > 0) {
        lines.push("━━━━━━━━━━━━", "└ 진짜 깃발 점령자 예외: " + holderExceptionTargets.length + "명");
        for (var holderExceptionIndex = 0; holderExceptionIndex < holderExceptionTargets.length; holderExceptionIndex++) {
            lines.push("  └[" + checkRank(data, petData, guildData, holderExceptionTargets[holderExceptionIndex]) + "] 피뢰침 미적용·미소모 · 탈락");
        }
    }
    musou.turnQueue = musou.turnQueue.filter(function (queuedUser) {
        return musou.players[queuedUser] && musou.players[queuedUser].alive && musou.players[queuedUser].attacksLeft > 0 && queuedUser !== musou.currentHolder;
    });
    musou.lightningRate = GLOBAL_CONFIG.petMusou.lightningStartRate;
    musou.lastLightningResult = {
        triggered: true,
        checkedAt: formatDateTime(new Date()),
        checkedRate: currentRate,
        targets: targets.slice(),
        eliminatedTargets: eliminatedTargets.slice(),
        protectedTargets: protectedTargets.slice(),
        failedRodTargets: failedRodTargets.slice(),
        holderExceptionTargets: holderExceptionTargets.slice(),
        nextRate: musou.lightningRate
    };
    lines.push("━━━━━━━━━━━━");
    lines.push("누적 벼락발생확률이 1.0%로 초기화됩니다.");
    return { triggered: true, targets: targets, eliminatedTargets: eliminatedTargets, protectedTargets: protectedTargets, failedRodTargets: failedRodTargets, holderExceptionTargets: holderExceptionTargets, message: lines.join("\n") };
}

// 펫무쌍 방어권→공격권→종합매력 순서로 점령 결투를 판정하는 함수
function resolvePetMusouBattle(data, petData, musou, attackerName, defenderName) {
    var defenseItem = getGuildTerritorySpecialItem(data.member[defenderName].bag, [
        { name: "영지절대방어권🛡(50%)", successRate: 0.5, label: "절대🛡(50%)" }
    ]);
    if (defenseItem && Math.random() <= defenseItem.successRate) {
        decreaseGuildTerritoryItem(data, defenderName, defenseItem.name);
        return { attackerWin: false, defenseItem: defenseItem, offenseItem: null, attacker: null, defender: null };
    }
    var offenseItem = getGuildTerritorySpecialItem(data.member[attackerName].bag, [
        { name: "영지기습공격권🔥(40%)", successRate: 0.4, label: "기습🔥(40%)" }
    ]);
    if (offenseItem && Math.random() <= offenseItem.successRate) {
        decreaseGuildTerritoryItem(data, attackerName, offenseItem.name);
        return { attackerWin: true, defenseItem: null, offenseItem: offenseItem, attacker: null, defender: null };
    }
    var attackerSnapshot = musou.players[attackerName].totalCharmSnapshot;
    var defenderSnapshot = musou.players[defenderName].totalCharmSnapshot;
    var attackerCritical = Math.random() < attackerSnapshot.critChance;
    var defenderCritical = Math.random() < defenderSnapshot.critChance;
    var attackerFinal = attackerCritical ? Math.round(attackerSnapshot.baseExp * attackerSnapshot.critMultiplier) : attackerSnapshot.baseExp;
    var defenderFinal = defenderCritical ? Math.round(defenderSnapshot.baseExp * defenderSnapshot.critMultiplier) : defenderSnapshot.baseExp;
    return {
        attackerWin: attackerFinal > defenderFinal,
        defenseItem: null,
        offenseItem: null,
        attacker: { name: attackerName, petName: attackerSnapshot.petName, baseExp: attackerSnapshot.baseExp, finalExp: attackerFinal, isCritical: attackerCritical },
        defender: { name: defenderName, petName: defenderSnapshot.petName, baseExp: defenderSnapshot.baseExp, finalExp: defenderFinal, isCritical: defenderCritical }
    };
}

// 펫무쌍 종합매력 결투 상세 메시지를 생성하는 함수
function buildPetMusouBattleMessage(data, petData, guildData, result) {
    if (result.defenseItem) return "🛡 방어성공 [" + result.defenseItem.label + "] 발동\n[공격 실패❌]";
    if (result.offenseItem) return "🔥 공격 성공! [" + result.offenseItem.label + "] 발동\n[공격 성공✅]";
    var compareSymbol = result.attacker.finalExp > result.defender.finalExp ? ">" : result.attacker.finalExp < result.defender.finalExp ? "<" : "=";
    var lines = [result.attackerWin ? "[공격 성공✅]" : "[공격 실패❌]", "━━━━━━━━━━━━", "펫무쌍 결과 상세보기📋" + allsee, "⚔️ 공격", "유저: " + checkRank(data, petData, guildData, result.attacker.name), "펫: [" + result.attacker.petName + "]", "기본: " + numberWithCommas(result.attacker.baseExp) + "💕", "최종: " + numberWithCommas(result.attacker.finalExp) + "💕" + (result.attacker.isCritical ? " 💥크리티컬" : ""), "", "              🆚", "", "🛡️ 방어", "유저: " + checkRank(data, petData, guildData, result.defender.name), "펫: [" + result.defender.petName + "]", "기본: " + numberWithCommas(result.defender.baseExp) + "💕", "최종: " + numberWithCommas(result.defender.finalExp) + "💕" + (result.defender.isCritical ? " 💥크리티컬" : ""), "", "━━━━━━━━━━━━", "📊 최종 매력 비교", numberWithCommas(result.attacker.finalExp) + " " + compareSymbol + " " + numberWithCommas(result.defender.finalExp), "매력 차이: " + numberWithCommas(Math.abs(result.attacker.finalExp - result.defender.finalExp)) + "💕"];
    return lines.join("\n");
}

// 양자 결투 상세가 없는 펫무쌍 공격의 시작 시점 능력치를 출력하는 함수
function buildPetMusouAttackDetailMessage(data, petData, guildData, musou, attackerName) {
    var player = musou.players[attackerName];
    var snapshot = player && player.totalCharmSnapshot ? player.totalCharmSnapshot : null;
    if (!snapshot) return "";
    return "펫무쌍 공격 상세정보📋" + allsee + "\n" +
        "⚔️ 공격\n" +
        "유저: " + checkRank(data, petData, guildData, attackerName) + "\n" +
        "펫: [" + snapshot.petName + "]\n" +
        "종합매력(시작 기준): " + numberWithCommas(snapshot.baseExp) + "💕";
}

// 현재 탈락하지 않은 펫무쌍 참가자 명단을 생성하는 함수
function buildPetMusouAliveParticipantList(data, petData, guildData, musou) {
    var names = [];
    for (var user in musou.players) {
        if (musou.players.hasOwnProperty(user) && musou.players[user].alive) names.push("• " + checkRank(data, petData, guildData, user));
    }
    return "👥 참가자 명단 (" + names.length + "명)" + allsee + "\n" + names.join("\n");
}

// 펫무쌍 현재 공격 차례와 깃발·생존 참가자 상태를 출력하는 함수
function buildPetMusouStatusMessage(data, petData, guildData, musou) {
    var attacker = getPetMusouCurrentAttacker(musou);
    if (!attacker) return "";
    var player = musou.players[attacker];
    var maxAttacks = parseInt(player.maxAttacks, 10) || GLOBAL_CONFIG.petMusou.attackLimit; // 구버전 진행 데이터는 기본 공격 한도로 표시
    var lines = ["[" + checkRank(data, petData, guildData, attacker) + "] 님의 공격 차례입니다.", "[⏳ 제한시간: " + Math.floor(GLOBAL_CONFIG.petMusou.turnTimeoutMs / 1000) + "초]", "[남은 공격(" + player.attacksLeft + "/" + maxAttacks + "⚔)]"];
    if (maxAttacks > GLOBAL_CONFIG.petMusou.attackLimit) {
        var equippedBonusAttackSkillNames = player.bonusAttackSkillNames || (player.bonusAttackSkillName ? [player.bonusAttackSkillName] : ["무쌍신화"]); // 구버전 진행 데이터의 단일 스킬 스냅샷도 함께 지원
        for (var bonusSkillIndex = 0; bonusSkillIndex < equippedBonusAttackSkillNames.length; bonusSkillIndex++) {
            if (equippedBonusAttackSkillNames[bonusSkillIndex] === GLOBAL_CONFIG.petMusou.attackRewardBonusSkillName) {
                lines.push("무쌍귀신📙[A]: 공격횟수+1 · 공격 보상+1억");
            } else {
                lines.push("무쌍신화📙[B]: 어이 원코(공격횟수+1)");
            }
        }
    }
    lines.push("[⚡ 누적 벼락발생확률: " + (musou.lightningRate * 100).toFixed(1) + "%]", "━━━━━━━━━━━━━━━━", "🗡️현재 펫 무쌍 대회 상황🗡️", "━━━━━━━━━━━━");
    for (var flagNo = 1; flagNo <= GLOBAL_CONFIG.petMusou.flagCount; flagNo++) {
        var stateText = "미확인(❓)";
        if (musou.realFlagFound && flagNo === musou.realFlagNo) {
            stateText = musou.currentHolder ? checkRank(data, petData, guildData, musou.currentHolder) + "(🚩)" : "주인 없음(🚩)";
        } else if (musou.fakeFlags[String(flagNo)] || musou.realFlagFound) {
            stateText = "가짜(✖️)";
        }
        lines.push("[" + flagNo + "] " + getPetMusouFlagName(flagNo) + ": " + stateText);
    }
    lines.push("━━━━━━━━━━━━", "[" + checkRank(data, petData, guildData, attacker) + "] 님의 공격 차례입니다.", buildPetMusouAliveParticipantList(data, petData, guildData, musou));
    return lines.join("\n");
}

// 펫무쌍 공격 1회를 처리하고 다음 턴 또는 종료 결과를 반환하는 함수
function processPetMusouAttack(data, petData, petSkillData, guildData, sender, flagNo) {
    var musou = ensurePetMusouData(data);
    if (!musou.active) return { ok: false, message: "❌ 현재 진행 중인 펫무쌍 대회가 없습니다." };
    if (!musou.startReady) {
        var remainingGraceSeconds = Math.max(1, Math.ceil((musou.startGraceDeadlineAt - new Date().getTime()) / 1000));
        return { ok: false, message: "⏳ 펫무쌍 시작 준비 중입니다.\n첫 공격은 " + remainingGraceSeconds + "초 뒤 시작됩니다." };
    }
    if (!musou.players[sender]) return { ok: false, message: "❌ 펫무쌍 참가자만 공격할 수 있습니다." };
    if (!musou.players[sender].alive) return { ok: false, message: "❌ 이미 펫무쌍에서 탈락했습니다." };
    if (musou.players[sender].attacksLeft < 1) return { ok: false, message: "❌ 남은 펫무쌍 공격권이 없습니다." };
    var currentAttacker = getPetMusouCurrentAttacker(musou);
    if (currentAttacker !== sender) return { ok: false, message: "❌ 현재 공격 차례가 아닙니다.\n현재 공격자: " + currentAttacker };
    if (!getPetMusouGuildInfo(data, guildData, sender)) return { ok: false, message: "❌ 길드 가입 상태가 확인되지 않아 공격할 수 없습니다." };
    if (new Date().getTime() > musou.turnDeadlineAt) return { ok: false, expired: true, message: "❌ 공격 제한시간이 지났습니다." };
    clearPetMusouTurnTimer();
    musou.turnQueue.shift();
    musou.players[sender].attacksLeft--;
    var ticketEventCouponReward = grantPetMusouTicketEventCoupon(data, sender); // 유효 공격권 차감 후 확정되는 이벤트 쿠폰
    musou.actionSeq++;
    musou.lastActionId = musou.roundId + "_" + musou.actionSeq;
    musou.turnToken = "";
    musou.turnDeadlineAt = 0;
    var lines = ["🗡️펫 무쌍 대회 결과🗡️", "━━━━━━━━━━━━", "공격자: [" + checkRank(data, petData, guildData, sender) + "]", "공격 깃발: [" + flagNo + "] " + getPetMusouFlagName(flagNo)];
    var rewardGranted = false;
    var attackSucceeded = false; // 깃발 발견·점령·전투 승리 여부에 따른 공격 성공 판정
    var hasBattleDetail = false; // 공격자·점령자 양쪽의 종합매력 상세 출력 여부
    var equippedBonusAttackSkillNames = musou.players[sender].bonusAttackSkillNames || (musou.players[sender].bonusAttackSkillName ? [musou.players[sender].bonusAttackSkillName] : []); // 구버전 단일 스킬 스냅샷을 포함한 공격 보너스 스킬 목록
    var rewardBonusActive = equippedBonusAttackSkillNames.indexOf(GLOBAL_CONFIG.petMusou.attackRewardBonusSkillName) !== -1; // 시작 시 저장한 무쌍귀신 공격 보상 적용 여부
    var attackRewardPoint = GLOBAL_CONFIG.petMusou.attackRewardPoint + (rewardBonusActive ? GLOBAL_CONFIG.petMusou.attackRewardBonusPoint : 0); // 이번 공격의 최종 포인트 보상
    var attackRewardText = "🅟" + (attackRewardPoint / 100000000) + "억";
    var discoveryBonusPoint = 0; // 진짜 깃발 최초 발견 시 별도 지급되는 보너스 포인트

    if (!musou.realFlagFound && musou.fakeFlags[String(flagNo)]) {
        musou.players[sender].alive = false;
        musou.players[sender].attacksLeft = 0;
        lines.push("공격 보상🤑: 미지급", "", "이미 가짜로 밝혀진 깃발입니다!", "[" + checkRank(data, petData, guildData, sender) + "] 님은 즉시 탈락합니다.");
    } else if (!musou.realFlagFound) {
        rewardGranted = true;
        data.member[sender].point = (data.member[sender].point || 0) + attackRewardPoint;
        if (flagNo === musou.realFlagNo) {
            attackSucceeded = true;
            musou.realFlagFound = true;
            musou.currentHolder = sender;
            if (!musou.realFlagDiscoveryBonusPaid) {
                discoveryBonusPoint = GLOBAL_CONFIG.petMusou.realFlagDiscoveryBonusPoint;
                data.member[sender].point = (data.member[sender].point || 0) + discoveryBonusPoint;
                musou.realFlagDiscoveryBonusPaid = true;
                musou.realFlagDiscovery = {
                    user: sender,
                    at: formatDateTime(new Date()),
                    attackRewardPoint: attackRewardPoint,
                    discoveryBonusPoint: discoveryBonusPoint
                };
            }
            for (var fakeNo = 1; fakeNo <= GLOBAL_CONFIG.petMusou.flagCount; fakeNo++) {
                if (fakeNo !== musou.realFlagNo) musou.fakeFlags[String(fakeNo)] = true;
            }
            var discoveryTotalPoint = attackRewardPoint + discoveryBonusPoint;
            var discoveryRewardText = "🅟" + (attackRewardPoint / 100000000) + "억+" + (discoveryBonusPoint / 100000000) + "억 = " + (discoveryTotalPoint / 100000000) + "억";
            lines.push("공격 보상🤑: " + discoveryRewardText, "", "[진짜 깃발 발견🚩]", "🎁 발견 보너스: " + (discoveryBonusPoint / 100000000) + "억 포인트", "[" + checkRank(data, petData, guildData, sender) + "] 님이 진짜 깃발을 점령했습니다!");
        } else {
            musou.fakeFlags[String(flagNo)] = true;
            var attackerMaxAttacks = parseInt(musou.players[sender].maxAttacks, 10) || GLOBAL_CONFIG.petMusou.attackLimit; // 대회 시작 시 확정된 개인 공격 한도
            lines.splice(1, 0, "[" + checkRank(data, petData, guildData, sender) + "] 님의 남은 공격(" + musou.players[sender].attacksLeft + "/" + attackerMaxAttacks + "⚔)");
            lines.push("공격 보상🤑: " + attackRewardText, "", "가짜 깃발입니다!");
        }
    } else if (flagNo !== musou.realFlagNo) {
        musou.players[sender].alive = false;
        musou.players[sender].attacksLeft = 0;
        lines.push("공격 보상🤑: 미지급", "", "이미 가짜로 밝혀진 깃발입니다!", "[" + checkRank(data, petData, guildData, sender) + "] 님은 즉시 탈락합니다.");
    } else if (!musou.currentHolder) {
        attackSucceeded = true;
        rewardGranted = true;
        data.member[sender].point = (data.member[sender].point || 0) + attackRewardPoint;
        musou.currentHolder = sender;
        lines.push("공격 보상🤑: " + attackRewardText, "", "주인 없는 진짜 깃발을 즉시 점령했습니다!");
    } else {
        rewardGranted = true;
        data.member[sender].point = (data.member[sender].point || 0) + attackRewardPoint;
        var previousHolder = musou.currentHolder;
        var battleResult = resolvePetMusouBattle(data, petData, musou, sender, previousHolder);
        lines.push("공격 보상🤑: " + attackRewardText, "", buildPetMusouBattleMessage(data, petData, guildData, battleResult));
        hasBattleDetail = !!(battleResult.attacker && battleResult.defender);
        if (battleResult.attackerWin) {
            attackSucceeded = true;
            musou.currentHolder = sender;
            if (musou.players[previousHolder] && musou.players[previousHolder].alive && musou.players[previousHolder].attacksLeft > 0 && musou.turnQueue.indexOf(previousHolder) === -1) {
                musou.turnQueue.push(previousHolder);
            }
        }
    }
    if (ticketEventCouponReward) {
        for (var rewardLineIndex = 0; rewardLineIndex < lines.length; rewardLineIndex++) {
            if (String(lines[rewardLineIndex]).indexOf("공격 보상🤑:") === 0) {
                lines.splice(rewardLineIndex + 1, 0, "이벤트 보상🎟️: " + ticketEventCouponReward.display);
                break;
            }
        }
    }
    lines[0] += attackSucceeded ? "[성공✅]" : "[실패❌]";
    var lightningResult = processPetMusouLightning(musou, data, petData, guildData);
    var lightningMessage = lightningResult.triggered ? lightningResult.message : ""; // 실제 벼락 발생 문구는 공격 결과와 분리해 전송
    if (!lightningResult.triggered) lines.push("━━━━━━━━━━━━", lightningResult.message);
    if (!hasBattleDetail) {
        var attackDetailMessage = buildPetMusouAttackDetailMessage(data, petData, guildData, musou, sender);
        if (attackDetailMessage) lines.push("━━━━━━━━━━━━", attackDetailMessage);
    }
    musou.lastActionRewardGranted = rewardGranted;
    musou.lastActionAttackRewardPoint = rewardGranted ? attackRewardPoint : 0;
    musou.lastActionDiscoveryBonusPoint = discoveryBonusPoint;

    if (musou.turnQueue.length < 1 && !shouldFinishPetMusou(musou)) preparePetMusouNextRound(musou);
    if (shouldFinishPetMusou(musou)) {
        var finishResult = finishPetMusou(data, petData, petSkillData, guildData, "공격 가능 횟수 소진");
        return { ok: true, ended: true, message: lines.join("\n"), lightningMessage: lightningMessage, finishMessage: finishResult.message, ticketEventCouponReward: ticketEventCouponReward };
    }
    return { ok: true, ended: false, message: lines.join("\n"), lightningMessage: lightningMessage, statusMessage: buildPetMusouStatusMessage(data, petData, guildData, musou), ticketEventCouponReward: ticketEventCouponReward };
}

// 펫무쌍 현재 공격자의 제한시간 초과를 처리하는 함수
function processPetMusouTimeout(data, petData, petSkillData, guildData) {
    var musou = ensurePetMusouData(data);
    var attacker = getPetMusouCurrentAttacker(musou);
    if (!musou.active || !musou.startReady || !attacker || !musou.players[attacker]) return { ok: false };
    musou.turnQueue.shift();
    musou.players[attacker].alive = false;
    musou.players[attacker].attacksLeft = 0;
    musou.turnToken = "";
    musou.turnDeadlineAt = 0;
    var timeoutMember = data.member[attacker];
    var timeoutPointBefore = Math.max(0, Number(timeoutMember.point) || 0); // 시간초과 직전 보유 포인트
    var timeoutPointAfter = Math.max(0, timeoutPointBefore - GLOBAL_CONFIG.petMusou.timeoutPenaltyPoint); // 0 미만으로 내려가지 않는 패널티 적용 결과
    timeoutMember.point = timeoutPointAfter;
    var timeoutAutomationSettings = ensureHoiPassPremiumAutomationSettings(timeoutMember);
    timeoutAutomationSettings.petMusouAutoReady = false;
    appendPetMusouAutomationLog(data, {
        feature: "PET_MUSOU_AUTO_READY",
        action: "OFF",
        user: attacker,
        result: "TIMEOUT_ELIMINATED",
        reason: "펫무쌍 시간초과 탈락",
        processedAt: formatDateTime(new Date())
    });
    musou.lightningRate = Math.min(1, Math.max(0, musou.lightningRate) + GLOBAL_CONFIG.petMusou.timeoutLightningStepRate);
    var message = "🗡️펫 무쌍 대회 결과🗡️[시간 초과⚠️]\n" +
        "━━━━━━━━━━━━━━━━\n" +
        "공격 보상🤑: 미지급\n" +
        "벼락 판정⚡: 판정 없음\n" +
        "시간초과 패널티💸: -🅟1억\n" +
        "(남은 포인트 🅟" + numberWithCommas(timeoutPointAfter) + ")\n" +
        "펫무쌍 자동준비🐹: OFF [❌]\n" +
        "누적 벼락발생확률⚡: +" + (GLOBAL_CONFIG.petMusou.timeoutLightningStepRate * 100).toFixed(1) + "% (현재 " + (musou.lightningRate * 100).toFixed(1) + "%)\n\n" +
        Math.floor(GLOBAL_CONFIG.petMusou.turnTimeoutMs / 1000) + "초 이내에 공격하지 않아 즉시 탈락합니다.\n" +
        "남은 공격권이 모두 소멸했습니다.";
    if (musou.turnQueue.length < 1 && !shouldFinishPetMusou(musou)) preparePetMusouNextRound(musou);
    if (shouldFinishPetMusou(musou)) {
        var finishResult = finishPetMusou(data, petData, petSkillData, guildData, "공격 제한시간 종료");
        return { ok: true, ended: true, message: message, finishMessage: finishResult.message };
    }
    return { ok: true, ended: false, message: message, statusMessage: buildPetMusouStatusMessage(data, petData, guildData, musou) };
}

// 펫무쌍 실행 컨텍스트의 시작 유예 타이머를 해제하는 함수
function clearPetMusouOpeningTimer(ctx) {
    var targetCtx = ctx || getCurrentContext();
    var ctxKey = targetCtx.key();
    if (petMusouOpeningTimers[ctxKey]) {
        clearTimeout(petMusouOpeningTimers[ctxKey]);
        delete petMusouOpeningTimers[ctxKey];
    }
}

// 펫무쌍 참가 모집 종료 후 참가자를 확정하고 첫 공격을 시작하는 함수
function openPetMusouForAttacks(data, petData, petSkillData, guildData, replier, isGroupChat, homeData) {
    var musou = ensurePetMusouData(data);
    if (!musou.active || musou.startReady) return false;
    if (musou.signupOpen) {
        var startResult = beginPetMusou(data, petData, homeData, petSkillData, guildData, true);
        if (!startResult.ok) {
            musou.active = false;
            musou.startGraceToken = "";
            musou.startGraceDeadlineAt = 0;
            saveJsonFile(data, filePath);
            castleMsg(startResult.message, replier, true);
            return false;
        }
        musou.startReady = true;
        musou.startGraceToken = "";
        musou.startGraceDeadlineAt = 0;
        saveJsonFile(data, filePath);
        castleMsg(startResult.message, replier, true);
    }
    if (!getPetMusouCurrentAttacker(musou)) return false;
    musou.startReady = true;
    musou.startGraceToken = "";
    musou.startGraceDeadlineAt = 0;
    startPetMusouTurnTimer(data, petData, petSkillData, guildData, replier, isGroupChat, false);
    castleMsg(buildPetMusouStatusMessage(data, petData, guildData, musou), replier, isGroupChat);
    return true;
}

// 펫무쌍 저장 마감시각을 기준으로 참가 모집 타이머를 예약하거나 복구하는 함수
function startPetMusouOpeningTimer(data, petData, petSkillData, guildData, replier, isGroupChat, preserveDeadline) {
    var musou = ensurePetMusouData(data);
    if (!musou.active || musou.startReady) return;
    var timerCtx = getCurrentContext();
    var timerCtxKey = timerCtx.key();
    clearPetMusouOpeningTimer(timerCtx);
    var now = new Date().getTime();
    if (!preserveDeadline || !musou.startGraceToken || musou.startGraceDeadlineAt <= 0) {
        musou.startGraceToken = String(now) + "_" + String(Math.random());
        musou.startGraceDeadlineAt = now + GLOBAL_CONFIG.petMusou.startGraceMs;
        saveJsonFile(data, filePath);
    }
    var token = musou.startGraceToken;
    var delayMs = Math.max(1, musou.startGraceDeadlineAt - now);
    petMusouOpeningTimers[timerCtxKey] = setTimeout(function () {
        var prevCtx = enterCommandContext(timerCtx);
        var timerTransactionAcquired = false;
        var timerTransactionEntered = false;
        try {
            dataTransactionLock.lock();
            timerTransactionAcquired = true;
            beginDataSaveTransaction();
            timerTransactionEntered = true;
            delete petMusouOpeningTimers[timerCtxKey];
            var latestData = loadJsonFile(filePath);
            var latestMusou = ensurePetMusouData(latestData);
            if (!latestMusou.active || latestMusou.startReady || latestMusou.startGraceToken !== token) return;
            var latestPetData = loadJsonFile(memberPetPath);
            var latestPetSkillData = loadJsonFile(petSkillDataPath);
            var latestGuildData = loadJsonFile(guildPath);
            var latestHomeData = loadJsonFile(homeDataFile);
            openPetMusouForAttacks(latestData, latestPetData, latestPetSkillData, latestGuildData, replier, isGroupChat, latestHomeData);
        } finally {
            if (timerTransactionEntered) endDataSaveTransaction();
            if (timerTransactionAcquired) dataTransactionLock.unlock();
            exitCommandContext(prevCtx);
        }
    }, delayMs);
}

// 펫무쌍 실행 컨텍스트의 턴 타이머를 해제하는 함수
function clearPetMusouTurnTimer(ctx) {
    var targetCtx = ctx || getCurrentContext();
    var ctxKey = targetCtx.key();
    if (petMusouTurnTimers[ctxKey]) {
        clearTimeout(petMusouTurnTimers[ctxKey]);
        delete petMusouTurnTimers[ctxKey];
    }
}

// 펫무쌍 현재 턴의 제한시간 타이머를 시작하거나 저장된 마감시각으로 복구하는 함수
function startPetMusouTurnTimer(data, petData, petSkillData, guildData, replier, isGroupChat, preserveDeadline) {
    var musou = ensurePetMusouData(data);
    var attacker = getPetMusouCurrentAttacker(musou);
    if (!musou.active || !musou.startReady || !attacker) return;
    var timerCtx = getCurrentContext();
    var timerCtxKey = timerCtx.key();
    clearPetMusouTurnTimer(timerCtx);
    var now = new Date().getTime();
    if (!preserveDeadline || !musou.turnToken || musou.turnDeadlineAt <= now) {
        musou.turnToken = String(now) + "_" + String(Math.random());
        musou.turnDeadlineAt = now + GLOBAL_CONFIG.petMusou.turnTimeoutMs;
    }
    var token = musou.turnToken;
    var delayMs = Math.max(1, musou.turnDeadlineAt - now);
    saveJsonFile(data, filePath);
    petMusouTurnTimers[timerCtxKey] = setTimeout(function () {
        var prevCtx = enterCommandContext(timerCtx);
        var timerTransactionAcquired = false;
        var timerTransactionEntered = false;
        try {
            dataTransactionLock.lock();
            timerTransactionAcquired = true;
            beginDataSaveTransaction();
            timerTransactionEntered = true;
            delete petMusouTurnTimers[timerCtxKey];
            var latestData = loadJsonFile(filePath);
            var latestMusou = ensurePetMusouData(latestData);
            if (!latestMusou.active || latestMusou.turnToken !== token) return;
            var latestPetData = loadJsonFile(memberPetPath);
            var latestPetSkillData = loadJsonFile(petSkillDataPath);
            var latestGuildData = loadJsonFile(guildPath);
            var timeoutResult = processPetMusouTimeout(latestData, latestPetData, latestPetSkillData, latestGuildData);
            if (!timeoutResult.ok) return;
            saveJsonFile(latestData, filePath);
            castleMsg(timeoutResult.message, replier, isGroupChat);
            if (timeoutResult.ended) {
                if (timeoutResult.finishMessage) castleMsg(timeoutResult.finishMessage, replier, isGroupChat);
                return;
            }
            castleMsg(timeoutResult.statusMessage, replier, isGroupChat);
            startPetMusouTurnTimer(latestData, latestPetData, latestPetSkillData, latestGuildData, replier, isGroupChat, false);
        } finally {
            if (timerTransactionEntered) endDataSaveTransaction();
            if (timerTransactionAcquired) dataTransactionLock.unlock();
            exitCommandContext(prevCtx);
        }
    }, delayMs);
}

// 봇 재시작 후 저장된 펫무쌍 턴을 다음 수신 메시지에서 복구하는 함수
function recoverPetMusouTurnIfNeeded(data, petData, petSkillData, guildData, replier, isGroupChat, homeData) {
    var musou = ensurePetMusouData(data);
    if (!musou.active) return;
    var ctx = getCurrentContext();
    if (!musou.startReady) {
        if (petMusouOpeningTimers[ctx.key()]) return;
        if (musou.startGraceDeadlineAt > 0 && musou.startGraceDeadlineAt <= new Date().getTime()) {
            openPetMusouForAttacks(data, petData, petSkillData, guildData, replier, isGroupChat, homeData);
            return;
        }
        startPetMusouOpeningTimer(data, petData, petSkillData, guildData, replier, isGroupChat, true);
        return;
    }
    if (petMusouTurnTimers[ctx.key()]) return;
    if (musou.turnDeadlineAt > 0 && musou.turnDeadlineAt <= new Date().getTime()) {
        var timeoutResult = processPetMusouTimeout(data, petData, petSkillData, guildData);
        if (!timeoutResult.ok) return;
        saveJsonFile(data, filePath);
        castleMsg(timeoutResult.message, replier, isGroupChat);
        if (timeoutResult.ended) {
            if (timeoutResult.finishMessage) castleMsg(timeoutResult.finishMessage, replier, isGroupChat);
            return;
        }
        castleMsg(timeoutResult.statusMessage, replier, isGroupChat);
        startPetMusouTurnTimer(data, petData, petSkillData, guildData, replier, isGroupChat, false);
        return;
    }
    startPetMusouTurnTimer(data, petData, petSkillData, guildData, replier, isGroupChat, true);
}

// 누적 펫무쌍 우승 순위와 현재 칭호 보유자를 출력하는 함수
function buildPetMusouRankingMessage(data, petData, guildData) {
    var musou = ensurePetMusouData(data);
    var users = [];
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var winCount = parseInt(data.member[user].musouWinCount, 10) || 0;
        if (winCount > 0) users.push({ user: user, winCount: winCount, lastWinAt: data.member[user].musouLastWinAt || "" });
    }
    users.sort(function (a, b) {
        if (a.winCount !== b.winCount) return b.winCount - a.winCount;
        if (a.lastWinAt !== b.lastWinAt) return a.lastWinAt < b.lastWinAt ? 1 : -1;
        return a.user < b.user ? -1 : a.user > b.user ? 1 : 0;
    });
    var lines = ["⚔️ 펫무쌍 누적 순위 ⚔️", "━━━━━━━━━━━━━━━━"];
    if (users.length < 1) {
        lines.push("아직 펫무쌍 대회 우승자가 없습니다.");
    } else {
        for (var i = 0; i < Math.min(10, users.length); i++) {
            lines.push((i + 1) + ". [" + checkRank(data, petData, guildData, users[i].user).replace(/^\[무쌍⚔️\]/, "") + "] — 무쌍 " + users[i].winCount + "회");
        }
    }
    lines.push("━━━━━━━━━━━━━━━━");
    var champion = musou.currentChampion;
    if (champion && champion.user && champion.expiresAt > new Date().getTime() && data.member[champion.user]) {
        var remainMs = champion.expiresAt - new Date().getTime();
        var remainHours = Math.floor(remainMs / 3600000);
        var remainMinutes = Math.floor((remainMs % 3600000) / 60000);
        lines.push("🚩 현재 무쌍: [무쌍⚔️][" + checkRank(data, petData, guildData, champion.user).replace(/^\[무쌍⚔️\]/, "") + "]");
        lines.push("└ 칭호 남은시간: " + remainHours + "시간 " + remainMinutes + "분");
    } else {
        lines.push("🚩 현재 무쌍: 없음");
        lines.push("└ 다음 펫무쌍 대회 우승자를 기다리는 중입니다");
    }
    return lines.join("\n");
}

// 후원패스 설정 목록 반환 함수
function getSupportPassConfigs() {
    return [
        { key: "oneday", label: "원데이패스🎲", commandNames: ["원데이패스"] },
        { key: "newbie", label: "초보패스🐥", commandNames: ["초보", "초보패스"] },
        { key: "hoi", label: "호이패스🐶", commandNames: ["호이패스"] },
        { key: "premium", label: "호이패스 프리미엄👑", commandNames: ["호패프리미엄"] },
        { key: "contribution", label: "길드공헌패스🎖️", commandNames: ["공헌패스"] },
        { key: "diamond", label: "다이아패스💎", commandNames: ["다이아패스"] },
        { key: "territory", label: "영지기습패스", commandNames: ["영지패스"] },
        { key: "doll", label: "인형뽑기패스🧸", commandNames: ["인형패스"] }
    ];
}

// 후원패스 명령어명으로 설정을 찾는 함수
function getSupportPassConfigByCommandName(commandName) {
    var configs = getSupportPassConfigs();
    for (var i = 0; i < configs.length; i++) {
        for (var j = 0; j < configs[i].commandNames.length; j++) {
            if (configs[i].commandNames[j] === commandName) return configs[i];
        }
    }
    return null;
}

// 후원패스 저장 구조를 보장하는 함수
function ensureSupportPassStore(data, user) {
    if (!data.member[user]) return null;
    var member = data.member[user];
    if (!member.pass || typeof member.pass !== "object") member.pass = {};
    return member.pass;
}

// 영지기습패스 변경 전후 값을 로그용 단순 객체로 복사하는 함수
function copyTerritoryPassAuditValue(pass) {
    if (!pass || typeof pass !== "object") return null;
    return {
        enabled: pass.enabled === true,
        permanent: pass.permanent === true,
        endDate: pass.endDate || "",
        updatedAt: pass.updatedAt || "",
        updatedBy: pass.updatedBy || ""
    };
}

// 영지기습패스 추가·연장·삭제 이력을 저장하는 함수
function appendTerritoryPassAuditLog(data, operator, user, action, beforeValue, afterValue) {
    if (!Array.isArray(data.territoryPassAuditLogs)) data.territoryPassAuditLogs = [];
    data.territoryPassAuditLogs.push({
        operator: operator || "시스템",
        user: user,
        action: action,
        processedAt: formatDateTime(new Date()),
        expireAt: afterValue && afterValue.permanent ? "영구권" : (afterValue && afterValue.endDate ? afterValue.endDate : ""),
        before: beforeValue,
        after: afterValue
    });
    var logMax = GLOBAL_CONFIG.supportPass.territoryAuditLogMax;
    if (data.territoryPassAuditLogs.length > logMax) {
        data.territoryPassAuditLogs.splice(0, data.territoryPassAuditLogs.length - logMax);
    }
}

// 후원패스 날짜 문자열이 유효한지 확인하는 함수
function isValidSupportPassDateText(text) {
    return getSupportPassDateValue(text) !== null;
}

// 후원패스 날짜 문자열을 비교 가능한 값으로 변환하는 함수
function getSupportPassDateValue(text) {
    var match = String(text || "").match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
    if (!match) return null;
    var year = 2000 + parseInt(match[1], 10);
    var month = parseInt(match[2], 10);
    var day = parseInt(match[3], 10);
    var date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) return null;
    return year * 10000 + month * 100 + day;
}

// 한국 시간의 오늘 날짜를 후원패스 비교값으로 반환하는 함수
function getTodaySupportPassDateValue() {
    var now = new Date(new Date().getTime() + 9 * 60 * 60 * 1000);
    var y = now.getUTCFullYear();
    var m = now.getUTCMonth() + 1;
    var d = now.getUTCDate();
    return y * 10000 + m * 100 + d;
}

// 후원패스가 현재 사용 가능한지 확인하는 함수
function isSupportPassActive(data, user, passKey) {
    var member = data.member && data.member[user] ? data.member[user] : null;
    var pass = member && member.pass && member.pass[passKey] ? member.pass[passKey] : null;
    if (!pass || pass.enabled !== true) {
        var configs = getSupportPassConfigs();
        for (var i = 0; i < configs.length; i++) {
            if (configs[i].key === passKey && configs[i].arrayName) {
                var legacyArr = data[configs[i].arrayName];
                return legacyArr instanceof Array && legacyArr.indexOf(user) !== -1;
            }
        }
        return false;
    }
    if (pass.permanent === true) return true;
    var expireValue = getSupportPassDateValue(pass.endDate);
    if (expireValue === null) {
        if (passKey === "doll") throw new Error("인형패스 종료일 형식 오류");
        return true;
    }
    return expireValue >= getTodaySupportPassDateValue();
}

// 호이패스 또는 초보패스가 현재 활성 상태인지 확인하는 함수
function hasActiveHoiOrNewbiePass(data, user) {
    return isSupportPassActive(data, user, "hoi") || isSupportPassActive(data, user, "newbie");
}

// 호이패스 프리미엄이 현재 활성 상태인지 확인하는 함수
function isHoiPassPremiumActive(data, user) {
    return isSupportPassActive(data, user, "premium");
}

// 펫홈·개인톡 등 패스 공통 기능을 이용할 수 있는지 확인하는 함수
function hasActiveHoiPassAccess(data, user) {
    return hasActiveHoiOrNewbiePass(data, user) || isHoiPassPremiumActive(data, user);
}

// 패스 없이도 개인톡에서 실행할 수 있는 홈뱃지 명령인지 확인하는 함수
function isPassFreeHomeBadgeCommand(msg) {
    return msg === "/홈뱃지" ||
        msg === "/홈뱃지전체" ||
        msg === "/홈뱃지장착" ||
        msg === "/홈뱃지해제" ||
        msg === "홈뱃지교체" ||
        msg === "홈뱃지해제확정" ||
        msg === "홈뱃지취소" ||
        msg === "/큐브확률" ||
        /^\/홈뱃지정보\s+\S(?:.*\S)?$/.test(msg) ||
        /^\/홈뱃지장착(?:\s+.*)?$/.test(msg) ||
        /^\/홈뱃지해제(?:\s+.*)?$/.test(msg) ||
        /^\/홈뱃지삭제\s+(?:\d+|[A-Za-z]{1,4}\d{2,3})$/.test(msg) ||
        /^\/홈뱃지큐브(?:\s+.*)?$/.test(msg) ||
        /^\/홈뱃지큐브수정(?:\s+.*)?$/.test(msg);
}

// 현재 권한 명단을 기준으로 최우선 타이틀뱃지를 반환하는 함수
function getAuthorityTitleBadge(data, user) {
    if (data && Array.isArray(data.master) && data.master.indexOf(user) !== -1) return GLOBAL_CONFIG.authorityBadge.master;
    if (data && data.admin && Object.prototype.hasOwnProperty.call(data.admin, user)) {
        var member = data.member && data.member[user];
        return member && member.displaySettings && member.displaySettings.hideAdminTitle === true ? "" : GLOBAL_CONFIG.authorityBadge.admin;
    }
    return "";
}

// 권한 뱃지와 호이패스 프리미엄 공통 출력 헤더를 반환하는 함수
function getHoiPassPremiumHeader(data, user) {
    var authorityBadge = getAuthorityTitleBadge(data, user);
    return (authorityBadge ? authorityBadge + "\n" : "") + (isHoiPassPremiumActive(data, user) ? "[👑호이패스 프리미엄👑]\n" : "");
}

// 호이패스 프리미엄 종료일을 가방 표시 형식으로 변환하는 함수
function formatHoiPassPremiumBagExpiry(data, user) {
    var member = data.member && data.member[user] ? data.member[user] : null;
    var pass = member && member.pass ? member.pass.premium : null;
    if (!pass) return "정보 확인 불가";
    if (pass.permanent === true || !String(pass.endDate || "").trim()) return "영구권";

    var match = String(pass.endDate).match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
    if (!match) return "정보 확인 불가";
    return (2000 + parseInt(match[1], 10)) + "년 " + parseInt(match[2], 10) + "월 " + parseInt(match[3], 10) + "일까지";
}

// 호이패스 프리미엄 이용자의 전용 가방 요약과 전체 아이템 목록을 만드는 함수
function buildHoiPassPremiumBagMessage(data, petData, guildData, petExploreData, user, bagInfo) {
    var member = data.member[user];
    var bagItems = member.bag || {};
    var sortedItemList = bagInfo && bagInfo.sortedItemList ? bagInfo.sortedItemList : [];
    var currentLevel = parseInt(member.lv, 10); // 현재 레벨 표시값
    var currentExp = Number(member.exp); // 현재 단계 경험치
    var requiredExp = !isNaN(currentLevel) ? getLevelRequiredExperience(currentLevel) : 0; // 다음 레벨 필요 경험치
    var boosterCount = parseInt(member.boostercnt, 10);
    var expSummary = "🌟 현재 레벨: 경험치 정보 확인 불가";

    if (!isNaN(currentLevel) && currentLevel >= 0 && isFinite(currentExp) && currentExp >= 0 && requiredExp > 0) {
        var expRatio = currentExp / requiredExp; // 경험치 게이지와 퍼센트의 원본 비율
        var filledCount = Math.floor(expRatio * 10); // 원본 비율을 버림한 채움 칸 수
        if (filledCount < 0) filledCount = 0;
        if (filledCount > 10) filledCount = 10;
        var expGauge = "";
        for (var gaugeIndex = 0; gaugeIndex < 10; gaugeIndex++) expGauge += gaugeIndex < filledCount ? "■" : "□";
        expSummary = getAdventureLevelTitle(currentLevel) + "\n🌟 현재 레벨: Lv." + numberWithCommas(currentLevel) + "\n[" + expGauge + "] " + (expRatio * 100).toFixed(2) + "%\n📊 EXP " + formatAdventureExperience(currentExp) + " / " + formatAdventureExperience(requiredExp);
    }

    if (isNaN(boosterCount) || boosterCount < 0) boosterCount = 0;
    var vaultCount = normalizeSealedVaultCount(bagItems[GLOBAL_CONFIG.sealedVault.vaultItemName]); // 실제 개봉에 사용하는 봉인금고 수량
    var keyCount = normalizeSealedVaultCount(bagItems[GLOBAL_CONFIG.sealedVault.keyItemName]); // 실제 개봉에 사용하는 해방의 열쇠 수량
    var itemOutput = bagInfo && bagInfo.bagOutput ? bagInfo.bagOutput : "가방이 비어 있습니다.";
    var pointHidden = member.hidePremiumBagPoint === true; // 전용 가방에서 포인트 숨김 여부
    var pointDisplay = pointHidden ? "쉿 비밀🤫" : numberWithCommas(member.point || 0); // 잠금 상태를 반영한 포인트 표시값
    var pointLockGuide = pointHidden ? "" : "※ 포인트 안보이게 원하시면 /포인트잠금\n"; // 포인트 공개 상태에서만 표시하는 잠금 안내
    var chuseokCarrotLine = isChuseokExploreEventActive(petExploreData) ? "🌕 황금당근: " + numberWithCommas(getChuseokCarrotBalance(petExploreData, user, data)) + "개 / 이벤트종료시 삭제\n" : ""; // 이벤트 전용 잔액 표시

    return getHoiPassPremiumHeader(data, user) +
        "[" + checkRank(data, petData, guildData, user) + "]의 호패프 전용가방🧳\n" +
        "━━━━━━━━━━━━\n" +
        getHalloweenCandyLine(getCurrentContext(), false) +
        "🪙: " + pointDisplay + "\n" +
        "💎 다이아: " + numberWithCommas(member.diamond || 0) + "개\n" +
        chuseokCarrotLine +
        "🔒 호이의 봉인금고: " + numberWithCommas(vaultCount) + "개\n" +
        "🗝️ 해방의 열쇠: " + numberWithCommas(keyCount) + "개\n" +
        "━━━━━━━━━━━━\n" +
        expSummary + "\n" +
        "🚀 " + GLOBAL_CONFIG.level.boosterName + ":" + (boosterCount === 0 ? " 없음" : "") + "\n" +
        (boosterCount > 0 ? "🚀 " + numberWithCommas(boosterCount) + "회\n" : "") +
        "━━━━━━━━━━━━\n" +
        "👑 호패 프리미엄: 이용 중\n" +
        "📅 만료일: " + formatHoiPassPremiumBagExpiry(data, user) + "\n" +
        pointLockGuide +
        "━━━━━━━━━━━━\n" +
        "【🎒 가방 보러가기 ·아이템 보유 " + sortedItemList.length + "개】" +
        allsee + "\n" + itemOutput;
}

// 호이패스 프리미엄 적용 여부에 따른 가구 가방 최대 칸 수를 반환하는 함수
function getFurnitureBagLimit(data, user) {
    var config = GLOBAL_CONFIG.supportPass.premium;
    return config.furnitureBagBaseCount + (isHoiPassPremiumActive(data, user) ? config.furnitureBagBonusCount : 0);
}

// 호이패스 프리미엄 적용 여부에 따른 미니펫 가방 최대 칸 수를 반환하는 함수
function getMiniPetBagLimit(data, user) {
    var config = GLOBAL_CONFIG.supportPass.premium;
    return config.miniPetBagBaseCount + (isHoiPassPremiumActive(data, user) ? config.miniPetBagBonusCount : 0);
}

// 호이패스 프리미엄 전용 홈뱃지를 지급하는 함수
function grantHoiPassPremiumBadge(activityData, user, operator) {
    var social = getPetHomeSocialUser(activityData, user);
    var badgeId = GLOBAL_CONFIG.supportPass.premium.badgeId;
    removePetHomeStringListValue(social.deletedBadgeIds, badgeId);
    if (petHomeStringListContains(social.badges, badgeId)) return false;
    social.badges.push(badgeId);
    social.specialBadgeLogs.push({ badgeId: badgeId, action: "프리미엄지급", adminId: operator || "시스템", createdAt: formatDateTime(new Date()) });
    var alert = addPetHomeActivityAlert(activityData, user, "special_badge_granted", operator || "시스템", "");
    alert.badgeId = badgeId;
    return true;
}

// 호이패스 프리미엄 전용 홈뱃지를 회수하는 함수
function revokeHoiPassPremiumBadge(data, activityData, user, operator) {
    var social = getPetHomeSocialUser(activityData, user);
    var badgeId = GLOBAL_CONFIG.supportPass.premium.badgeId;
    if (!removePetHomeStringListValue(social.badges, badgeId)) return false;
    removeHomeBadgeFromEquippedSlots(data, social, user, badgeId);
    social.specialBadgeLogs.push({ badgeId: badgeId, action: "프리미엄회수", adminId: operator || "시스템", createdAt: formatDateTime(new Date()) });
    var alert = addPetHomeActivityAlert(activityData, user, "special_badge_revoked", operator || "시스템", "");
    alert.badgeId = badgeId;
    return true;
}

// 중복 장착 검사 후 빈 슬롯만큼 프리미엄 잠금 펫스킬을 다시 활성화하는 함수
function restoreHoiPassPremiumLockedSkills(data, petSkillData, user) {
    var skills = initPetSkillUser(petSkillData, user);
    var restoredCount = 0, lockedIndex = 0; // 충돌한 잠금은 보존하고 뒤의 복구 가능한 스킬도 검사
    while (lockedIndex < skills.lockedPremium.length && skills.equipped.length < getPetSkillSlotCount(data, petSkillData, user)) {
        var skillName = normalizePetSkillName(skills.lockedPremium[lockedIndex]);
        if (!skillName) { skills.lockedPremium.splice(lockedIndex, 1); continue; }
        if (!isPetSkillCompatible(petSkillData, user, skillName).ok) { lockedIndex++; continue; }
        skills.lockedPremium.splice(lockedIndex, 1);
        skills.equipped.push(skillName);
        restoredCount++;
    }
    return restoredCount;
}

// 호이패스 프리미엄 만료·삭제 후처리를 한 번만 수행하는 함수
function expireHoiPassPremium(data, petSkillData, activityData, user, reason, operator) {
    var member = data.member && data.member[user] ? data.member[user] : null;
    var pass = member && member.pass ? member.pass.premium : null;
    if (!pass || pass.enabled !== true) return { changed: false, lockedSkillCount: 0, removedTicketCount: 0, badgeRevoked: false };
    pass.enabled = false;
    pass.expiredAt = formatDateTime(new Date());
    pass.expireReason = reason || "기간 만료";
    var lockedSkillCount = 0; // 한도가 줄어도 기존 장착과 효과를 보존하고 추가 장착만 제한
    var removedTicketCount = 0;
    if (!hasActiveHoiOrNewbiePass(data, user)) removedTicketCount = removeAllAutoExploreTickets(data, user);
    var badgeRevoked = revokeHoiPassPremiumBadge(data, activityData, user, operator || "시스템");
    pass.badgeGranted = false;
    debuggerLog("[호이패스 프리미엄 종료] " + user + " / " + pass.expireReason + " / 펫스킬 잠금 " + lockedSkillCount + "개 / 자동탐험권 회수 " + removedTicketCount + "개");
    return { changed: true, lockedSkillCount: lockedSkillCount, removedTicketCount: removedTicketCount, badgeRevoked: badgeRevoked };
}

// 기간이 지난 호이패스 프리미엄 유저 목록을 반환하는 함수
function getExpiredHoiPassPremiumUsers(data, targetUser) {
    var users = [];
    if (!data || !data.member) return users;
    if (targetUser) {
        if (typeof targetUser !== "string" || !Object.prototype.propertyIsEnumerable.call(data.member, targetUser)) return users;
        var targetPass = data.member[targetUser] && data.member[targetUser].pass ? data.member[targetUser].pass.premium : null;
        if (!targetPass || targetPass.enabled !== true || targetPass.permanent === true) return users;
        var targetExpireValue = getSupportPassDateValue(targetPass.endDate);
        if (targetExpireValue !== null && targetExpireValue < getTodaySupportPassDateValue()) users.push(targetUser);
        return users;
    }
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user) || (targetUser && user !== targetUser)) continue;
        var pass = data.member[user] && data.member[user].pass ? data.member[user].pass.premium : null;
        if (!pass || pass.enabled !== true || pass.permanent === true) continue;
        var expireValue = getSupportPassDateValue(pass.endDate);
        if (expireValue !== null && expireValue < getTodaySupportPassDateValue()) users.push(user);
    }
    return users;
}

// 지정된 유저들의 만료된 호이패스 프리미엄을 일괄 정리하는 함수
function cleanupExpiredHoiPassPremium(data, petSkillData, activityData, users) {
    var result = { changed: false, expiredCount: 0, lockedSkillCount: 0 };
    for (var i = 0; i < users.length; i++) {
        var expireResult = expireHoiPassPremium(data, petSkillData, activityData, users[i], "기간 만료", "시스템");
        if (!expireResult.changed) continue;
        result.changed = true;
        result.expiredCount++;
        result.lockedSkillCount += expireResult.lockedSkillCount;
    }
    return result;
}

// 호이월톡 이용기간이 끝난 유저인지 확인하는 함수
function hasExpiredHoiPassForPrivateChat(data, user) {
    var member = data && data.member ? data.member[user] : null;
    if (!member || !member.pass) return false;
    var passKeys = ["hoi", "premium"];
    for (var i = 0; i < passKeys.length; i++) {
        var pass = member.pass[passKeys[i]];
        if (!pass || pass.permanent === true) continue;
        var expiry = getSupportPassDateValue(pass.endDate);
        if (expiry !== null && expiry < getTodaySupportPassDateValue()) return true;
    }
    return false;
}

// 패스 종료로 차단된 유저에게 보낼 호월톡 1:1 안내를 만드는 함수
function buildExpiredHoiPassPrivateChatMessage(data, guildData, user) {
    return "[" + checkRank(data, null, guildData, user) + "]님, 패스 이용기간이 종료되었습니다. 🎫\n" +
        "━━━━━━━━━━━━\n" +
        "현재 호월톡 1:1 기능을 이용할 수 없습니다.\n\n" +
        "호이패스 또는 호이패스 프리미엄을\n" +
        "연장하신 후 다시 이용해주세요. 😊\n\n" +
        "🎟️ 호이패스 안내\nhttps://hoiland123.tistory.com/647\n\n" +
        "👑 호이패스 프리미엄 안내\nhttps://hoiland123.tistory.com/648";
}

// 패스가 없는 유저에게 보낼 호월톡 1:1 이용 제한 안내를 만드는 함수
function buildNoHoiPassPrivateChatMessage(data, guildData, user) {
    return "[" + checkRank(data, null, guildData, user) + "]님, 호이패스 유저 외에는 호월톡 1:1을 이용할 수 없습니다. 🎫\n" +
        "━━━━━━━━━━━━\n" +
        "호이패스 또는 호이패스 프리미엄 가입 후 다시 이용해주세요.\n\n" +
        "🎟️ 호이패스 안내\nhttps://hoiland123.tistory.com/647\n\n" +
        "👑 호이패스 프리미엄 안내\nhttps://hoiland123.tistory.com/648";
}

// 차단된 1:1톡에 보낼 유저 안내 종류를 패스 상태와 관리자 감지 주기에 따라 정하는 함수
function getBlockedPrivateChatNoticeKind(data, user, detectionSent) {
    if (hasExpiredHoiPassForPrivateChat(data, user)) return detectionSent ? "expired" : "";
    return "noPass";
}

// 패스 미사용 유저의 1:1톡 차단 횟수를 기록하고 주기마다 운영진에게 알리는 함수
function recordBlockedPrivateChatAttempt(room, sender, msg) {
    var attemptCount = (privateChatBlockedTracker[sender] || 0) + 1; // 봇 실행 후 유저별 누적 차단 횟수
    privateChatBlockedTracker[sender] = attemptCount;
    if (attemptCount % GLOBAL_CONFIG.privateChat.notifyEvery !== 0) return false;

    var messagePreview = String(msg || "").replace(/[\r\n]+/g, " ").trim(); // 운영 알림용 최근 메시지 한 줄 요약
    if (messagePreview.length > GLOBAL_CONFIG.privateChat.messagePreviewMaxLength) {
        messagePreview = messagePreview.substring(0, GLOBAL_CONFIG.privateChat.messagePreviewMaxLength) + "...";
    }
    if (!messagePreview) messagePreview = "-";

    Api.replyRoom(
        room90,
        "[패스 미사용 1:1톡 감지]\n" +
        "유저: " + sender + "\n" +
        "개인톡방: " + room + "\n" +
        "누적 횟수: " + attemptCount + "회\n" +
        "최근 메시지: " + messagePreview
    );
    return true;
}

// 호이패스·초보패스 활성 유저의 펫홈 기능 비용을 면제하는 함수
function getPetHomePassBenefitCost(data, user, baseCost) {
    return hasActiveHoiPassAccess(data, user) ? 0 : baseCost;
}

// 현재 사용 가능한 후원패스 유저 목록을 반환하는 함수
function getActiveSupportPassUsers(data, passKey) {
    var users = [];
    if (!data || !data.member) return users;
    for (var user in data.member) {
        if (isSupportPassActive(data, user, passKey)) users.push(user);
    }
    return users;
}

// 지정 후원패스의 일일 보상을 계정당 하루 한 번 지급하는 함수
function grantSupportPassDailyRewards(data, passKey, rewards) {
    var result = { grantedUserCount: 0, skippedUserCount: 0, grantedUsers: [], skippedUsers: [] };
    var users = getActiveSupportPassUsers(data, passKey);
    var today = String(getTodaySupportPassDateValue());
    for (var userIndex = 0; userIndex < users.length; userIndex++) {
        var user = users[userIndex];
        var pass = data.member[user].pass[passKey];
        if (pass.dailyRewardLastDate === today) {
            result.skippedUserCount++;
            result.skippedUsers.push(user);
            continue;
        }
        for (var rewardIndex = 0; rewardIndex < rewards.length; rewardIndex++) {
            addItem(data, user, rewards[rewardIndex].name, rewards[rewardIndex].count);
        }
        pass.dailyRewardLastDate = today;
        result.grantedUserCount++;
        result.grantedUsers.push(user);
    }
    return result;
}

// 인형패스 지급 예정 수량을 검사한 뒤 기존 일일 지급 흐름으로 지급하는 함수
function grantDollPassDailyRewards(data) {
    var up = GLOBAL_CONFIG.doll.probabilityUp;
    var upName = up.itemPrefix + "(" + up.dailyPassPercent + "%)";
    var users = getActiveSupportPassUsers(data, "doll");
    var today = String(getTodaySupportPassDateValue());
    for (var i = 0; i < users.length; i++) {
        var member = data.member[users[i]];
        if (member.pass.doll.dailyRewardLastDate === today) continue;
        if (member.bag !== undefined && (!member.bag || typeof member.bag !== "object" || Array.isArray(member.bag))) throw new Error("인형패스 가방 형식 오류");
        var count = member.bag && member.bag[GLOBAL_CONFIG.doll.ticketName] !== undefined ? member.bag[GLOBAL_CONFIG.doll.ticketName] : 0;
        if (!isSearchAuthenticationCount(count) || !isSearchAuthenticationCount(count + GLOBAL_CONFIG.doll.dailyPassTickets)) throw new Error("인형패스 이용권 수량 오류");
        var upCount = member.bag && member.bag[upName] !== undefined ? member.bag[upName] : 0;
        if (!isSearchAuthenticationCount(upCount) || !isSearchAuthenticationCount(upCount + up.dailyPassCount)) throw new Error("인형패스 확률UP 수량 오류");
    }
    return grantSupportPassDailyRewards(data, "doll", [{ name: GLOBAL_CONFIG.doll.ticketName, count: GLOBAL_CONFIG.doll.dailyPassTickets }, { name: upName, count: up.dailyPassCount }]);
}
// 영지기습패스 일일 지급 결과를 최근 운영 로그에 기록하는 함수
function appendTerritoryPassPayoutLogs(data, result, operator) {
    if (!Array.isArray(data.supportPassPayoutLogs)) data.supportPassPayoutLogs = [];
    var nowText = formatDateTime(new Date());
    var today = String(getTodaySupportPassDateValue());
    for (var grantedIndex = 0; grantedIndex < result.grantedUsers.length; grantedIndex++) {
        data.supportPassPayoutLogs.push({
            paidAt: nowText,
            operator: operator || "시스템",
            user: result.grantedUsers[grantedIndex],
            passType: "territory",
            offenseCount: 2,
            defenseCount: 2,
            success: true,
            reason: "지급 완료",
            duplicateKey: today + ":" + result.grantedUsers[grantedIndex]
        });
    }
    for (var skippedIndex = 0; skippedIndex < result.skippedUsers.length; skippedIndex++) {
        data.supportPassPayoutLogs.push({
            paidAt: nowText,
            operator: operator || "시스템",
            user: result.skippedUsers[skippedIndex],
            passType: "territory",
            offenseCount: 0,
            defenseCount: 0,
            success: false,
            reason: "당일 지급 완료로 제외",
            duplicateKey: today + ":" + result.skippedUsers[skippedIndex]
        });
    }
    var logMax = GLOBAL_CONFIG.supportPass.territoryPayoutLogMax;
    if (data.supportPassPayoutLogs.length > logMax) {
        data.supportPassPayoutLogs.splice(0, data.supportPassPayoutLogs.length - logMax);
    }
}

// 모든 구독패스의 일일 보상을 순서대로 지급하고 패스별 처리 수를 반환하는 함수
function grantAllSupportPassDailyRewards(data, operator) {
    var config = GLOBAL_CONFIG.supportPass;
    var rows = [];
    rows.push({ label: "호프", result: grantHoiPassPremiumDailyRewards(data) });
    rows.push({ label: "인형뽑기패스", result: grantDollPassDailyRewards(data) });
    rows.push({ label: "호이패스", result: grantSupportPassDailyRewards(data, "hoi", config.hoiDailyRewards) });
    rows.push({ label: "초보패스", result: grantSupportPassDailyRewards(data, "newbie", config.newbieDailyRewards) });
    rows.push({ label: "공헌패스", result: grantSupportPassDailyRewards(data, "contribution", config.contributionDailyRewards) });
    rows.push({
        label: "다이아패스",
        result: grantSupportPassDailyRewards(data, "diamond", [{ name: GLOBAL_CONFIG.items.diamondBoxName, count: config.diamondBoxCount }])
    });
    var territoryResult = grantSupportPassDailyRewards(data, "territory", config.territoryDailyRewards);
    rows.push({ label: "영지기습패스", result: territoryResult });
    appendTerritoryPassPayoutLogs(data, territoryResult, operator);
    var totalGrantedCount = 0; // 패스별 실제 지급 건수 합계
    var totalSkippedCount = 0; // 당일 중복으로 제외된 패스 건수 합계
    for (var rowIndex = 0; rowIndex < rows.length; rowIndex++) {
        totalGrantedCount += rows[rowIndex].result.grantedUserCount;
        totalSkippedCount += rows[rowIndex].result.skippedUserCount;
    }
    return {
        changed: totalGrantedCount > 0 || territoryResult.skippedUserCount > 0,
        rows: rows,
        totalGrantedCount: totalGrantedCount,
        totalSkippedCount: totalSkippedCount
    };
}

// 구독패스 통합 지급 결과를 운영자용 요약 메시지로 생성하는 함수
function buildSupportPassPayoutResultMessage(result) {
    var lines = ["🎁 구독 패스 일괄 지급 완료", "━━━━━━━━━━━━━━━"];
    for (var rowIndex = 0; rowIndex < result.rows.length; rowIndex++) {
        var row = result.rows[rowIndex];
        lines.push(row.label + ": " + row.result.grantedUserCount + "명");
    }
    lines.push("━━━━━━━━━━━━━━━");
    lines.push("총 지급 처리: " + result.totalGrantedCount + "건");
    if (result.totalSkippedCount > 0) lines.push("금일 지급 완료로 제외: " + result.totalSkippedCount + "건");
    return lines.join("\n");
}

// 호이패스 프리미엄 일일 아이템을 계정당 하루 한 번 지급하는 함수
function grantHoiPassPremiumDailyRewards(data) {
    var result = { grantedUserCount: 0, skippedUserCount: 0, grantedUsers: [], skippedUsers: [] };
    var users = getActiveSupportPassUsers(data, "premium");
    var today = String(getTodaySupportPassDateValue());
    var rewards = GLOBAL_CONFIG.supportPass.premium.dailyRewards;
    for (var i = 0; i < users.length; i++) {
        var user = users[i];
        var pass = data.member[user].pass.premium;
        if (pass.dailyRewardLastDate === today) {
            result.skippedUserCount++;
            result.skippedUsers.push(user);
            continue;
        }
        for (var rewardIndex = 0; rewardIndex < rewards.length; rewardIndex++) {
            addItem(data, user, rewards[rewardIndex].name, rewards[rewardIndex].count);
        }
        pass.dailyRewardLastDate = today;
        result.grantedUserCount++;
        result.grantedUsers.push(user);
    }
    return result;
}

// 만료된 후원패스를 정리하고 자격이 끝난 자동탐험권을 회수하는 함수
function cleanupExpiredSupportPasses(data) {
    var result = { changed: false, expiredCount: 0, removedTicketCount: 0, invalidDateCount: 0 };
    if (!data || !data.member) return result;
    var configs = getSupportPassConfigs();
    var todayValue = getTodaySupportPassDateValue();
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var member = data.member[user];
        if (!member || !member.pass) continue;
        var autoPassExpired = false;
        for (var i = 0; i < configs.length; i++) {
            var config = configs[i];
            var pass = member.pass[config.key];
            if (!pass || pass.enabled !== true || pass.permanent === true) continue;
            var expireValue = getSupportPassDateValue(pass.endDate);
            if (expireValue === null) {
                result.invalidDateCount++;
                debuggerLog("[후원패스 만료 정리] 잘못된 날짜로 자동 정리 제외: " + user + " / " + config.key + " / " + pass.endDate);
                continue;
            }
            if (expireValue >= todayValue) continue;
            pass.enabled = false;
            result.changed = true;
            result.expiredCount++;
            if (config.key === "newbie" || config.key === "hoi") autoPassExpired = true;
            debuggerLog("[후원패스 만료 정리] 패스 만료: " + user + " / " + config.key + " / " + pass.endDate);
        }
        if (autoPassExpired && !hasActiveAutoExplorePass(data, user)) {
            var removedTicketCount = removeAllAutoExploreTickets(data, user);
            if (removedTicketCount > 0) {
                result.changed = true;
                result.removedTicketCount += removedTicketCount;
                debuggerLog("[후원패스 만료 정리] 자동탐험권 회수: " + user + " / " + removedTicketCount + "개");
            }
        }
    }
    return result;
}

// 자동탐험권 아이템명의 숨은 이모지 선택자와 끝 공백을 제거하는 함수
function normalizeAutoExploreTicketItemName(itemName) {
    return String(itemName || "").replace(/[\uFE0E\uFE0F]/g, "").trim();
}

// 유저 가방의 자동탐험권 표기 변형을 합산하는 함수
function getAutoExploreTicketCount(data, user) {
    if (!data || !data.member || !data.member[user] || !data.member[user].bag) return 0;
    var bag = data.member[user].bag;
    var targetName = normalizeAutoExploreTicketItemName("자동탐험권🌄");
    var count = 0;
    for (var itemName in bag) {
        if (!bag.hasOwnProperty(itemName)) continue;
        if (normalizeAutoExploreTicketItemName(itemName) !== targetName) continue;
        count += parseInt(bag[itemName], 10) || 0;
    }
    return count;
}

// 유저 가방의 자동탐험권 표기 변형을 모두 회수하는 함수
function removeAllAutoExploreTickets(data, user) {
    if (!data || !data.member || !data.member[user] || !data.member[user].bag) return 0;
    var bag = data.member[user].bag;
    var targetName = normalizeAutoExploreTicketItemName("자동탐험권🌄");
    var removedCount = 0;
    for (var itemName in bag) {
        if (!bag.hasOwnProperty(itemName)) continue;
        if (normalizeAutoExploreTicketItemName(itemName) !== targetName) continue;
        removedCount += parseInt(bag[itemName], 10) || 0;
        delete bag[itemName];
    }
    return removedCount;
}

// 자동탐험권 보유 자격이 없는 유저 목록을 반환하는 함수
function getInvalidAutoExploreTicketUsers(data) {
    var users = [];
    if (!data || !data.member) return users;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var ticketCount = getAutoExploreTicketCount(data, user);
        if (ticketCount < 1) continue;
        if (hasActiveAutoExplorePass(data, user)) continue;
        users.push({ user: user, count: ticketCount });
    }
    users.sort(function (a, b) {
        if (a.user < b.user) return -1;
        if (a.user > b.user) return 1;
        return 0;
    });
    return users;
}

// 호이응원 무료패키지 아이템명의 1~10번 변형 번호를 반환하는 함수
function getHoiFreeSupportPackageVariant(itemName) {
    var packageConfig = GLOBAL_CONFIG.supportPass.freeSupportPackage;
    var packagePrefix = packageConfig.baseName.replace(/[\uFE0E\uFE0F]/g, "") + "[";
    var normalizedItemName = String(itemName || "").replace(/[\uFE0E\uFE0F]/g, "").trim();
    if (normalizedItemName.indexOf(packagePrefix) !== 0 || normalizedItemName.charAt(normalizedItemName.length - 1) !== "]") return null;
    var variantText = normalizedItemName.substring(packagePrefix.length, normalizedItemName.length - 1);
    if (!/^\d+$/.test(variantText)) return null;
    var variant = parseInt(variantText, 10);
    if (variant < packageConfig.minVariant || variant > packageConfig.maxVariant) return null;
    if (variantText !== String(variant)) return null;
    return variant;
}

// 유저 가방의 호이응원 무료패키지 1~10번 수량을 합산하는 함수
function getHoiFreeSupportPackageCount(data, user) {
    if (!data || !data.member || !data.member[user] || !data.member[user].bag) return 0;
    var bag = data.member[user].bag;
    var count = 0;
    for (var itemName in bag) {
        if (!bag.hasOwnProperty(itemName)) continue;
        if (getHoiFreeSupportPackageVariant(itemName) === null) continue;
        var itemCount = parseInt(bag[itemName], 10) || 0;
        if (itemCount > 0) count += itemCount;
    }
    return count;
}

// 모든 유저 가방에서 호이응원 무료패키지 1~10번 데이터를 제거하는 함수
function removeAllHoiFreeSupportPackages(data) {
    var result = { removedUserCount: 0, removedPackageCount: 0 };
    if (!data || !data.member) return result;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var bag = data.member[user] && data.member[user].bag;
        if (!bag || typeof bag !== "object" || bag instanceof Array) continue;
        var removableItemNames = [];
        for (var itemName in bag) {
            if (!bag.hasOwnProperty(itemName)) continue;
            if (getHoiFreeSupportPackageVariant(itemName) === null) continue;
            removableItemNames.push(itemName);
        }
        for (var itemIndex = 0; itemIndex < removableItemNames.length; itemIndex++) {
            var removableItemName = removableItemNames[itemIndex];
            var itemCount = parseInt(bag[removableItemName], 10) || 0;
            if (itemCount > 0) result.removedPackageCount += itemCount;
            delete bag[removableItemName];
        }
        if (removableItemNames.length > 0) result.removedUserCount++;
    }
    return result;
}

// 호이응원 무료패키지를 기준 수량 이상 보유한 유저 목록을 반환하는 함수
function getHoiFreeSupportPackageAlertUsers(data) {
    var users = [];
    if (!data || !data.member) return users;
    var alertCount = GLOBAL_CONFIG.supportPass.freeSupportPackage.alertCount;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var packageCount = getHoiFreeSupportPackageCount(data, user);
        if (packageCount < alertCount) continue;
        users.push({ user: user, count: packageCount });
    }
    users.sort(function (a, b) {
        if (a.count !== b.count) return b.count - a.count;
        if (a.user < b.user) return -1;
        if (a.user > b.user) return 1;
        return 0;
    });
    return users;
}

// 후원패스 표시 문자열을 만드는 함수
function formatSupportPassStatus(data, user, config) {
    var packageLabel = config.key === "territory" ? "영지기습패스⚔️🛡️" : config.label;
    if (!isSupportPassActive(data, user, config.key)) return packageLabel + ": 미사용 [❌]";
    var pass = data.member[user].pass && data.member[user].pass[config.key] ? data.member[user].pass[config.key] : null;
    if (!pass) return packageLabel + ": 미사용 [❌]";
    if (pass.permanent === true || !String(pass.endDate || "").trim()) return packageLabel + ": 영구권 사용 중 [✅]";
    return packageLabel + ": " + pass.endDate + " 종료 예정 [✅]";
}

// 유저 패키지가방용 후원패스 표시 줄을 만드는 함수
function buildUserSupportPassLines(data, user) {
    var configs = getSupportPassConfigs();
    var lines = [];
    for (var i = 0; i < configs.length; i++) {
        lines.push(formatSupportPassStatus(data, user, configs[i]));
    }
    return lines;
}

// 기존 미니펫 연금 순위와 보상표를 공통 지급 경로에서 계산하는 함수
function payMiniPetRankingReward(data, petData, guildData) {
    let result = getMiniPetExpRanking(petData, data, guildData); // 순위 계산
    let ranking = result.ranking;
    if (!data.member) data.member = {};
    let rewardsGiven = 0;
    let rewardItem = "펫 강화석⭐";
    let rewardMsg =
        "🐹[보상알림]\n" +
        "미니펫이 휘날리며~ 🐹 흩날리는 미니펫과 함께~ 🐹\n" +
        "아름다운 이 거리를 둘이 걸어요~ 🌸\n" +
        "🐹🐹🐹🐹🐹🐹🐹🐹🐹🐹🐹\n" +
        "미니펫 연금(1-200등) 보상 지급이 완료되었습니다.\n" +
        "(/미니펫순위) 참조해주세요🐹\n\n";
    for (let i = 0; i < ranking.length; i++) {
        let user = ranking[i].user;
        let reward = 0;
        if (i === 0) reward = 40;
        else if (i === 1) reward = 30;
        else if (i === 2) reward = 25;
        else if (i === 3) reward = 24;
        else if (i === 4) reward = 23;
        else if (i === 5) reward = 22;
        else if (i === 6) reward = 21;
        else if (i === 7) reward = 20;
        else if (i === 8) reward = 19;
        else if (i === 9) reward = 18;
        else if (i < 20) reward = 17;
        else if (i < 30) reward = 16;
        else if (i < 40) reward = 15;
        else if (i < 50) reward = 14;
        else if (i < 70) reward = 13;
        else if (i < 80) reward = 12;
        else if (i < 90) reward = 11;
        else if (i < 100) reward = 10;
        else if (i < 110) reward = 9;
        else if (i < 120) reward = 8;
        else if (i < 130) reward = 7;
        else if (i < 140) reward = 6;
        else if (i < 150) reward = 5;
        else if (i < 160) reward = 4;
        else if (i < 170) reward = 3;
        else if (i < 180) reward = 2;
        else if (i < 200) reward = 1;
        if (reward > 0) {
            if (!data.member[user]) data.member[user] = {};
            if (!data.member[user].bag) data.member[user].bag = {};
            data.member[user].bag[rewardItem] = (data.member[user].bag[rewardItem] || 0) + reward;
            rewardsGiven++;
            // 메시지 구성
            if (i === 10) {
                rewardMsg += allsee;
            }
            rewardMsg += getRankEmoji(i + 1) + checkRank(data, petData, guildData, user) + " 🐹 " + rewardItem + " " + reward + "개 지급\n";
        }
    }
    return { ok: true, message: rewardMsg, noticeMessage: rewardMsg };
}

// 기존 종합순위 계산과 보상표를 공통 지급 경로에서 그대로 적용하는 함수
function payOverallRankingReward(data, petData, guildData, homeData, petSkillData) {
    // 종합순위보상
    let members = data.member;
    let sortedUsrs = Object.keys(members)
        .filter((key) => petData[key])
        .sort((a, b) => {
            let A =
                (calculateCastleExp(a, data, petData, homeData, petSkillData, false, guildData) || 0) +
                (calculateRaidExp(a, data, petData, homeData, petSkillData, false, guildData) || 0) +
                calculatePetUpgradeCharm(a, data, petData);
            let B =
                (calculateCastleExp(b, data, petData, homeData, petSkillData, false, guildData) || 0) +
                (calculateRaidExp(b, data, petData, homeData, petSkillData, false, guildData) || 0) +
                calculatePetUpgradeCharm(b, data, petData);
            return B - A;
        });
    // 보상 구간 설정
    // 보상 구간 설정
    let rewardsTarget = {
        top1: [],
        top2: [],
        top3: [],
        top4: [],
        top5: [],
        top6: [],
        top7: [],
        top8: [],
        top9: [],
        top10: [],
        top11_20: [],
        top21_30: [],
        top31_40: [],
        top41_50: [],
        top51_70: [],
        top71_100: [],
        top101_130: [],
        top131_150: []
    };
    // 보상 목록
    let rewards = {
        top1: [
            {
                itemName: "펫 강화석⭐",
                count: 70
            }
        ],
        top2: [
            {
                itemName: "펫 강화석⭐",
                count: 60
            }
        ],
        top3: [
            {
                itemName: "펫 강화석⭐",
                count: 55
            }
        ],
        top4: [
            {
                itemName: "펫 강화석⭐",
                count: 45
            }
        ],
        top5: [
            {
                itemName: "펫 강화석⭐",
                count: 40
            }
        ],
        top6: [
            {
                itemName: "펫 강화석⭐",
                count: 37
            }
        ],
        top7: [
            {
                itemName: "펫 강화석⭐",
                count: 34
            }
        ],
        top8: [
            {
                itemName: "펫 강화석⭐",
                count: 31
            }
        ],
        top9: [
            {
                itemName: "펫 강화석⭐",
                count: 27
            }
        ],
        top10: [
            {
                itemName: "펫 강화석⭐",
                count: 23
            }
        ],
        top11_20: [
            {
                itemName: "펫 강화석⭐",
                count: 15
            }
        ],
        top21_30: [
            {
                itemName: "펫 강화석⭐",
                count: 14
            }
        ],
        top31_40: [
            {
                itemName: "펫 강화석⭐",
                count: 13
            }
        ],
        top41_50: [
            {
                itemName: "펫 강화석⭐",
                count: 12
            }
        ],
        top51_70: [
            {
                itemName: "펫 강화석⭐",
                count: 11
            }
        ],
        top71_100: [
            {
                itemName: "펫 강화석⭐",
                count: 10
            }
        ],
        top101_130: [
            {
                itemName: "펫 강화석⭐",
                count: 5
            }
        ],
        top131_150: [
            {
                itemName: "펫 강화석⭐",
                count: 2
            }
        ]
    };
    // 사용자 등수에 따른 보상 분배
    let userRanks = {};
    for (let i = 0; i < sortedUsrs.length; i++) {
        let user = sortedUsrs[i];
        userRanks[user] = i + 1;
        if (i === 0) rewardsTarget.top1.push(user);
        else if (i === 1) rewardsTarget.top2.push(user);
        else if (i === 2) rewardsTarget.top3.push(user);
        else if (i === 3) rewardsTarget.top4.push(user);
        else if (i === 4) rewardsTarget.top5.push(user);
        else if (i === 5) rewardsTarget.top6.push(user);
        else if (i === 6) rewardsTarget.top7.push(user);
        else if (i === 7) rewardsTarget.top8.push(user);
        else if (i === 8) rewardsTarget.top9.push(user);
        else if (i === 9) rewardsTarget.top10.push(user);
        else if (i >= 10 && i < 20) rewardsTarget.top11_20.push(user);
        else if (i >= 20 && i < 30) rewardsTarget.top21_30.push(user);
        else if (i >= 30 && i < 40) rewardsTarget.top31_40.push(user);
        else if (i >= 40 && i < 50) rewardsTarget.top41_50.push(user);
        else if (i >= 50 && i < 70) rewardsTarget.top51_70.push(user);
        else if (i >= 70 && i < 100) rewardsTarget.top71_100.push(user);
        else if (i >= 100 && i < 130)
            // 추가: 101~130등
            rewardsTarget.top101_130.push(user);
        else if (i >= 130 && i < 150)
            // 추가: 131~150등
            rewardsTarget.top131_150.push(user);
        else break;
    }
    let message = "✨✨ 펑! 펑펑! ✨✨💥 펑펑 💥\n💥 펑펑 💥\n🔥 빵! 펑펑펑 🔥\n💥 펑펑 💥✨ 펑 💫 펑펑펑 ✨\n";
    message += "[보상알림]\n🔔종합순위 보상 지급이 완료되었습니다.🔔\n(/종합순위) (/종합순위보상) 참조해주세요🐶\n\n[하루에 한번 1등~150등 차등으로 보상됩니다.]\n\n";
    let isBelowTop10 = false; // 10위 이후 문구 추가 여부
    // 보상 지급 로직 실행 및 메시지 누적
    Object.keys(rewardsTarget).forEach((rank) => {
        rewardsTarget[rank].forEach((user) => {
            rewards[rank].forEach((item) => {
                let itemName = item.itemName;
                let count = item.count;
                let rankNum = userRanks[user]; // 등수 가져오기
                // 보상지급
                if (!data.member[user].bag) {
                    data.member[user].bag = {};
                }
                if (!data.member[user].bag[itemName]) {
                    data.member[user].bag[itemName] = 0;
                }
                data.member[user].bag[itemName] += count;
                // 10위 이후 전체보기
                if (!isBelowTop10 && rank === "top10") {
                    message += allsee;
                    isBelowTop10 = true;
                }
                message += getRankEmoji(rankNum) + user + "에게 " + itemName + " " + count + "개 지급\n";
            });
        });
    });
    return { ok: true, message: message, noticeMessage: message };
}

// 통합·개별 지급 명령을 기존 보상 종류에 연결하는 함수
function getDailyRankingPayoutRequest(msg) {
    if (msg === "/최종순위보상지급") return { all:true };
    if (msg === "/길드영지보상지급") return { key:"territory" };
    var rows = GLOBAL_CONFIG.rewardPayout.schedules;
    for (var i = 0; i < rows.length; i++) if (msg === rows[i].command) return { key:rows[i].key };
    return null;
}

// 통합 권한과 개별 명령의 기존 허용 대상을 확인하는 함수
function isDailyRankingPayoutOperator(sender, request) {
    if (request.all) return sender === "오픈채팅봇" || isMaster(sender);
    if (request.key === "territory") return isMaster(sender) || isAdmin(sender);
    return (request.key === "guildRank" ? GLOBAL_CONFIG.rewardPayout.guildOperators : GLOBAL_CONFIG.rewardPayout.basicOperators).indexOf(sender) !== -1;
}

// 리셋과 분리해 보존할 날짜별 지급 원본을 만드는 함수
function createDailyRankingStore() {
    return { version:1, days:{} };
}

// 날짜·종류별 실제 지급 완료 기록을 검증하는 함수
function requireDailyRankingStore(store) {
    if (!store || store.version !== 1 || !store.days || typeof store.days !== "object" || Array.isArray(store.days)) throw new Error("순위 지급 기록 형식 오류");
    if (store.reset !== undefined) getDailyRankingPayoutCycle({ rewardPayoutReset: store.reset });
    var schedules = GLOBAL_CONFIG.rewardPayout.schedules, keys = [];
    for (var k = 0; k < schedules.length; k++) keys.push(schedules[k].key);
    for (var day in store.days) if (Object.prototype.hasOwnProperty.call(store.days,day)) {
        var rows = store.days[day];
        if (!/^\d{8}(?::[1-9]\d*)?$/.test(day) || !rows || typeof rows !== "object" || Array.isArray(rows)) throw new Error("순위 지급 날짜 형식 오류");
        for (var key in rows) if (Object.prototype.hasOwnProperty.call(rows,key)) {
            var row = rows[key];
            if (keys.indexOf(key) === -1 || !row || ["DONE","FAILED"].indexOf(row.status) === -1 || typeof row.at !== "string" || !isFinite(Date.parse(row.at))) throw new Error("순위 지급 완료 기록 오류");
        }
    }
    return store;
}

// 기존 다섯 지급 함수의 실제 보상 계산을 호출하는 함수
function applyDailyRankingReward(key, data, petData, guildData, homeData, petSkillData, sender) {
    if (key === "overall") return payOverallRankingReward(data,petData,guildData,homeData,petSkillData);
    if (key === "miniPet") return payMiniPetRankingReward(data,petData,guildData);
    if (key === "tier") return payTierRankingReward(data,petData,guildData);
    if (key === "territory") return runGuildTerritoryRankReward(data,guildData,sender,true);
    if (key === "guildRank") {
        var result = runGuildRankReward(data,petData,guildData,homeData,petSkillData);
        if (result.error) return {ok:false,message:"❌ 등록된 길드가 없습니다."};
        var message = buildGuildRankRewardPayoutMessage(result);
        return {ok:true,message:message,noticeMessage:message};
    }
    throw new Error("알 수 없는 순위 보상 종류");
}

// 한 종류의 전체 지급과 완료 기록을 동일한 최종 원문으로 묶는 함수
function buildDailyRankingPublication(data, guildData, store) {
    if (data.rewardPayoutReset !== undefined) store.reset = data.rewardPayoutReset; // 회원과 지급 원장에 같은 확정 회차를 보존
    var adventure = data.__adventureRecordContext;
    if (adventure && JSON.stringify(adventure.store) !== adventure.text) throw new Error("순위 지급 중 저장하지 않은 퀘스트 기록 변경 감지");
    var plan = buildMemberSplitSavePlan(data), writes = [];
    if (plan) for (var i = 0; i < plan.writes.length; i++) writes.push({name:String(new java.io.File(plan.writes[i].path).getName()),text:plan.writes[i].text});
    writes.push({name:"member.json",text:JSON.stringify(plan ? plan.member : data)},{name:"guildData.json",text:JSON.stringify(guildData)},{name:GLOBAL_CONFIG.rewardPayout.fileName,text:JSON.stringify(requireDailyRankingStore(store))});
    var journal = {version:1,pending:writes};
    validateDailyRankingPending(journal);
    return journal;
}

// 지급 복구 대상과 최종 원문을 쓰기 전에 모두 검증하는 함수
function validateDailyRankingPending(journal) {
    if (!journal || journal.version !== 1 || !Object.prototype.hasOwnProperty.call(journal,"pending") || journal.pending !== null && !Array.isArray(journal.pending)) throw new Error("순위 지급 복구 형식 오류");
    if (journal.pending === null) return;
    var seen = {};
    for (var i = 0; i < journal.pending.length; i++) {
        var row = journal.pending[i];
        if (!row || typeof row.name !== "string" || !/^(?:member|guildData|dailyRankingPayout|serverRaidData(?:_next)?|memberOperationLogs(?:_next)?)\.json$/.test(row.name) || seen[row.name] || typeof row.text !== "string") throw new Error("순위 지급 복구 대상 오류");
        seen[row.name] = true;
        var parsed = parseJsonContent(row.text,row.name);
        if (row.name === "member.json" && (!parsed || !parsed.member || typeof parsed.member !== "object" || Array.isArray(parsed.member))) throw new Error("순위 지급 회원 원문 오류");
        if (row.name === "guildData.json" && (!parsed || !parsed.guilds || typeof parsed.guilds !== "object" || Array.isArray(parsed.guilds))) throw new Error("순위 지급 길드 원문 오류");
        if (row.name === GLOBAL_CONFIG.rewardPayout.fileName) requireDailyRankingStore(parsed);
        if (/^(serverRaidData|memberOperationLogs)/.test(row.name)) requireMemberSplitStore(parsed,row.name.indexOf("serverRaidData") === 0 ? "raid" : "logs");
    }
    if (!seen["member.json"] || !seen["guildData.json"] || !seen[GLOBAL_CONFIG.rewardPayout.fileName]) throw new Error("순위 지급 복구 필수 원문 누락");
}

// 중단된 전체 지급과 완료 상태를 재계산 없이 복구하는 저장 진입 함수
function recoverDailyRankingPending() {
    dataTransactionLock.lock();
    try {
        var path = resolveActiveDataPath(DATA_ROOT_PATH+GLOBAL_CONFIG.rewardPayout.pendingName), file = new java.io.File(path), rollback = new java.io.File(path+".rollback");
        if (!file.exists() && rollback.exists()) {
            validateDailyRankingPending(parseJsonContent(FileStream.read(path+".rollback","utf-8"),path));
            if (!rollback.renameTo(file)) throw new Error("순위 지급 복구 원문 복원 실패");
        }
        if (!file.exists()) return false;
        var journal = parseJsonContent(FileStream.read(path,"utf-8"),path);
        validateDailyRankingPending(journal);
        if (journal.pending === null) return false;
        for (var i = 0; i < journal.pending.length; i++) {
            var targetPath = resolveActiveDataPath(DATA_ROOT_PATH+journal.pending[i].name);
            if (!new java.io.File(targetPath).exists() || String(FileStream.read(targetPath,"utf-8")) !== journal.pending[i].text) writeVerifiedJsonFile(targetPath,journal.pending[i].text,false);
        }
        writeVerifiedJsonFile(path,{version:1,pending:null},true);
        memberSplitBackupCache = {};
        return true;
    } finally { dataTransactionLock.unlock(); }
}

// 통합·개별·봇 지급에 같은 잠금과 날짜별 확정 기록을 적용하는 저장 진입 함수
function runDailyRankingPayoutEntry(ctx, replier, msg, sender) {
    var request = getDailyRankingPayoutRequest(msg);
    if (!request || !isDailyRankingPayoutOperator(sender,request)) { replier.reply("⛔ 권한이 없습니다.\n/최종순위보상지급 명령어는\n오픈채팅봇 또는 MASTER만 사용할 수 있습니다."); return; }
    var schedules = GLOBAL_CONFIG.rewardPayout.schedules, day = null, outcomes = [], singleMessage = "";
    var path = resolveActiveDataPath(DATA_ROOT_PATH+GLOBAL_CONFIG.rewardPayout.fileName), pendingPath = resolveActiveDataPath(DATA_ROOT_PATH+GLOBAL_CONFIG.rewardPayout.pendingName);
    dataTransactionLock.lock();
    try {
        recoverDailyRankingPending();
        for (var i = 0; i < schedules.length; i++) {
            var schedule = schedules[i];
            if (GLOBAL_CONFIG.guildWar.legacyPaused && schedule.key === "territory") {
                outcomes.push("⏸️ " + schedule.label + ": 영지전 휴식 중 (지급 중단)"); singleMessage = outcomes[outcomes.length - 1]; continue;
            }
            if (!request.all && request.key !== schedule.key) continue;
            if (!new java.io.File(path).exists() && (new java.io.File(path+".rollback").exists() || new java.io.File(getManagedJsonBackupPath(path)).exists() || new java.io.File(getManagedJsonSecondaryBackupPath(path)).exists())) throw new Error("순위 지급 완료 원본이 누락되어 확인이 필요합니다.");
            var store = new java.io.File(path).exists() ? requireDailyRankingStore(loadJsonFile(path)) : createDailyRankingStore();
            var data = loadJsonFile(filePath), guildData = loadJsonFile(guildPath);
            if (store.reset !== undefined) {
                if (data.rewardPayoutReset === undefined) throw new Error("순위 보상 /리셋 회차 원본이 누락되어 확인이 필요합니다.");
                var storedCycle = getDailyRankingPayoutCycle({ rewardPayoutReset: store.reset }), memberCycle = getDailyRankingPayoutCycle(data);
                if (memberCycle.cycle < storedCycle.cycle || memberCycle.cycle === storedCycle.cycle && (memberCycle.day !== storedCycle.day || memberCycle.at !== storedCycle.at)) throw new Error("회원과 순위 보상의 /리셋 회차가 일치하지 않습니다.");
            }
            if (data.rewardPayoutReset === undefined) {
                var initialCycle = getDailyRankingPayoutCycle(data); // 기존 완료 기록을 보존하며 최초 기준일만 고정
                data.rewardPayoutReset = { day: initialCycle.day, cycle: 0, at: 0 };
                writeVerifiedJsonFile(pendingPath, buildDailyRankingPublication(data, guildData, store), true);
                endDataSaveTransaction(); beginDataSaveTransaction();
                recoverDailyRankingPending();
                endDataSaveTransaction(); beginDataSaveTransaction();
            }
            var cycle = getDailyRankingPayoutCycle(data);
            if (day === null) day = cycle.key;
            if (day !== cycle.key) throw new Error("순위 보상 처리 중 /리셋 회차가 변경되었습니다.");
            if (!store.days[day]) store.days[day] = {};
            if (isDailyRewardPayoutDone(data,guildData,schedule.key,store)) {
                if (!store.days[day][schedule.key] || store.days[day][schedule.key].status !== "DONE") {
                    store.days[day][schedule.key] = {status:"DONE",at:new Date().toISOString()};
                    writeVerifiedJsonFile(path,store,false);
                    endDataSaveTransaction(); beginDataSaveTransaction();
                }
                outcomes.push("↪️ "+schedule.label+": 금일 지급 완료 (건너뜀)");
                singleMessage = "금일 "+schedule.label+"은 이미 지급되었습니다. 중복 지급하지 않습니다.";
                continue;
            }
            try {
                var petData = schedule.key === "territory" ? null : loadJsonFile(memberPetPath);
                var needsCharm = schedule.key === "overall" || schedule.key === "guildRank";
                var petSkillData = needsCharm ? loadJsonFile(petSkillDataPath) : null, homeData = needsCharm ? loadJsonFile(homeDataFile) : null;
                if (schedule.key !== "territory" && !petData) throw new Error("순위 산정에 필요한 미니펫 원본을 읽지 못했습니다.");
                if (needsCharm && (!petSkillData || !homeData)) throw new Error("순위 산정에 필요한 펫스킬·펫홈 원본을 읽지 못했습니다.");
                var result = applyDailyRankingReward(schedule.key,data,petData,guildData,homeData,petSkillData,sender);
                if (!result.ok) throw new Error(result.message || "보상 지급을 완료하지 못했습니다.");
                if (getDailyRankingPayoutCycle(data).key !== day) throw new Error("/리셋 회차가 변경되어 지급 전에 취소했습니다. 다시 실행해 주세요.");
                recordDailyRewardPayout(data,schedule.key,cycle.day);
                if (schedule.key === "tier") { data.tierReward.lastPaidDate=cycle.day; data.tierReward.lastPaidCycle=cycle.key; }
                store.days[day][schedule.key] = {status:"DONE",at:new Date().toISOString()};
                var journal = buildDailyRankingPublication(data,guildData,store);
                writeVerifiedJsonFile(pendingPath,journal,true);
                endDataSaveTransaction(); beginDataSaveTransaction();
                recoverDailyRankingPending();
                endDataSaveTransaction(); beginDataSaveTransaction();
                outcomes.push("✅ "+schedule.label+": 이번 실행에 지급 완료");
                singleMessage = result.message;
                if (result.noticeMessage) {
                    try { noticeMsg(result.noticeMessage); }
                    catch (noticeError) { debuggerLog("[순위 지급 알림 실패] "+noticeError); }
                }
            } catch (error) {
                try { recoverDailyRankingPending(); }
                catch (recoveryError) {
                    outcomes.push("⚠️ "+schedule.label+": 저장 복구 대기 · 확인 후 재실행해 주세요.");
                    singleMessage=outcomes[outcomes.length-1];
                    if (request.all) for (var wait=i+1;wait<schedules.length;wait++) outcomes.push("⚠️ "+schedules[wait].label+": 이전 항목의 저장 복구 후 재실행 필요");
                    break;
                }
                var confirmed = new java.io.File(path).exists() ? requireDailyRankingStore(loadJsonFile(path)) : createDailyRankingStore();
                if (confirmed.days[day] && confirmed.days[day][schedule.key] && confirmed.days[day][schedule.key].status === "DONE") {
                    endDataSaveTransaction(); beginDataSaveTransaction();
                    outcomes.push("✅ "+schedule.label+": 중단된 저장 복구 완료");
                    singleMessage=outcomes[outcomes.length-1]; continue;
                }
                if (!confirmed.days[day]) confirmed.days[day]={};
                confirmed.days[day][schedule.key]={status:"FAILED",at:new Date().toISOString()};
                writeVerifiedJsonFile(path,confirmed,false);
                endDataSaveTransaction(); beginDataSaveTransaction();
                outcomes.push("⚠️ "+schedule.label+": 미완료 · "+String(error.message || error));
                singleMessage=outcomes[outcomes.length-1];
            }
        }
        if (!request.all) { replier.reply(singleMessage); return; }
        var complete=0, skipped=0, paused=0; // 실제 지급·기완료·휴식 항목을 구분해 미완료 수 계산
        for (var r=0;r<outcomes.length;r++) {if(outcomes[r].indexOf("✅")===0)complete++;if(outcomes[r].indexOf("↪️")===0)skipped++;if(outcomes[r].indexOf("⏸️")===0)paused++;}
        replier.reply("🎁 호이월드 최종 순위보상 통합 지급\n━━━━━━━━━━━━\n"+outcomes.join("\n")+"\n━━━━━━━━━━━━\n🏆 처리 결과: 신규·복구 "+complete+"종 / 기완료 "+skipped+"종 / 휴식 "+paused+"종 / 미완료 "+(schedules.length-complete-skipped-paused)+"종\n🔒 같은 /리셋 회차 중복 지급 방지 적용");
    } finally {dataTransactionLock.unlock();}
}

// 순위 보상 명령의 당일 지급 완료 시각을 기록하는 함수
function recordDailyRewardPayout(data, rewardKey, paidDay) {
    if (!data.rewardPayoutStatus || typeof data.rewardPayoutStatus !== "object" || data.rewardPayoutStatus instanceof Array) {
        data.rewardPayoutStatus = {};
    }
    data.rewardPayoutStatus[rewardKey] = {
        lastPaidDate: paidDay || getDailyRankingPayoutCycle(data).day,
        lastPaidCycle: getDailyRankingPayoutCycle(data).key,
        lastPaidAt: formatDateTime(new Date())
    };
}

// 순위 보상별 현재 /리셋 회차의 지급 완료 여부를 확인하는 함수
function isDailyRewardPayoutDone(data, guildData, rewardKey, store) {
    var cycle = getDailyRankingPayoutCycle(data), row = store && store.days[cycle.key] && store.days[cycle.key][rewardKey];
    if (row && row.status === "DONE") return true;
    var payout = data.rewardPayoutStatus && data.rewardPayoutStatus[rewardKey] ? data.rewardPayoutStatus[rewardKey] : null;
    if (payout && payout.lastPaidCycle === cycle.key) return true;
    if (rewardKey === "tier" && data.tierReward && data.tierReward.lastPaidCycle === cycle.key) return true;
    if (rewardKey === "territory" && guildData && guildData.guildTerritoryReward && guildData.guildTerritoryReward.lastPaidCycle === cycle.key) return true;
    if (cycle.cycle !== 0) return false; // 실제 /리셋 뒤에는 과거 날짜 기록을 새 회차의 지급으로 간주하지 않는다.
    if (payout && payout.lastPaidCycle === undefined && payout.lastPaidDate === cycle.day) return true;
    if (rewardKey === "tier") return !!(data.tierReward && data.tierReward.lastPaidCycle === undefined && data.tierReward.lastPaidDate === cycle.day);
    if (rewardKey === "territory") return getGuildTerritoryRewardPaidDay(guildData) === cycle.day;
    return false;
}

// 패스목록에 표시할 현재 /리셋 회차의 순위 보상 현황을 만드는 함수
function buildDailyRewardPayoutStatusLines(data, guildData, store) {
    var schedules = GLOBAL_CONFIG.rewardPayout.schedules;
    var lines = ["《🎁 금일 순위 보상 지급 현황》"], completedCount=0;
    for (var i = 0; i < schedules.length; i++) {
        var schedule = schedules[i];
        if (GLOBAL_CONFIG.guildWar.legacyPaused && schedule.key === "territory") { lines.push("⏸️ 길드영지포인트 순위보상: 영지전 휴식 중 · 지급 중단"); completedCount++; continue; }
        var day = getDailyRankingPayoutCycle(data).key, row = store && store.days[day] && store.days[day][schedule.key];
        var paidMark = isDailyRewardPayoutDone(data, guildData, schedule.key, store) ? "✅" : row && row.status === "FAILED" ? "⚠️" : "❌";
        if (paidMark === "✅") completedCount++;
        lines.push(schedule.command + " " + schedule.time + " [" + paidMark + "]");
        lines.push("└ " + schedule.label);
    }
    lines.push("━━━━━━━━━━━━");
    if (completedCount === schedules.length) lines.push("✅ 금일 운영 중인 순위보상 지급 완료", "🛠️ 통합 지급: /최종순위보상지급");
    else lines.push("🎁 통합 순위보상 지급", "🛠️ /최종순위보상지급", "└ 관리자 명령어 한 번으로 운영 중인 순위보상 일괄 지급", "└ 이미 지급된 보상은 중복 지급하지 않음", "└ 사용 권한: 오픈채팅봇, MASTER");
    lines.push("※ 표기 시각은 기존 지급 안내 시각입니다. 기존 영지포인트 순위보상은 휴식 중이에요.", "※ 지급 완료는 /리셋할 때까지 유지되며 자정에 초기화되지 않아요.");
    return lines;
}

// 전체 후원패스 목록 메시지를 만드는 함수
function buildSupportPassListMessage(data, petData, guildData, rankingStore) {
    var configs = getSupportPassConfigs();
    var lines = ["호월패스 전체목록 안내:", "[원데이패스, 초보패스, 호이패스, 호이패스 프리미엄, 길드공헌패스, 다이아패스, 영지기습패스] / " + allsee, ""];
    for (var i = 0; i < configs.length; i++) {
        var config = configs[i];
        var activeUsers = [];
        for (var user in data.member) {
            if (isSupportPassActive(data, user, config.key)) activeUsers.push(user);
        }
        activeUsers.sort(function (a, b) {
            var ap = data.member[a].pass && data.member[a].pass[config.key] ? data.member[a].pass[config.key] : { permanent: true };
            var bp = data.member[b].pass && data.member[b].pass[config.key] ? data.member[b].pass[config.key] : { permanent: true };
            if (ap.permanent && !bp.permanent) return 1;
            if (!ap.permanent && bp.permanent) return -1;
            return (getSupportPassDateValue(ap.endDate) || 99999999) - (getSupportPassDateValue(bp.endDate) || 99999999);
        });
        lines.push(config.label + " 명단");
        if (activeUsers.length < 1) {
            lines.push("미사용중[❌]");
        } else {
            for (var j = 0; j < activeUsers.length; j++) {
                var pass = data.member[activeUsers[j]].pass && data.member[activeUsers[j]].pass[config.key] ? data.member[activeUsers[j]].pass[config.key] : null;
                var endText = !pass ? "미사용중[❌]" : (pass.permanent ? "영구권 사용중[✅]" : pass.endDate + " 까지");
                lines.push("[" + checkRank(data, petData, guildData, activeUsers[j]) + "] " + endText);
            }
        }
        lines.push("━━━━━━━━━━━");
        lines.push("");
    }
    var rewardPayoutLines = buildDailyRewardPayoutStatusLines(data, guildData, rankingStore);
    for (var rewardLineIndex = 0; rewardLineIndex < rewardPayoutLines.length; rewardLineIndex++) {
        lines.push(rewardPayoutLines[rewardLineIndex]);
    }
    lines.push("");
    var invalidTicketUsers = getInvalidAutoExploreTicketUsers(data);
    lines.push("━━━━━━━━━━━━");
    if (invalidTicketUsers.length < 1) {
        lines.push("✅ 자동탐험권 정합성 검사");
        lines.push("삭제 대상 유저가 없습니다.");
    } else {
        lines.push("⚠️ 자동탐험권 수동 삭제해야하는 유저");
        lines.push("━━━━━━━━━━━━");
        lines.push("초보패스·호이패스·호이패스 프리미엄 명단에는 없지만");
        lines.push("자동탐험권🌄을 보유 중인 유저입니다.");
        lines.push("");
        for (var invalidIndex = 0; invalidIndex < invalidTicketUsers.length; invalidIndex++) {
            var invalidTicketUser = invalidTicketUsers[invalidIndex];
            lines.push((invalidIndex + 1) + ". " + checkRank(data, petData, guildData, invalidTicketUser.user) + " — 자동탐험권🌄 x" + invalidTicketUser.count);
        }
        lines.push("");
        lines.push("총 " + invalidTicketUsers.length + "명");
    }
    lines.push("");
    var freeSupportPackageConfig = GLOBAL_CONFIG.supportPass.freeSupportPackage;
    var freeSupportPackageUsers = getHoiFreeSupportPackageAlertUsers(data);
    lines.push("━━━━━━━━━━━━");
    if (freeSupportPackageUsers.length < 1) {
        lines.push("✅ " + freeSupportPackageConfig.baseName + " 보유 검사");
        lines.push(freeSupportPackageConfig.alertCount + "개 이상 소지 유저가 없습니다.");
    } else {
        lines.push("⚠️ " + freeSupportPackageConfig.baseName + " " + freeSupportPackageConfig.alertCount + "개 이상 소지 유저");
        lines.push("━━━━━━━━━━━━");
        lines.push("[" + freeSupportPackageConfig.minVariant + "]~[" + freeSupportPackageConfig.maxVariant + "] 합산 기준입니다.");
        lines.push("");
        for (var packageUserIndex = 0; packageUserIndex < freeSupportPackageUsers.length; packageUserIndex++) {
            var freeSupportPackageUser = freeSupportPackageUsers[packageUserIndex];
            lines.push((packageUserIndex + 1) + ". " + checkRank(data, petData, guildData, freeSupportPackageUser.user) + " — " + freeSupportPackageConfig.baseName + " x" + freeSupportPackageUser.count);
        }
        lines.push("");
        lines.push("총 " + freeSupportPackageUsers.length + "명");
    }
    return lines.join("\n");
}

// 후원패스 명령어의 대상과 옵션을 분석하는 함수
function parseSupportPassCommandMeta(msg) {
    var passMatch = String(msg || "").match(/^\/(원데이패스|공헌패스|초보패스|초보|호이패스|다이아패스|영지패스|인형패스)(추가|삭제),\s*([^]+)$/);
    if (!passMatch) return null;
    var passConfig = getSupportPassConfigByCommandName(passMatch[1]);
    if (!passConfig) return null;
    var action = passMatch[2];
    var body = String(passMatch[3] || "").trim();
    var tokens = body.split(/\s+/);
    var lastToken = tokens.length > 0 ? tokens[tokens.length - 1] : "";
    var option = action === "추가" && (lastToken === "영구권" || isValidSupportPassDateText(lastToken)) ? lastToken : "";
    var shouldSplitTerritoryOption = action === "추가" && (passConfig.key === "territory" || passConfig.key === "doll");
    var userIDText = action === "추가" && (option || shouldSplitTerritoryOption) ? tokens.slice(0, tokens.length - 1).join(" ") : body;
    return { config: passConfig, action: action, user: userIDText, option: option };
}

// 저장된 후원패스 상태를 확인하는 함수
function buildSupportPassSaveCheckMessage(msg, savedData) {
    var meta = parseSupportPassCommandMeta(msg);
    if (!meta || !savedData || !savedData.member || !savedData.member[meta.user]) return "\n⚠️ 저장확인: member.json에서 대상 유저를 확인하지 못했습니다.";
    var member = savedData.member[meta.user];
    var pass = member.pass && member.pass[meta.config.key] ? member.pass[meta.config.key] : null;
    if (meta.action === "추가") {
        if (!pass || pass.enabled !== true) return "\n⚠️ 저장확인: member.json에서 패스 저장을 확인하지 못했습니다.";
        var savedEndText = pass.permanent === true ? "영구권" : pass.endDate + "까지";
        var lines = ["\n저장확인: 패스 저장 완료 (" + savedEndText + ")"];
        if (meta.config.key === "newbie" || meta.config.key === "hoi") {
            var ticketCount = getAutoExploreTicketCount(savedData, meta.user);
            lines.push("저장확인: 자동탐험권🌄 " + ticketCount + "개");
        }
        return lines.join("\n");
    }
    if (pass && pass.enabled === true) return "\n⚠️ 저장확인: member.json에서 패스 삭제를 확인하지 못했습니다.";
    var deleteLines = ["\n저장확인: 패스 삭제 저장 완료"];
    if (meta.config.key === "newbie" || meta.config.key === "hoi") {
        var remainingTicketCount = getAutoExploreTicketCount(savedData, meta.user);
        if (!hasActiveAutoExplorePass(savedData, meta.user)) {
            if (remainingTicketCount > 0) {
                deleteLines.push("⚠️ 저장확인: 자동탐험권🌄 " + remainingTicketCount + "개가 남아 있습니다.");
            } else {
                deleteLines.push("저장확인: 자동탐험권🌄 회수 완료");
            }
        } else {
            deleteLines.push("저장확인: 다른 자동탐험 패스가 유효하여 자동탐험권🌄 유지");
        }
    }
    return deleteLines.join("\n");
}

// 자동탐험권을 유지할 수 있는 후원패스가 활성 상태인지 확인하는 함수
function hasActiveAutoExplorePass(data, user) {
    return isSupportPassActive(data, user, "newbie") ||
        isSupportPassActive(data, user, "hoi") ||
        isHoiPassPremiumActive(data, user);
}

// 호이패스 프리미엄 관리자 명령어 형식이 정확한지 확인하는 함수
function isHoiPassPremiumAdminCommandMessage(msg) {
    var text = String(msg || "");
    return /^\/호패프리미엄추가\s+[^]+\s+\d{2}\.\d{2}\.\d{2}$/.test(text) ||
        /^\/호패프리미엄추가,\s*[^]+\s+\d{2}\.\d{2}\.\d{2}$/.test(text) ||
        /^\/호패프리미엄삭제,\s*[^]+$/.test(text) ||
        /^\/호프단체추가\s+[^\/]+\/\d{2}\.\d{2}\.\d{2}$/.test(text);
}

// 호이패스 프리미엄 관리자 명령어의 대상과 날짜를 분석하는 함수
function parseHoiPassPremiumCommand(msg) {
    var text = String(msg || "");
    var addMatch = text.match(/^\/호패프리미엄추가,\s*([^]+)\s+(\d{2}\.\d{2}\.\d{2})$/) ||
        text.match(/^\/호패프리미엄추가\s+([^]+)\s+(\d{2}\.\d{2}\.\d{2})$/);
    if (addMatch) return { action: "추가", user: addMatch[1].trim(), endDate: addMatch[2] };
    var deleteMatch = text.match(/^\/호패프리미엄삭제,\s*([^]+)$/);
    if (deleteMatch) return { action: "삭제", user: deleteMatch[1].trim(), endDate: "" };
    var groupMatch = text.match(/^\/호프단체추가\s+([^\/]+)\/(\d{2}\.\d{2}\.\d{2})$/);
    if (groupMatch) {
        var rawUsers = groupMatch[1].split(",");
        var users = [];
        var seenUsers = {};
        for (var i = 0; i < rawUsers.length; i++) {
            var user = String(rawUsers[i] || "").trim();
            if (!user) return null;
            if (!seenUsers[user]) {
                seenUsers[user] = true;
                users.push(user);
            }
        }
        return { action: "단체추가", users: users, endDate: groupMatch[2] };
    }
    return null;
}

// 기간권 명령의 종류·개수를 완전 일치로 확인하는 함수
function parsePassDurationRequest(message) {
    var configs = GLOBAL_CONFIG.passDuration.tickets;
    for (var i = 0; i < configs.length; i++) {
        var commands = [configs[i].command];
        if (configs[i].key === "premium" && configs[i].days === 30) commands.push(GLOBAL_CONFIG.passDuration.legacyPremiumCommand);
        for (var j = 0; j < commands.length; j++) {
            var command = commands[j];
            if (message !== command && (message.indexOf(command) !== 0 || !/\s/.test(message.charAt(command.length)))) continue;
            var suffix = message.substring(command.length), match = /^(?:[ \t]+(\d+))?$/.exec(suffix);
            var count = match && match[0] === suffix ? (match[1] === undefined ? 1 : Number(match[1])) : 0;
            return { config: configs[i], count: count, valid: isPointShopSafeCount(count) && count > 0 && isPointShopSafeCount(count * configs[i].days) };
        }
    }
    return null;
}

// 기간권의 정식 사용법을 안내하는 함수
function buildPassDurationUsage(config) {
    return "❌ 올바른 사용 개수를 입력해주세요.\n━━━━━━━━━━━━\n📌 1개 사용: " + config.command + "\n📌 여러 개 사용: " + config.command + " [개수]";
}

// 구 프리미엄 30일권도 신규 지급부터 정식 이름으로 통일하는 함수
function normalizePassDurationItemName(name) {
    return name === GLOBAL_CONFIG.passDuration.legacyPremiumItem ? GLOBAL_CONFIG.passDuration.tickets[5].itemName : name;
}

// 운영 중인 패키지를 보존하며 기간권 6종의 고정 구성만 카탈로그에 제공하는 함수
function getPassDurationPackageCatalog(packages) {
    if (!Array.isArray(packages)) throw new Error("패키지 목록 형식 오류");
    var result = packages.slice(), configs = GLOBAL_CONFIG.passDuration.tickets;
    for (var i = 0; i < configs.length; i++) {
        var found = false, config = configs[i];
        for (var j = 0; j < result.length; j++) {
            if (getPackageBagItemName(result[j]) !== config.packageName) continue;
            found = true;
        }
        if (!found) result.push({ id: "pass_duration_" + config.key + "_" + config.days, name: config.packageName, enabled: true, rewards: [{ type: "item", name: config.itemName, count: 1 }] });
    }
    return result;
}

// 정식 기간권 패키지 이름에 해당하는 설정을 찾는 함수
function getPassDurationPackageConfig(name) {
    var tickets = GLOBAL_CONFIG.passDuration.tickets;
    for (var i = 0; i < tickets.length; i++) if (tickets[i].packageName === name) return tickets[i];
    return null;
}

// 정식 기간권 패키지의 고정 구성 오류를 변경·개봉 전에 확인하는 함수
function getPassDurationPackageError(packageInfo) {
    var config = getPassDurationPackageConfig(getPackageBagItemName(packageInfo));
    if (!config) return "";
    var rewards = packageInfo.rewards;
    if (!Array.isArray(rewards) || rewards.length !== 1 || !rewards[0] || rewards[0].type !== "item" || normalizePassDurationItemName(rewards[0].name) !== config.itemName || rewards[0].count !== 1) return "기간권 패키지는 해당 이용권 1개로 구성해야 합니다: " + config.packageName;
    return "";
}

// 기간권 지급 합계를 사전 검증해 개봉 후 수량 손상과 일부 지급을 막는 함수
function validatePassDurationPackageStock(data, user, packageInfo, useCount) {
    var rewards = packageInfo.rewards || [], tickets = GLOBAL_CONFIG.passDuration.tickets;
    var bag = data.member[user].bag || {}, totals = {}; // 동일 이용권의 여러 보상 항목을 합산
    for (var i = 0; i < rewards.length; i++) {
        var reward = rewards[i];
        if (!reward || reward.type !== "item") continue;
        var name = normalizePassDurationItemName(reward.name), config = null;
        for (var j = 0; j < tickets.length; j++) if (tickets[j].itemName === name) { config = tickets[j]; break; }
        if (!config) continue;
        if (!isPointShopSafeCount(useCount) || useCount < 1 || !isPointShopSafeCount(reward.count) || reward.count < 1 || !isPointShopSafeCount(reward.count * useCount)) throw new Error("기간권 지급 수량을 확인해주세요. 패키지는 사용하지 않았습니다.");
        if (totals[name] === undefined) {
            var held = bag[name] === undefined ? 0 : bag[name];
            if (!isPointShopSafeCount(held)) throw new Error("기간권 보유 수량을 확인해주세요. 패키지는 사용하지 않았습니다.");
            if (config.key === "premium" && config.days === 30) {
                var legacyHeld = bag[GLOBAL_CONFIG.passDuration.legacyPremiumItem] === undefined ? 0 : bag[GLOBAL_CONFIG.passDuration.legacyPremiumItem];
                if (!isPointShopSafeCount(legacyHeld) || !isPointShopSafeCount(held + legacyHeld)) throw new Error("기간권 보유 수량을 확인해주세요. 패키지는 사용하지 않았습니다.");
                held += legacyHeld;
            }
            totals[name] = held;
        }
        var next = totals[name] + reward.count * useCount; // 구·신 보유량과 이번 지급량의 최종 합계
        if (!isPointShopSafeCount(next)) throw new Error("기간권 보유 수량의 안전한 처리 범위를 초과했습니다. 패키지는 사용하지 않았습니다.");
        totals[name] = next;
    }
}

// 검증된 기간권을 차감하고 해당 패스의 KST 종료일만 연장하는 함수
function applyPassDurationExtension(data, skills, activity, user, request, today) {
    var config = request.config, count = request.count;
    if (!request.valid) return { ok: false, message: buildPassDurationUsage(config) };
    var member = data.member && data.member[user];
    if (!member) return { ok: false, message: "❌ 가입 상태를 확인해주세요." };
    if (member.bag !== undefined && (!member.bag || typeof member.bag !== "object" || Array.isArray(member.bag)) || member.pass !== undefined && (!member.pass || typeof member.pass !== "object" || Array.isArray(member.pass))) throw new Error("기간권 보유·패스 정보 형식 오류");
    var bag = member.bag || {}, names = [config.itemName], stock = 0;
    if (config.key === "premium" && config.days === 30) names.push(GLOBAL_CONFIG.passDuration.legacyPremiumItem);
    for (var i = 0; i < names.length; i++) {
        var itemCount = bag[names[i]] === undefined ? 0 : bag[names[i]];
        if (!isPointShopSafeCount(itemCount) || !isPointShopSafeCount(stock + itemCount)) throw new Error("기간권 보유 수량 오류");
        stock += itemCount;
    }
    if (stock < count) return { ok: false, message: "❌ 이용권 사용 실패!\n━━━━━━━━━━━━\n🎟️ 아이템: " + config.itemName + "\n📦 보유: " + stock + "개 / 요청: " + count + "개 / 부족: " + (count - stock) + "개\n📌 사용법: " + config.command + " [개수]" };
    var previous = member.pass && member.pass[config.key];
    if (previous !== undefined && (!previous || typeof previous !== "object" || Array.isArray(previous))) throw new Error("기존 패스 정보 형식 오류");
    var label = config.key === "hoi" ? "호이패스🐶" : "호이패스 프리미엄👑";
    if (previous && previous.enabled === true && previous.permanent === true) return { ok: false, message: "❌ 이용권 사용 실패!\n━━━━━━━━━━━━\n" + label + " 영구권 사용 중이므로 기간 연장권을 사용할 수 없습니다.\n📦 아이템은 차감되지 않았습니다." };
    var oldText = previous ? previous.endDate : "", oldDate = getSupportPassDateValue(oldText);
    if (previous && previous.permanent !== true && oldDate === null) return { ok: false, message: "❌ 기존 패스 종료일을 확인해주세요. 아이템은 사용하지 않았습니다." };
    var active = !!(previous && previous.enabled === true && oldDate >= today);
    var base = active ? oldDate : today; // 미가입·만료는 사용 당일을 첫날로 포함
    var year = Math.floor(base / 10000), month = Math.floor(base / 100) % 100, day = base % 100;
    var end = new Date(Date.UTC(year, month - 1, day + count * config.days - (active ? 0 : 1)));
    if (!isFinite(end.getTime()) || end.getUTCFullYear() < 2000 || end.getUTCFullYear() > 2099) return { ok: false, message: "❌ 적용 가능한 기간을 초과했습니다. 아이템은 사용하지 않았습니다." };
    var endText = String(end.getUTCFullYear()).slice(-2) + "." + ("0" + (end.getUTCMonth() + 1)).slice(-2) + "." + ("0" + end.getUTCDate()).slice(-2);
    if (active) previous.endDate = endText;
    else if (config.key === "premium") addHoiPassPremium(data, skills, activity, user, endText, user, true);
    else {
        var pass = previous || {};
        pass.enabled = true; pass.permanent = false; pass.endDate = endText;
        ensureSupportPassStore(data, user).hoi = pass;
        if (getAutoExploreTicketCount(data, user) < 1) addItem(data, user, "자동탐험권🌄", 1);
    }
    var remaining = count; // 신·구 30일권을 합쳐 요청 수량만 한 번 차감
    for (var n = 0; n < names.length && remaining > 0; n++) {
        var used = Math.min(bag[names[n]] || 0, remaining);
        if (used > 0) removeItem(data, user, names[n], used);
        remaining -= used;
    }
    var displayLabel = config.key === "hoi" ? "🐶 호이패스 기간" : "👑 호이패스 프리미엄";
    var text = displayLabel + " " + (active ? "연장" : "활성화") + " 완료!\n━━━━━━━━━━━━\n🎟️ 사용: " + config.itemName + " ×" + count;
    text += active ? "\n📅 기존 종료일: " + oldText + "\n➕ 추가 기간: " + count * config.days + "일" : "\n📅 적용 기간: " + count * config.days + "일";
    text += "\n✅ " + (active ? "변경 종료일: " : "종료 예정일: ") + endText + (active ? "\n\n기존 " + (config.key === "hoi" ? "호이패스" : "프리미엄") + " 혜택은 그대로 유지됩니다." : "\n\n🐹 호월패스 사용 현황에 반영되었습니다.");
    return { ok: true, premiumActivated: config.key === "premium" && !active, message: text };
}

// 검증된 유저에게 프리미엄 자격·홈뱃지·잠금 스킬을 적용하는 함수
function addHoiPassPremium(data, petSkillData, activityData, user, endDate, operator, avoidDuplicateTicket) {
    var passStore = ensureSupportPassStore(data, user);
    var previous = passStore.premium || {};
    var shouldGrantAutoExploreTicket = !isSupportPassActive(data, user, "hoi") && (!avoidDuplicateTicket || getAutoExploreTicketCount(data, user) < 1); // 기본 호이패스가 없을 때 프리미엄용 자동탐험권 지급
    passStore.premium = {
        enabled: true,
        endDate: endDate,
        permanent: false,
        dailyRewardLastDate: previous.dailyRewardLastDate || "",
        badgeGranted: true
    };
    if (shouldGrantAutoExploreTicket) addItem(data, user, "자동탐험권🌄", 1);
    grantHoiPassPremiumBadge(activityData, user, operator);
    var restoredSkillCount = restoreHoiPassPremiumLockedSkills(data, petSkillData, user);
    return { autoExploreTicketGranted: shouldGrantAutoExploreTicket, restoredSkillCount: restoredSkillCount };
}

// 호이패스 프리미엄 추가·삭제를 저장 전 데이터에 반영하는 함수
function processHoiPassPremiumCommand(msg, data, petSkillData, activityData, operator) {
    var meta = parseHoiPassPremiumCommand(msg);
    if (!meta) return { changed: false, message: "사용법:\n/호패프리미엄추가, 아이디 YY.MM.DD\n/호패프리미엄삭제, 아이디\n/호프단체추가 아이디,아이디/YY.MM.DD" };

    if (meta.action === "추가" || meta.action === "단체추가") {
        var expireValue = getSupportPassDateValue(meta.endDate);
        if (expireValue === null) return { changed: false, message: "❌ 날짜 형식이 올바르지 않습니다.\n예: /호패프리미엄추가, 콘트 남 26.08.30" };
        if (expireValue < getTodaySupportPassDateValue()) return { changed: false, message: "❌ 지난 날짜로 호이패스 프리미엄을 추가할 수 없습니다." };
    }

    if (meta.action === "단체추가") {
        if (meta.users.length < 1) return { changed: false, message: "❌ 적용할 유저를 한 명 이상 입력해주세요." };
        var missingUsers = [];
        for (var groupUserIndex = 0; groupUserIndex < meta.users.length; groupUserIndex++) {
            if (!data.member || !data.member[meta.users[groupUserIndex]]) missingUsers.push(meta.users[groupUserIndex]);
        }
        if (missingUsers.length > 0) return { changed: false, message: "❌ 존재하지 않는 유저가 포함되어 있어 단체 적용을 취소했습니다.\n대상: " + missingUsers.join(", ") };
        var autoTicketGrantedCount = 0;
        var restoredSkillCount = 0;
        for (var applyIndex = 0; applyIndex < meta.users.length; applyIndex++) {
            var groupAddResult = addHoiPassPremium(data, petSkillData, activityData, meta.users[applyIndex], meta.endDate, operator);
            if (groupAddResult.autoExploreTicketGranted) autoTicketGrantedCount++;
            restoredSkillCount += groupAddResult.restoredSkillCount;
        }
        return {
            changed: true,
            action: "단체추가",
            requiresPetSkillSave: restoredSkillCount > 0,
            message: "✅ 호이패스 프리미엄 단체 적용을 완료했습니다.\n종료 예정일: " + meta.endDate + "\n적용: " + meta.users.length + "명\n자동탐험권 지급: " + autoTicketGrantedCount + "명" + (restoredSkillCount > 0 ? "\n잠금 펫스킬 재활성화: " + restoredSkillCount + "개" : "") + "\n대상: " + meta.users.join(", ")
        };
    }

    if (!data.member || !data.member[meta.user]) return { changed: false, message: "❌ 해당 유저를 찾을 수 없습니다." };

    if (meta.action === "추가") {
        var addResult = addHoiPassPremium(data, petSkillData, activityData, meta.user, meta.endDate, operator);
        return {
            changed: true,
            action: "추가",
            requiresPetSkillSave: addResult.restoredSkillCount > 0,
            message: "✅ [" + meta.user + "] 님에게 호이패스 프리미엄을 적용했습니다.\n종료 예정일: " + meta.endDate + "\n전용 홈뱃지:  호패 프리미엄" + (addResult.autoExploreTicketGranted ? "\n자동탐험권🌄 1개를 지급했습니다." : "\n기존 호이패스가 활성 상태여서 자동탐험권🌄을 추가 지급하지 않았습니다.") + (addResult.restoredSkillCount > 0 ? "\n잠금 펫스킬 " + addResult.restoredSkillCount + "개를 다시 활성화했습니다." : "")
        };
    }

    var currentPass = data.member[meta.user].pass && data.member[meta.user].pass.premium ? data.member[meta.user].pass.premium : null;
    if (!currentPass || currentPass.enabled !== true) return { changed: false, message: "❌ 해당 유저는 호이패스 프리미엄을 이용 중이지 않습니다." };
    var expireResult = expireHoiPassPremium(data, petSkillData, activityData, meta.user, "관리자 삭제", operator);
    return {
        changed: expireResult.changed,
        action: "삭제",
        targetUser: meta.user,
        requiresPetSkillSave: expireResult.changed,
        message: "✅ [" + meta.user + "] 님의 호이패스 프리미엄을 삭제했습니다.\n프리미엄 전용 혜택과 홈뱃지가 해제되었습니다." + (expireResult.lockedSkillCount > 0 ? "\n프리미엄 슬롯 펫스킬 " + expireResult.lockedSkillCount + "개는 잠금 보관되며 효과가 적용되지 않습니다." : "")
    };
}

function processUserIDCommand(msg, data, operator) {
    var passMeta = parseSupportPassCommandMeta(msg);
    if (!passMeta) return "알 수 없는 명령어입니다.";

    var passConfig = passMeta.config;
    if (!passConfig) return "알 수 없는 명령어입니다.";
    var action = passMeta.action;
    var option = passMeta.option;
    var userIDText = passMeta.user;

    if (action === "추가") {
        if ((passConfig.key === "territory" || passConfig.key === "doll") && !option) {
            return "❌ 날짜 형식이 올바르지 않습니다.\n\n사용법:\n/" + passConfig.commandNames[0] + "추가, 아이디 YY.MM.DD\n/" + passConfig.commandNames[0] + "추가, 아이디 영구권";
        }
        if (!data.member || !data.member[userIDText]) return "❌ 해당 유저를 찾을 수 없습니다.";
        if (!option) option = "영구권";
        if (option !== "영구권") {
            var expireValue = getSupportPassDateValue(option);
            if (expireValue !== null && expireValue < getTodaySupportPassDateValue()) {
                return "❌ 지난 날짜로 패스를 추가할 수 없습니다.\n오늘 이후 날짜를 입력해주세요.\n예) /" + passConfig.commandNames[0] + "추가, " + userIDText + " 26.09.30";
            }
        }
        var passStore = ensureSupportPassStore(data, userIDText);
        var previousPass = passStore[passConfig.key] || {};
        var previousTerritoryPassValue = passConfig.key === "territory" ? copyTerritoryPassAuditValue(previousPass) : null;
        var beforeActive = previousPass.enabled === true;
        var nextPass = {
            enabled: true,
            endDate: option === "영구권" ? "" : option,
            permanent: option === "영구권"
        };
        if (passConfig.key === "territory" || passConfig.key === "doll") nextPass.dailyRewardLastDate = previousPass.dailyRewardLastDate || "";
        passStore[passConfig.key] = nextPass;
        if (passConfig.key === "territory") {
            passStore[passConfig.key].createdAt = previousPass.createdAt || formatDateTime(new Date());
            passStore[passConfig.key].updatedAt = formatDateTime(new Date());
            passStore[passConfig.key].createdBy = previousPass.createdBy || operator || "시스템";
            passStore[passConfig.key].updatedBy = operator || "시스템";
            appendTerritoryPassAuditLog(data, operator, userIDText, beforeActive ? "연장" : "추가", previousTerritoryPassValue, copyTerritoryPassAuditValue(passStore[passConfig.key]));
        }
        var passEndText = option === "영구권" ? "영구권" : option + "까지";
        if (passConfig.key === "territory") {
            return "✅ 영지기습패스 추가 완료\n" +
                "━━━━━━━━━━━━━━━━\n" +
                "대상: " + userIDText + "\n" +
                "만료일: " + passEndText + "\n\n" +
                "일일 지급 구성\n" +
                "└ 영지기습공격권🔥(40%) x2\n" +
                "└ 영지절대방어권🛡(50%) x2\n" +
                "└ 🌪️ 전쟁불안정 증폭권(/불안정) x1\n" +
                "└ 다이아상자💎(/다이아상자오픈) x1\n" +
                "└ 피뢰침⚡(자동 벼락 방지) 1개\n" +
                "\n구독 기능\n" +
                "└ 길드영지 자동 준비\n" +
                "└ 영지 자동 공격(/영지온, /영지오프)\n" +
                "━━━━━━━━━━━━━━━━" +
                (beforeActive ? "\n기존 패스의 만료일을 갱신했습니다." : "");
        }
        var addLines = [
            beforeActive ? "⚠️ 이미 해당 패스를 보유 중입니다.\n기존 종료일을 새 종료일로 갱신합니다." : userIDText + " 사용자에게 패스가 추가되었습니다.",
            "패스 기간: " + passEndText
        ];
        if (passConfig.key === "newbie" || passConfig.key === "hoi") {
            addItem(data, userIDText, "자동탐험권🌄", 1);
            addLines.push("자동탐험권🌄 1개가 지급되었습니다.");
        }
        return addLines.join("\n");
    }

    if (!data.member || !data.member[userIDText]) return "❌ 해당 유저를 찾을 수 없습니다.";
    var userPassStore = ensureSupportPassStore(data, userIDText);
    if (!userPassStore[passConfig.key] || userPassStore[passConfig.key].enabled !== true) {
        return "❌ 해당 유저는 해당 패스를 보유하고 있지 않습니다.";
    }
    var deletedTerritoryPassBeforeValue = passConfig.key === "territory" ? copyTerritoryPassAuditValue(userPassStore[passConfig.key]) : null;
    userPassStore[passConfig.key].enabled = false;
    if (passConfig.key === "territory") {
        userPassStore[passConfig.key].updatedAt = formatDateTime(new Date());
        userPassStore[passConfig.key].updatedBy = operator || "시스템";
        if (!hasGuildTerritoryAutoAttackEntitlement(data, userIDText) && data.member[userIDText].guildTerritoryAutoAttackEnabled === true) {
            data.member[userIDText].guildTerritoryAutoAttackEnabled = false;
            appendGuildTerritoryAutomationDataLog(data, {
                type: "AUTO_ATTACK_OFF",
                user: userIDText,
                reason: "영지기습패스 관리자 삭제",
                processedAt: formatDateTime(new Date())
            });
        }
        appendTerritoryPassAuditLog(data, operator, userIDText, "삭제", deletedTerritoryPassBeforeValue, copyTerritoryPassAuditValue(userPassStore[passConfig.key]));
        return "✅ 영지기습패스 삭제 완료\n" +
            "━━━━━━━━━━━━━━━━\n" +
            "대상: " + userIDText + "\n\n" +
            "영지기습패스 명단에서 삭제되었습니다.\n" +
            "패스로 이용하던 길드영지 자동화 권한도 종료됩니다.\n" +
            "다른 패스 가입 정보는 유지됩니다.\n" +
            "━━━━━━━━━━━━━━━━";
    }
    var deleteLines = [userIDText + " 사용자의 패스가 삭제되었습니다."];
    if (passConfig.key === "newbie" || passConfig.key === "hoi") {
        if (!hasActiveAutoExplorePass(data, userIDText)) {
            removeAllAutoExploreTickets(data, userIDText);
            deleteLines.push("자동탐험권🌄을 모두 회수했습니다.");
        } else {
            deleteLines.push("다른 자동탐험 패스가 유효하여 자동탐험권🌄을 유지합니다.");
        }
    }
    return deleteLines.join("\n");
}
//////////////////////////////////////////////////////////////////////
// 이 아래는 info.js와 같은 함수를 사용하므로 수정 시 싱크맞춰야합니다.//
//////////////////////////////////////////////////////////////////////
function runPetUpgradeOnce(sender, data, petData, guildData, petSkillData) {
    var user = data.member[sender];
    if (!petData[sender]) {
        return { ok: false, message: "펫이 없습니다.", costSpent: false };
    }
    if (!petData[sender].upgrade) petData[sender].upgrade = 0;

    var upgradeLevel = petData[sender].upgrade;
    var upgradeCost = upgradeLevel < 100 ? 20000000 : upgradeLevel < 200 ? 50000000 : 100000000;
    if (user.point < upgradeCost) {
        return {
            ok: false,
            message: "포인트가 부족합니다.\n현재 포인트: " + numberWithCommas(user.point) + "\n필요한 포인트: " + numberWithCommas(upgradeCost),
            costSpent: false
        };
    }

    var needItemCount = upgradeLevel + 1;
    if (!user.bag["펫 강화석⭐"] || user.bag["펫 강화석⭐"] < needItemCount) {
        return {
            ok: false,
            message: "펫 강화석⭐이 부족합니다.\n필요한 펫 강화석⭐: " + needItemCount + "개",
            costSpent: false
        };
    }

    function findBestPetBoostItem(bag) {
        var best = null,
            bestPct = 0;
        var re = /^펫강화확률UP🌟\((\d+(?:\.\d+)?)%\)$/;
        for (var k in bag) {
            if (!bag.hasOwnProperty(k)) continue;
            if (!bag[k] || bag[k] <= 0) continue;
            var m = k.match(re);
            if (m) {
                var pct = parseFloat(m[1]);
                if (!isNaN(pct) && pct > bestPct) {
                    bestPct = pct;
                    best = k;
                }
            }
        }
        return best
            ? {
                name: best,
                addPct: bestPct
            }
            : null;
    }

    var traitApplied = hasPetSkill(petSkillData, sender, "대머리 대장장이");
    var traitBonus = traitApplied ? 0.05 : 0.0;
    var baseProbNow = upgradeLevel < 100 ? 0.55 - upgradeLevel * 0.005 : 0.05;
    var boostEligible = baseProbNow + traitBonus < 1.0;
    var chosenBoost = boostEligible ? findBestPetBoostItem(user.bag) : null;
    var boostApplied = !!chosenBoost;
    var boostBonus = boostApplied ? chosenBoost.addPct / 100 : 0.0;

    var currentProb = baseProbNow + boostBonus + traitBonus;
    if (currentProb > 1) currentProb = 1;

    var bonusLines = [];
    if (boostApplied) {
        removeItem(data, sender, chosenBoost.name, 1);
        var leftCntAfterUse = Math.max(0, user.bag[chosenBoost.name] || 0);
        bonusLines.push(chosenBoost.name + " 사용 (보유: " + leftCntAfterUse + "개)");
    }
    if (traitApplied) {
        bonusLines.push("대머리 대장장이📙 펫스킬을 적용 받았습니다(5%)");
    }
    var bonusText = bonusLines.join("\n");

    var success = Math.random() < currentProb;

    addPoint(data, sender, -upgradeCost);

    if (success) {
        removeItem(data, sender, "펫 강화석⭐", needItemCount);
        petData[sender].upgrade++;
        petData[sender].upgradeDateTime = new Date();

        var newLv = petData[sender].upgrade;
        var effectiveNewLv = calculateEffectivePetUpgradeLevel(sender, data, petData); // 홈뱃지 반영 후 실제 효과 강화수치
        var newCritChance = getCritChance(effectiveNewLv);
        var critMul = getPetUpgradeCritMul(effectiveNewLv);
        var nextLevel = newLv + 1;
        var baseProbNext = nextLevel < 100 ? 0.55 - nextLevel * 0.005 : 0.05;
        var nextBoostEligible = baseProbNext + traitBonus < 1.0;
        var nextBestAfterUse = nextBoostEligible ? findBestPetBoostItem(user.bag) : null;
        var nextItemBonus = nextBestAfterUse ? nextBestAfterUse.addPct / 100 : 0.0;
        var nextProb = baseProbNext + nextItemBonus + traitBonus;
        if (nextProb > 1) nextProb = 1;

        var successMessage =
            "[" +
            newLv +
            "강⭐ 펫 강화성공]\n" +
            "[" +
            checkRank(data, petData, guildData, sender) +
            "] 님의 [" +
            petData[sender].petimg +
            petData[sender].petname +
            "]이(가)\n" +
            "강화에 성공하였습니다.\n" +
            "[강화 " +
            newLv +
            "⭐] [치명타 확률 " +
            newCritChance +
            "%] [" +
            critMul +
            "배]\n" +
            "현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n\n" +
            "다음 펫강화확률⭐️: " +
            (nextProb * 100).toFixed(2) +
            "%(⬆️)\n" +
            "남은 펫 강화석⭐️: " +
            numberWithCommas(user.bag["펫 강화석⭐"] || 0) +
            (bonusText ? "\n\n" + bonusText : "");

        return {
            ok: true,
            success: true,
            costSpent: true,
            stonePreservedByArtisan: false,
            message: successMessage
        };
    }

    var artisanBreathTriggered = false;
    if (hasPetSkill(petSkillData, sender, "장인의 숨결")) {
        artisanBreathTriggered = Math.random() < 0.07;
    }
    if (!artisanBreathTriggered) {
        removeItem(data, sender, "펫 강화석⭐", needItemCount);
    }

    var nextLevelFail = upgradeLevel;
    var baseProbNextFail = nextLevelFail < 100 ? 0.55 - nextLevelFail * 0.005 : 0.05;
    var nextBoostEligibleFail = baseProbNextFail + traitBonus < 1.0;
    var nextBestAfterUseFail = nextBoostEligibleFail ? findBestPetBoostItem(user.bag) : null;
    var nextItemBonusFail = nextBestAfterUseFail ? nextBestAfterUseFail.addPct / 100 : 0.0;
    var nextProbIfFail = baseProbNextFail + nextItemBonusFail + traitBonus;
    if (nextProbIfFail > 1) nextProbIfFail = 1;

    return {
        ok: true,
        success: false,
        costSpent: true,
        stonePreservedByArtisan: artisanBreathTriggered,
        message:
            "[" +
            petData[sender].upgrade +
            "강⭐ 펫 강화실패]\n" +
            (artisanBreathTriggered ? "장인의 숨결📙 [펫 강화석⭐]을 소모하지 않았습니다.\n" : "하,, 펫 강화석⭐이 소멸하였습니다...\n") +
            "[" +
            checkRank(data, petData, guildData, sender) +
            "] 님의 [" +
            petData[sender].petimg +
            petData[sender].petname +
            "] 이(가)\n" +
            "강화에 실패하였습니다." +
            "\n현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n\n현재 펫강화확률⭐️: " +
            (nextProbIfFail * 100).toFixed(2) +
            "%(⬆️)" +
            "\n남은 펫 강화석⭐️: " +
            numberWithCommas(user.bag["펫 강화석⭐"] || 0) +
            (bonusText ? "\n\n" + bonusText : "")
    };
}

function runRepeatPetUpgrade(sender, data, petData, guildData, petSkillData, count) {
    var results = [];
    var tryCount = parseInt(count, 10) || 1;
    var successCount = 0;
    var failCount = 0;
    var artisanSavedCount = 0;
    var stoppedEarly = false;
    var beforePetName = (petData[sender] && petData[sender].petimg ? petData[sender].petimg : "") + (petData[sender] && petData[sender].petname ? petData[sender].petname : "펫");
    var beforePetUpgrade = petData[sender] && petData[sender].upgrade ? petData[sender].upgrade : 0;

    for (var i = 0; i < tryCount; i++) {
        var result = runPetUpgradeOnce(sender, data, petData, guildData, petSkillData);
        if (!result.costSpent) {
            results.push(result.message);
            stoppedEarly = true;
            break;
        }

        if (result.success) {
            successCount++;
        } else {
            failCount++;
        }
        if (result.stonePreservedByArtisan) {
            artisanSavedCount++;
        }

        if (tryCount === 1) {
            results.push(result.message);
        } else {
            results.push("[" + (i + 1) + "회]\n" + result.message);
        }
    }

    if (tryCount === 1) {
        return results.join("\n");
    }

    var afterPetName = (petData[sender] && petData[sender].petimg ? petData[sender].petimg : "") + (petData[sender] && petData[sender].petname ? petData[sender].petname : "펫");
    var afterPetUpgrade = petData[sender] && petData[sender].upgrade ? petData[sender].upgrade : 0;
    var summary = "⭐️펫강화 연속시도⭐️\n\n";
    summary += "강화 전: " + beforePetName + " [+" + beforePetUpgrade + "]\n";
    summary += "강화 후: " + afterPetName + " [+" + afterPetUpgrade + "]\n\n";
    summary += "시도🔂: [" + results.length + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]";
    if (artisanSavedCount > 0) {
        summary += "\n장인의 숨결📙 발동: [" + artisanSavedCount + "회] (강화석 미소모)";
    }
    summary += "\n현재 포인트: 🅟" + numberWithCommas(data.member[sender].point);
    if (stoppedEarly) {
        summary += "\n중간 종료: 포인트 또는 재료가 부족합니다.";
    }
    summary += "\n(펫강화 기록 상세보기)" + allsee;
    return summary + "\n\n" + results.join("\n\n");
}

// 입력 번호로 대표·보조·가방 미니펫 강화 대상을 조회하는 함수
function getMiniUpgradeTargetInfo(sender, petData, idxParam) {
    if (idxParam === "00") {
        var supportOwner = petData[sender];
        if (!supportOwner || !supportOwner.miniPetSupport) {
            return {
                ok: false,
                message: "보조로 장착된 미니펫이 없습니다.\n먼저 보조 미니펫을 장착해주세요.\n※ 보조장착: /미니펫보조장착 [미니펫가방번호]"
            };
        }
        return { ok: true, mini: supportOwner.miniPetSupport, targetType: "support" };
    }
    if (!petData[sender]) petData[sender] = {};

    if (idxParam === null || typeof idxParam === "undefined") {
        if (!petData[sender].miniPet) {
            return {
                ok: false,
                message: "❌ 강화할 미니펫이 없습니다.\n/미니펫강화 또는 /미니펫강화 [미니펫가방번호]"
            };
        }
        return {
            ok: true,
            mini: petData[sender].miniPet,
            targetType: "equipped"
        };
    }

    var bagIndex = parseInt(idxParam, 10);
    if (isNaN(bagIndex) || bagIndex < 0) {
        return {
            ok: false,
            message: "❌ 올바른 가방 번호를 입력해주세요.\n/미니펫강화 [미니펫가방번호]"
        };
    }
    if (bagIndex === 0) {
        if (!petData[sender].miniPet) {
            return {
                ok: false,
                message: "❌ 강화할 미니펫이 없습니다.\n/미니펫강화 또는 /미니펫강화 [미니펫가방번호]"
            };
        }
        return {
            ok: true,
            mini: petData[sender].miniPet,
            targetType: "equipped"
        };
    }

    var mini = (petData[sender].miniPetBag || []).find(function (pet) {
        return pet.sortIndex === bagIndex;
    });
    if (!mini) {
        return {
            ok: false,
            message: "❌ 올바른 가방 번호입니다.\n/미니펫강화 [미니펫가방번호]"
        };
    }
    return {
        ok: true,
        mini: mini,
        targetType: "bag"
    };
}

function getMiniUpgradeStateText(mini) {
    if (!mini) return "미니펫 없음";
    var name = (mini.name || "") + (mini.emoji || "");
    var battleExp = numberWithCommas(Number(mini.battleExp || 0));
    var grade = mini.grade || "일반";
    var upgradeDisplay = getMiniPetUpgradeDisplay(mini);
    var text = name + "(+" + battleExp + "💕)[" + grade + "]";
    if (upgradeDisplay) {
        text += " +" + upgradeDisplay + "💫";
    }
    return text;
}

function runMiniPetUpgradeOnce(sender, data, petData, guildData, petSkillData, idxParam) {
    var user = data.member[sender];
    if (!user) {
        return { ok: false, success: false, costSpent: false, message: "❌ 유저 정보가 없습니다." };
    }

    var targetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    if (!targetInfo.ok) {
        return { ok: false, success: false, costSpent: false, message: targetInfo.message };
    }

    var mini = targetInfo.mini;
    if (!mini.upgrade) mini.upgrade = 0;

    var curLv = mini.upgrade;
    var maxLv = isElite(mini) ? ELITE_MINIPET_MAX_LV : MINIPET_MAX_LV;
    if (curLv >= maxLv) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "해당 미니펫은 이미 최대 강화(+MAX💫)입니다."
        };
    }

    var targetLv = curLv + 1;
    var battleExp = mini.battleExp || 0;
    var upgradeItemName = "미니펫 강화석💫";
    var needItemCount = targetLv;
    var stoneOwned = user.bag[upgradeItemName] || 0;
    if (stoneOwned < needItemCount) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "❌ 미니펫 강화석💫이 부족합니다.\n필요 수량: " + needItemCount + "개(보유 :" + stoneOwned + "개)"
        };
    }

    var costPoint = MINI_COST[targetLv];
    if (user.point < costPoint) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "❌ 포인트가 부족합니다.\n현재 포인트: " + numberWithCommas(user.point) + "\n필요 포인트: " + numberWithCommas(costPoint)
        };
    }

    var baseProb = MINI_PROB[targetLv];
    var traitPct = hasPetSkill(petSkillData, sender, "개통령") ? 10 : 0;
    var traitAdd = traitPct / 100;
    var boostEligible = baseProb + traitAdd < 1.0;
    var boost = boostEligible ? findBestMiniBoostItem(user.bag) : null;
    var boostAdd = boost ? boost.addPct / 100 : 0.0;
    var currentProb = baseProb + traitAdd + boostAdd;
    if (currentProb > 1) currentProb = 1.0;
    var success = Math.random() < currentProb;

    addPoint(data, sender, -costPoint);
    removeItem(data, sender, upgradeItemName, needItemCount);

    var boostLine = "";
    if (boost) {
        removeItem(data, sender, boost.name, 1);
        var leftBoost = Math.max(0, user.bag[boost.name] || 0);
        boostLine = "\n\n" + boost.name + " 사용 (보유: " + leftBoost + "개)";
    }
    var traitLine = "";
    if (traitPct > 0) {
        traitLine = "\n" + (traitPct === 10 ? "개같은집념(" + traitPct + "%) 특성을 적용 받았습니다." : "강조하고반복하는소리로도노래를들려주는붴쑉(" + traitPct + "%) 특성을 적용 받았습니다.");
    }

    var stonesLeft = Math.max(0, user.bag[upgradeItemName] || 0);
    var nextLvAfter = success ? Math.min(maxLv, curLv + 1) : curLv;
    var nextTargetLv = Math.min(maxLv, nextLvAfter + 1);
    var nextProbLine = "";
    if (nextLvAfter < maxLv) {
        var baseNext = MINI_PROB[nextTargetLv];
        var nextBoostEligible = baseNext + traitAdd < 1.0;
        var nextBest = nextBoostEligible ? findBestMiniBoostItem(user.bag) : null;
        var nextBoostAdd = nextBest ? nextBest.addPct / 100 : 0.0;
        var nextEffective = baseNext + traitAdd + nextBoostAdd;
        if (nextEffective > 1) nextEffective = 1.0;
        nextProbLine = (success ? "다음 미니펫 강화확률🐹 : " : "현재 미니펫 강화확률🐹 : ") + (nextEffective * 100).toFixed(2) + "%(⬆️)";
    } else {
        nextProbLine = success ? "다음 미니펫 강화확률🐹 : MAX" : "현재 미니펫 강화확률🐹 : MAX";
    }

    var nickname = checkRank(data, petData, guildData, sender);
    var header = "[" + nickname + "] 님\n" + mini.name + (mini.emoji || "") + "(+" + numberWithCommas(battleExp) + "💕)[" + (mini.grade || "일반") + "]\n";

    if (success) {
        var gain = getCharmGainFor(mini, targetLv) || 0;
        var beforeBattle = Number(mini.battleExp) || 0;
        var beforeCastle = Number(mini.castleExp) || 0;
        var beforeRaid = Number(mini.raidExp) || 0;
        mini.upgrade = nextLvAfter;
        mini.battleExp = beforeBattle + gain;
        mini.castleExp = beforeCastle + gain;
        mini.raidExp = beforeRaid + gain;
        // 강화 중에는 가방 번호를 유지하고 /미니펫가방 조회 시 재정렬한다.

        if (mini.upgrade == maxLv) {
            noticeMsg("[" + nickname + "] 님의 [" + mini.name + (mini.emoji || "") + "] 미니펫이 +MAX💫에 도달했습니다! 축하해주세요!");
        }

        return {
            ok: true,
            success: true,
            costSpent: true,
            message:
                "[" +
                nextLvAfter +
                "강💫 미니펫 강화성공]\n" +
                header +
                "미니펫 강화에 성공하셨습니다!!\n\n" +
                numberWithCommas(beforeBattle) +
                "+" +
                numberWithCommas(gain) +
                "💕➡️ " +
                numberWithCommas(mini.battleExp || 0) +
                "💕 매력이 증가합니다.\n\n현재 포인트: 🅟" +
                numberWithCommas(user.point || 0) +
                "\n" +
                nextProbLine +
                "\n남은 " +
                upgradeItemName +
                " : " +
                numberWithCommas(stonesLeft) +
                "개" +
                (boostLine || "") +
                (traitLine || "")
        };
    }

    return {
        ok: true,
        success: false,
        costSpent: true,
        message:
            "[" +
            nextLvAfter +
            "강💫 미니펫 강화실패]\n" +
            header +
            "강화에 실패했습니다.\n\n현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n" +
            nextProbLine +
            "\n남은 " +
            upgradeItemName +
            " : " +
            numberWithCommas(stonesLeft) +
            "개" +
            (boostLine || "") +
            (traitLine || "")
    };
}

function runRepeatMiniPetUpgrade(sender, data, petData, guildData, petSkillData, idxParam, count) {
    var tryCount = parseInt(count, 10) || 1;
    var targetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    if (!targetInfo.ok) {
        return targetInfo.message;
    }

    var beforeState = getMiniUpgradeStateText(targetInfo.mini);
    var successCount = 0;
    var failCount = 0;
    var actualTryCount = 0;
    var stopReason = "";
    var resultLogs = [];

    for (var i = 0; i < tryCount; i++) {
        var result = runMiniPetUpgradeOnce(sender, data, petData, guildData, petSkillData, idxParam);
        if (!result.costSpent) {
            stopReason = result.message;
            break;
        }

        actualTryCount++;
        if (result.success) {
            successCount++;
        } else {
            failCount++;
        }
        resultLogs.push("[" + actualTryCount + "회]\n" + result.message);
    }

    if (tryCount === 1) {
        if (resultLogs.length > 0) {
            return resultLogs.join("\n");
        }
        return stopReason || "강화를 진행할 수 없습니다.";
    }

    if (actualTryCount === 0) {
        return stopReason || "강화를 진행할 수 없습니다.";
    }

    var afterTargetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    var afterMini = afterTargetInfo.ok ? afterTargetInfo.mini : targetInfo.mini;
    var afterState = getMiniUpgradeStateText(afterMini);

    var summary = "💫미니펫강화 연속시도💫\n\n";
    summary += "강화 전: " + beforeState + "\n";
    summary += "강화 후: " + afterState + "\n\n";
    summary += "시도🔂: [" + actualTryCount + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]\n";
    summary += "현재 포인트: 🅟" + numberWithCommas(data.member[sender].point || 0);
    if (stopReason) {
        summary += "\n\n※ " + stopReason.split("\n")[0];
    }
    summary += "\n\n(미니펫강화 기록 상세보기)" + allsee;
    return summary + "\n\n" + resultLogs.join("\n\n");
}

function runRepeatUpgrade(type, petFieldName, memberName, data, petData, guildData, petSkillData, count) {
    var results = [];
    var tryCount = parseInt(count, 10) || 1;
    var successCount = 0;
    var failCount = 0;
    var artisanSavedCount = 0;
    var stoppedEarly = false;
    var beforeUpgradeObj =
        petData[memberName] && petData[memberName][petFieldName]
            ? {
                name: petData[memberName][petFieldName].name,
                grade: petData[memberName][petFieldName].grade,
                upgrade: petData[memberName][petFieldName].upgrade
            }
            : null;

    for (var i = 0; i < tryCount; i++) {
        var upgradeResult = upgradeItemInfo(type, memberName, data, petData, guildData, petSkillData);
        var pointCost = upgradeResult.pointCost;
        var itemCostName = upgradeResult.itemCostName;
        var itemCost = upgradeResult.itemCost;

        // [FIX] 재화 부족 등으로 시도 자체가 안 된 경우 — fail 카운트 제외하고 즉시 중단
        if (!pointCost && !itemCost) {
            results.push(upgradeResult.message);
            stoppedEarly = true;
            break;
        }

        if (pointCost) addPoint(data, memberName, -pointCost);
        if (upgradeResult.shouldConsumeItem !== false && itemCostName && itemCost) removeItem(data, memberName, itemCostName, itemCost);
        if (upgradeResult.boostItemUsedName) removeItem(data, memberName, upgradeResult.boostItemUsedName, 1);

        if (upgradeResult.successFlag) {
            petData[memberName][petFieldName] = upgradeResult.obj;
            successCount++;
        } else {
            failCount++;
        }
        if (upgradeResult.stonePreservedByArtisan) {
            artisanSavedCount++;
        }

        if (tryCount === 1) {
            results.push(upgradeResult.message);
        } else {
            results.push("[" + (i + 1) + "회]\n" + upgradeResult.message);
        }
    }

    if (tryCount === 1) {
        return results.join("\n");
    }

    var summary = "";
    if (type == "ring") {
        summary += "💍반지강화 연속시도💍\n\n";
    } else if (type == "elemental") {
        summary += "🥀정령강화 연속시도🥀\n\n";
    }
    var afterUpgradeObj = petData[memberName] && petData[memberName][petFieldName] ? petData[memberName][petFieldName] : null;
    if (beforeUpgradeObj) {
        summary += "강화 전: " + beforeUpgradeObj.name + " [" + beforeUpgradeObj.grade + "](+" + beforeUpgradeObj.upgrade + ")\n";
    }
    if (afterUpgradeObj) {
        summary += "강화 후: " + afterUpgradeObj.name + " [" + afterUpgradeObj.grade + "](+" + afterUpgradeObj.upgrade + ")\n\n";
    }
    summary += "시도🔂: [" + results.length + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]";
    if (artisanSavedCount > 0) {
        summary += "\n장인의 숨결📙 발동: [" + artisanSavedCount + "회] (강화석 미소모)";
    }
    summary += "\n현재 포인트: 🅟" + numberWithCommas(data.member[memberName].point);
    if (stoppedEarly) {
        summary += "\n중간 종료: 재화 또는 재료 부족가 부족합니다.";
    }
    summary += "\n(강화 기록 상세보기)" + allsee;

    return summary + "\n\n" + results.join("\n\n");
}
