// 패키지 추가 시작 명령어인지 확인하는 함수
function isPackageAddStartCommand(msg) {
    return msg === "/패키지추가시작" || msg === "/패키지추가취소" || msg === "/패키지추가상태" || msg === "/패키지추가방법";
}

// 패키지 단계별 추가 상태 초기화 함수
function startPackageAddFlow(sender) {
    if (!userState[sender]) userState[sender] = {};
    userState[sender].packageAdd = {
        step: "NAME",
        name: "",
        desc: "",
        rewards: [],
        pendingReward: null,
        startedAt: formatDateTime(new Date())
    };
    var lines = [];
    lines.push("📦 패키지 추가를 시작합니다.");
    lines.push("");
    lines.push("1단계: 패키지 이름을 입력해주세요.");
    lines.push("");
    lines.push("예:");
    lines.push("이벤트패키지🎁");
    lines.push("");
    lines.push("※ 별도 가방 아이템명은 사용하지 않고 패키지 이름으로 저장됩니다.");
    lines.push("취소하려면 \"취소\" 또는 /패키지추가취소");
    return lines.join("\n");
}

// 패키지 단계별 추가 상태 취소 함수
function cancelPackageAddFlow(sender) {
    if (userState[sender] && userState[sender].packageAdd) {
        delete userState[sender].packageAdd;
        return "✅ 패키지 추가가 취소되었습니다.";
    }
    return "ℹ️ 진행 중인 패키지 추가가 없습니다.";
}

// 패키지 단계별 추가 진행 상태 조회 메시지 생성 함수
function buildPackageAddStateMessage(sender) {
    if (!userState[sender] || !userState[sender].packageAdd) return "ℹ️ 진행 중인 패키지 추가가 없습니다.";
    var state = userState[sender].packageAdd; // 현재 관리자별 패키지 추가 상태
    var lines = ["📦 패키지 추가 진행 상태", ""];
    lines.push("단계: " + state.step);
    lines.push("패키지: " + (state.name || "-"));
    lines.push("설명: " + (state.desc || "-"));
    lines.push("보상:");
    lines.push(formatPackageRewardLines(state.rewards || []));
    return lines.join("\n");
}

// 패키지 단계별 보상 선택 입력 정규화 함수
function normalizePackageRewardChoice(input) {
    var text = String(input || "").trim(); // 보상 선택 원문
    if (text === "1" || text === "포인트") return "POINT";
    if (text === "2" || text === "아이템") return "ITEM";
    if (text === "3" || text === "완료") return "DONE";
    if (text === "4" || text === "취소") return "CANCEL";
    return "";
}

// 패키지 보상 목록 출력 문자열 생성 함수
function formatPackageRewardLines(rewards) {
    if (!(rewards instanceof Array) || rewards.length < 1) return "- 없음";
    var lines = [];
    for (var i = 0; i < rewards.length; i++) {
        var reward = normalizeRetiredCarrotPackageReward(rewards[i]); // 출력할 보상 항목
        if (reward.name === GLOBAL_CONFIG.spiritRetirement.removedItem) continue;
        if (reward.type === "point") {
            lines.push("- 포인트 🅟" + numberWithCommas(reward.count));
        } else if (reward.type === "item") {
            lines.push("- " + reward.name + " x" + numberWithCommas(reward.count));
        }
    }
    return lines.join("\n");
}

// 패키지 보상 선택 안내 메시지 생성 함수
function buildPackageRewardChoiceMessage(state) {
    var lines = [];
    lines.push("3단계: 무엇을 추가할까요?");
    lines.push("");
    lines.push("1. 포인트");
    lines.push("2. 아이템");
    lines.push("3. 완료");
    lines.push("4. 취소");
    lines.push("");
    lines.push("숫자 또는 이름으로 입력할 수 있습니다.");
    lines.push("예: 1 또는 포인트");
    if (state && state.rewards && state.rewards.length > 0) {
        lines.push("");
        lines.push("현재 보상:");
        lines.push(formatPackageRewardLines(state.rewards));
    }
    return lines.join("\n");
}

// 패키지 추가 미리보기 메시지 생성 함수
function buildPackageAddPreviewMessage(state) {
    var lines = [];
    lines.push("📦 패키지 추가 미리보기");
    lines.push("");
    lines.push("패키지: " + state.name);
    lines.push("설명: " + state.desc);
    lines.push("");
    lines.push("보상:");
    lines.push(formatPackageRewardLines(state.rewards));
    lines.push("");
    lines.push("등록하려면 \"등록\"");
    lines.push("보상을 더 추가하려면 \"수정\"");
    lines.push("취소하려면 \"취소\"");
    return lines.join("\n");
}

// 패키지 추가 상태를 실제 packageInfo 항목으로 변환하는 함수
function createPackageInfoFromState(state, packageInfoData) {
    return {
        id: createPackageIdFromName(state.name, packageInfoData),
        name: state.name,
        desc: state.desc,
        enabled: true,
        maxUseOnce: GLOBAL_CONFIG.package.maxUseOnce,
        rewards: state.rewards
    };
}

// 패키지 단계별 추가 메시지 처리 함수
function handlePackageAddFlowMessage(sender, msg, packageInfoData) {
    var text = String(msg || "").trim(); // 단계별 입력 원문
    var state = userState[sender].packageAdd; // 관리자별 패키지 추가 상태
    if (!text) return { ok: false, message: "❌ 값을 입력해주세요." };
    if (text === "취소") return { ok: true, message: cancelPackageAddFlow(sender) };

    if (state.step === "NAME") {
        for (var n = 0; n < packageInfoData.length; n++) {
            if (packageInfoData[n] && packageInfoData[n].name === text) {
                return { ok: false, message: "❌ 같은 패키지명이 이미 등록되어 있습니다." };
            }
        }
        state.name = text;
        state.step = "DESC";
        return { ok: true, message: "✅ 1단계 입력 완료\n\n패키지 이름:\n" + state.name + "\n\n2단계: 패키지 설명을 입력해주세요." };
    }

    if (state.step === "DESC") {
        state.desc = text;
        state.step = "REWARD_CHOICE";
        return { ok: true, message: "✅ 2단계 입력 완료\n\n" + buildPackageRewardChoiceMessage(state) };
    }

    if (state.step === "REWARD_CHOICE") {
        var choice = normalizePackageRewardChoice(text); // 포인트/아이템/완료/취소 선택값
        if (choice === "POINT") {
            state.step = "POINT_COUNT";
            return { ok: true, message: "포인트 수량을 입력해주세요.\n예: 10000000" };
        }
        if (choice === "ITEM") {
            state.step = "ITEM_NAME";
            return { ok: true, message: "아이템명을 입력해주세요.\n예: 펫 강화석⭐" };
        }
        if (choice === "DONE") {
            if (!state.rewards || state.rewards.length < 1) return { ok: false, message: "❌ 보상을 1개 이상 추가해야 합니다." };
            state.step = "CONFIRM";
            return { ok: true, message: buildPackageAddPreviewMessage(state) };
        }
        if (choice === "CANCEL") return { ok: true, message: cancelPackageAddFlow(sender) };
        return { ok: false, message: "❌ 1/포인트, 2/아이템, 3/완료, 4/취소 중 하나를 입력해주세요." };
    }

    if (state.step === "POINT_COUNT") {
        var pointCount = parseInt(text, 10); // 추가할 포인트 수량
        if (isNaN(pointCount) || pointCount < 1) return { ok: false, message: "❌ 포인트 수량은 1 이상 숫자로 입력해주세요." };
        state.rewards.push({ type: "point", count: pointCount });
        state.step = "REWARD_CHOICE";
        return { ok: true, message: "✅ 보상 추가 완료\n- 포인트 🅟" + numberWithCommas(pointCount) + "\n\n" + buildPackageRewardChoiceMessage(state) };
    }

    if (state.step === "ITEM_NAME") {
        state.pendingReward = { type: "item", name: text };
        state.step = "ITEM_COUNT";
        return { ok: true, message: "수량을 입력해주세요.\n예: 10" };
    }

    if (state.step === "ITEM_COUNT") {
        var itemCount = parseInt(text, 10); // 추가할 아이템 수량
        if (isNaN(itemCount) || itemCount < 1) return { ok: false, message: "❌ 아이템 수량은 1 이상 숫자로 입력해주세요." };
        var itemName = normalizePassDurationItemName(normalizeMiniPetRewardBoxItemName(state.pendingReward ? state.pendingReward.name : "")); // 기존 등급 확정 이름도 신규 이름으로 등록
        if (!itemName) {
            state.step = "ITEM_NAME";
            return { ok: false, message: "❌ 아이템명이 없습니다. 아이템명을 다시 입력해주세요." };
        }
        state.rewards.push({ type: "item", name: itemName, count: itemCount });
        state.pendingReward = null;
        state.step = "REWARD_CHOICE";
        return { ok: true, message: "✅ 보상 추가 완료\n- " + itemName + " x" + numberWithCommas(itemCount) + "\n\n" + buildPackageRewardChoiceMessage(state) };
    }

    if (state.step === "CONFIRM") {
        if (text === "등록") {
            for (var i = 0; i < packageInfoData.length; i++) {
                if (packageInfoData[i] && packageInfoData[i].name === state.name) {
                    return { ok: false, message: "❌ 같은 패키지명이 이미 등록되어 있습니다." };
                }
            }
            var newPackage = createPackageInfoFromState(state, packageInfoData);
            packageInfoData.push(newPackage);
            delete userState[sender].packageAdd;
            var lines = [];
            lines.push("✅ 패키지 추가 완료");
            lines.push("");
            lines.push("번호: " + packageInfoData.length);
            lines.push("패키지: " + newPackage.name);
            lines.push("구성: " + formatPackageRewardSummary(newPackage.rewards));
            return { ok: true, message: lines.join("\n"), packageInfoData: packageInfoData };
        }
        if (text === "수정") {
            state.step = "REWARD_CHOICE";
            return { ok: true, message: buildPackageRewardChoiceMessage(state) };
        }
        if (text === "취소") return { ok: true, message: cancelPackageAddFlow(sender) };
        return { ok: false, message: "❌ 등록, 수정, 취소 중 하나를 입력해주세요." };
    }

    return { ok: false, message: "❌ 패키지 추가 상태가 올바르지 않습니다. /패키지추가취소 후 다시 진행해주세요." };
}

// 패키지 id 후보 문자열 생성 함수
function createPackageIdFromName(name, packageInfoData) {
    var base = "package_" + (packageInfoData.length + 1);
    var id = base;
    var suffix = 1;
    var exists = true;
    while (exists) {
        exists = false;
        for (var i = 0; i < packageInfoData.length; i++) {
            if (packageInfoData[i] && packageInfoData[i].id === id) {
                exists = true;
                break;
            }
        }
        if (exists) {
            suffix++;
            id = base + "_" + suffix;
        }
    }
    return id;
}

// 아이템명 x수량 형식의 패키지 보상 입력 문자열 파싱 함수
function parsePackageNaturalItemRewardSpec(rewardSpec) {
    var rewards = [];
    var text = String(rewardSpec || "").trim(); // 자연어형 보상 입력 원문
    var pattern = /\s+x\s*(\d(?:[\d,]*\d)?)/g;
    var lastEnd = 0;
    var match = null;
    while ((match = pattern.exec(text)) !== null) {
        var rawName = text.substring(lastEnd, match.index).replace(/^[\s,]+/, "").trim(); // 직전 수량 이후부터 현재 x수량 전까지의 아이템명
        if (rawName.indexOf("item:") === 0) rawName = rawName.substring("item:".length).trim();
        if (!rawName) return { error: "아이템명이 비어 있습니다." };

        var itemCount = parseInt(String(match[1]).replace(/,/g, ""), 10); // 쉼표가 포함된 수량 정규화
        if (isNaN(itemCount) || itemCount < 1) return { error: "아이템 보상 수량이 올바르지 않습니다: " + rawName };
        rewards.push({ type: "item", name: normalizePassDurationItemName(normalizeMiniPetRewardBoxItemName(rawName)), count: itemCount });
        lastEnd = pattern.lastIndex;
    }

    var trailing = text.substring(lastEnd).replace(/^[\s,]+/, "").trim(); // 마지막 x수량 뒤에 남은 잘못된 입력
    if (rewards.length < 1) return { error: "보상목록을 1개 이상 입력해야 합니다." };
    if (trailing) return { error: "보상 형식을 확인해주세요: " + trailing };
    return { rewards: rewards };
}

// 패키지 보상 입력 문자열 파싱 함수
function parsePackageRewardSpec(rewardSpec) {
    if (/\s+x\s*\d/.test(String(rewardSpec || ""))) {
        return parsePackageNaturalItemRewardSpec(rewardSpec);
    }

    var rewards = [];
    var parts = String(rewardSpec || "").split(","); // 쉼표 기준 보상 항목 목록
    for (var i = 0; i < parts.length; i++) {
        var raw = parts[i].trim(); // 보상 항목 원문
        if (!raw) continue;
        if (raw.indexOf("point:") === 0) {
            var pointCount = parseInt(raw.substring("point:".length).trim(), 10); // 포인트 보상 수량
            if (isNaN(pointCount) || pointCount < 1) return { error: "포인트 보상 수량이 올바르지 않습니다." };
            rewards.push({ type: "point", count: pointCount });
        } else if (raw.indexOf("item:") === 0) {
            var itemBody = raw.substring("item:".length).trim(); // item: 제거 후 아이템명:수량 본문
            var lastColon = itemBody.lastIndexOf(":"); // 아이템명에 공백이 있어도 마지막 콜론으로 수량 분리
            if (lastColon <= 0) return { error: "아이템 보상 형식이 올바르지 않습니다: " + raw };
            var itemName = itemBody.substring(0, lastColon).trim(); // 보상 아이템명
            var itemCount = parseInt(itemBody.substring(lastColon + 1).trim(), 10); // 보상 아이템 수량
            if (!itemName) return { error: "아이템명이 비어 있습니다." };
            if (isNaN(itemCount) || itemCount < 1) return { error: "아이템 보상 수량이 올바르지 않습니다: " + itemName };
            rewards.push({ type: "item", name: normalizePassDurationItemName(normalizeMiniPetRewardBoxItemName(itemName)), count: itemCount });
        } else {
            return { error: "지원하지 않는 보상 형식입니다: " + raw };
        }
    }
    if (rewards.length < 1) return { error: "보상목록을 1개 이상 입력해야 합니다." };
    return { rewards: rewards };
}

// 관리자 패키지 추가 명령어 처리 함수
function addPackageInfoByCommand(sender, msg, packageInfoData) {
    var body = String(msg || "").replace(/^\/패키지추가\s+/, "").trim(); // 명령어를 제거한 패키지 추가 본문
    var parts = body.split("|").map(function (part) {
        return part.trim();
    });
    if (parts.length !== 3) {
        return { ok: false, message: "❌ 사용법:\n/패키지추가 패키지명 | 설명 | 보상목록\n\n자세한 예시는 /패키지추가방법" };
    }

    var packageName = parts[0]; // /패키지리스트 표시명 및 member bag 저장명
    var desc = parts[1]; // 패키지 설명
    var rewardParseResult = parsePackageRewardSpec(parts[2]); // 보상목록 파싱 결과
    if (!packageName || !desc) return { ok: false, message: "❌ 패키지명, 설명은 비울 수 없습니다." };
    if (rewardParseResult.error) return { ok: false, message: "❌ " + rewardParseResult.error + "\n\n자세한 예시는 /패키지추가방법" };

    for (var i = 0; i < packageInfoData.length; i++) {
        var exists = packageInfoData[i]; // 중복 확인 대상 패키지
        if (exists && getPackageBagItemName(exists) === packageName) {
            return { ok: false, message: "❌ 같은 패키지명이 이미 등록되어 있습니다." };
        }
    }

    var newPackage = {
        id: createPackageIdFromName(packageName, packageInfoData),
        name: packageName,
        desc: desc,
        enabled: true,
        maxUseOnce: GLOBAL_CONFIG.package.maxUseOnce,
        rewards: rewardParseResult.rewards
    };
    packageInfoData.push(newPackage);
    var lines = [];
    lines.push("✅ 패키지 추가 완료");
    lines.push("");
    lines.push("번호: " + packageInfoData.length);
    lines.push("패키지: " + newPackage.name);
    lines.push("구성: " + formatPackageRewardSummary(newPackage.rewards));
    lines.push("추가자: " + sender);
    return {
        ok: true,
        message: lines.join("\n"),
        packageInfoData: packageInfoData
    };
}

// 관리자 패키지 수정 명령어 처리 함수
function editPackageInfoByCommand(sender, msg, packageInfoData) {
    var body = String(msg || "").replace(/^\/패키지수정\s+/, "").trim(); // 명령어를 제거한 패키지 수정 본문
    var match = body.match(/^(\d+)\s+(.+)$/); // 리스트 번호와 수정할 보상목록 분리
    if (!match) {
        return { ok: false, message: buildPackageEditUsageMessage() };
    }

    var listNumber = parseInt(match[1], 10); // 패키지리스트 기준 수정 대상 번호
    var rewardSpecText = match[2].replace(/^\s*[|:：]\s*/, ""); // 번호 뒤 구분자를 실수로 넣은 경우 제거
    var rewardParseResult = parsePackageRewardSpec(rewardSpecText); // 수정 후 보상목록 파싱 결과
    var packageInfo = getPackageByListNumber(packageInfoData, listNumber); // 수정 대상 패키지
    if (!packageInfo) return { ok: false, message: "❌ 패키지 번호가 올바르지 않습니다." };
    if (rewardParseResult.error) return { ok: false, message: "❌ " + rewardParseResult.error + "\n\n자세한 예시는 /패키지추가방법" };

    var packageName = packageInfo.name || getPackageBagItemName(packageInfo); // 기존 패키지 표시명
    var durationPackageError = getPassDurationPackageError({ itemName: getPackageBagItemName(packageInfo), rewards: rewardParseResult.rewards });
    if (durationPackageError) return { ok: false, message: "❌ " + durationPackageError };
    packageInfo.enabled = packageInfo.enabled === false ? false : true;
    packageInfo.maxUseOnce = GLOBAL_CONFIG.package.maxUseOnce;
    packageInfo.rewards = rewardParseResult.rewards;

    var lines = [];
    lines.push("✅ 패키지 수정 완료");
    lines.push("");
    lines.push("번호: " + listNumber);
    lines.push("패키지: " + packageName);
    lines.push("구성: " + formatPackageRewardSummary(packageInfo.rewards));
    lines.push("처리자: " + sender);
    lines.push("※ 패키지명과 설명은 변경하지 않고 보상 내용만 수정했습니다.");
    return {
        ok: true,
        message: lines.join("\n"),
        packageInfoData: packageInfoData
    };
}

// 관리자 패키지 리스트 항목 실제 제거 처리 함수
function removePackageByCommand(sender, msg, packageInfoData) {
    var parts = String(msg || "").trim().split(/\s+/); // /패키지제거 번호 또는 /패키지리스트제거 번호
    var listNumber = parseInt(parts[1], 10); // 패키지리스트 번호
    var packageInfo = getPackageByListNumber(packageInfoData, listNumber); // 제거 대상 패키지
    if (!packageInfo) return { ok: false, message: "❌ 패키지 번호가 올바르지 않습니다." };
    packageInfoData.splice(listNumber - 1, 1);
    var lines = [];
    lines.push("✅ 패키지 제거 완료");
    lines.push("");
    lines.push("번호: " + listNumber);
    lines.push("패키지: " + (packageInfo.name || getPackageBagItemName(packageInfo)));
    lines.push("상태: 목록에서 삭제");
    lines.push("처리자: " + sender);
    lines.push("※ 이후 패키지 리스트 번호가 당겨집니다.");
    return {
        ok: true,
        message: lines.join("\n"),
        packageInfoData: packageInfoData
    };
}

// 관리자 패키지 활성/비활성 처리 함수
function setPackageEnabledByCommand(sender, msg, enabled, packageInfoData) {
    var parts = String(msg || "").trim().split(/\s+/); // /패키지제거 번호 또는 /패키지활성 번호
    var listNumber = parseInt(parts[1], 10); // 패키지리스트 번호
    var packageInfo = getPackageByListNumber(packageInfoData, listNumber); // 상태 변경 대상 패키지
    if (!packageInfo) return { ok: false, message: "❌ 패키지 번호가 올바르지 않습니다." };
    packageInfo.enabled = !!enabled;
    var lines = [];
    lines.push(enabled ? "✅ 패키지 활성 완료" : "✅ 패키지 제거 완료");
    lines.push("");
    lines.push("번호: " + listNumber);
    lines.push("패키지: " + (packageInfo.name || getPackageBagItemName(packageInfo)));
    lines.push("상태: " + (packageInfo.enabled ? "활성" : "비활성"));
    lines.push("처리자: " + sender);
    if (!enabled) lines.push("※ 번호 유지를 위해 삭제하지 않고 비활성화했습니다.");
    return {
        ok: true,
        message: lines.join("\n"),
        packageInfoData: packageInfoData
    };
}

// 호이월드 소식 저장 구조를 보장하는 함수
function ensureWorldNewsData(data) {
    if (!data.worldNews || typeof data.worldNews !== "object" || data.worldNews instanceof Array) data.worldNews = {};
    if (!(data.worldNews.posts instanceof Array)) data.worldNews.posts = [];
    var nextId = parseInt(data.worldNews.nextId, 10);
    if (isNaN(nextId) || nextId < 1) {
        nextId = 1;
        for (var i = 0; i < data.worldNews.posts.length; i++) {
            var postId = parseInt(data.worldNews.posts[i] && data.worldNews.posts[i].id, 10);
            if (!isNaN(postId) && postId >= nextId) nextId = postId + 1;
        }
    }
    data.worldNews.nextId = nextId;
    return data.worldNews;
}

// 현재 소식에 존재하는 픽 번호만 중복 없이 남기는 함수
function sanitizeWorldNewsPickIds(news) {
    if (!(news.pickIds instanceof Array)) return false;
    var validPostIds = {};
    var cleanPickIds = [];
    for (var i = 0; i < news.posts.length; i++) {
        var postId = parseInt(news.posts[i] && news.posts[i].id, 10);
        if (!isNaN(postId) && postId > 0) validPostIds[postId] = true;
    }
    for (var j = 0; j < news.pickIds.length; j++) {
        var pickId = parseInt(news.pickIds[j], 10);
        if (!isNaN(pickId) && pickId > 0 && validPostIds[pickId] && cleanPickIds.indexOf(pickId) < 0) cleanPickIds.push(pickId);
    }
    var changed = cleanPickIds.length !== news.pickIds.length;
    if (!changed) {
        for (var k = 0; k < cleanPickIds.length; k++) {
            if (cleanPickIds[k] !== news.pickIds[k]) {
                changed = true;
                break;
            }
        }
    }
    if (changed) news.pickIds = cleanPickIds;
    return changed;
}

// 현재 유효한 소식픽 번호를 반환하는 함수
function getWorldNewsValidPickIds(news) {
    if (!(news.pickIds instanceof Array)) return [];
    return news.pickIds.slice(0);
}

// 관리자 화면에 표시할 소식픽 상태를 반환하는 함수
function formatWorldNewsPickStatus(news) {
    var pickIds = getWorldNewsValidPickIds(news);
    if (pickIds.length < 1) return "미설정 · 최신 소식 표시";
    var labels = [];
    for (var i = 0; i < pickIds.length; i++) labels.push("#" + pickIds[i]);
    return labels.join(" · ");
}

// 소식픽 또는 최신 글에서 이번 조회의 대표 소식을 한 번 선택하는 함수
function selectWorldNewsFeaturedPost(news) {
    var pickIds = getWorldNewsValidPickIds(news);
    if (pickIds.length < 1) return { post: news.posts.length ? news.posts[0] : null, picked: false };
    var selectedId = pickIds[Math.floor(Math.random() * pickIds.length)];
    for (var i = 0; i < news.posts.length; i++) {
        if (parseInt(news.posts[i] && news.posts[i].id, 10) === selectedId) return { post: news.posts[i], picked: true };
    }
    return { post: news.posts.length ? news.posts[0] : null, picked: false };
}

// 소식픽 사용법과 현재 설정을 만드는 함수
function buildWorldNewsPickGuide(news) {
    return "🎯 소식픽 설정\n━━━━━━━━━━━━\n" +
        "현재 소식픽: " + formatWorldNewsPickStatus(news) + "\n\n" +
        "사용법: /소식픽 [번호] [번호] [번호]\n" +
        "예시: /소식픽 4 3 1\n\n" +
        "※ 서로 다른 소식관리번호 3개를 입력해주세요.\n" +
        "※ 새 설정은 기존 소식픽 전체를 교체합니다.\n" +
        "※ 해제: /소식픽해제";
}

// 한국 시간 기준 소식 작성 일시를 반환하는 함수
function getWorldNewsKstDateTime() {
    var formatter = new java.text.SimpleDateFormat("yyyy.MM.dd HH:mm");
    formatter.setTimeZone(java.util.TimeZone.getTimeZone("Asia/Seoul"));
    return String(formatter.format(new Date()));
}

// 소식 작성 상태를 관리자와 채팅방 조합으로 구분하는 함수
function getWorldNewsDraftKey(sender, room) {
    return String(sender) + "\u0000" + String(room);
}

// 소식 작성 상태의 5분 만료를 예약하는 함수
function scheduleWorldNewsDraftTimeout(draftKey, room, updatedAt) {
    setTimeout(function () {
        var draft = worldNewsDraftState[draftKey];
        if (!draft || draft.updatedAt !== updatedAt) return;
        if (Date.now() - draft.updatedAt < GLOBAL_CONFIG.worldNews.draftTimeoutMs) return;
        delete worldNewsDraftState[draftKey];
        Api.replyRoom(room, "⌛ 5분간 입력이 없어 소식 작성이 종료되었습니다.\n\n새 글 작성: /소식작성\n기존 글 수정: /소식수정 [번호]");
    }, GLOBAL_CONFIG.worldNews.draftTimeoutMs + 100);
}

// 소식 작성 상태의 입력 시각을 갱신하고 만료를 다시 예약하는 함수
function refreshWorldNewsDraft(draftKey, room) {
    var draft = worldNewsDraftState[draftKey];
    if (!draft) return;
    draft.updatedAt = Date.now();
    scheduleWorldNewsDraftTimeout(draftKey, room, draft.updatedAt);
}

// 소식복권 확률표에서 당첨 보상을 선택하는 함수
function drawWorldNewsReward() {
    var roll = Math.random() * 100;
    var cumulative = 0;
    for (var i = 0; i < GLOBAL_CONFIG.worldNews.rewards.length; i++) {
        cumulative += GLOBAL_CONFIG.worldNews.rewards[i].rate;
        if (roll < cumulative) return GLOBAL_CONFIG.worldNews.rewards[i];
    }
    return GLOBAL_CONFIG.worldNews.rewards[GLOBAL_CONFIG.worldNews.rewards.length - 1];
}

// 소식 게시글 한 건을 유저 화면 형식으로 만드는 함수
function formatWorldNewsPost(post, includeId) {
    var lines = [];
    if (includeId) lines.push("🔢 글번호: #" + post.id);
    lines.push("📌 " + post.title);
    lines.push("━━━━━━━━━━━━");
    lines.push("👤 작성자: " + post.authorAdjective + " 호월이🐹");
    lines.push("🗓️ 작성일: " + post.createdAt);
    lines.push("");
    lines.push(post.content);
    if (post.link) {
        lines.push("");
        lines.push("🔗 안내 링크");
        lines.push(post.link);
    }
    return lines.join("\n");
}

// 현재 소식 목록의 가장 큰 글번호를 유저의 마지막 확인 번호로 저장하는 함수
function markWorldNewsPostsRead(posts, member) {
    var latestId = parseInt(member.worldNewsLastReadId, 10); // 기존 마지막 확인 소식 번호
    if (isNaN(latestId)) latestId = 0;
    for (var i = 0; i < posts.length; i++) {
        var postId = parseInt(posts[i] && posts[i].id, 10);
        if (!isNaN(postId) && postId > latestId) latestId = postId;
    }
    if (parseInt(member.worldNewsLastReadId, 10) === latestId) return false;
    member.worldNewsLastReadId = latestId;
    return true;
}

// 소식복권 결과와 최신·지난 소식을 하나의 유저 화면으로 만드는 함수
function buildWorldNewsUserMessage(data, petData, guildData, sender, lotteryResult) {
    var news = ensureWorldNewsData(data);
    var posts = news.posts;
    var featured = selectWorldNewsFeaturedPost(news); // 이번 응답에서 한 번만 선택한 대표 소식
    var lines = ["📢 잠깐! 호이월드 소식 왔어요 👀", "━━━━━━━━━━━━"];
    if (lotteryResult.attendanceRequired) {
        lines.push("🎰 소식복권은 출석체크 후 참여할 수 있어요.");
        lines.push("👉 채팅창에 ㅊㅊ을 입력해주세요.");
    } else if (lotteryResult.firstEntry) {
        lines.push("🎰 [" + checkRank(data, petData, guildData, sender) + "] 님");
        lines.push(lotteryResult.reward.label + " 당첨! 지급 완료 ✅");
        lines.push("🍀 하루 1회 · 최대 10억 포인트");
    } else {
        lines.push("🎰 [" + checkRank(data, petData, guildData, sender) + "] 님 · 오늘 참여 완료 ✅");
        lines.push("🍀 내일 다시 도전하세요!");
    }
    lines.push("━━━━━━━━━━━━");

    if (posts.length < 1) {
        lines.push("📭 아직 등록된 소식이 없습니다.");
        lines.push("🗂 최근 등록된 소식: 0개");
        return lines.join("\n");
    }

    lines.push(featured.picked ? "🎯 소식픽" : "🆕 가장 최근 소식");
    lines.push("");
    lines.push(formatWorldNewsPost(featured.post, false));
    lines.push("━━━━━━━━━━━━");
    lines.push("🗂 최근 등록된 소식: " + posts.length + "개");
    if (posts.length > 1) {
        lines.push("📚 지난 소식은 전체보기로 확인하세요 👇");
        lines.push(allsee);
        var remainingCount = 0; // 대표 소식을 제외하고 출력한 글 수
        for (var i = 0; i < posts.length; i++) {
            if (featured.post && parseInt(posts[i].id, 10) === parseInt(featured.post.id, 10)) continue;
            if (remainingCount > 0) lines.push("");
            lines.push("━━━━━━━━━━━━");
            lines.push(formatWorldNewsPost(posts[i], false));
            remainingCount++;
        }
        lines.push("━━━━━━━━━━━━");
    }
    return lines.join("\n");
}

// 10억 포인트 당첨 전체알림 문구를 만드는 함수
function buildWorldNewsJackpotBroadcast(data, petData, guildData, sender) {
    return "📢 소식복권 10억 포인트 당첨 소식!\n" +
        "━━━━━━━━━━━━\n" +
        "👑 [" + checkRank(data, petData, guildData, sender) + "] 님!\n\n" +
        "🎉 소식복권 10억 포인트 당첨입니다!\n" +
        "축하드려요! 🥳\n\n" +
        "💰 당첨 포인트가 지급되었습니다.\n" +
        "━━━━━━━━━━━━\n" +
        "🍀 다음 행운의 주인공은?\n" +
        "지금 /소식 입력하고 도전하세요!\n\n" +
        "🎰 하루 1회 · 꽝 없이 최대 10억 포인트";
}

// 관리자 소식 전체 목록을 관리 화면 형식으로 만드는 함수
function buildWorldNewsManageMessage(data) {
    var news = ensureWorldNewsData(data);
    var posts = news.posts;
    var lines = ["📋 소식 관리", "🗂 최근 등록된 소식: " + posts.length + "개", "🎯 소식픽: " + formatWorldNewsPickStatus(news)];
    if (posts.length < 1) {
        lines.push("📭 아직 등록된 소식이 없습니다.");
    } else {
        lines.push(allsee);
        for (var i = 0; i < posts.length; i++) {
            lines.push("━━━━━━━━━━━━");
            lines.push(formatWorldNewsPost(posts[i], true));
            if (i < posts.length - 1) lines.push("");
        }
    }
    lines.push("━━━━━━━━━━━━");
    lines.push("✏️ 수정: /소식수정 [번호]");
    lines.push("🗑️ 삭제: /소식삭제 [번호]");
    lines.push("🎯 소식픽: /소식픽 [번호] [번호] [번호]");
    lines.push("🔓 픽 해제: /소식픽해제");
    return lines.join("\n");
}

// 소식 작성·수정 미리보기 화면을 만드는 함수
function buildWorldNewsDraftPreview(draft) {
    var post = {
        id: draft.targetId || "",
        title: draft.title,
        content: draft.content,
        link: draft.link,
        createdAt: draft.mode === "edit" ? draft.createdAt : "등록 시 자동 기록",
        authorAdjective: draft.authorAdjective
    };
    var lines = [draft.mode === "edit" ? "📝 소식 수정 완료! 저장 전 확인해주세요." : "📝 소식 작성 완료! 등록 전 확인해주세요.", "━━━━━━━━━━━━"];
    lines.push(formatWorldNewsPost(post, false));
    lines.push("━━━━━━━━━━━━");
    if (draft.mode === "edit") {
        lines.push("✅ 수정 저장: /소식등록");
        lines.push("🔄 처음부터 다시 수정: /소식수정 " + draft.targetId);
        lines.push("❌ 수정 취소: /소식취소");
    } else {
        lines.push("✅ 최종 등록: /소식등록");
        lines.push("🔄 처음부터 다시 작성: /소식작성");
        lines.push("❌ 작성 취소: /소식취소");
    }
    return lines.join("\n");
}

// 소식 명령과 관리자 작성 상태 입력을 처리하는 함수
function processWorldNewsCommand(data, petData, guildData, sender, room, msg, allowLottery) {
    var result = { handled: false, changed: false, message: "", broadcastMessage: "" };
    var news = ensureWorldNewsData(data);
    var isOperator = isAdmin(sender) || isMaster(sender);
    var draftKey = getWorldNewsDraftKey(sender, room);
    var draft = worldNewsDraftState[draftKey];

    if (msg === "/소식") {
        var member = data.member[sender];
        var firstEntry = allowLottery && member.worldNewsLotteryPlayed !== true;
        var reward = null;
        if (sanitizeWorldNewsPickIds(news)) result.changed = true;
        if (firstEntry) {
            reward = drawWorldNewsReward();
            member.point = (Number(member.point) || 0) + reward.point;
            member.worldNewsLotteryPlayed = true;
            result.changed = true;
            if (reward.broadcast) result.broadcastMessage = buildWorldNewsJackpotBroadcast(data, petData, guildData, sender);
        }
        result.handled = true;
        result.message = buildWorldNewsUserMessage(data, petData, guildData, sender, { firstEntry: firstEntry, reward: reward, attendanceRequired: !allowLottery });
        if (markWorldNewsPostsRead(news.posts, member)) result.changed = true;
        return result;
    }

    var isAdminCommand = /^\/소식(?:작성|관리|등록|취소|픽해제)(?:\s+.*)?$/.test(msg) || /^\/소식(?:삭제|수정|픽)(?:\s+.*)?$/.test(msg);
    if (isAdminCommand && !isOperator) {
        result.handled = true;
        result.message = "❌ 소식 관리 명령어를 사용할 권한이 없습니다.";
        return result;
    }

    if (msg === "/소식작성") {
        var adjectives = GLOBAL_CONFIG.worldNews.authorAdjectives;
        worldNewsDraftState[draftKey] = {
            mode: "create",
            step: "title",
            authorAdjective: adjectives[Math.floor(Math.random() * adjectives.length)]
        };
        refreshWorldNewsDraft(draftKey, room);
        result.handled = true;
        result.message = "📝 소식 추가 [1/3] · 제목\n\n소식의 제목을 입력해주세요.\n\n❌ 취소: /소식취소";
        return result;
    }

    if (msg === "/소식관리") {
        if (sanitizeWorldNewsPickIds(news)) result.changed = true;
        result.handled = true;
        result.message = buildWorldNewsManageMessage(data);
        return result;
    }

    if (msg === "/소식픽") {
        if (sanitizeWorldNewsPickIds(news)) result.changed = true;
        result.handled = true;
        result.message = buildWorldNewsPickGuide(news);
        return result;
    }

    if (msg === "/소식픽해제") {
        if (sanitizeWorldNewsPickIds(news)) result.changed = true;
        result.handled = true;
        if (getWorldNewsValidPickIds(news).length < 1) {
            result.message = "ℹ️ 소식픽이 이미 해제되어 있습니다.\n최신 소식을 표시하는 설정을 유지합니다.";
            return result;
        }
        news.pickIds = [];
        result.changed = true;
        result.message = "🔓 소식픽이 해제되었습니다.\n/소식 입력 시 최신 소식 1개가 표시됩니다.";
        return result;
    }

    var pickMatch = msg.match(/^\/소식픽\s+(\d+)\s+(\d+)\s+(\d+)$/);
    if (pickMatch) {
        var pickIds = [parseInt(pickMatch[1], 10), parseInt(pickMatch[2], 10), parseInt(pickMatch[3], 10)];
        result.handled = true;
        if (pickIds[0] < 1 || pickIds[1] < 1 || pickIds[2] < 1) {
            result.message = "❌ 소식관리번호는 양의 정수로 입력해주세요.\n기존 소식픽 설정은 유지됩니다.";
            return result;
        }
        if (pickIds[0] === pickIds[1] || pickIds[0] === pickIds[2] || pickIds[1] === pickIds[2]) {
            result.message = "❌ 서로 다른 소식관리번호 3개를 입력해주세요.\n기존 소식픽 설정은 유지됩니다.";
            return result;
        }
        var existingIds = {};
        for (var pi = 0; pi < news.posts.length; pi++) existingIds[parseInt(news.posts[pi].id, 10)] = true;
        var missingPickIds = [];
        for (var pj = 0; pj < pickIds.length; pj++) if (!existingIds[pickIds[pj]]) missingPickIds.push("#" + pickIds[pj]);
        if (missingPickIds.length > 0) {
            result.message = "❌ 존재하지 않는 소식관리번호입니다: " + missingPickIds.join(" · ") + "\n/소식관리에서 글번호를 확인해주세요.\n기존 소식픽 설정은 유지됩니다.";
            return result;
        }
        news.pickIds = pickIds;
        result.changed = true;
        result.message = "🎯 소식픽 설정 완료!\n" +
            "━━━━━━━━━━━━\n" +
            "선택한 소식: " + formatWorldNewsPickStatus(news) + "\n\n" +
            "/소식 입력 시 선택한 소식 중\n" +
            "1개가 동일한 확률로 상단에 표시됩니다.\n" +
            "━━━━━━━━━━━━\n" +
            "설정 해제: /소식픽해제";
        return result;
    }

    var deleteMatch = msg.match(/^\/소식삭제\s+(\d+)$/);
    if (deleteMatch) {
        var deleteId = parseInt(deleteMatch[1], 10);
        var deleteIndex = -1;
        for (var di = 0; di < news.posts.length; di++) if (parseInt(news.posts[di].id, 10) === deleteId) deleteIndex = di;
        result.handled = true;
        if (deleteIndex < 0) {
            result.message = "❌ 해당 번호의 소식을 찾을 수 없습니다.\n/소식관리에서 글번호를 확인해주세요.";
            return result;
        }
        news.posts.splice(deleteIndex, 1);
        sanitizeWorldNewsPickIds(news);
        result.changed = true;
        result.message = "🗑️ 소식이 삭제되었습니다.\n\n🔢 삭제한 글번호: #" + deleteId;
        return result;
    }

    var editMatch = msg.match(/^\/소식수정\s+(\d+)$/);
    if (editMatch) {
        var editId = parseInt(editMatch[1], 10);
        var editPost = null;
        for (var ei = 0; ei < news.posts.length; ei++) if (parseInt(news.posts[ei].id, 10) === editId) editPost = news.posts[ei];
        result.handled = true;
        if (!editPost) {
            result.message = "❌ 해당 번호의 소식을 찾을 수 없습니다.\n/소식관리에서 글번호를 확인해주세요.";
            return result;
        }
        worldNewsDraftState[draftKey] = {
            mode: "edit",
            step: "title",
            targetId: editId,
            authorAdjective: editPost.authorAdjective,
            createdAt: editPost.createdAt
        };
        refreshWorldNewsDraft(draftKey, room);
        result.message = "📝 소식 수정 [1/3] · 글번호 #" + editId + "\n\n새 제목을 입력해주세요.\n\n❌ 취소: /소식취소";
        return result;
    }

    if (msg === "/소식취소") {
        result.handled = true;
        if (worldNewsDraftState[draftKey]) delete worldNewsDraftState[draftKey];
        result.message = "❌ 진행 중인 소식 작성·수정을 취소했습니다.";
        return result;
    }

    if (msg === "/소식등록") {
        result.handled = true;
        draft = worldNewsDraftState[draftKey];
        if (!draft || draft.step !== "preview") {
            result.message = "❌ 등록할 소식 미리보기가 없습니다.\n새 글 작성: /소식작성";
            return result;
        }
        if (draft.mode === "edit") {
            var targetPost = null;
            for (var ti = 0; ti < news.posts.length; ti++) if (parseInt(news.posts[ti].id, 10) === draft.targetId) targetPost = news.posts[ti];
            if (!targetPost) {
                delete worldNewsDraftState[draftKey];
                result.message = "❌ 수정 대상 소식을 찾을 수 없습니다.\n새 글로 등록하지 않았습니다.";
                return result;
            }
            targetPost.title = draft.title;
            targetPost.content = draft.content;
            targetPost.link = draft.link;
            delete worldNewsDraftState[draftKey];
            result.changed = true;
            result.message = "✅ 소식이 수정되었습니다!\n\n🔢 글번호: #" + targetPost.id + "\n📌 " + targetPost.title;
            return result;
        }
        var newPost = {
            id: news.nextId++,
            title: draft.title,
            content: draft.content,
            link: draft.link,
            createdAt: getWorldNewsKstDateTime(),
            authorAdjective: draft.authorAdjective
        };
        news.posts.unshift(newPost);
        while (news.posts.length > GLOBAL_CONFIG.worldNews.maxPosts) news.posts.pop();
        sanitizeWorldNewsPickIds(news);
        delete worldNewsDraftState[draftKey];
        result.changed = true;
        result.message = "✅ 새로운 소식이 등록되었습니다!\n\n📌 " + newPost.title + "\n🔢 글번호: #" + newPost.id + "\n\n/소식관리에서 등록 결과를 확인해주세요.";
        return result;
    }

    if (/^\/소식픽(?:\s+.*)?$/.test(msg) || /^\/소식픽해제\s+.*$/.test(msg)) {
        result.handled = true;
        result.message = "사용법: /소식픽 [번호] [번호] [번호]\n서로 다른 기존 소식관리번호 3개를 입력해주세요.\n기존 소식픽 설정은 유지됩니다.";
        return result;
    }
    if (/^\/소식(?:작성|관리|등록|취소)\s+.*$/.test(msg) || /^\/소식삭제(?:\s+.*)?$/.test(msg) || /^\/소식수정(?:\s+.*)?$/.test(msg)) {
        result.handled = true;
        result.message = "사용법: /소식작성, /소식관리, /소식수정 [번호], /소식삭제 [번호], /소식등록, /소식취소";
        return result;
    }

    draft = worldNewsDraftState[draftKey];
    if (!draft || !isOperator || String(msg).charAt(0) === "/") return result;
    result.handled = true;
    if (draft.step === "title") {
        draft.title = String(msg).trim();
        if (!draft.title) {
            result.message = "❌ 제목을 입력해주세요.";
            return result;
        }
        draft.step = "content";
        refreshWorldNewsDraft(draftKey, room);
        result.message = "📝 소식 " + (draft.mode === "edit" ? "수정" : "추가") + " [2/3] · 내용\n\n📌 제목: " + draft.title + "\n\n소식의 내용을 입력해주세요.\n줄바꿈을 포함해 한 메시지로 보내주세요.\n\n❌ 취소: /소식취소";
        return result;
    }
    if (draft.step === "content") {
        draft.content = String(msg).trim();
        if (!draft.content) {
            result.message = "❌ 소식 내용을 입력해주세요.";
            return result;
        }
        draft.step = "link";
        refreshWorldNewsDraft(draftKey, room);
        result.message = "📝 소식 " + (draft.mode === "edit" ? "수정" : "추가") + " [3/3] · 안내 링크\n\n🔗 안내 링크를 입력해주세요.\n입력한 링크는 본문 아래에 표시됩니다.\n\n링크가 없으면 ‘없음’을 입력해주세요.\n\n❌ 취소: /소식취소";
        return result;
    }
    if (draft.step === "link") {
        draft.link = String(msg).trim() === "없음" ? "" : String(msg).trim();
        if (!draft.link && String(msg).trim() !== "없음") {
            result.message = "❌ 안내 링크를 입력하거나 ‘없음’을 입력해주세요.";
            return result;
        }
        draft.step = "preview";
        refreshWorldNewsDraft(draftKey, room);
        result.message = buildWorldNewsDraftPreview(draft);
        return result;
    }
    return result;
}

// 운영 알림 저장소를 보장하는 함수
function ensureOperationNoticeData(data) {
    if (!data.operationNotices || typeof data.operationNotices !== "object") data.operationNotices = {};
    if (typeof data.operationNotices.cleanup !== "string") data.operationNotices.cleanup = "";
    if (typeof data.operationNotices.packageBag !== "string") data.operationNotices.packageBag = "";
    return data.operationNotices;
}

// 운영 알림 문구를 반환하는 함수
function getOperationNotice(data, type) {
    var notices = data.operationNotices && typeof data.operationNotices === "object" ? data.operationNotices : {};
    var value = notices[type] || "";
    return normalizeOperationNoticeText(value);
}

// 운영 알림 입력의 줄바꿈 표기를 실제 줄바꿈으로 변환하는 함수
function normalizeOperationNoticeText(text) {
    return String(text || "").replace(/\\n|\/n/g, "\n").trim();
}

// 운영 알림 설정 명령어 처리 함수
function setOperationNoticeByCommand(data, msg) {
    var match = String(msg || "").match(/^\/(정리알림|패키지알림)\s+([^]+)$/);
    if (!match) return { ok: false, message: "❌ 사용법: /정리알림 내용 또는 /패키지알림 내용" };
    var notices = ensureOperationNoticeData(data);
    var key = match[1] === "정리알림" ? "cleanup" : "packageBag";
    notices[key] = normalizeOperationNoticeText(match[2]);
    return {
        ok: true,
        message: "✅ " + (key === "cleanup" ? "정리 알림" : "패키지가방 알림") + "을 저장했습니다."
    };
}

// 유저 패키지가방 메시지 생성 함수
function buildUserPackageBagMessage(data, petData, petSkillData, guildData, sender, packageInfoData) {
    var packageBagList = getUserPackageBagList(data, sender, packageInfoData); // 유저가 보유한 패키지 목록
    var lines = ["🎁 [" + checkRank(data, petData, guildData, sender) + "] 님의 패키지가방🎁"];
    var packageBagNotice = getOperationNotice(data, "packageBag"); // 패키지가방 상단 운영 알림 문구
    if (packageBagNotice) {
        lines.push("━━━━━━━━━━━");
        lines.push("(알림) " + packageBagNotice);
        lines.push("━━━━━━━━━━━");
        lines.push("🛍️현재 보유중인 패키지🛍️");
    }
    if (packageBagList.length < 1) {
        lines.push("보유한 패키지가 없습니다.");
    } else {
        for (var i = 0; i < packageBagList.length; i++) {
            var row = packageBagList[i]; // 패키지가방 표시 행
            var packageInfo = row.packageInfo;
            var disabledText = packageInfo.enabled === false ? " [비활성]" : "";
            lines.push(i + 1 + ". " + (packageInfo.name || getPackageBagItemName(packageInfo)) + disabledText + " x " + numberWithCommas(row.count));
        }
    }
    lines.push("");
    lines.push("사용 방법: /패키지사용 [가방번호] [오픈갯수]");
    lines.push(allsee);
    lines.push("━━━━━━━━━━━");
    lines.push("🐹 호월패스 사용 현황");
    lines.push("━━━━━━━━━━━");
    var passLines = buildUserSupportPassLines(data, sender);
    for (var p = 0; p < passLines.length; p++) {
        lines.push(passLines[p]);
    }
    var member = data.member[sender];
    var premiumActive = isHoiPassPremiumActive(data, sender); // 프리미엄 자동기능 이용 가능 여부
    var premiumAutomation = member.premiumAutomation && typeof member.premiumAutomation === "object" ? member.premiumAutomation : {};
    var territoryValidation = validateGuildTerritoryAutoAttack(data, guildData, petSkillData, sender); // 영지패스와 현재 길드 직책을 함께 확인한 결과
    var territoryStatus = territoryValidation.ok ? (member.guildTerritoryAutoAttackEnabled === true ? "ON [✅]" : "OFF [❌]") : "이용 불가 [🔒]";
    var musouStatus = premiumActive ? (premiumAutomation.petMusouAutoReady === true ? "ON [✅]" : "OFF [❌]") : "이용 불가 [🔒]";
    var attendanceStatus = premiumActive ? (premiumAutomation.autoAttendance === true ? "ON [✅]" : "OFF [❌]") : "이용 불가 [🔒]";
    lines.push("");
    lines.push("━━━━━━━━━━━");
    lines.push("⚙️ 자동기능 설정");
    lines.push("━━━━━━━━━━━");
    lines.push("⚔️ 길드영지 자동공격: " + territoryStatus);
    lines.push("└ 내 공격 차례에 영지 1~7번 중 자동 공격");
    lines.push("└ 같은 길드 영지를 공격할 수도 있으니 확인이 필요합니다.");
    lines.push("└ 설정: /영지온 · /영지오프");
    lines.push("└ 필요: 영지기습패스⚔️🛡️");
    lines.push("");
    lines.push("🐹 펫무쌍 자동준비: " + musouStatus);
    lines.push("└ 펫무쌍 준비 시 자동 참가 등록");
    lines.push("└ 설정: /무쌍온 · /무쌍오프");
    lines.push("└ 필요: 호이패스 프리미엄👑");
    lines.push("");
    lines.push("📅 자동 출석체크: " + attendanceStatus);
    lines.push("└ 매일 00:01 자동 출석체크");
    lines.push("└ 설정: /출첵온 · /출첵오프");
    lines.push("└ 필요: 호이패스 프리미엄👑");
    lines.push("");
    lines.push("[✅] ON　[❌] OFF　[🔒] 이용 불가");
    lines.push("※ 패스가 만료되면 연결된 자동기능도 중지됩니다.");
    return lines.join("\n");
}

// 공백 포함 이름과 마지막 두 양의 정수 인자만 지급 명령으로 허용하는 함수
function isPackageGrantCommand(msg) {
    return /^\/패키지지급[ \t]+[^\r\n]+[ \t]+\d+[ \t]+\d+$/.test(String(msg));
}

// 패키지 지급 명령어 파싱 함수
function parsePackageGrantCommand(msg) {
    if (!isPackageGrantCommand(msg)) return null;
    var body = String(msg || "").replace(/^\/패키지지급\s+/, "").trim(); // 명령어를 제거한 입력 본문
    var parts = body.split(/\s+/); // 뒤에서부터 번호/갯수를 파싱하기 위한 토큰 배열
    if (parts.length < 3) return null;
    var count = parseInt(parts.pop(), 10); // 지급 수량
    var listNumber = parseInt(parts.pop(), 10); // 패키지리스트 번호
    var target = parts.join(" "); // 공백 포함 유저 이름
    if (!target || isNaN(listNumber) || isNaN(count)) return null;
    return {
        target: target,
        listNumber: listNumber,
        count: count
    };
}

// 패키지 실적의 최초 준비 상태를 반환하는 함수
function createPackageGrantStore() {
    return { version: 1, historyImported: false, trackedFrom: null, records: [] };
}

// 실적 원본의 필수 값과 중복 지급 식별값을 검증하는 함수
function requirePackageGrantStore(store) {
    if (!store || store.version !== 1 || typeof store.historyImported !== "boolean" || !Array.isArray(store.records) || store.trackedFrom !== null && (typeof store.trackedFrom !== "string" || !isFinite(Date.parse(store.trackedFrom)))) throw new Error("패키지 실적 파일 형식 오류");
    var seen = {};
    for (var i = 0; i < store.records.length; i++) {
        var row = store.records[i];
        if (!row || typeof row.id !== "string" || !row.id || seen["$" + row.id] || typeof row.operatorId !== "string" || !row.operatorId || typeof row.operator !== "string" || !row.operator || typeof row.targetId !== "string" || !row.targetId || typeof row.target !== "string" || !row.target || typeof row.packageName !== "string" || !row.packageName || !isSearchAuthenticationCount(row.quantity) || row.quantity < 1 || typeof row.at !== "string" || !/T\d{2}:\d{2}:\d{2}.*(?:Z|[+-]\d{2}:\d{2})$/.test(row.at) || !isFinite(Date.parse(row.at)) || row.listNumber !== null && (!isSearchAuthenticationCount(row.listNumber) || row.listNumber < 1) || row.legacy !== true && (typeof row.command !== "string" || typeof row.reply !== "string" || row.listNumber === null)) throw new Error("패키지 지급 기록 오류");
        seen["$" + row.id] = true;
    }
    return store;
}

// 현재 계정의 기존 고정 ID 또는 과거 이름 식별값을 반환하는 함수
function getPackageGrantIdentity(data, user) {
    var member = data.member && data.member[user];
    return member && member.serverRaidAccount && member.serverRaidAccount.id ? member.serverRaidAccount.id : "legacy:" + user;
}

// 보관된 실제 지급 로그만 날짜별 원본 실적으로 한 번 가져오는 함수
function importPackageGrantHistory(store, logs, data) {
    assertPackageLogData(logs);
    if (store.historyImported) return;
    var seen = {};
    for (var s = 0; s < store.records.length; s++) seen["$" + store.records[s].id] = true;
    for (var i = 0; i < logs.logs.length; i++) {
        var row = logs.logs[i], id = row && "legacy:" + row.id;
        if (!row || row.type !== "GRANT" || !isSearchAuthenticationCount(row.id) || row.id < 1 || seen["$" + id] || typeof row.by !== "string" || !row.by || typeof row.target !== "string" || !row.target || typeof row.packageName !== "string" || !row.packageName || !isSearchAuthenticationCount(row.count) || row.count < 1 || typeof row.date !== "string" || !/T\d{2}:\d{2}:\d{2}.*(?:Z|[+-]\d{2}:\d{2})$/.test(row.date) || !isFinite(Date.parse(row.date))) continue;
        store.records.push({ id: id, at: row.date, operatorId: getPackageGrantIdentity(data, row.by), operator: row.by, targetId: getPackageGrantIdentity(data, row.target), target: row.target, packageName: row.packageName, listNumber: null, quantity: row.count, legacy: true });
        seen["$" + id] = true;
    }
    store.historyImported = true;
    requirePackageGrantStore(store);
}

// 동일하게 접수된 지급 사건의 기존 완료 기록을 반환하는 함수
function findPackageGrantRecord(store, id) {
    for (var i = 0; i < store.records.length; i++) if (store.records[i].id === id) return store.records[i];
    return null;
}

// 성공한 지급만 기존 계정 ID와 당시 상품 정보로 한 번 기록하는 함수
function recordPackageGrant(store, data, sender, parsed, packageInfo, id, command, reply, now) {
    if (findPackageGrantRecord(store, id)) throw new Error("패키지 실적 중복 기록");
    var names = [sender, parsed.target];
    for (var n = 0; n < names.length; n++) {
        var member = data.member[names[n]];
        if (member && !member.serverRaidAccount) member.serverRaidAccount = { id: String(java.util.UUID.randomUUID()), period: 0, server: normalizeHoiServerLabel(member.server), latest: null, total: null };
        if (member && (!member.serverRaidAccount || typeof member.serverRaidAccount.id !== "string" || !member.serverRaidAccount.id)) throw new Error("패키지 담당자·대상 계정 ID 오류");
    }
    var operatorId = getPackageGrantIdentity(data, sender), at = new Date(now).toISOString();
    for (var i = 0; i < store.records.length; i++) if (store.records[i].operatorId === "legacy:" + sender) store.records[i].operatorId = operatorId;
    if (store.trackedFrom === null) store.trackedFrom = at;
    store.records.push({ id: id, at: at, operatorId: operatorId, operator: sender, targetId: getPackageGrantIdentity(data, parsed.target), target: parsed.target, packageName: packageInfo.name || getPackageBagItemName(packageInfo), listNumber: parsed.listNumber, quantity: parsed.count, command: command, reply: reply });
    requirePackageGrantStore(store);
}

// 패키지 실적의 개인·전체·한국시간 월 지정 입력을 해석하는 함수
function getPackageGrantStatsRequest(msg) {
    if (!/^\/패키지실적(?:\s|$)/.test(String(msg))) return null;
    var match = String(msg).match(/^\/패키지실적(?:[ \t]+([^\r\n]+))?$/);
    var error = "❌ 사용법: /패키지실적 [전체 또는 담당자 아이디] [YYYY-MM]";
    if (!match) return { error: error };
    var input = (match[1] || "").trim(), current = getGmEducationMonthKey(), parts = input.match(/^(?:(.*)[ \t]+)?([^ \t]+)$/), last = parts ? parts[2] : "", month = current;
    if (/^\d{4}[-/.]/.test(last)) {
        if (!/^(?!0000)\d{4}-(?:0[1-9]|1[0-2])$/.test(last)) return { error: "❌ 월은 2026-10처럼 YYYY-MM 형식으로 입력해 주세요." };
        month = last; input = (parts[1] || "").trim();
    } else if (/(?:^|[ \t])\d{4}[-/.]/.test(input)) return { error: error };
    if (input === "초기화") return { error: "패키지 실적은 월별로 보존합니다. /패키지실적 전체 YYYY-MM으로 지난 기록을 조회하세요." };
    return { target: input, all: input === "전체", month: month };
}

// 지급 확정 시각을 한국시간의 날짜와 시분초로 표시하는 함수
function formatPackageGrantTime(at) {
    var date = new Date(Date.parse(at) + 9 * 60 * 60 * 1000);
    return date.getUTCFullYear() + "-" + ("0" + (date.getUTCMonth() + 1)).slice(-2) + "-" + ("0" + date.getUTCDate()).slice(-2) + " " + ("0" + date.getUTCHours()).slice(-2) + ":" + ("0" + date.getUTCMinutes()).slice(-2) + ":" + ("0" + date.getUTCSeconds()).slice(-2);
}

// 성공 원본에서 월별 합계·공동 순위·당시 지급 내역을 읽기 전용으로 표시하는 함수
function buildPackageGrantStatsMessage(store, data, sender, request) {
    var target = request.target || sender, id = getPackageGrantIdentity(data, target), accounts = buildServerRaidAccountIndex(data), matchingIds = {};
    if (!request.all && !Object.prototype.hasOwnProperty.call(data.member, target)) {
        for (var t = 0; t < store.records.length; t++) if (store.records[t].operator === target) matchingIds["$" + store.records[t].operatorId] = store.records[t].operatorId;
        var found = Object.keys(matchingIds);
        if (found.length !== 1) return "❌ 해당 담당자 아이디를 찾을 수 없습니다.";
        id = matchingIds[found[0]];
    }
    var heading = (request.all ? "📊 호이월드 패키지 지급 전체 실적" : "📦 [" + target + "] 님의 패키지 지급 실적") + "\n📅 " + request.month.slice(0,4) + "년 " + request.month.slice(5) + "월\n━━━━━━━━━━━━\n";
    if (request.month > getGmEducationMonthKey()) return heading + "아직 집계가 시작되지 않은 달입니다.";
    var groups = {}, count = 0, quantity = 0; // 조회 월의 실제 성공 건수와 패키지 수량 합계
    for (var i = 0; i < store.records.length; i++) {
        var record = store.records[i];
        if (getGmEducationMonthKey(record.at) !== request.month || !request.all && record.operatorId !== id) continue;
        var key = "$" + record.operatorId, account = accounts[record.operatorId];
        if (!groups[key]) groups[key] = { name: account ? account.user : record.operator, records: [], quantity: 0 };
        groups[key].records.push(record); groups[key].quantity += record.quantity;
        count++; quantity += record.quantity;
        if (!isSearchAuthenticationCount(quantity)) throw new Error("패키지 실적 합계 범위 초과");
    }
    var rows = Object.keys(groups).map(function (key) { return groups[key]; });
    rows.sort(function (a,b) { return b.records.length - a.records.length || a.name.localeCompare(b.name); });
    var partial = store.trackedFrom === null || request.month <= getGmEducationMonthKey(store.trackedFrom); // 도입 월까지는 과거 보관 로그만 확인 가능한 불완전 집계
    var summary = heading + (request.all ? "📨 총 지급 횟수: " : "📨 지급 횟수: ") + numberWithCommas(count) + "회\n" + (request.all ? "🎁 총 지급 갯수: " : "🎁 지급 갯수: ") + numberWithCommas(quantity) + "개\n━━━━━━━━━━━━\n";
    if (partial) summary += "※ 기록 시작 이전은 보관된 지급 로그만 집계해 일부 내역이 없을 수 있어요.\n";
    if (!count) return summary + (partial ? "확인 가능한 기록 없음" : "해당 월의 패키지 지급 실적이 없습니다.");
    var full = [], top = [], rankLines = [], rank = 0, shown = 0, omitted = false, omittedRanks = false;
    for (var r = 0; r < rows.length; r++) {
        if (!r || rows[r].records.length !== rows[r-1].records.length) rank = r+1;
        var line = rank + "등 [" + rows[r].name + "] · " + numberWithCommas(rows[r].records.length) + "회 · " + numberWithCommas(rows[r].quantity) + "개";
        if (request.all && r < 3) top.push(line);
        if (request.all) rankLines.push(line);
    }
    if (request.all) summary += "🏆 담당자 순위 (지급 횟수 기준)\n" + top.join("\n") + "\n━━━━━━━━━━━━\n";
    summary += "📋 지급 대상·상품·날짜는 전체보기에서 확인하세요.";
    var detailBudget = Math.max(0,GLOBAL_CONFIG.packageGrant.detailMaxLength-summary.length-allsee.length-GLOBAL_CONFIG.packageGrant.footerReserve); // 전체보기 구분자·합계·생략 안내까지 남긴 본문 길이
    if (request.all) full.push("📊 전체 담당자 지급 실적");
    for (var p = 0; p < rankLines.length; p++) {
        if (full.join("\n\n").length + rankLines[p].length + 2 > detailBudget) { omittedRanks = true; break; }
        full.push(rankLines[p]);
    }
    if (full.join("\n\n").length + 30 <= detailBudget) full.push("━━━━━━━━━━━━", "📋 패키지 지급 상세 기록");
    for (var g = 0; g < rows.length; g++) {
        rows[g].records.sort(function(a,b) { return Date.parse(b.at)-Date.parse(a.at) || a.id.localeCompare(b.id); });
        if (request.all) {
            var groupLine = "👤 [" + rows[g].name + "] · " + rows[g].records.length + "회 / " + numberWithCommas(rows[g].quantity) + "개";
            if (full.join("\n\n").length + groupLine.length + 2 > detailBudget) { omitted = true; break; }
            full.push(groupLine);
        }
        for (var d = 0; d < rows[g].records.length; d++) {
            var item = rows[g].records[d];
            var detail = formatPackageGrantTime(item.at) + " · [" + item.target + "]\n" + (item.listNumber === null ? "당시 번호 미기록" : item.listNumber + "번") + " · " + item.packageName + " ×" + numberWithCommas(item.quantity);
            if (full.join("\n\n").length + detail.length + 2 > detailBudget) { omitted = true; break; }
            full.push(detail); shown++;
        }
        if (omitted) break;
    }
    if (omitted || omittedRanks) full.push("※ 출력 길이 제한: 상세 " + shown + "/" + count + "건 · 담당자 " + rows.length + "명. 원본 기록은 모두 보존돼요. /패키지실적 담당자 YYYY-MM으로 범위를 좁혀 확인하세요.");
    full.push("━━━━━━━━━━━━", "합계: " + numberWithCommas(count) + "회 / " + numberWithCommas(quantity) + "개");
    return summary + "\n" + allsee + full.join("\n\n");
}

// 회원 분리 저장 계획과 지급·통계를 재시작 후 완결할 게시 원문으로 묶는 함수
function buildPackageGrantPublication(data, logs, stats, extra) {
    var adventure = data.__adventureRecordContext;
    if (adventure && JSON.stringify(adventure.store) !== adventure.text) throw new Error("패키지 지급 중 저장하지 않은 퀘스트 기록 변경 감지");
    var plan = buildMemberSplitSavePlan(data), writes = [];
    if (plan) for (var i = 0; i < plan.writes.length; i++) writes.push({ name: String(new java.io.File(plan.writes[i].path).getName()), text: plan.writes[i].text });
    writes.push({ name: "member.json", text: JSON.stringify(plan ? plan.member : data) });
    for (var e = 0; e < extra.length; e++) writes.push(extra[e]);
    writes.push({ name: "packageLog.json", text: JSON.stringify(logs) }, { name: GLOBAL_CONFIG.packageGrant.fileName, text: JSON.stringify(requirePackageGrantStore(stats)) });
    var publication = { version: 1, pending: writes };
    validatePackageGrantPending(publication);
    return publication;
}

// 지급 게시 원문의 닫힌 파일 목록과 복구 데이터 형식을 검증하는 함수
function validatePackageGrantPending(journal) {
    if (!journal || journal.version !== 1 || !Object.prototype.hasOwnProperty.call(journal,"pending") || journal.pending !== null && !Array.isArray(journal.pending)) throw new Error("패키지 지급 복구 형식 오류");
    if (journal.pending === null) return;
    var seen = {};
    for (var i = 0; i < journal.pending.length; i++) {
        var row = journal.pending[i];
        if (!row || typeof row.name !== "string" || !/^(?:member|packageLog|packageGrantStats|serverRaidData(?:_next)?|memberOperationLogs(?:_next)?|halloweenEvent|halloweenAccount_[A-Za-z0-9_-]{1,128})\.json$/.test(row.name) || seen[row.name] || typeof row.text !== "string") throw new Error("패키지 지급 복구 대상 오류");
        seen[row.name] = true;
        var parsed = parseJsonContent(row.text,row.name);
        if (row.name === "member.json" && (!parsed || !parsed.member || typeof parsed.member !== "object" || Array.isArray(parsed.member))) throw new Error("패키지 지급 회원 원문 오류");
        if (row.name === GLOBAL_CONFIG.packageGrant.fileName) requirePackageGrantStore(parsed);
        if (row.name === "packageLog.json") assertPackageLogData(parsed);
        if (/^halloweenAccount_/.test(row.name)) requireHalloweenAccount(parsed,parsed.id);
        if (row.name === GLOBAL_CONFIG.halloween.stateName) requireHalloweenState(parsed);
        if (/^(serverRaidData|memberOperationLogs)/.test(row.name)) requireMemberSplitStore(parsed,row.name.indexOf("serverRaidData") === 0 ? "raid" : "logs");
    }
    if (!seen["member.json"] || !seen["packageLog.json"] || !seen[GLOBAL_CONFIG.packageGrant.fileName]) throw new Error("패키지 지급 복구 필수 원문 누락");
}

// 접수된 지급 게시를 재실행·재지급 없이 동일 원문으로 끝내는 저장 진입 함수
function recoverPackageGrantPending() {
    dataTransactionLock.lock();
    try {
        var path = resolveActiveDataPath(DATA_ROOT_PATH + GLOBAL_CONFIG.packageGrant.pendingName), file = new java.io.File(path), rollback = new java.io.File(path + ".rollback");
        if (!file.exists() && rollback.exists()) {
            var interrupted = String(FileStream.read(path + ".rollback","utf-8"));
            validatePackageGrantPending(parseJsonContent(interrupted,path));
            if (!rollback.renameTo(file)) throw new Error("패키지 지급 복구 파일 복원 실패");
        }
        if (!file.exists()) return false;
        var journal = parseJsonContent(FileStream.read(path,"utf-8"),path);
        validatePackageGrantPending(journal);
        if (journal.pending === null) return false;
        for (var i = 0; i < journal.pending.length; i++) {
            var targetPath = resolveActiveDataPath(DATA_ROOT_PATH + journal.pending[i].name);
            if (!new java.io.File(targetPath).exists() || String(FileStream.read(targetPath,"utf-8")) !== journal.pending[i].text) writeVerifiedJsonFile(targetPath,journal.pending[i].text,false);
        }
        writeVerifiedJsonFile(path,{ version: 1, pending: null },true);
        memberSplitBackupCache = {};
        return true;
    } finally { dataTransactionLock.unlock(); }
}

// 관리자 패키지 지급 처리 함수
function grantPackageToUser(data, sender, msg, packageInfoData, packageLogData) {
    var parsed = parsePackageGrantCommand(msg); // 지급 명령어 파싱 결과
    if (!parsed) return { ok: false, message: "❌ 사용법: /패키지지급 이름 리스트번호 갯수" };
    if (parsed.count < 1 || parsed.count > 10000) return { ok: false, message: "❌ 지급 수량은 1 이상 10000 이하만 가능합니다." };

    var packageInfo = getPackageByListNumber(packageInfoData, parsed.listNumber); // 지급 대상 패키지 정보
    var packageBagItemName = getPackageBagItemName(packageInfo); // member bag에 저장할 패키지명
    if (!packageInfo) return { ok: false, message: "❌ 패키지 번호가 올바르지 않습니다." };
    if (!packageBagItemName) return { ok: false, message: "❌ 패키지명이 올바르지 않습니다." };
    if (packageInfo.enabled === false) return { ok: false, message: "❌ 비활성화된 패키지는 지급할 수 없습니다." };
    if (!data.member || !data.member[parsed.target]) return { ok: false, message: "❌ 대상 유저가 존재하지 않습니다: " + parsed.target };
    if (!data.member[parsed.target].bag) data.member[parsed.target].bag = {};

    var beforeCount = parseInt(data.member[parsed.target].bag[packageBagItemName], 10) || 0; // 지급 전 보유 수량
    var afterCount = beforeCount + parsed.count; // 지급 후 보유 수량
    if (!isSearchAuthenticationCount(beforeCount) || !isSearchAuthenticationCount(afterCount)) return { ok: false, message: "❌ 패키지 보유 수량의 안전한 처리 범위를 초과했습니다." };
    data.member[parsed.target].bag[packageBagItemName] = afterCount;

    packageLogData = appendPackageLog(packageLogData, "GRANT", packageInfo, parsed.target, parsed.count, sender, beforeCount, afterCount);
    var lines = [];
    lines.push("✅ 패키지 지급 완료");
    lines.push("");
    lines.push("대상: " + parsed.target);
    lines.push("패키지: " + (packageInfo.name || packageBagItemName));
    lines.push("지급 수량: " + numberWithCommas(parsed.count) + "개");
    lines.push("보유 수량: " + numberWithCommas(beforeCount) + "개 → " + numberWithCommas(afterCount) + "개");
    lines.push("지급자: " + sender);
    return {
        ok: true,
        message: lines.join("\n"),
        packageLogData: packageLogData
    };
}

// 패키지 사용 명령어 파싱 함수
function parsePackageUseCommand(msg) {
    var parts = String(msg || "").trim().split(/\s+/); // /패키지사용 번호 갯수 토큰
    if (parts.length < 2 || parts.length > 3) return null;
    var bagNumber = parseInt(parts[1], 10); // 패키지가방 번호
    var count = parts.length >= 3 ? parseInt(parts[2], 10) : 1; // 사용 수량, 생략 시 1개
    if (isNaN(bagNumber) || isNaN(count)) return null;
    return {
        bagNumber: bagNumber,
        count: count
    };
}

// 패키지 사용 전 보상 타입과 사용 조건 검사 함수
function validatePackageUse(packageInfo, useCount, halloween) {
    if (hasHalloweenPackageReward(packageInfo) && (!halloween || !halloween.state.active)) return "할로윈 이벤트 진행 중에만 이 패키지를 사용할 수 있습니다.";
    if (!packageInfo) return "패키지 정보가 없습니다.";
    var durationPackageError = getPassDurationPackageError(packageInfo);
    if (durationPackageError) return durationPackageError;
    if (packageInfo.enabled === false) return "비활성화된 패키지는 사용할 수 없습니다.";
    if (packageInfo.blockCastle && castleSiegeFlag) return "이벤트 진행 중에는 해당 패키지를 사용할 수 없습니다.";
    if (useCount < 1) return "사용 수량은 1개 이상이어야 합니다.";
    var maxUseOnce = GLOBAL_CONFIG.package.maxUseOnce; // 통합 패키지 1회 최대 사용량
    if (useCount > maxUseOnce) return "1회 최대 사용 수량(" + numberWithCommas(maxUseOnce) + "개)을 초과했습니다.";
    var rewards = packageInfo.rewards || []; // 사용 시 지급할 보상 목록
    for (var i = 0; i < rewards.length; i++) {
        var reward = normalizeRetiredCarrotPackageReward(rewards[i]); // 사전 검사 대상 보상 항목
        if (!reward || (reward.type !== "item" && reward.type !== "point")) {
            return "아직 지원하지 않는 보상 타입이 포함되어 있습니다: " + (reward && reward.type ? reward.type : "unknown");
        }
        var rewardCount = parseInt(reward.count, 10) || 0; // 보상 기본 수량
        if (rewardCount < 1) return "보상 수량이 올바르지 않습니다.";
        if (reward.type === "item" && !reward.name) return "보상 아이템명이 없습니다.";
    }
    return "";
}

// 패키지 보상 지급 함수
function applyPackageRewards(data, user, packageInfo, useCount, halloween) {
    getPackagePointAward(packageInfo, useCount, data.member[user].point);
    var rewards = packageInfo.rewards || []; // 패키지 보상 목록
    var rewardLines = []; // 지급 결과 메시지 라인
    for (var i = 0; i < rewards.length; i++) {
        var reward = normalizeRetiredCarrotPackageReward(rewards[i]); // 지급할 보상 항목
        if (reward.name === GLOBAL_CONFIG.spiritRetirement.removedItem) continue;
        var totalCount = (parseInt(reward.count, 10) || 0) * useCount; // 사용 수량을 곱한 최종 지급량
        if (reward.type === "item" && reward.name === GLOBAL_CONFIG.halloween.currencyName) {
            if (!halloween || !halloween.state.active) throw new Error("할로윈 사탕 지급 컨텍스트 없음");
            requireHalloweenInteger(totalCount);
            halloween.account.candy = requireHalloweenInteger(halloween.account.candy + totalCount);
            halloween.account.history.push({ kind: "packageCandy", candy: totalCount, packageName: packageInfo.name, at: halloween.at, txId: halloween.txId });
            rewardLines.push(GLOBAL_CONFIG.halloween.currencyName + " x" + numberWithCommas(totalCount));
        } else if (reward.type === "item") {
            var packageRewardItemName = normalizePassDurationItemName(normalizeMiniPetRewardBoxItemName(reward.name)); // 구 이용권도 새 정식 이름으로 지급
            addItem(data, user, packageRewardItemName, totalCount);
            rewardLines.push(packageRewardItemName + " x" + numberWithCommas(totalCount));
        } else if (reward.type === "point") {
            if (typeof data.member[user].point !== "number") data.member[user].point = 0;
            addPoint(data, user, totalCount);
            rewardLines.push("포인트 🅟" + numberWithCommas(totalCount));
        }
    }
    return rewardLines;
}

// 유저 패키지 사용 처리 함수
function usePackageFromBag(data, petData, guildData, sender, msg, packageInfoData, packageLogData, halloween) {
    var parsed = parsePackageUseCommand(msg); // 사용 명령어 파싱 결과
    if (!parsed) return { ok: false, message: "❌ 사용법: /패키지사용 가방번호 갯수" };
    var packageBagList = getUserPackageBagList(data, sender, packageInfoData); // 유저 패키지가방 목록
    if (packageBagList.length < 1) return { ok: false, message: "❌ 보유한 패키지가 없습니다." };
    if (parsed.bagNumber < 1 || parsed.bagNumber > packageBagList.length) return { ok: false, message: "❌ 패키지가방 번호가 올바르지 않습니다." };

    var selected = packageBagList[parsed.bagNumber - 1]; // 사용 대상 패키지가방 행
    var packageInfo = selected.packageInfo; // 사용 대상 패키지 정보
    var packageBagItemName = getPackageBagItemName(packageInfo); // member bag에서 차감할 패키지명
    var beforeCount = selected.count; // 사용 전 보유 수량
    if (parsed.count > beforeCount) return { ok: false, message: "❌ 보유 수량이 부족합니다. (보유: " + numberWithCommas(beforeCount) + "개)" };
    var validationMessage = validatePackageUse(packageInfo, parsed.count, halloween); // 차감 전 사전 검사 결과
    if (validationMessage) return { ok: false, message: "❌ " + validationMessage };

    try {
        validatePassDurationPackageStock(data, sender, packageInfo, parsed.count);
        getPackagePointAward(packageInfo, parsed.count, data.member[sender].point);
    } catch (pointError) { return { ok: false, message: "❌ " + pointError.message }; }
    var afterCount = beforeCount - parsed.count; // 사용 후 보유 수량
    if (afterCount > 0) {
        data.member[sender].bag[packageBagItemName] = afterCount;
    } else {
        delete data.member[sender].bag[packageBagItemName];
    }
    var rewardLines = applyPackageRewards(data, sender, packageInfo, parsed.count, halloween); // 패키지 보상 지급 결과
    packageLogData = appendPackageLog(packageLogData, "USE", packageInfo, sender, parsed.count, sender, beforeCount, afterCount);
    var lines = [];
    lines.push("🎁 패키지 사용 완료!");
    lines.push("");
    lines.push("사용자: " + sender);
    lines.push("사용 패키지: " + (packageInfo.name || packageBagItemName));
    lines.push("사용 수량: " + numberWithCommas(parsed.count) + "개");
    lines.push("");
    lines.push("획득 보상:");
    lines.push(rewardLines.join("\n"));
    return {
        ok: true,
        message: lines.join("\n"),
        packageLogData: packageLogData
    };
}

