function checkFee(data, user) {
    var tierName = data.member[user].rank.tier || "새싹";
    var tierData = ticketTierData[tierName] || ticketTierData["새싹"];
    var LowFeeR = tierData.low || 0.95;
    var HighFeeR = tierData.high || 0.7;
    var emoji = tierData.emoji || "";
    var FeeInfo = "(" + emoji + "수수료: " + ((1 - LowFeeR) * 100).toFixed(0) + "% / 고액수수료: " + ((1 - HighFeeR) * 100).toFixed(0) + "%)";
    return {
        FeeInfo: FeeInfo,
        LowFeeR: LowFeeR,
        HighFeeR: HighFeeR
    };
}
// 순위에 따른 이모지 반환 함수
function getRankEmoji(rank) {
    switch (rank) {
        case 1:
            return "🥇. ";
        case 2:
            return "🥈. ";
        case 3:
            return "🥉. ";
        default:
            return addsingle(rank) + ". ";
    }
}
// 숫자가 1자리 수면 앞에 띄어쓰기를 추가하는 함수
function addsingle(number) {
    return number < 10 ? "  " + number : " " + number;
}

// 회원의 저장 티어에 해당하는 최신 이모지를 반환하는 함수
function getTierEmojiForMember(member) {
    if (!member || !member.rank) return "";
    var tierName = member.rank.tier === "벚꽃" ? "벛꽃" : member.rank.tier;
    var tier = ticketTierData[tierName];
    return tier && tier.emoji ? tier.emoji : (member.rank.emoji || "");
}

// 저장 티어를 기준으로 닉네임에 표시할 이모지를 반환하는 함수
function getCheckRankTierEmoji(data, user) {
    return getTierEmojiForMember(data && data.member ? data.member[user] : null);
}

// 순위 이모지 감추기 상태에서는 티어 이모지로 전환하는 함수
function getVisibleRankEmoji(data, user, emoji) {
    var member = data && data.member ? data.member[user] : null;
    return member && member.displaySettings && member.displaySettings.hideRankEmoji === true ? getTierEmojiForMember(member) : emoji;
}

// 회원의 직접 저장된 티어 이모지를 표시 설정에 맞춰 반환하는 함수
function getMemberRankEmojiForDisplay(member) {
    if (!member || !member.rank) return "";
    return member.displaySettings && member.displaySettings.hideRankEmoji === true ? getTierEmojiForMember(member) : (member.rank.emoji || "");
}

function checkRank(data, petData, guildData, user) {
    let userwithrank = user;
    if (!guildData) {
        guildData = loadJsonFile(guildPath);
    }
    if (data.member[user]) {
        var isCastleGuildMember = false;

        if (guildData && data.HoiCastle && data.HoiCastle.lord) {
            var lordGuildInfo = getMyGuildInfo(data, guildData, data.HoiCastle.lord);
            var userGuildInfo = getMyGuildInfo(data, guildData, user);

            if (lordGuildInfo && !lordGuildInfo.error && lordGuildInfo.guild && userGuildInfo && !userGuildInfo.error && userGuildInfo.guild) {
                if (lordGuildInfo.guild.name === userGuildInfo.guild.name) {
                    isCastleGuildMember = true;
                }
            }
        }

        var rankPrefix = ""; // 순위·칭호에 따라 닉네임 앞에 붙는 이모지
        if (isCastleGuildMember) {
            // 성주 또는 성주와 같은 길드원
            rankPrefix = "🏰";
        } else if (user == data.star) {
            //좋아요
            rankPrefix = "💞";
        } else if (user == data.topCarrotGive) {
            //당근
            rankPrefix = "🥕";
        } else if (user == data.topThermo) {
            //온도
            rankPrefix = "🌡";
        } else if (user == data.miniPetTop) {
            //미니펫
            rankPrefix = "✨";
        } else if (user == data.toplv) {
            //최고 레벨
            rankPrefix = "🌟";
        } else if (user == data.mc) {
            //mc
            rankPrefix = "💬";
        } else if (user == data.intimacyTop) {
            //친밀도
            rankPrefix = "🍼";
        } else {
            rankPrefix = getCheckRankTierEmoji(data, user);
        }
        userwithrank = getVisibleRankEmoji(data, user, rankPrefix) + userwithrank;

        // 길드 계급 이모지 추가
        if (guildData) {
            var myGuildInfo = getMyGuildInfo(data, guildData, user);
            if (myGuildInfo && !myGuildInfo.error && myGuildInfo.guild) {
                var g = myGuildInfo.guild;
                var guildRank = g.rank;

                if (typeof guildRank === "number" && guildRank >= 1 && guildRank <= 20) {
                    var guildEmoji = getGuildMasterRankEmoji(guildRank);
                    if (guildEmoji) {
                        userwithrank += "_" + guildEmoji;
                    }
                }
            }
        }

        var musouChampion = data.petMusou && data.petMusou.currentChampion ? data.petMusou.currentChampion : null;
        if (musouChampion && musouChampion.user === user && musouChampion.expiresAt > new Date().getTime()) {
            userwithrank = "[무쌍⚔️]" + userwithrank;
        }

        return rememberHalloweenRank(userwithrank);
    } else {
        return rememberHalloweenRank(userwithrank);
    }
}

