        bag["미니펫뽑기🐹(/미니펫오픈)"] = (bag["미니펫뽑기🐹(/미니펫오픈)"] || 0) + mini;
        bag["펫스윗홈인테리어샵🖼️(/샵오픈)"] = (bag["펫스윗홈인테리어샵🖼️(/샵오픈)"] || 0) + shop;

