    var fullName = normalizeFreeMarketSearchText(listing.itemName).replace(/\(\/[^)]*\)/g, "").replace(/[\uFE0E\uFE0F]/g, "");
    var names = [fullName], plainName = normalizeFreeMarketFullName(listing.itemName);
