// Mini-pet upgrade probability table builder
function buildMiniUpgradeProbabilityTable(maxLevel) {
    var table = [null];
    for (var lv = 1; lv <= maxLevel; lv++) {
        if (lv <= 20) table[lv] = 0.7;
        else if (lv <= 50) table[lv] = 0.5;
        else if (lv <= 80) table[lv] = 0.4;
        else if (lv <= 90) table[lv] = 0.25;
        else if (lv <= 100) table[lv] = 0.07;
        else if (lv <= 150) table[lv] = 0.05;
        else if (lv <= 200) table[lv] = 0.03;
        else if (lv <= 250) table[lv] = 0.02;
        else table[lv] = 0.01;
    }
    return table;
}

// Mini-pet upgrade point cost table builder
function buildMiniUpgradeCostTable(maxLevel) {
    var table = [null];
    for (var lv = 1; lv <= maxLevel; lv++) {
        if (lv <= 100) table[lv] = 10000000;
        else if (lv <= 200) table[lv] = 20000000;
        else table[lv] = 30000000;
    }
    return table;
}

// Mini-pet upgrade charm gain table builder
function buildMiniUpgradeCharmTable(maxLevel, charmPerLevel) {
    var table = [null];
    for (var lv = 1; lv <= maxLevel; lv++) {
        table[lv] = charmPerLevel;
    }
    return table;
}

// 가방에서 가장 높은 %의 확률UP 아이템 찾기: "미니펫강화확률UP🐷(x%)"
function findBestMiniBoostItem(bag) {
    var best = null,
        bestPct = 0;
    var re = /^미니펫강화확률UP🐷\((\d+(?:\.\d+)?)%\)$/;
    for (var k in bag) {
        if (!bag.hasOwnProperty(k)) continue;
        if (!bag[k] || bag[k] <= 0) continue;
        var m = k.match(re);
        if (m) {
            var pct = parseFloat(m[1]);
            if (!isNaN(pct) && pct > bestPct) {
                bestPct = pct;
                best = k;
            }
        }
    }
    return best
        ? {
            name: best,
            addPct: bestPct
        }
        : null;
}
// 엘리트 등급 판정
function isElite(mini) {
    return mini && (mini.grade === "엘리트" || mini.grade === "엘리트급" || mini.grade === "ELITE");
}
// 마스터 등급 판정
function isMasterMiniPet(mini) {
    return mini && mini.grade === "마스터";
}
// 도달 레벨(targetLv)에서 오르는 매력 수치
function getCharmGainFor(mini, targetLv) {
    if (!mini) return 0;

    let table = isMasterMiniPet(mini) ? MINI_CHARM_MASTER : isElite(mini) ? MINI_CHARM_ELITE : MINI_CHARM_OTHER;
    return table[targetLv] || 0;
}
//  불변 필드 위주 동일성 체크 (battleExp 등 가변값은 제외)
function isSameMiniShallow(a, b) {
    if (!a || !b) return false;
    if (a === b) return true;
    return a.name === b.name && a.emoji === b.emoji && a.grade === b.grade && Number(a.price) === Number(b.price);
}
//  선택된 mini(복사본일 수도 있음)를 petData 원본에 강제 반영
function persistMiniToOriginal(petData, sender, picked, level, battleExp, castleExp, raidExp) {
    if (!petData || !petData[sender] || !picked || !picked.mini) return;
    let s = petData[sender];
    if (picked.where === "equipped" && s.miniPet) {
        s.miniPet.upgrade = level;
        s.miniPet.battleExp = battleExp;
        s.miniPet.castleExp = castleExp;
        s.miniPet.raidExp = raidExp;
        return;
    }
    if (picked.where === "bag") {
        let bag = Array.isArray(s.miniPetBag) ? s.miniPetBag : [];
        if (picked.bagIndex >= 0 && picked.bagIndex < bag.length) {
            bag[picked.bagIndex].upgrade = level;
            bag[picked.bagIndex].battleExp = battleExp;
            bag[picked.bagIndex].castleExp = castleExp;
            bag[picked.bagIndex].raidExp = raidExp;
            return;
        }
        replier.reply("❌ 미니펫 강화 대상이 유효하지 않습니다.");
    }
}
function rollDiceRoulette() {
    var table = [
        {
            pct: 86.0,
            reward: 1
        },
        {
            pct: 10.0,
            reward: 5
        },
        {
            pct: 3.0,
            reward: 20
        },
        {
            pct: 0.9,
            reward: 50
        },
        {
            pct: 0.1,
            reward: 300
        }
    ];
    var r = Math.random() * 100;
    var acc = 0;
    for (var i = 0; i < table.length; i++) {
        acc += table[i].pct;
        if (r < acc) {
            //  개수 + 확률 같이 반환
            return {
                reward: table[i].reward,
                pct: table[i].pct
            };
        }
    }
    return {
        reward: table[0].reward,
        pct: table[0].pct
    };
}
// 미니펫강화수치 표기
/**"miniPet": {
 "name": "별이",
 "emoji": "🦔",
 "grade": "일반",
 "price": 30000000,
 "battleExp": 1000,
 "castleExp": 1000,
 "raidExp": 1000
 }*/
function getMiniPetUpgradeDisplay(miniPetObj) {
    if (!miniPetObj) return "";
    if (isElite(miniPetObj) && miniPetObj.upgrade == ELITE_MINIPET_MAX_LV) {
        return "MAX";
    } else if (!isElite(miniPetObj) && miniPetObj.upgrade == MINIPET_MAX_LV) {
        return "MAX";
    } else {
        return miniPetObj.upgrade ? "+" + miniPetObj.upgrade : "";
    }
}

function getMiniPetUpgradeMaxLevel(mini) {
    return isElite(mini) ? ELITE_MINIPET_MAX_LV : MINIPET_MAX_LV;
}

function getMiniPetCollectionAutoUpgradePlan(user, mini, targetStage) {
    var currentUpgrade = parseInt((mini && mini.upgrade) || 0, 10);
    var maxLevel = getMiniPetUpgradeMaxLevel(mini);
    var plan = {
        canTry: false,
        needPoint: 0,
        needStone: 0,
        failReason: null
    };

    if (!mini) {
        plan.failReason = "미니펫 정보가 없습니다.";
        return plan;
    }

    if (currentUpgrade >= targetStage) {
        plan.canTry = true;
        return plan;
    }

    if (targetStage > maxLevel) {
        plan.failReason = "최대 강화 수치를 초과하여 등록할 수 없습니다.";
        return plan;
    }

    for (var lv = currentUpgrade + 1; lv <= targetStage; lv++) {
        plan.needPoint += parseInt(MINI_COST[lv] || 0, 10);
        plan.needStone += lv;
    }

    var stoneOwned = parseInt((user && user.bag && user.bag["미니펫 강화석💫"]) || 0, 10);
    var pointOwned = parseInt((user && user.point) || 0, 10);

    if (stoneOwned < plan.needStone) {
        plan.failReason = "미니펫 강화석이 부족합니다.";
        return plan;
    }

    if (pointOwned < plan.needPoint) {
        plan.failReason = "포인트가 부족합니다.";
        return plan;
    }

    plan.canTry = true;
    return plan;
}

function tryAutoUpgradeMiniPetForCollection(data, petData, petSkillData, sender, mini, targetStage) {
    var user = data.member[sender];
    var result = {
        success: false,
        upgraded: false,
        startUpgrade: parseInt((mini && mini.upgrade) || 0, 10),
        endUpgrade: parseInt((mini && mini.upgrade) || 0, 10),
        spentPoint: 0,
        spentStone: 0,
        boostUsage: {},
        failReason: null
    };

    if (!user || !mini) {
        result.failReason = "미니펫 정보가 없어 등록되지 않았습니다.";
        return result;
    }

    var maxLevel = getMiniPetUpgradeMaxLevel(mini);
    if (targetStage > maxLevel) {
        result.failReason = "최대 강화 수치를 초과하여 등록되지 않았습니다.";
        return result;
    }

    var attemptCount = 0;
    while (parseInt(mini.upgrade || 0, 10) < targetStage) {
        attemptCount++;
        if (attemptCount > 50000) {
            result.failReason = "자동 강화 시도 횟수가 너무 많아 등록이 중단되었습니다.";
            result.endUpgrade = parseInt(mini.upgrade || 0, 10);
            return result;
        }

        var curLv = parseInt(mini.upgrade || 0, 10);
        var nextLv = curLv + 1;
        var needStone = nextLv;
        var needPoint = parseInt(MINI_COST[nextLv] || 0, 10);
        var stoneOwned = parseInt(user.bag["미니펫 강화석💫"] || 0, 10);
        var pointOwned = parseInt(user.point || 0, 10);

        if (stoneOwned < needStone) {
            result.failReason = "미니펫 강화석이 부족하여 등록되지 않았습니다.";
            result.endUpgrade = curLv;
            return result;
        }

        if (pointOwned < needPoint) {
            result.failReason = "포인트가 부족하여 자동 강화 및 등록에 실패했습니다.";
            result.endUpgrade = curLv;
            return result;
        }

        var traitPct = hasPetSkill(petSkillData, sender, "개통령") ? 10 : 0;
        var traitAdd = traitPct / 100;
        var baseProb = parseFloat(MINI_PROB[nextLv] || 0);
        var boostEligible = baseProb + traitAdd < 1.0;
        var boost = boostEligible ? findBestMiniBoostItem(user.bag) : null;
        var boostAdd = boost ? boost.addPct / 100 : 0;
        var currentProb = baseProb + traitAdd + boostAdd;
        if (currentProb > 1) currentProb = 1;

        addPoint(data, sender, -needPoint);
        removeItem(data, sender, "미니펫 강화석💫", needStone);
        result.spentPoint += needPoint;
        result.spentStone += needStone;

        if (boost) {
            removeItem(data, sender, boost.name, 1);
            result.boostUsage[boost.name] = (result.boostUsage[boost.name] || 0) + 1;
        }

        if (Math.random() < currentProb) {
            var gain = getCharmGainFor(mini, nextLv) || 0;
            mini.upgrade = nextLv;
            mini.battleExp = (Number(mini.battleExp) || 0) + gain;
            mini.castleExp = (Number(mini.castleExp) || 0) + gain;
            mini.raidExp = (Number(mini.raidExp) || 0) + gain;
            result.upgraded = true;
        }
    }

    result.success = true;
    result.endUpgrade = parseInt(mini.upgrade || 0, 10);
    return result;
}
function refreshMiniPetSortIndex(petData, owner, gradeTable) {
    if (!petData[owner] || !Array.isArray(petData[owner].miniPetBag)) return;
    let bag = petData[owner].miniPetBag;
    // 정렬
    sortMiniPetBag(bag, gradeTable);
    // 번호 다시 부여
    for (let i = 0; i < bag.length; i++) {
        bag[i].sortIndex = i + 1;
    }
}
// 펫홈 데이터 생성 가능 회원인지 확인하는 함수
function isRegisteredHomeMember(data, user) {
    return !!(data && data.member && data.member[user]);
}

// 펫홈 댓글 저장소 기본 구조를 보장하는 함수
function initPetHomeCommentsData(commentsData) {
    if (!commentsData || typeof commentsData !== "object") commentsData = {};
    if (!commentsData.comments || typeof commentsData.comments !== "object") commentsData.comments = {};
    if (!commentsData.pinnedComments || typeof commentsData.pinnedComments !== "object") commentsData.pinnedComments = {};
    for (var owner in commentsData.comments) {
        if (Object.prototype.hasOwnProperty.call(commentsData.comments, owner)) trimPetHomeComments(commentsData.comments[owner], commentsData.pinnedComments[owner] || []);
    }
    return commentsData;
}

// 펫홈 활동 파일의 필수 구조를 검증하는 함수
function requirePetHomeActivityData(activityData) {
    if (!activityData || typeof activityData !== "object" || activityData instanceof Array) {
        throw new Error("Invalid pet home activity data");
    }
    if (!activityData.alerts || typeof activityData.alerts !== "object" || activityData.alerts instanceof Array) {
        throw new Error("Invalid pet home alerts data");
    }
    if (!activityData.recentVisitors || typeof activityData.recentVisitors !== "object" || activityData.recentVisitors instanceof Array) {
        throw new Error("Invalid pet home recent visitors data");
    }
    for (var alertOwner in activityData.alerts) {
        if (!activityData.alerts.hasOwnProperty(alertOwner)) continue;
        var ownerAlerts = activityData.alerts[alertOwner];
        if (!(ownerAlerts instanceof Array) || ownerAlerts.length > GLOBAL_CONFIG.petHomeActivity.maxAlerts) {
            throw new Error("Invalid pet home alert list: " + alertOwner);
        }
        for (var alertIndex = 0; alertIndex < ownerAlerts.length; alertIndex++) {
            var storedAlert = ownerAlerts[alertIndex];
            if (!storedAlert || typeof storedAlert !== "object" || storedAlert instanceof Array ||
                typeof storedAlert.type !== "string" || typeof storedAlert.actorId !== "string" ||
                typeof storedAlert.createdAt !== "string" || typeof storedAlert.read !== "boolean" ||
                (storedAlert.commentPreview !== undefined && typeof storedAlert.commentPreview !== "string") ||
                (storedAlert.badgeId !== undefined && typeof storedAlert.badgeId !== "string") ||
                (storedAlert.actorName !== undefined && typeof storedAlert.actorName !== "string") ||
                (storedAlert.feedId !== undefined && typeof storedAlert.feedId !== "string") ||
                (storedAlert.feedContent !== undefined && typeof storedAlert.feedContent !== "string") ||
                (storedAlert.type === "feed" && (typeof storedAlert.feedId !== "string" || !storedAlert.feedId || typeof storedAlert.feedContent !== "string" || !storedAlert.feedContent)) ||
                (storedAlert.mutual !== undefined && typeof storedAlert.mutual !== "boolean") ||
                (storedAlert.count !== undefined && (typeof storedAlert.count !== "number" || storedAlert.count <= 0))) {
                throw new Error("Invalid pet home alert entry: " + alertOwner);
            }
        }
    }
    for (var visitorOwner in activityData.recentVisitors) {
        if (!activityData.recentVisitors.hasOwnProperty(visitorOwner)) continue;
        var ownerVisitors = activityData.recentVisitors[visitorOwner];
        if (!(ownerVisitors instanceof Array) || ownerVisitors.length > GLOBAL_CONFIG.petHomeActivity.maxRecentVisitors) {
            throw new Error("Invalid pet home recent visitor list: " + visitorOwner);
        }
        for (var visitorIndex = 0; visitorIndex < ownerVisitors.length; visitorIndex++) {
            var storedVisitor = ownerVisitors[visitorIndex];
            if (!storedVisitor || typeof storedVisitor !== "object" || storedVisitor instanceof Array ||
                typeof storedVisitor.visitorId !== "string" || typeof storedVisitor.visitedAt !== "string") {
                throw new Error("Invalid pet home recent visitor entry: " + visitorOwner);
            }
        }
    }
    if (activityData.petHomeSocial === undefined) activityData.petHomeSocial = {};
    if (!activityData.petHomeSocial || typeof activityData.petHomeSocial !== "object" || activityData.petHomeSocial instanceof Array) {
        throw new Error("Invalid pet home social data");
    }
    for (var socialOwner in activityData.petHomeSocial) {
        if (!activityData.petHomeSocial.hasOwnProperty(socialOwner)) continue;
        validatePetHomeSocialUser(activityData.petHomeSocial[socialOwner], socialOwner);
    }
    if (activityData.migrations === undefined) activityData.migrations = {};
    if (!activityData.migrations || typeof activityData.migrations !== "object" || activityData.migrations instanceof Array) {
        throw new Error("Invalid pet home activity migrations");
    }
    return activityData;
}

// 펫홈 대표·보조 뱃지 슬롯을 기존 단일 필드와 호환되게 정규화하는 함수
function normalizePetHomeEquippedBadgeIds(social) {
    var ids;
    if (social.equippedBadgeIds === undefined) {
        ids = [social.equippedBadgeId || null, null];
    } else {
        if (!(social.equippedBadgeIds instanceof Array) || social.equippedBadgeIds.length !== 2) throw new Error("Invalid pet home equipped badge slots");
        ids = [social.equippedBadgeIds[0] || null, social.equippedBadgeIds[1] || null];
    }
    for (var i = 0; i < ids.length; i++) {
        if (ids[i] !== null && typeof ids[i] !== "string") throw new Error("Invalid pet home equipped badge slot");
    }
    if (ids[0] && ids[0] === ids[1]) ids[1] = null;
    if (!ids[0] && ids[1]) {
        ids[0] = ids[1];
        ids[1] = null;
    }
    social.equippedBadgeIds = ids;
    social.equippedBadgeId = ids[0]; // 기존 대표 뱃지 소비자용 호환 필드
    return ids;
}

// 펫홈 소셜 유저 데이터의 저장 구조를 검증하는 함수
function validatePetHomeSocialUser(social, user) {
    if (!social || typeof social !== "object" || social instanceof Array) throw new Error("Invalid pet home social user: " + user);
    if (!(social.followers instanceof Array) || !(social.following instanceof Array) ||
        !(social.badges instanceof Array) || !(social.deletedBadgeIds instanceof Array) ||
        !(social.specialBadgeLogs instanceof Array)) {
        throw new Error("Invalid pet home social lists: " + user);
    }
    var stringLists = [social.followers, social.following, social.badges, social.deletedBadgeIds];
    for (var listIndex = 0; listIndex < stringLists.length; listIndex++) {
        for (var itemIndex = 0; itemIndex < stringLists[listIndex].length; itemIndex++) {
            if (typeof stringLists[listIndex][itemIndex] !== "string") throw new Error("Invalid pet home social list entry: " + user);
        }
    }
    if (!social.heartUsage || typeof social.heartUsage !== "object" || social.heartUsage instanceof Array ||
        typeof social.heartUsage.date !== "string" || typeof social.heartUsage.count !== "number" || social.heartUsage.count < 0) {
        throw new Error("Invalid pet home heart usage: " + user);
    }
    if (!social.badgeStats || typeof social.badgeStats !== "object" || social.badgeStats instanceof Array) {
        throw new Error("Invalid pet home badge stats: " + user);
    }
    if (social.feedActivityDates === undefined) social.feedActivityDates = [];
    if (!(social.feedActivityDates instanceof Array)) throw new Error("Invalid pet home feed activity dates: " + user);
    var feedActivityDateMap = {};
    for (var feedDateIndex = 0; feedDateIndex < social.feedActivityDates.length; feedDateIndex++) {
        var feedActivityDate = social.feedActivityDates[feedDateIndex];
        if (typeof feedActivityDate !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(feedActivityDate) || feedActivityDateMap.hasOwnProperty(feedActivityDate)) {
            throw new Error("Invalid pet home feed activity date: " + user);
        }
        feedActivityDateMap[feedActivityDate] = true;
    }
    var statKeys = ["receivedComments", "receivedHomeLikes", "receivedReactions", "totalVisits"];
    for (var i = 0; i < statKeys.length; i++) {
        var value = social.badgeStats[statKeys[i]];
        if (typeof value !== "number" || value < 0) throw new Error("Invalid pet home badge stat: " + user + "/" + statKeys[i]);
    }
    var equippedBadgeIds = normalizePetHomeEquippedBadgeIds(social);
    if (social.equippedBadgeId !== null && typeof social.equippedBadgeId !== "string") {
        throw new Error("Invalid pet home equipped badge: " + user);
    }
    if (!(equippedBadgeIds instanceof Array) || equippedBadgeIds.length !== 2) throw new Error("Invalid pet home equipped badge slots: " + user);
    for (var logIndex = 0; logIndex < social.specialBadgeLogs.length; logIndex++) {
        var log = social.specialBadgeLogs[logIndex];
        if (!log || typeof log !== "object" || typeof log.badgeId !== "string" || typeof log.action !== "string" ||
            typeof log.adminId !== "string" || typeof log.createdAt !== "string") {
            throw new Error("Invalid pet home special badge log: " + user);
        }
    }
}

// 새 펫홈 소셜 유저의 기본 구조를 생성하는 함수
function createPetHomeSocialUser() {
    return {
        followers: [],
        following: [],
        badges: [],
        deletedBadgeIds: [],
        equippedBadgeId: null,
        equippedBadgeIds: [null, null],
        heartUsage: { date: "", count: 0 },
        feedActivityDates: [],
        badgeStats: {
            receivedComments: 0,
            receivedHomeLikes: 0,
            receivedReactions: 0,
            totalVisits: 0
        },
        specialBadgeLogs: []
    };
}

// 특정 유저의 펫홈 소셜 데이터를 반환하고 없으면 초기화하는 함수
function getPetHomeSocialUser(activityData, user) {
    if (!activityData || typeof activityData !== "object" || !activityData.petHomeSocial ||
        typeof activityData.petHomeSocial !== "object" || activityData.petHomeSocial instanceof Array) {
        throw new Error("Invalid pet home social data");
    }
    if (!activityData.petHomeSocial.hasOwnProperty(user)) activityData.petHomeSocial[user] = createPetHomeSocialUser();
    return activityData.petHomeSocial[user];
}

// 유저의 대표·보조 홈뱃지 슬롯을 보유 상태에 맞춰 반환하는 함수
function getPetHomeEquippedBadgeIds(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var ids = normalizePetHomeEquippedBadgeIds(social);
    for (var i = 0; i < ids.length; i++) {
        if (ids[i] && !petHomeStringListContains(social.badges, ids[i])) ids[i] = null;
    }
    return normalizePetHomeEquippedBadgeIds(social).slice(0);
}

// 유저의 대표·보조 홈뱃지 슬롯을 저장하고 기존 대표 필드를 동기화하는 함수
function setPetHomeEquippedBadgeIds(social, badgeIds) {
    social.equippedBadgeIds = [badgeIds && badgeIds[0] ? badgeIds[0] : null, badgeIds && badgeIds[1] ? badgeIds[1] : null];
    return normalizePetHomeEquippedBadgeIds(social);
}

// 문자열 배열에 값이 있는지 확인하는 함수
function petHomeStringListContains(list, value) {
    return list instanceof Array && list.indexOf(value) !== -1;
}

// 문자열 배열에 중복 없이 값을 추가하는 함수
function addPetHomeStringListValue(list, value) {
    if (!petHomeStringListContains(list, value)) list.push(value);
}

// 문자열 배열에서 일치하는 값을 모두 제거하는 함수
function removePetHomeStringListValue(list, value) {
    var removed = false;
    for (var i = list.length - 1; i >= 0; i--) {
        if (list[i] === value) {
            list.splice(i, 1);
            removed = true;
        }
    }
    return removed;
}

// 전체 펫홈 뱃지 설정을 고정 순서로 반환하는 함수
function getAllPetHomeBadges() {
    return GLOBAL_CONFIG.petHomeActivity.achievementBadges
        .concat(GLOBAL_CONFIG.petHomeActivity.specialBadges)
        .concat(GLOBAL_CONFIG.petHomeActivity.gachaBadges)
        .concat(GLOBAL_CONFIG.petHomeActivity.gacha2.badges)
        .concat(GLOBAL_CONFIG.petHomeActivity.gacha3.badges);
}

// 등급 확률과 등급 내 균등 확률로 홈뱃지 한 종을 추첨하는 함수
function drawPetHomeGachaBadge() {
    var rates = GLOBAL_CONFIG.petHomeActivity.gachaGradeRates;
    var roll = Math.random() * 100;
    var cumulativeRate = 0;
    var selectedGrade = rates[rates.length - 1].grade;
    for (var rateIndex = 0; rateIndex < rates.length; rateIndex++) {
        cumulativeRate += rates[rateIndex].rate;
        if (roll < cumulativeRate) {
            selectedGrade = rates[rateIndex].grade;
            break;
        }
    }
    var gradeBadges = [];
    var badges = GLOBAL_CONFIG.petHomeActivity.gachaBadges;
    for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
        if (badges[badgeIndex].grade === selectedGrade) gradeBadges.push(badges[badgeIndex]);
    }
    return gradeBadges[Math.floor(Math.random() * gradeBadges.length)];
}

// 유저가 보유한 홈뱃지 뽑기 전용 뱃지 수를 반환하는 함수
function getOwnedPetHomeGachaBadgeCount(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var badges = GLOBAL_CONFIG.petHomeActivity.gachaBadges;
    var ownedCount = 0;
    for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
        if (petHomeStringListContains(social.badges, badges[badgeIndex].id)) ownedCount++;
    }
    return ownedCount;
}

// MBTI 홈뱃지뽑기[2]에서 20종 중 한 종을 균등 추첨하는 함수
function drawPetHomeGacha2Badge() {
    var badges = GLOBAL_CONFIG.petHomeActivity.gacha2.badges;
    return badges[Math.floor(Math.random() * badges.length)];
}

// 유저가 보유한 MBTI 홈뱃지뽑기[2] 뱃지 수를 반환하는 함수
function getOwnedPetHomeGacha2BadgeCount(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var badges = GLOBAL_CONFIG.petHomeActivity.gacha2.badges;
    var ownedCount = 0;
    for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
        if (petHomeStringListContains(social.badges, badges[badgeIndex].id)) ownedCount++;
    }
    return ownedCount;
}

// 연애유형 홈뱃지뽑기[3]에서 50종 중 한 종을 균등 추첨하는 함수
function drawPetHomeGacha3Badge() {
    var badges = GLOBAL_CONFIG.petHomeActivity.gacha3.badges;
    return badges[Math.floor(Math.random() * badges.length)];
}

// 유저가 보유한 연애유형 홈뱃지뽑기[3] 뱃지 수를 반환하는 함수
function getOwnedPetHomeGacha3BadgeCount(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var badges = GLOBAL_CONFIG.petHomeActivity.gacha3.badges;
    var ownedCount = 0;
    for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
        if (petHomeStringListContains(social.badges, badges[badgeIndex].id)) ownedCount++;
    }
    return ownedCount;
}

// 회원 데이터의 홈뱃지 큐브 저장소를 검증하고 반환하는 함수
function getHomeBadgeCubeStore(data, user, createIfMissing) {
    var member = data && data.member ? data.member[user] : null;
    if (!member) return null;
    if (member.homeBadgeCube === undefined) {
        if (!createIfMissing) return null;
        member.homeBadgeCube = { equippedBadgeId: null, equippedBadgeIds: [null, null], badges: {} };
    }
    if (!member.homeBadgeCube || typeof member.homeBadgeCube !== "object" || member.homeBadgeCube instanceof Array) throw new Error("Invalid home badge cube store");
    if (member.homeBadgeCube.badges === undefined) {
        if (!createIfMissing) return null;
        member.homeBadgeCube.badges = {};
    }
    if (!member.homeBadgeCube.badges || typeof member.homeBadgeCube.badges !== "object" || member.homeBadgeCube.badges instanceof Array) throw new Error("Invalid home badge cube badge store");
    normalizeHomeBadgeCubeEquippedBadgeIds(member.homeBadgeCube);
    return member.homeBadgeCube;
}

// 회원 데이터의 대표·보조 홈뱃지 큐브 슬롯을 기존 단일 필드와 호환되게 정규화하는 함수
function normalizeHomeBadgeCubeEquippedBadgeIds(store) {
    var ids;
    if (store.equippedBadgeIds === undefined) {
        ids = [store.equippedBadgeId || null, null];
    } else {
        if (!(store.equippedBadgeIds instanceof Array) || store.equippedBadgeIds.length !== 2) throw new Error("Invalid home badge cube equipped slots");
        ids = [store.equippedBadgeIds[0] || null, store.equippedBadgeIds[1] || null];
    }
    for (var i = 0; i < ids.length; i++) {
        if (ids[i] !== null && typeof ids[i] !== "string") throw new Error("Invalid home badge cube equipped slot");
    }
    if (ids[0] && ids[0] === ids[1]) ids[1] = null;
    if (!ids[0] && ids[1]) {
        ids[0] = ids[1];
        ids[1] = null;
    }
    store.equippedBadgeIds = ids;
    store.equippedBadgeId = ids[0]; // 기존 대표 뱃지 소비자용 호환 필드
    return ids;
}

// 홈뱃지 한 종의 큐브 옵션 기록을 검증하고 반환하는 함수
function getHomeBadgeCubeRecord(data, user, badgeId, createIfMissing) {
    var store = getHomeBadgeCubeStore(data, user, createIfMissing);
    if (!store) return null;
    var record = store.badges[badgeId];
    if (record === undefined) {
        if (!createIfMissing) return null;
        record = { castle: 0, raid: 0, petUpgrade: 0, explore: 0, notified10: {}, allMaxNotified: false };
        store.badges[badgeId] = record;
    }
    if (!record || typeof record !== "object" || record instanceof Array) throw new Error("Invalid home badge cube record");
    var optionKeys = GLOBAL_CONFIG.petHomeActivity.cube.optionKeys;
    for (var i = 0; i < optionKeys.length; i++) {
        var optionValue = parseFloat(record[optionKeys[i]]);
        var optionConfig = getHomeBadgeCubeOptionConfig(i + 1);
        if (isNaN(optionValue) || optionValue < 0) optionValue = 0;
        if (optionConfig && optionValue > optionConfig.max) optionValue = optionConfig.max;
        if (createIfMissing) record[optionKeys[i]] = Math.round(optionValue * 10) / 10;
    }
    if (createIfMissing && (!record.notified10 || typeof record.notified10 !== "object" || record.notified10 instanceof Array)) record.notified10 = {};
    if (createIfMissing) record.allMaxNotified = record.allMaxNotified === true;
    return record;
}

// 번호로 홈뱃지 큐브 옵션 설정을 찾는 함수
function getHomeBadgeCubeOptionConfig(optionNumber) {
    var options = GLOBAL_CONFIG.petHomeActivity.cube.options;
    for (var i = 0; i < options.length; i++) {
        if (options[i].number === optionNumber) return options[i];
    }
    return null;
}

// 홈뱃지 큐브 옵션 수치를 소수점 한 자리로 표시하는 함수
function formatHomeBadgeCubePercent(value) {
    return (parseFloat(value) || 0).toFixed(1) + "%";
}

// 홈뱃지 카드의 큐브 옵션 수치를 불필요한 소수점 없이 표시하는 함수
function formatHomeBadgeCubeCardPercent(value) {
    return (parseFloat(value) || 0).toFixed(1).replace(/\.0$/, "") + "%";
}

// 홈뱃지의 네 옵션이 모두 최대 수치인지 확인하는 함수
function isHomeBadgeCubeAllMax(record) {
    if (!record) return false;
    var options = GLOBAL_CONFIG.petHomeActivity.cube.options;
    for (var i = 0; i < options.length; i++) {
        if ((parseFloat(record[options[i].key]) || 0) !== options[i].max) return false;
    }
    return true;
}

// 홈뱃지 네 옵션 기본 수치 합계가 100% 이상인지 확인하는 함수
function isHomeBadgeCubeTotalBuffActive(record) {
    if (!record) return false;
    var optionKeys = GLOBAL_CONFIG.petHomeActivity.cube.optionKeys;
    var total = 0;
    for (var i = 0; i < optionKeys.length; i++) total += parseFloat(record[optionKeys[i]]) || 0;
    return total >= 100;
}

// 홈뱃지 슬롯과 옵션 종류에 따라 실제 효과 적용 여부를 반환하는 함수
function isHomeBadgeCubeOptionAppliedInSlot(slotIndex, optionKey) {
    return slotIndex === 0 || optionKey === "castle" || optionKey === "raid";
}

// 장착 홈뱃지 한 슬롯의 실제 적용 옵션 수치를 반환하는 함수
function getHomeBadgeCubeSlotOptionPercent(data, user, slotIndex, optionKey) {
    var store = getHomeBadgeCubeStore(data, user, false);
    if (!store || !isHomeBadgeCubeOptionAppliedInSlot(slotIndex, optionKey)) return 0;
    var equippedBadgeIds = normalizeHomeBadgeCubeEquippedBadgeIds(store);
    var badgeId = equippedBadgeIds[slotIndex];
    if (!badgeId) return 0;
    var record = getHomeBadgeCubeRecord(data, user, badgeId, false);
    var value = record ? (parseFloat(record[optionKey]) || 0) : 0;
    var appliedValue = record && isHomeBadgeCubeTotalBuffActive(record) ? Math.round(value * 11) / 10 : value;
    if (isHoiPassPremiumActive(data, user)) appliedValue += GLOBAL_CONFIG.supportPass.premium.cubeOptionBonusPercent;
    return appliedValue;
}

// 대표·보조 홈뱃지의 실제 적용 옵션 합계를 반환하는 함수
function getHomeBadgeCubeActiveOptionPercent(data, user, optionKey) {
    var total = getHomeBadgeCubeSlotOptionPercent(data, user, 0, optionKey);
    if (optionKey === "castle" || optionKey === "raid") total += getHomeBadgeCubeSlotOptionPercent(data, user, 1, optionKey);
    return total;
}

// 홈뱃지 큐브 효과를 반영한 유효 펫 강화수치를 반올림해 계산하는 함수
function calculateEffectivePetUpgradeLevel(user, data, petData, excludeHomeBadgeCube) {
    var baseLevel = petData && petData[user] ? (parseInt(petData[user].upgrade, 10) || 0) : 0;
    var cubePercent = excludeHomeBadgeCube === true ? 0 : getHomeBadgeCubeActiveOptionPercent(data, user, "petUpgrade");
    return Math.round(baseLevel * (1 + cubePercent / 100));
}

// 유효 펫 강화수치가 종합매력에 더하는 값을 계산하는 함수
function calculatePetUpgradeCharm(user, data, petData, excludeHomeBadgeCube) {
    return calculateEffectivePetUpgradeLevel(user, data, petData, excludeHomeBadgeCube) * GLOBAL_CONFIG.pet.totalCharmPerUpgrade;
}

// 홈뱃지 큐브 장착 전후 효과를 디버깅용 비교 문구로 생성하는 함수
function buildHomeBadgeCubeDebugMessage(data, petData, homeData, petSkillData, petExploreData, user, guildData) {
    var castleBefore = calculateCastleExp(user, data, petData, homeData, petSkillData, true, guildData);
    var castleAfter = calculateCastleExp(user, data, petData, homeData, petSkillData, false, guildData);
    var raidBefore = calculateRaidExp(user, data, petData, homeData, petSkillData, true, guildData);
    var raidAfter = calculateRaidExp(user, data, petData, homeData, petSkillData, false, guildData);
    var upgradeBefore = calculateEffectivePetUpgradeLevel(user, data, petData, true);
    var upgradeAfter = calculateEffectivePetUpgradeLevel(user, data, petData);
    var castleRate = castleBefore > 0 ? (castleAfter - castleBefore) / castleBefore * 100 : 0;
    var raidRate = raidBefore > 0 ? (raidAfter - raidBefore) / raidBefore * 100 : 0;
    var upgradeRate = upgradeBefore > 0 ? (upgradeAfter - upgradeBefore) / upgradeBefore * 100 : 0;
    var lines = ["[💟 홈뱃지 큐브 장착 디버깅]", "대상: " + user, "━━━━━━━━━━━━━━━"];
    lines.push("실제 적용 옵션: ⚔️+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "castle")) + " / 👾+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "raid")) + " / 🌟+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "petUpgrade")) + " / ⛰️+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "explore")));
    lines.push("캐슬 매력: " + numberWithCommas(castleBefore) + " → " + numberWithCommas(castleAfter) + " (기존 대비 +" + castleRate.toFixed(2) + "%)");
    lines.push("레이드 매력: " + numberWithCommas(raidBefore) + " → " + numberWithCommas(raidAfter) + " (기존 대비 +" + raidRate.toFixed(2) + "%)");
    lines.push("펫강화 수치: " + upgradeBefore + "강 → " + upgradeAfter + "강 (기존 대비 +" + upgradeRate.toFixed(2) + "%)");

    var exploreDungeon = petExploreData && petExploreData.userBet && petExploreData.userBet[user] !== null && typeof petExploreData.userBet[user] !== "undefined" ? String(petExploreData.userBet[user]) : null;
    var exploreCube = getHomeBadgeCubeActiveOptionPercent(data, user, "explore");
    if (exploreDungeon !== null) {
        var explorePercent = calcExploreSuccessPercent(data, petData, homeData, petSkillData, user, exploreDungeon, guildData);
        var exploreRate = explorePercent.totalPBeforeHomeBadge > 0 ? (explorePercent.totalP - explorePercent.totalPBeforeHomeBadge) / explorePercent.totalPBeforeHomeBadge * 100 : 0;
        lines.push("펫탐험 확률[" + exploreDungeon + "]: " + explorePercent.totalPBeforeHomeBadge.toFixed(2) + "% → " + explorePercent.totalP.toFixed(2) + "% (+" + (explorePercent.totalP - explorePercent.totalPBeforeHomeBadge).toFixed(2) + "%p, 기존 대비 +" + exploreRate.toFixed(2) + "%)");
    } else {
        lines.push("펫탐험 확률: 현재 참여 던전 없음 (장착 효과 +" + exploreCube.toFixed(1) + "%p, 상한 적용 전)");
    }
    return lines.join("\n");
}

// 홈뱃지 옵션의 기본값·합계 버프·프리미엄 보너스·실제 적용값을 디버깅용으로 반환하는 함수
function getHomeBadgeCubeOptionDebugDetail(data, user, optionKey) {
    var store = getHomeBadgeCubeStore(data, user, false);
    var equippedBadgeIds = store ? normalizeHomeBadgeCubeEquippedBadgeIds(store).slice(0) : [null, null];
    var basePercent = 0;
    var totalBuffAppliedPercent = 0;
    var totalBuffActive = false;
    var appliedSlotCount = optionKey === "castle" || optionKey === "raid" ? 2 : 1;
    var activeBadgeCount = 0; // 해당 옵션에 실제 반영되는 장착 뱃지 수
    for (var slotIndex = 0; slotIndex < appliedSlotCount; slotIndex++) {
        var badgeId = equippedBadgeIds[slotIndex];
        if (!badgeId) continue;
        var record = getHomeBadgeCubeRecord(data, user, badgeId, false);
        var slotBasePercent = record ? (parseFloat(record[optionKey]) || 0) : 0;
        var slotBuffActive = !!(record && isHomeBadgeCubeTotalBuffActive(record));
        basePercent += slotBasePercent;
        totalBuffAppliedPercent += slotBuffActive ? Math.round(slotBasePercent * 11) / 10 : slotBasePercent;
        if (slotBuffActive) totalBuffActive = true;
        activeBadgeCount++;
    }
    var premiumBonusPercent = isHoiPassPremiumActive(data, user) ? activeBadgeCount * GLOBAL_CONFIG.supportPass.premium.cubeOptionBonusPercent : 0;
    return {
        equippedBadgeId: equippedBadgeIds[0],
        equippedBadgeIds: equippedBadgeIds,
        basePercent: basePercent,
        totalBuffActive: totalBuffActive,
        totalBuffAppliedPercent: totalBuffAppliedPercent,
        premiumBonusPercent: premiumBonusPercent,
        appliedPercent: getHomeBadgeCubeActiveOptionPercent(data, user, optionKey)
    };
}

// 홈뱃지 옵션의 단계별 적용 수식을 디버깅 문구로 반환하는 함수
function formatHomeBadgeCubeDebugOptionFormula(detail) {
    var text = "+" + formatHomeBadgeCubeCardPercent(detail.basePercent);
    if (detail.totalBuffActive) text += " → +" + formatHomeBadgeCubeCardPercent(detail.totalBuffAppliedPercent) + "(기본합계 100% ×1.1)";
    if (detail.premiumBonusPercent > 0) text += " +" + formatHomeBadgeCubeCardPercent(detail.premiumBonusPercent) + "👑";
    return text + " = +" + formatHomeBadgeCubeCardPercent(detail.appliedPercent);
}

// 현재 매력 구성과 콘텐츠별 실시간·스냅샷 적용값을 디버깅 메시지로 생성하는 함수
function buildCharmBuffDebugMessage(data, petData, homeData, petSkillData, guildData, user) {
    var pet = petData && petData[user] ? petData[user] : {};
    var miniPet = pet.miniPet || {};
    var rawHomeExp = getHomeTotalExp(homeData, user) || 0;
    var appliedHomeExp = hasPetSkill(petSkillData, user, "인테리어 장인") ? Math.floor(rawHomeExp * 1.1) : rawHomeExp;
    var castleHomeDetail = getHomeBadgeCubeOptionDebugDetail(data, user, "castle");
    var raidHomeDetail = getHomeBadgeCubeOptionDebugDetail(data, user, "raid");
    var upgradeHomeDetail = getHomeBadgeCubeOptionDebugDetail(data, user, "petUpgrade");
    var guildCastlePercent = getGuildContributionCubeMemberPercent(data, guildData, user, "castle");
    var guildRaidPercent = getGuildContributionCubeMemberPercent(data, guildData, user, "raid");
    var adventureLevelPercent = getAdventureLevelCharmPercent(data && data.member && data.member[user] ? data.member[user].lv : 1); // 모험가 레벨의 캐슬·레이드 공통 보너스
    var charmDetail = buildTotalExpTimeCheckDetail(user, data, petData, homeData, petSkillData, guildData); // 퍼센트 적용 전 실제 구성 합계와 상세 항목
    var castleBase = charmDetail.castleBase; // 레벨·퀘스트·큐브 적용 전 캐슬매력 원본
    var raidBase = charmDetail.raidBase; // 레벨·퀘스트·큐브 적용 전 레이드매력 원본
    var questTotals = data && data.member && data.member[user] && data.member[user].adventureQuest ? data.member[user].adventureQuest.totals : null;
    var castleQuestPercent = questTotals ? Number(questTotals.castlePercent) || 0 : 0;
    var raidQuestPercent = questTotals ? Number(questTotals.raidPercent) || 0 : 0;
    var castleTotalPercent = adventureLevelPercent + castleHomeDetail.appliedPercent + guildCastlePercent + castleQuestPercent; // 캐슬의 모든 합산 퍼센트
    var raidTotalPercent = adventureLevelPercent + raidHomeDetail.appliedPercent + guildRaidPercent + raidQuestPercent; // 레이드의 모든 합산 퍼센트
    var expectedCastle = applyPercentWithExactFloor(castleBase, castleTotalPercent); // 표시 수식으로 재계산한 캐슬매력
    var expectedRaid = applyPercentWithExactFloor(raidBase, raidTotalPercent); // 표시 수식으로 재계산한 레이드매력
    var actualCastle = calculateCastleExp(user, data, petData, homeData, petSkillData, false, guildData);
    var actualRaid = calculateRaidExp(user, data, petData, homeData, petSkillData, false, guildData);
    var baseUpgradeLevel = parseInt(pet.upgrade, 10) || 0;
    var expectedUpgradeLevel = Math.round(baseUpgradeLevel * (1 + upgradeHomeDetail.appliedPercent / 100));
    var actualUpgradeLevel = calculateEffectivePetUpgradeLevel(user, data, petData);
    var upgradeCharm = calculatePetUpgradeCharm(user, data, petData);
    var expectedTotal = expectedCastle + expectedRaid + expectedUpgradeLevel * GLOBAL_CONFIG.pet.totalCharmPerUpgrade;
    var actualTotal = calculateTotalExp(user, data, petData, homeData, petSkillData, guildData);
    var premiumActive = isHoiPassPremiumActive(data, user);
    var lines = ["[🧪 매력 버프 적용 체크]", "대상: [" + checkRank(data, petData, guildData, user) + "] 님", "━━━━━━━━━━━━━━━"];

    lines.push("봇 버전: ver_" + HoiBotVersion);
    lines.push("호패프리미엄: " + (premiumActive ? "ON" : "OFF"));
    lines.push("대표 홈뱃지 ID: " + (castleHomeDetail.equippedBadgeIds[0] || "없음"));
    lines.push("보조 홈뱃지 ID: " + (castleHomeDetail.equippedBadgeIds[1] || "없음"));
    lines.push("프리미엄 홈뱃지 +" + GLOBAL_CONFIG.supportPass.premium.cubeOptionBonusPercent + "%p: " + (castleHomeDetail.premiumBonusPercent > 0 ? "적용 [✅]" : "미적용 [❌]"));
    lines.push("");
    lines.push("[기본 구성]");
    lines.push("펫 매력: " + numberWithCommas(pet.petexp || 0) + " (캐슬·레이드 각각 반영)");
    lines.push("미니펫: 캐슬 " + numberWithCommas(getMiniPetModeCharm(user, petData)) + " / 레이드 " + numberWithCommas(getMiniPetModeCharm(user, petData)));
    lines.push("가구: " + numberWithCommas(rawHomeExp) + (appliedHomeExp !== rawHomeExp ? " → " + numberWithCommas(appliedHomeExp) + " (인테리어 장인)" : ""));
    lines.push("평수 기본 추가: 캐슬·레이드 각각 +" + numberWithCommas(getPetHomeFloorCharm(homeData && homeData[user])) + " (인테리어·빌리지 적용 전)");
    lines.push("펫강화: " + baseUpgradeLevel + "강 → " + actualUpgradeLevel + "강 / 종합매력 +" + numberWithCommas(upgradeCharm));
    lines.push("");
    lines.push("[퍼센트 적용 전 상세]");
    for (var detailIndex = 0; detailIndex < charmDetail.rows.length; detailIndex++) {
        var detailRow = charmDetail.rows[detailIndex]; // 시간과 관계없이 출력할 기본 매력 구성 항목
        if (detailRow.label.indexOf("-최종합계") !== -1 || detailRow.label === "강화 보너스") continue;
        lines.push(detailRow.label + ": " + numberWithCommas(detailRow.value));
    }
    lines.push("");
    lines.push("[캐슬매력]");
    lines.push("기본 매력: " + numberWithCommas(castleBase));
    lines.push("모험가 레벨: +" + formatAdventureLevelPercent(adventureLevelPercent) + "%");
    lines.push("퀘스트: +" + formatAdventureQuestPercent(castleQuestPercent) + "%");
    lines.push("홈뱃지: " + formatHomeBadgeCubeDebugOptionFormula(castleHomeDetail));
    lines.push("길드큐브: +" + formatHomeBadgeCubeCardPercent(guildCastlePercent));
    lines.push("합산 버프: +" + formatAdventureQuestPercent(castleTotalPercent) + "%");
    lines.push("계산식: 내림(" + numberWithCommas(castleBase) + " × (1 + " + formatAdventureQuestPercent(castleTotalPercent) + " / 100))");
    lines.push("계산 검증: " + numberWithCommas(expectedCastle) + " / 공용함수 " + numberWithCommas(actualCastle) + (expectedCastle === actualCastle ? " [✅일치]" : " [❌불일치]"));
    lines.push("");
    lines.push("[레이드매력]");
    lines.push("기본 매력: " + numberWithCommas(raidBase));
    lines.push("모험가 레벨: +" + formatAdventureLevelPercent(adventureLevelPercent) + "%");
    lines.push("퀘스트: +" + formatAdventureQuestPercent(raidQuestPercent) + "%");
    lines.push("홈뱃지: " + formatHomeBadgeCubeDebugOptionFormula(raidHomeDetail));
    lines.push("길드큐브: +" + formatHomeBadgeCubeCardPercent(guildRaidPercent));
    lines.push("합산 버프: +" + formatAdventureQuestPercent(raidTotalPercent) + "%");
    lines.push("계산식: 내림(" + numberWithCommas(raidBase) + " × (1 + " + formatAdventureQuestPercent(raidTotalPercent) + " / 100))");
    lines.push("계산 검증: " + numberWithCommas(expectedRaid) + " / 공용함수 " + numberWithCommas(actualRaid) + (expectedRaid === actualRaid ? " [✅일치]" : " [❌불일치]"));
    lines.push("");
    lines.push("[종합매력]");
    lines.push("캐슬 " + numberWithCommas(actualCastle) + " + 레이드 " + numberWithCommas(actualRaid) + " + 펫강화 " + numberWithCommas(upgradeCharm));
    lines.push("계산 검증: " + numberWithCommas(expectedTotal) + " / 공용함수 " + numberWithCommas(actualTotal) + (expectedTotal === actualTotal && expectedUpgradeLevel === actualUpgradeLevel ? " [✅일치]" : " [❌불일치]"));
    lines.push("");
    lines.push("[콘텐츠 사용값]");
    lines.push("펫정보·종합순위·시련의탑: " + numberWithCommas(actualTotal) + " (현재값, 시련의탑 일시보정 전)");
    lines.push("캐슬대전: " + numberWithCommas(actualCastle) + " (현재값)");

    var matzangParticipant = data && data.matzangField && data.matzangField.participants ? data.matzangField.participants[user] : null;
    if (matzangParticipant && typeof matzangParticipant.totalExp === "number" && matzangParticipant.totalExp > 0) {
        var matzangDifference = matzangParticipant.totalExp - actualTotal; // 맞짱필드 참여 스냅샷과 현재 종합매력 차이
        lines.push("맞짱필드: " + numberWithCommas(matzangParticipant.totalExp) + " (참여 종합매력 스냅샷, 현재 대비 " + (matzangDifference >= 0 ? "+" : "") + numberWithCommas(matzangDifference) + ", " + (matzangParticipant.totalExpUpdatedAt || "시각 없음") + ", 치명타 강화는 현재 " + actualUpgradeLevel + "강)");
    } else {
        lines.push("맞짱필드: 참여 스냅샷 없음");
    }

    var territoryWar = guildData && guildData.territoryWar ? guildData.territoryWar : null;
    var territorySnapshot = territoryWar && territoryWar.castleExpSnapshots ? territoryWar.castleExpSnapshots[user] : null;
    if (typeof territorySnapshot === "number") {
        var territoryDifference = territorySnapshot - actualCastle; // 영지전 시작 스냅샷과 현재 캐슬매력 차이
        lines.push("길드영지전: " + numberWithCommas(territorySnapshot) + " (시작 캐슬·치명타 스냅샷, 현재 대비 " + (territoryDifference >= 0 ? "+" : "") + numberWithCommas(territoryDifference) + ", 전쟁 " + (territoryWar.active ? "진행 중" : "종료") + ")");
    } else {
        lines.push("길드영지전: 캐슬매력 스냅샷 없음");
    }
    return lines.join("\n");
}

// 대표·보조 홈뱃지 ID를 회원 데이터의 큐브 효과 대상과 동기화하는 함수
function syncHomeBadgeCubeEquippedBadges(data, user, badgeIds) {
    var store = getHomeBadgeCubeStore(data, user, true);
    store.equippedBadgeIds = [badgeIds && badgeIds[0] ? badgeIds[0] : null, badgeIds && badgeIds[1] ? badgeIds[1] : null];
    normalizeHomeBadgeCubeEquippedBadgeIds(store);
}

// 기존 단일 대표 홈뱃지 동기화 호출을 두 슬롯 구조로 연결하는 함수
function syncHomeBadgeCubeEquippedBadge(data, user, badgeId) {
    syncHomeBadgeCubeEquippedBadges(data, user, [badgeId || null, null]);
}

// 홈뱃지 큐브의 구간 확률을 먼저 뽑고 구간 안 소수 첫째 자리를 균등 추첨하는 함수
function rollHomeBadgeCubePercent() {
    var rates = GLOBAL_CONFIG.petHomeActivity.cube.rates;
    var roll = Math.random() * 100;
    var cumulativeRate = 0;
    var selected = rates[rates.length - 1];
    for (var i = 0; i < rates.length; i++) {
        cumulativeRate += rates[i].rate;
        if (roll < cumulativeRate) {
            selected = rates[i];
            break;
        }
    }
    var minTenths = Math.round(selected.min * 10);
    var maxTenths = Math.round(selected.max * 10);
    return (minTenths + Math.floor(Math.random() * (maxTenths - minTenths + 1))) / 10;
}

// 현재 수치에서 다음 1% 보호 단계 또는 옵션 최대치를 반환하는 함수
function getHomeBadgeCubeNextTarget(currentPercent, maxPercent) {
    currentPercent = parseFloat(currentPercent) || 0;
    maxPercent = parseFloat(maxPercent) || 0;
    if (currentPercent >= maxPercent) return maxPercent;
    return Math.min(maxPercent, Math.floor(currentPercent) + 1);
}

// 홈뱃지 큐브 확률 안내 메시지를 생성하는 함수
function buildHomeBadgeCubeRateMessage(data, petData, guildData, user) {
    var rates = GLOBAL_CONFIG.petHomeActivity.cube.rates;
    var lines = ["[" + checkRank(data, petData, guildData, user) + "] 님", "💟 홈뱃지 큐브 확률", "━━━━━━━━━━━━━━━"];
    for (var i = 0; i < rates.length; i++) {
        if (i > 0 && (rates[i].min === 10.1 || rates[i].min === 15 || rates[i].min === 20 || rates[i].min === 30 || rates[i].min === 40 || rates[i].min === 45 || rates[i].min === 48)) lines.push("");
        var rangeText = rates[i].min === rates[i].max ? formatHomeBadgeCubePercent(rates[i].min) : formatHomeBadgeCubePercent(rates[i].min) + "~" + formatHomeBadgeCubePercent(rates[i].max);
        lines.push(rangeText + " : " + rates[i].rate.toFixed(6) + "%");
    }
    lines.push("━━━━━━━━━━━━━━━");
    lines.push("구간을 먼저 추첨한 뒤 구간 안의 0.1% 단위를 같은 확률로 뽑습니다.");
    lines.push("추첨된 소수 첫째 자리 수치를 적용하며, 실패해도 달성한 1% 단위 보호선이 유지됩니다.");
    lines.push("옵션별 최대 수치: 캐슬 50% / 레이드 50% / 펫강화 30% / 펫탐험 15%");
    lines.push("네 옵션의 기본 합계가 100% 이상이면 장착 시 모든 효과에 10% 추가 버프가 적용됩니다.");
    return lines.join("\n");
}

// 홈뱃지의 큐브 옵션 제목과 번호별 한 줄씩을 카드용으로 생성하는 함수
function buildHomeBadgeCubeOptionLines(data, user, badge) {
    var record = getHomeBadgeCubeRecord(data, user, badge.id, false);
    var castle = record ? record.castle : 0;
    var raid = record ? record.raid : 0;
    var petUpgrade = record ? record.petUpgrade : 0;
    var explore = record ? record.explore : 0;
    var store = getHomeBadgeCubeStore(data, user, false);
    var equippedBadgeIds = store ? normalizeHomeBadgeCubeEquippedBadgeIds(store) : [null, null];
    var equippedSlotIndex = equippedBadgeIds[0] === badge.id ? 0 : (equippedBadgeIds[1] === badge.id ? 1 : -1);
    var premiumSuffix = equippedSlotIndex >= 0 && isHoiPassPremiumActive(data, user) ? "(+" + GLOBAL_CONFIG.supportPass.premium.cubeOptionBonusPercent + "%👑)" : "";
    var castleFinal = equippedSlotIndex >= 0 ? "=" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeSlotOptionPercent(data, user, equippedSlotIndex, "castle")) : "";
    var raidFinal = equippedSlotIndex >= 0 ? "=" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeSlotOptionPercent(data, user, equippedSlotIndex, "raid")) : "";
    var petUpgradeFinal = equippedSlotIndex === 0 ? "=" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeSlotOptionPercent(data, user, 0, "petUpgrade")) : "";
    var exploreFinal = equippedSlotIndex === 0 ? "=" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeSlotOptionPercent(data, user, 0, "explore")) : "";
    var lines = [];
    lines.push("💟 홈뱃지 큐브 옵션");
    lines.push("[1]⚔️+" + formatHomeBadgeCubeCardPercent(castle) + premiumSuffix + castleFinal);
    lines.push("[2]👾+" + formatHomeBadgeCubeCardPercent(raid) + premiumSuffix + raidFinal);
    if (equippedSlotIndex !== 1) {
        lines.push("[3]🌟+" + formatHomeBadgeCubeCardPercent(petUpgrade) + (equippedSlotIndex === 0 ? premiumSuffix : "") + petUpgradeFinal);
        lines.push("[4]⛰️+" + formatHomeBadgeCubeCardPercent(explore) + (equippedSlotIndex === 0 ? premiumSuffix : "") + exploreFinal);
    }
    if (isHomeBadgeCubeTotalBuffActive(record)) lines.push("└ 💟 기본 합계 100%! 장착 효과에 10% 추가 버프가 적용됩니다.");
    return lines.join("\n");
}

// 홈뱃지 출처에 맞는 카드용 유형·등급 꼬리표를 반환하는 함수
function getPetHomeBadgeTypeLabel(badge) {
    if (!badge) return "";
    if (badge.id.indexOf("S") === 0) return " [특별]";
    if (badge.source === "HOME_BADGE_GACHA") return " [" + badge.grade + "]";
    if (badge.source === "HOME_BADGE_GACHA_2") return " [MBTI]";
    if (badge.source === "HOME_BADGE_GACHA_3") return " [연애유형]";
    return "";
}

// 홈뱃지 뽑기의 등급별·개별 확률 안내 메시지를 생성하는 함수
function buildPetHomeGachaRateMessage(data, petData, guildData, user) {
    var rates = GLOBAL_CONFIG.petHomeActivity.gachaGradeRates;
    var badges = GLOBAL_CONFIG.petHomeActivity.gachaBadges;
    var lines = ["[" + checkRank(data, petData, guildData, user) + "] 님", "🛡️ 홈뱃지 뽑기 확률", "━━━━━━━━━━━━━━━"];
    for (var rateIndex = 0; rateIndex < rates.length; rateIndex++) {
        var gradeCount = 0;
        for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
            if (badges[badgeIndex].grade === rates[rateIndex].grade) gradeCount++;
        }
        var individualRate = gradeCount > 0 ? rates[rateIndex].rate / gradeCount : 0; // 등급 내 뱃지 한 종의 실제 당첨 확률
        lines.push("[" + rates[rateIndex].grade + "] " + rates[rateIndex].rate + "% | " + gradeCount + "종 | 각 " + individualRate.toFixed(2) + "%");
    }
    lines.push("━━━━━━━━━━━━━━━");
    lines.push("등급을 먼저 추첨한 뒤 같은 등급의 홈뱃지 중 한 종을 동일 확률로 뽑습니다.");
    return lines.join("\n");
}

// 전체 펫홈 뱃지 설정을 ID로 찾는 함수
function getPetHomeBadgeById(badgeId) {
    var ctx = typeof commandContextThreadLocal !== "undefined" ? commandContextThreadLocal.get() : null;
    var lookup = null;
    if (ctx && typeof badgeId === "string") {
        lookup = ctx.petHomeBadgeDefinitionLookup;
        if (lookup) {
            var lookupKey = "$" + badgeId;
            if (Object.prototype.hasOwnProperty.call(lookup.byId, lookupKey)) return lookup.byId[lookupKey];
            while (lookup.next < lookup.badges.length) {
                var badge = lookup.badges[lookup.next];
                var currentId = badge.id; // 처음 일치하기 전의 잘못된 정의는 기존대로 오류를 발생시킴
                if (typeof currentId === "string" && !Object.prototype.hasOwnProperty.call(lookup.byId, "$" + currentId)) lookup.byId["$" + currentId] = badge;
                lookup.next++;
                if (currentId === badgeId) return badge;
            }
            return null;
        } else {
            lookup = { badges: getAllPetHomeBadges(), byId: {}, next: 0 };
            ctx.petHomeBadgeDefinitionLookup = lookup; // 고정 정의만 이번 명령 안에서 재사용하며 개인 데이터·다음 명령에는 보관하지 않음
        }
    }
    var allBadges = lookup ? lookup.badges : getAllPetHomeBadges();
    for (var i = 0; i < allBadges.length; i++) {
        if (allBadges[i].id === badgeId) {
            if (lookup) lookup.byId["$" + badgeId] = allBadges[i]; // 첫 조회는 기존 검색만 하고 추가 조회부터 인덱스를 확장
            return allBadges[i];
        }
    }
    return null;
}

// 특별 펫홈 뱃지를 코드, 이름, 목록 표시 문구로 찾는 함수
function getPetHomeSpecialBadgeByName(badgeName) {
    var input = String(badgeName || "").trim();
    var badgeIdInput = input.toUpperCase();
    var bracketedBadgeIdMatch = badgeIdInput.match(/^\[([A-Z]\d{2})\]$/);
    if (bracketedBadgeIdMatch) badgeIdInput = bracketedBadgeIdMatch[1];
    var badges = GLOBAL_CONFIG.petHomeActivity.specialBadges;
    for (var i = 0; i < badges.length; i++) {
        var displayName = badges[i].emoji + " " + badges[i].name;
        var fullDisplayName = "[" + badges[i].id + "] " + displayName;
        if (badges[i].id === badgeIdInput || badges[i].name === input || displayName === input || fullDisplayName === input) return badges[i];
    }
    return null;
}

// 두 유저가 서로 팔로우 중인지 확인하는 함수
function isPetHomeMutualFollow(activityData, user, otherUser) {
    var userSocial = getPetHomeSocialUser(activityData, user);
    var otherSocial = getPetHomeSocialUser(activityData, otherUser);
    return petHomeStringListContains(userSocial.following, otherUser) && petHomeStringListContains(otherSocial.following, user);
}

// 특정 유저의 맞팔 목록을 반환하는 함수
function getPetHomeMutualUsers(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var mutualUsers = [];
    for (var i = 0; i < social.following.length; i++) {
        var otherUser = social.following[i];
        if (isPetHomeMutualFollow(activityData, user, otherUser)) mutualUsers.push(otherUser);
    }
    return mutualUsers;
}

// 현재 패스가 활성인 맞팔 수를 반환하는 함수
function getActivePetHomeMutualCount(data, activityData, user) {
    if (!hasActiveHoiPassAccess(data, user)) return 0;
    var mutualUsers = getPetHomeMutualUsers(activityData, user);
    var count = 0;
    for (var i = 0; i < mutualUsers.length; i++) {
        if (hasActiveHoiPassAccess(data, mutualUsers[i])) count++;
    }
    return count;
}

// 펫홈 뱃지 판정용 현재 수치를 계산하는 함수
function getPetHomeBadgeStatValues(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    return {
        followers: social.followers.length,
        mutual: getPetHomeMutualUsers(activityData, user).length,
        receivedComments: social.badgeStats.receivedComments,
        receivedHomeLikes: social.badgeStats.receivedHomeLikes,
        receivedReactions: social.badgeStats.receivedReactions,
        totalVisits: social.badgeStats.totalVisits,
        feedActiveDays: social.feedActivityDates.length
    };
}

// 펫홈 업적 뱃지의 획득 조건 충족 여부를 확인하는 함수
function isPetHomeAchievementBadgeEarned(badge, statValues, ownedBadgeIds) {
    if (badge.requiredBadgeIds) {
        for (var requiredIndex = 0; requiredIndex < badge.requiredBadgeIds.length; requiredIndex++) {
            if (!petHomeStringListContains(ownedBadgeIds, badge.requiredBadgeIds[requiredIndex])) return false;
        }
        return true;
    }
    if (badge.requirements) {
        for (var statKey in badge.requirements) {
            if (!badge.requirements.hasOwnProperty(statKey)) continue;
            if ((statValues[statKey] || 0) < badge.requirements[statKey]) return false;
        }
        return true;
    }
    return (statValues[badge.stat] || 0) >= badge.threshold;
}

// 조건을 충족한 일반 펫홈 뱃지를 지급하고 새 지급 목록을 반환하는 함수
function awardPetHomeAchievementBadges(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var statValues = getPetHomeBadgeStatValues(activityData, user);
    var badgeDefinitions = GLOBAL_CONFIG.petHomeActivity.achievementBadges;
    var awarded = [];
    for (var i = 0; i < badgeDefinitions.length; i++) {
        var badge = badgeDefinitions[i];
        if (petHomeStringListContains(social.badges, badge.id) || petHomeStringListContains(social.deletedBadgeIds, badge.id)) continue;
        if (!isPetHomeAchievementBadgeEarned(badge, statValues, social.badges)) continue;
        social.badges.push(badge.id);
        awarded.push(badge);
    }
    return awarded;
}

// 새로 획득한 일반 펫홈 뱃지를 활동 알림에 기록하는 함수
function addPetHomeBadgeAwardAlerts(activityData, user, awardedBadges) {
    if (!activityData.alerts.hasOwnProperty(user)) activityData.alerts[user] = [];
    var alerts = activityData.alerts[user];
    for (var i = 0; i < awardedBadges.length; i++) {
        alerts.push({
            type: "badge_earned",
            actorId: user,
            createdAt: formatDateTime(new Date()),
            read: false,
            badgeId: awardedBadges[i].id
        });
        while (alerts.length > GLOBAL_CONFIG.petHomeActivity.maxAlerts) alerts.shift();
    }
}

// 펫홈 뱃지 누적 통계를 증가시키는 함수
function addPetHomeBadgeStat(activityData, user, statKey, amount) {
    var social = getPetHomeSocialUser(activityData, user);
    var current = parseInt(social.badgeStats[statKey], 10) || 0;
    var increase = parseInt(amount, 10) || 0;
    if (increase > 0) social.badgeStats[statKey] = current + increase;
    return social.badgeStats[statKey];
}

// 펫홈 뱃지 누적 통계를 현재 확인 가능한 값 이상으로 맞추는 함수
function raisePetHomeBadgeStat(activityData, user, statKey, minimumValue) {
    var social = getPetHomeSocialUser(activityData, user);
    var current = parseInt(social.badgeStats[statKey], 10) || 0;
    var minimum = parseInt(minimumValue, 10) || 0;
    if (minimum > current) social.badgeStats[statKey] = minimum;
    return social.badgeStats[statKey];
}

// 보유 홈뱃지의 고정 목록 번호를 반환하는 함수
function getPetHomeOwnedBadgeNumber(activityData, user, badgeId) {
    var owned = getOwnedPetHomeBadges(activityData, user);
    for (var i = 0; i < owned.length; i++) {
        if (owned[i].id === badgeId) return i + 1;
    }
    return 0;
}

// 홈뱃지 ID의 보유 번호 포함 표시 문구를 반환하는 함수
function getPetHomeBadgeSlotTextById(activityData, user, badgeId) {
    var social = getPetHomeSocialUser(activityData, user);
    var badge = getPetHomeBadgeById(badgeId);
    if (!badge || !petHomeStringListContains(social.badges, badge.id)) return "장착된 뱃지가 없습니다.";
    var ownedNumber = getPetHomeOwnedBadgeNumber(activityData, user, badge.id);
    if (ownedNumber > 0) return badge.emoji + " " + badge.name + "[" + ownedNumber + "번]";
    return badge.emoji + " " + badge.name;
}

// 장착 슬롯의 홈뱃지 표시 문구를 반환하는 함수
function getPetHomeEquippedBadgeSlotText(activityData, user, slotIndex) {
    var equippedBadgeIds = getPetHomeEquippedBadgeIds(activityData, user);
    return getPetHomeBadgeSlotTextById(activityData, user, equippedBadgeIds[slotIndex]);
}

// 장착 중인 대표 펫홈 뱃지의 표시 문구를 반환하는 함수
function getPetHomeEquippedBadgeText(activityData, user) {
    return getPetHomeEquippedBadgeSlotText(activityData, user, 0);
}

// 홈뱃지 네 옵션의 현재 최종 적용값을 한 줄로 생성하는 함수
function buildHomeBadgeCubeEffectSummary(data, user) {
    return "⚔️+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "castle")) +
        " | 👾+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "raid")) +
        " | 🌟+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "petUpgrade")) +
        " | ⛰️+" + formatHomeBadgeCubeCardPercent(getHomeBadgeCubeActiveOptionPercent(data, user, "explore"));
}

// 홈뱃지 장착·해제 선택 안내 메시지를 생성하는 함수
function buildHomeBadgeSlotGuideMessage(data, petData, guildData, activityData, user, action) {
    var actionLabel = action === "해제" ? "해제" : "장착";
    var lines = ["🏅 [" + checkRank(data, petData, guildData, user) + "] 님의 홈뱃지 " + actionLabel, "━━━━━━━━━━━━━━━"];
    lines.push("[1] 대표  " + getPetHomeEquippedBadgeSlotText(activityData, user, 0));
    lines.push("[2] 보조  " + getPetHomeEquippedBadgeSlotText(activityData, user, 1));
    lines.push("");
    if (action === "해제") {
        var equippedIds = getPetHomeEquippedBadgeIds(activityData, user);
        var equippedNumbers = [];
        if (equippedIds[0]) equippedNumbers.push(getPetHomeOwnedBadgeNumber(activityData, user, equippedIds[0]));
        if (equippedIds[1]) equippedNumbers.push(getPetHomeOwnedBadgeNumber(activityData, user, equippedIds[1]));
        lines.push("해제할 장착 뱃지번호를 입력해 주세요.");
        lines.push("/홈뱃지해제 [대표뱃지번호] [보조뱃지번호]");
        if (equippedNumbers.length > 0) lines.push("현재 해제 명령: /홈뱃지해제 " + equippedNumbers.join(" "));
        else lines.push("현재 장착된 홈뱃지가 없습니다.");
        lines.push("");
        lines.push("※ 번호 1개를 입력하면 선택한 장착 뱃지만 해제합니다.");
    } else {
        lines.push("대표와 보조로 사용할 뱃지번호를 입력해 주세요.");
        lines.push("/홈뱃지장착 [대표뱃지번호] [보조뱃지번호]");
        lines.push("예: /홈뱃지장착 3 5");
        lines.push("");
        lines.push("※ 번호 1개를 입력하면 대표 뱃지만 장착합니다.");
        lines.push("💡 대표 슬롯은 펫홈에 표시되고 모든 효과가 적용됩니다.");
        lines.push("💡 보조 슬롯은 캐슬·레이드 효과만 적용됩니다.");
    }
    return lines.join("\n");
}

// 홈뱃지 장착·해제 확인 상태를 저장하는 함수
function setHomeBadgeMutationState(sender, state) {
    if (!userState[sender]) userState[sender] = {};
    state.requestedAt = Date.now();
    userState[sender].homeBadgeMutation = state;
}

// 만료되지 않은 홈뱃지 장착·해제 확인 상태를 반환하는 함수
function getHomeBadgeMutationState(sender) {
    var state = userState[sender] && userState[sender].homeBadgeMutation ? userState[sender].homeBadgeMutation : null;
    if (!state) return null;
    if (Date.now() - state.requestedAt > GLOBAL_CONFIG.petHomeActivity.badgeConfirmStaleMs) {
        clearHomeBadgeMutationState(sender);
        return null;
    }
    return state;
}

// 홈뱃지 장착·해제 확인 상태를 제거하는 함수
function clearHomeBadgeMutationState(sender) {
    if (!userState[sender]) return;
    delete userState[sender].homeBadgeMutation;
    if (Object.keys(userState[sender]).length === 0) delete userState[sender];
}

// 두 홈뱃지 슬롯 배열이 같은지 확인하는 함수
function areHomeBadgeSlotIdsEqual(left, right) {
    return left instanceof Array && right instanceof Array && left.length === 2 && right.length === 2 && left[0] === right[0] && left[1] === right[1];
}

// 특정 홈뱃지를 두 장착 슬롯에서 제거하고 보조 단독 상태를 정리하는 함수
function removeHomeBadgeFromEquippedSlots(data, social, user, badgeId) {
    var ids = normalizePetHomeEquippedBadgeIds(social).slice(0);
    var changed = false;
    for (var i = 0; i < ids.length; i++) {
        if (ids[i] === badgeId) {
            ids[i] = null;
            changed = true;
        }
    }
    if (changed) {
        setPetHomeEquippedBadgeIds(social, ids);
        syncHomeBadgeCubeEquippedBadges(data, user, social.equippedBadgeIds);
    }
    return changed;
}

// 호이 남의 펫홈 마음표현 일일 횟수 제한을 해제할지 확인하는 함수
function hasUnlimitedPetHomeHeartUsage(user) {
    return user === "호이 남";
}

// 펫홈 마음표현의 오늘 사용량과 한도를 반환하는 함수
function getPetHomeHeartUsageStatus(data, petSkillData, activityData, homeData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var today = getPetHomeTodayText();
    if (social.heartUsage.date !== today) {
        social.heartUsage.date = today;
        social.heartUsage.count = 0;
        if (homeData && homeData[user] && homeData[user].lastHeartExpressionDate === today) social.heartUsage.count = 1;
    }
    var mutualBonus = getActivePetHomeMutualCount(data, activityData, user); // 활성 맞팔로 추가되는 일일 사용 횟수
    var premiumBonus = isHoiPassPremiumActive(data, user) ? GLOBAL_CONFIG.supportPass.premium.heartBonus : 0;
    var skillBonus = getPetSkillHeartBonus(petSkillData, user); // 망므 등 장착 스킬로 추가되는 일일 사용 횟수
    var limit = 1 + mutualBonus + premiumBonus + skillBonus; // 기본·맞팔·프리미엄·스킬 보너스를 합친 최종 한도
    var used = parseInt(social.heartUsage.count, 10) || 0;
    var unlimited = hasUnlimitedPetHomeHeartUsage(user); // 호이 남 전용 일일 제한 해제 여부
    return { date: today, base: 1, mutualBonus: mutualBonus, premiumBonus: premiumBonus, skillBonus: skillBonus, limit: limit, used: used, unlimited: unlimited, remaining: unlimited ? null : Math.max(0, limit - used) };
}

// 유저가 보유한 펫홈 뱃지 설정을 고정 순서로 반환하는 함수
function getOwnedPetHomeBadges(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user);
    var allBadges = getAllPetHomeBadges();
    var owned = [];
    for (var i = 0; i < allBadges.length; i++) {
        if (petHomeStringListContains(social.badges, allBadges[i].id)) owned.push(allBadges[i]);
    }
    return owned;
}

// 번호, ID 또는 정확한 이름으로 펫홈 뱃지 설정을 찾는 함수
function resolvePetHomeBadgeSelection(activityData, user, selection, requireOwned) {
    var rawText = String(selection || "").trim();
    var text = rawText.toUpperCase();
    var bracketedBadgeIdMatch = text.match(/^\[([A-Z]{1,4}\d{2,3})\]$/);
    if (bracketedBadgeIdMatch) text = bracketedBadgeIdMatch[1];
    var social = getPetHomeSocialUser(activityData, user);
    var badge = null;
    if (/^\d+$/.test(text)) {
        var owned = getOwnedPetHomeBadges(activityData, user);
        var index = parseInt(text, 10) - 1;
        if (index >= 0 && index < owned.length) badge = owned[index];
    } else {
        badge = getPetHomeBadgeById(text);
        if (!badge) {
            var allBadges = getAllPetHomeBadges();
            for (var i = 0; i < allBadges.length; i++) {
                if (allBadges[i].name === rawText) {
                    badge = allBadges[i];
                    break;
                }
            }
        }
    }
    if (!badge) return null;
    if (requireOwned && !petHomeStringListContains(social.badges, badge.id)) return null;
    return badge;
}

// 펫홈 소셜 관계 목록 메시지를 생성하는 함수
function buildPetHomeFollowListMessage(data, petData, guildData, activityData, user, type, includePremiumHeader) {
    var social = getPetHomeSocialUser(activityData, user);
    var sourceList = type === "followers" ? social.followers : social.following;
    var nonMutualUsers = []; // 목록 상단에 표시할 맞팔이 아닌 유저
    var mutualUsers = []; // 비맞팔 다음에 표시할 맞팔 유저
    for (var listIndex = 0; listIndex < sourceList.length; listIndex++) {
        var listedUser = sourceList[listIndex];
        if (isPetHomeMutualFollow(activityData, user, listedUser)) mutualUsers.push(listedUser);
        else nonMutualUsers.push(listedUser);
    }
    var list = nonMutualUsers.concat(mutualUsers);
    var title = type === "followers" ? "🐾 팔로워 유저[명령어: /팔로우]\n※ 나에게 관심 있는 사람" : "🎀 팔로잉 유저[명령어: /팔로잉]\n※ 내가 관심 있는 사람";
    var out = (includePremiumHeader === false ? "" : getHoiPassPremiumHeader(data, user)) + "[" + checkRank(data, petData, guildData, user) + "] 님\n" + title + "\n━━━━━━━━━━━━\n";
    if (list.length === 0) return out + "등록된 유저가 없습니다.";
    for (var i = 0; i < list.length; i++) {
        var target = list[i];
        var displayName = data.member && data.member[target] ? checkRank(data, petData, guildData, target) : target;
        out += (i + 1) + ". " + displayName + (isPetHomeMutualFollow(activityData, user, target) ? " 🤝맞팔" : "") + "\n";
        if (i === 9) out += allsee + "\n";
    }
    return out.trim();
}

// 오늘의 펫홈 마음표현 사용 현황 메시지를 생성하는 함수
function buildPetHomeHeartUsageMessage(data, petData, petSkillData, guildData, activityData, homeData, user) {
    var status = getPetHomeHeartUsageStatus(data, petSkillData, activityData, homeData, user);
    return getHoiPassPremiumHeader(data, user) + "[" + checkRank(data, petData, guildData, user) + "] 님\n" +
        "💞 맞팔 마음표현 혜택\n" +
        "━━━━━━━━━━━━\n" +
        "기본 사용 가능 횟수: " + status.base + "회\n" +
        "맞팔 보너스: +" + status.mutualBonus + "회\n" +
        (status.premiumBonus > 0 ? "호이패스 프리미엄: +" + status.premiumBonus + "회\n" : "") +
        (status.skillBonus > 0 ? "망므📙: +" + status.skillBonus + "회\n" : "") +
        "오늘 사용: " + status.used + "회\n" +
        "남은 마음: " + (status.unlimited ? "무제한" : status.remaining + "회") + "\n" +
        "최종 사용 가능 횟수: " + (status.unlimited ? "무제한" : status.limit + "회");
}

// 펫홈 뱃지의 획득 조건과 현재 진행도를 생성하는 함수
function getPetHomeBadgeProgressText(activityData, user, badge) {
    var values = getPetHomeBadgeStatValues(activityData, user);
    var labels = {
        followers: "팔로워",
        mutual: "맞팔",
        receivedComments: "받은 댓글",
        receivedHomeLikes: "좋아홈",
        receivedReactions: "마음표현",
        totalVisits: "누적 방문",
        feedActiveDays: "피드 활동"
    };
    if (badge.requiredBadgeIds) return "종합 업적 A01~A08 모두 획득";
    if (badge.requirements) {
        var parts = [];
        for (var key in badge.requirements) {
            if (!badge.requirements.hasOwnProperty(key)) continue;
            parts.push(labels[key] + " " + numberWithCommas(values[key] || 0) + "/" + numberWithCommas(badge.requirements[key]));
        }
        return parts.join(" + ");
    }
    if (badge.source === "HOME_BADGE_GACHA") return "[" + badge.grade + "] " + badge.text;
    if (badge.source === "HOME_BADGE_GACHA_2") return "[MBTI] " + badge.description + " “" + badge.message + "”";
    if (badge.source === "HOME_BADGE_GACHA_3") return "[연애유형] “" + badge.text + "”";
    if (badge.id.indexOf("S") === 0) return "운영자 지급 특별 뱃지";
    return labels[badge.stat] + " " + numberWithCommas(values[badge.stat] || 0) + "/" + numberWithCommas(badge.threshold);
}

