// 기존 한줄평을 첫 피드로 이전하고 유저의 피드 목록을 검증하는 함수
function ensurePetHomeFeedList(userHome) {
    if (!userHome || typeof userHome !== "object" || userHome instanceof Array) throw new Error("Invalid pet home user data for feeds");
    if (userHome.feeds === undefined) userHome.feeds = [];
    if (!(userHome.feeds instanceof Array)) throw new Error("Invalid pet home feed list");
    if (userHome.feeds.length > GLOBAL_CONFIG.petHomeActivity.feedMaxStored) throw new Error("Invalid pet home feed list size");
    var feedIds = {};
    for (var i = 0; i < userHome.feeds.length; i++) {
        var feed = userHome.feeds[i];
        if (!feed || typeof feed !== "object" || feed instanceof Array ||
            typeof feed.id !== "string" || !feed.id || feedIds.hasOwnProperty(feed.id) || typeof feed.content !== "string" || !feed.content ||
            feed.content.length > GLOBAL_CONFIG.petHomeActivity.feedMaxLength ||
            (typeof feed.createdAt !== "number" && typeof feed.createdAt !== "string")) {
            throw new Error("Invalid pet home feed entry");
        }
        feedIds[feed.id] = true;
    }
    var migrated = false;
    if (userHome.feedMigration20260728 !== true) {
        var legacyComment = typeof userHome.comment === "string" ? userHome.comment.trim() : "";
        if (legacyComment) {
            var legacyFeedIdBase = "legacy-" + String(userHome.commentTime || Date.now());
            var legacyFeedId = legacyFeedIdBase;
            var legacyFeedSequence = 0;
            while (feedIds.hasOwnProperty(legacyFeedId)) {
                legacyFeedSequence++;
                legacyFeedId = legacyFeedIdBase + "-" + legacyFeedSequence;
            }
            userHome.feeds.unshift({
                id: legacyFeedId,
                content: legacyComment,
                createdAt: userHome.commentTime || Date.now()
            });
            while (userHome.feeds.length > GLOBAL_CONFIG.petHomeActivity.feedMaxStored) userHome.feeds.pop();
        }
        delete userHome.comment;
        delete userHome.commentTime;
        userHome.feedMigration20260728 = true;
        migrated = true;
    }
    return { feeds: userHome.feeds, migrated: migrated };
}

// 모든 기존 펫홈 한줄평을 유저별 첫 피드로 일괄 이전하는 함수
function migratePetHomeFeeds(homeData) {
    if (!homeData || typeof homeData !== "object" || homeData instanceof Array) throw new Error("Invalid pet home data for feed migration");
    var result = { userCount: 0, legacyFeedCount: 0 };
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user)) continue;
        if (!homeData[user] || typeof homeData[user] !== "object" || homeData[user] instanceof Array) throw new Error("Invalid pet home user for feed migration: " + user);
        if (typeof homeData[user].comment === "string" && homeData[user].comment.trim()) result.legacyFeedCount++;
        ensurePetHomeFeedList(homeData[user]);
        result.userCount++;
    }
    return result;
}

// 전체 펫홈 피드 마이그레이션 저장 상태를 변경 없이 검증하는 함수
function isPetHomeFeedMigrationComplete(homeData) {
    if (!homeData || typeof homeData !== "object" || homeData instanceof Array) return false;
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user)) continue;
        if (!homeData[user] || typeof homeData[user] !== "object" || homeData[user] instanceof Array) return false;
        var userHome = homeData[user];
        if (userHome.feedMigration20260728 !== true || !(userHome.feeds instanceof Array) ||
            userHome.comment !== undefined || userHome.commentTime !== undefined) return false;
        try {
            ensurePetHomeFeedList(userHome);
        } catch (feedMigrationValidationError) {
            return false;
        }
    }
    return true;
}

// 중복되지 않는 ID와 현재 시각으로 새 펫홈 피드를 생성하는 함수
function createPetHomeFeed(userHome, content) {
    var feeds = ensurePetHomeFeedList(userHome).feeds;
    var createdAt = Date.now();
    var sequence = 0;
    var feedId = "feed-" + createdAt;
    var duplicated = true;
    while (duplicated) {
        duplicated = false;
        for (var i = 0; i < feeds.length; i++) {
            if (feeds[i].id === feedId) {
                sequence++;
                feedId = "feed-" + createdAt + "-" + sequence;
                duplicated = true;
                break;
            }
        }
    }
    return { id: feedId, content: content, createdAt: createdAt };
}

// 피드를 작성한 날짜를 중복 없이 누적하고 현재 활동일 수를 반환하는 함수
function addPetHomeFeedActivityDate(activityData, user, activityDate) {
    var social = getPetHomeSocialUser(activityData, user);
    if (!petHomeStringListContains(social.feedActivityDates, activityDate)) social.feedActivityDates.push(activityDate);
    return social.feedActivityDates.length;
}

// 펫홈 최신 피드를 전체보기 형식으로 생성하는 함수
function buildPetHomeFeedMessage(data, petData, guildData, userHome, user) {
    var feeds = ensurePetHomeFeedList(userHome).feeds;
    var out = "[" + checkRank(data, petData, guildData, user) + "] 님\n▣━━ 집주인의 최신 피드 ━━▣\n" + allsee + "\n\n";
    if (feeds.length === 0) return out + "[등록된 피드가 없습니다.]";
    for (var i = 0; i < feeds.length; i++) {
        out += (i + 1) + ". ▣ “" + feeds[i].content + "”\n" +
            "└ " + formatDateTime(feeds[i].createdAt) + "\n\n";
    }
    return out.trim();
}

// 지정 유저들의 펫홈 알림 목록을 저장 전 상태로 보관하는 함수
function snapshotPetHomeAlertLists(activityData, users) {
    var snapshots = [];
    var seen = {};
    for (var i = 0; i < users.length; i++) {
        var user = users[i];
        if (seen.hasOwnProperty(user)) continue;
        seen[user] = true;
        snapshots.push({
            user: user,
            existed: activityData.alerts.hasOwnProperty(user),
            alerts: activityData.alerts.hasOwnProperty(user) ? JSON.parse(JSON.stringify(activityData.alerts[user])) : []
        });
    }
    return snapshots;
}

// 저장 실패 시 지정 유저들의 펫홈 알림 목록을 복구하는 함수
function restorePetHomeAlertLists(activityData, snapshots) {
    for (var i = 0; i < snapshots.length; i++) {
        if (snapshots[i].existed) activityData.alerts[snapshots[i].user] = snapshots[i].alerts;
        else delete activityData.alerts[snapshots[i].user];
    }
}

// 새 피드 알림을 대상 유저의 홈알림에 추가하는 함수
function addPetHomeFeedActivityAlert(activityData, targetUser, actorId, actorName, feed) {
    var alerts = getPetHomeAlertList(activityData, targetUser);
    alerts.push({
        type: "feed",
        actorId: actorId,
        actorName: actorName,
        feedId: feed.id,
        feedContent: feed.content,
        createdAt: formatDateTime(feed.createdAt),
        read: false
    });
    while (alerts.length > GLOBAL_CONFIG.petHomeActivity.maxAlerts) alerts.shift();
}

// 펫홈 소셜 순위 명령어의 점수를 계산하고 상위 100명을 출력하는 함수
function buildPetHomeSocialRankingMessage(data, petData, petSkillData, guildData, homeData, activityData, viewer, command) {
    var rows = [];
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var social = activityData.petHomeSocial.hasOwnProperty(user) ? activityData.petHomeSocial[user] : null;
        var score = 0;
        if (command === "/팔로워순위") {
            score += getPetSkillFollowerBonus(petSkillData, user);
            var validFollowers = {};
            if (social) {
                for (var followerIndex = 0; followerIndex < social.followers.length; followerIndex++) {
                    var follower = social.followers[followerIndex];
                    if (data.member[follower]) validFollowers[follower] = true;
                }
            }
            for (var validFollower in validFollowers) {
                if (validFollowers.hasOwnProperty(validFollower)) score++;
            }
        } else if (command === "/마음순위" && homeData[user]) {
            var heartCounts = ensurePetHomeHeartExpressions(homeData[user]);
            score = heartCounts.cute + heartCounts.cheer + heartCounts.cool + heartCounts.love;
        } else if (command === "/뱃지순위" && social) {
            var validBadges = {};
            for (var badgeIndex = 0; badgeIndex < social.badges.length; badgeIndex++) {
                var badgeId = social.badges[badgeIndex];
                if (getPetHomeBadgeById(badgeId) && !petHomeStringListContains(social.deletedBadgeIds, badgeId)) validBadges[badgeId] = true;
            }
            for (var validBadge in validBadges) {
                if (validBadges.hasOwnProperty(validBadge)) score++;
            }
        }
        if (score > 0) {
            var rankingRow = { user: user, score: score };
            if (command === "/마음순위") rankingRow.heartCounts = heartCounts;
            rows.push(rankingRow);
        }
    }
    rows.sort(function (a, b) {
        if (b.score !== a.score) return b.score - a.score;
        return String(a.user).localeCompare(String(b.user), "ko");
    });
    if (rows.length > 100) rows = rows.slice(0, 100);

    var settings = command === "/팔로워순위"
        ? { title: "🐾━━ 팔로워 순위 TOP 100 ━━🐾", unit: "팔로워 ", suffix: "명" }
        : (command === "/마음순위"
            ? { title: "💞━━ 마음표현 받은 순위 TOP 100 ━━💞", unit: "총 ", suffix: "회" }
            : { title: "🏅━━ 뱃지 순위 TOP 100 ━━🏅", unit: "뱃지 ", suffix: "개" });
    var out = "[" + checkRank(data, petData, guildData, viewer) + "] 님\n" + settings.title + "\n" + allsee + "\n\n";
    if (rows.length === 0) return out + "[순위에 등록된 유저가 없습니다.]";
    for (var rowIndex = 0; rowIndex < rows.length; rowIndex++) {
        out += (rowIndex + 1) + "위. " + checkRank(data, petData, guildData, rows[rowIndex].user) + " — " +
            settings.unit + numberWithCommas(rows[rowIndex].score) + settings.suffix + "\n";
        if (command === "/마음순위") {
            var rowHeartCounts = rows[rowIndex].heartCounts;
            out += "└ 귀여워🐾 " + numberWithCommas(rowHeartCounts.cute) +
                " | 멋져요✨ " + numberWithCommas(rowHeartCounts.cool) +
                " | 응원해⭐ " + numberWithCommas(rowHeartCounts.cheer) +
                " | 사랑해💖 " + numberWithCommas(rowHeartCounts.love) + "\n";
        }
    }
    return out.trim();
}

// 특정 유저의 펫홈 활동 알림 목록을 반환하는 함수
function getPetHomeAlertList(activityData, user) {
    activityData = requirePetHomeActivityData(activityData);
    if (!activityData.alerts.hasOwnProperty(user)) activityData.alerts[user] = [];
    return activityData.alerts[user];
}

// 특정 유저의 최근 방문자 목록을 반환하는 함수
function getPetHomeRecentVisitorList(activityData, user) {
    activityData = requirePetHomeActivityData(activityData);
    if (!activityData.recentVisitors.hasOwnProperty(user)) activityData.recentVisitors[user] = [];
    return activityData.recentVisitors[user];
}

// 펫홈 활동 알림을 추가하고 최대 보관 개수를 유지하는 함수
function addPetHomeActivityAlert(activityData, targetUser, type, actorId, commentPreview) {
    var alerts = getPetHomeAlertList(activityData, targetUser);
    var alert = {
        type: type,
        actorId: actorId,
        createdAt: formatDateTime(new Date()),
        read: false
    };
    if (commentPreview) alert.commentPreview = commentPreview;
    alerts.push(alert);
    while (alerts.length > GLOBAL_CONFIG.petHomeActivity.maxAlerts) alerts.shift();
    return alert;
}

// 최근 방문자를 중복 없이 최신순으로 기록하는 함수
function updatePetHomeRecentVisitor(activityData, targetUser, visitorId) {
    var visitors = getPetHomeRecentVisitorList(activityData, targetUser);
    for (var i = visitors.length - 1; i >= 0; i--) {
        if (visitors[i] && visitors[i].visitorId === visitorId) visitors.splice(i, 1);
    }
    visitors.unshift({ visitorId: visitorId, visitedAt: formatDateTime(new Date()) });
    while (visitors.length > GLOBAL_CONFIG.petHomeActivity.maxRecentVisitors) visitors.pop();
}

// 마음표현 명령어 이름에 해당하는 설정을 반환하는 함수
function getPetHomeHeartTypeByCommand(commandName) {
    var heartTypes = GLOBAL_CONFIG.petHomeActivity.heartTypes;
    for (var i = 0; i < heartTypes.length; i++) {
        if (heartTypes[i].command === commandName) return heartTypes[i];
    }
    return null;
}

// 마음표현 키에 해당하는 설정을 반환하는 함수
function getPetHomeHeartTypeByKey(heartKey) {
    var heartTypes = GLOBAL_CONFIG.petHomeActivity.heartTypes;
    for (var i = 0; i < heartTypes.length; i++) {
        if (heartTypes[i].key === heartKey) return heartTypes[i];
    }
    return null;
}

// 기존 펫홈의 마음표현 누적값을 0 기준으로 보정하는 함수
function ensurePetHomeHeartExpressions(userHome) {
    if (!userHome.heartExpressions || typeof userHome.heartExpressions !== "object" || userHome.heartExpressions instanceof Array) {
        userHome.heartExpressions = {};
    }
    var heartTypes = GLOBAL_CONFIG.petHomeActivity.heartTypes;
    for (var i = 0; i < heartTypes.length; i++) {
        var key = heartTypes[i].key;
        var count = parseInt(userHome.heartExpressions[key], 10);
        userHome.heartExpressions[key] = isNaN(count) || count < 0 ? 0 : count;
    }
    return userHome.heartExpressions;
}

// 마음표현 일일 제한에 사용할 현재 날짜를 반환하는 함수
function getPetHomeTodayText() {
    var formatter = new java.text.SimpleDateFormat("yyyy-MM-dd");
    formatter.setTimeZone(java.util.TimeZone.getTimeZone("Asia/Seoul"));
    return String(formatter.format(new Date()));
}

// 댓글 알림에 표시할 15자 미리보기를 생성하는 함수
function getPetHomeCommentPreview(comment) {
    var text = String(comment || "");
    var maxLength = GLOBAL_CONFIG.petHomeActivity.commentPreviewMaxLength;
    return text.length > maxLength ? text.substring(0, maxLength) + "..." : text;
}

// 홈알림 상단의 다섯 마음표현 누적 영역을 생성하는 함수
function buildPetHomeHeartExpressionMessage(userHome) {
    var counts = ensurePetHomeHeartExpressions(userHome);
    var likes = Number(userHome.likeCnt) || 0;
    var total = counts.cute + counts.cheer + counts.cool + counts.love + likes; // 다섯 반응의 누적 합계
    return "💝 받은 마음 " + numberWithCommas(total) + "회\n" +
        "[🐾 " + numberWithCommas(counts.cute) + "] [⭐ " + numberWithCommas(counts.cheer) + "] [✨ " + numberWithCommas(counts.cool) + "]\n" +
        "[💖 " + numberWithCommas(counts.love) + "] [💌 " + numberWithCommas(likes) + "]\n";
}

// 다른 유저의 행동으로 생성된 홈알림인지 확인하는 함수
function isPetHomeActorActivityAlert(alert) {
    if (!alert || typeof alert.type !== "string") return false;
    if (alert.type === "comment" || alert.type === "home_like" || alert.type === "follow" || alert.type === "unfollow" || alert.type === "feed") return true;
    return alert.type.indexOf("heart_") === 0;
}

// 홈알림 작성자의 현재 대표 뱃지를 알림용 형식으로 반환하는 함수
function getPetHomeAlertActorBadgeText(activityData, alert) {
    if (!isPetHomeActorActivityAlert(alert) || !alert.actorId || !activityData.petHomeSocial.hasOwnProperty(alert.actorId)) return "없음";
    var social = activityData.petHomeSocial[alert.actorId];
    var badge = getPetHomeBadgeById(social.equippedBadgeId);
    if (!badge || !petHomeStringListContains(social.badges, badge.id) || petHomeStringListContains(social.deletedBadgeIds, badge.id)) return "없음";
    return badge.emoji + " " + badge.name;
}

// 저장된 활동 유형을 홈알림 표시 문구로 변환하는 함수
function formatPetHomeActivityAlert(data, petData, guildData, alert) {
    var actorId = alert && alert.actorId ? alert.actorId : "알 수 없는 유저";
    var actorName = data.member && data.member[actorId] ? checkRank(data, petData, guildData, actorId) : (alert.actorName || actorId);
    if (alert.type === "comment") return actorName + "님이 댓글을 남겼습니다.";
    if (alert.type === "home_like") return actorName + "님이 좋아홈💌을 눌렀습니다.";
    if (alert.type === "follow") return actorName + "님이 회원님을 팔로우했습니다." + (alert.mutual ? "\n🤝 서로 팔로우 중인 맞팔 유저입니다.\n💞 맞팔 마음표현 추가 사용 가능 +1회" : "");
    if (alert.type === "unfollow") return actorName + "님이 회원님의 팔로우를 해제했습니다.";
    if (alert.type === "feed") return "📰  " + actorName + "님의 새로운 피드를 적었습니다.\n└ “" + (alert.feedContent || "내용 없음") + "”";
    if (alert.type === "badge_earned" || alert.type === "special_badge_granted" || alert.type === "special_badge_revoked") {
        var badge = getPetHomeBadgeById(alert.badgeId);
        var badgeText = badge ? badge.emoji + " " + badge.name : (alert.badgeId || "알 수 없는 뱃지");
        if (alert.type === "special_badge_granted") return "특별 펫홈 뱃지 " + badgeText + "를 지급받았습니다.";
        if (alert.type === "special_badge_revoked") return "특별 펫홈 뱃지 " + badgeText + "가 회수되었습니다.";
        return "새로운 펫홈 뱃지 " + badgeText + "를 획득했습니다.";
    }
    var heartKey = String(alert.type || "").replace(/^heart_/, "");
    var heartType = getPetHomeHeartTypeByKey(heartKey);
    if (heartType) return actorName + "님이 " + heartType.label + heartType.emoji + (alert.count && alert.count > 1 ? " x" + alert.count : "") + "를 남겼습니다.";
    return actorName + "님의 펫홈 활동이 있습니다.";
}

// 홈알림·누적 방문·방문 뱃지와 받은 마음 정보를 생성하는 함수
function buildPetHomeActivityMessage(data, petData, petSkillData, guildData, sender, activityData, homeData) {
    var alerts = getPetHomeAlertList(activityData, sender);
    var visitors = getPetHomeRecentVisitorList(activityData, sender);
    var social = getPetHomeSocialUser(activityData, sender);
    var mutualCount = getPetHomeMutualUsers(activityData, sender).length; // 현재 보존된 맞팔 관계 수
    var heartStatus = getPetHomeHeartUsageStatus(data, petSkillData, activityData, homeData, sender); // 활성 패스 기준 오늘 마음 사용 현황
    var followerDisplayCount = social.followers.length + getPetSkillFollowerBonus(petSkillData, sender); // 실제 팔로워와 장착 스킬 보너스 합계
    var unreadCount = 0; // 아직 확인하지 않은 활동 알림 개수
    for (var i = 0; i < alerts.length; i++) {
        if (alerts[i] && alerts[i].read !== true) unreadCount++;
    }

    var out = getHoiPassPremiumHeader(data, sender) + "🔔 [" + checkRank(data, petData, guildData, sender) + "] 님의 홈알림\n" +
        "대표 뱃지: " + getPetHomeEquippedBadgeText(activityData, sender) + "\n" +
        "━━━━━━━━━━━━\n" +
        "팔로워🐾 " + followerDisplayCount + "명 · 팔로잉🎀 " + social.following.length + "명\n" +
        "맞팔🤝 " + mutualCount + "명 · 남은 마음💌 " + (heartStatus.unlimited ? "무제한" : heartStatus.remaining + "개") + "\n" +
        "━━━━━━━━━━━━\n" +
        buildPetHomeHeartExpressionMessage(homeData && homeData[sender] ? homeData[sender] : {}) +
        "━━━━━━━━━━━━\n" +
        "🔔 새 알림 " + unreadCount + "개 · 📭 보관 [" + alerts.length + "/" + GLOBAL_CONFIG.petHomeActivity.maxAlerts + "]\n" +
        "👣 최근 방문자 [" + visitors.length + "/" + GLOBAL_CONFIG.petHomeActivity.maxRecentVisitors + "명]\n" +
        allsee + "\n\n";

    out += "🔔 최근 활동 알림\n━━━━━━━━━━━━\n";
    if (alerts.length === 0) {
        out += "등록된 활동 알림이 없습니다.\n";
    } else {
        for (var alertIndex = alerts.length - 1, alertNo = 1; alertIndex >= 0; alertIndex--, alertNo++) {
            var alert = alerts[alertIndex];
            if (isPetHomeActorActivityAlert(alert)) {
                out += "[" + alertNo + "] 대표 뱃지: [" + getPetHomeAlertActorBadgeText(activityData, alert) + "]\n";
                out += formatPetHomeActivityAlert(data, petData, guildData, alert) + "\n";
            } else {
                out += "[" + alertNo + "] " + formatPetHomeActivityAlert(data, petData, guildData, alert) + "\n";
            }
            if (alert.type === "comment" && alert.commentPreview) out += "💬 “" + alert.commentPreview + "”\n";
            out += "└ " + (alert.createdAt || "시간 정보 없음") + "\n\n";
        }
    }

    out += "\n\n" + buildPetHomeFollowListMessage(data, petData, guildData, activityData, sender, "followers", false) + "\n\n";
    out += buildPetHomeFollowListMessage(data, petData, guildData, activityData, sender, "following", false) + "\n\n";
    out += "👣 최근 방문자\n━━━━━━━━━━━━\n";
    if (visitors.length === 0) out += "등록된 최근 방문자가 없습니다.\n";
    else {
        for (var visitorIndex = 0; visitorIndex < visitors.length; visitorIndex++) {
            var visitor = visitors[visitorIndex] || {};
            var visitorId = visitor.visitorId || "알 수 없는 유저";
            var visitorName = data.member && data.member[visitorId] ? checkRank(data, petData, guildData, visitorId) : visitorId;
            out += (visitorIndex + 1) + ". " + visitorName + " ─ " + (visitor.visitedAt || "시간 정보 없음") + "\n";
        }
    }
    out += "\n누적 방문👣 " + numberWithCommas(homeData && homeData[sender] ? homeData[sender].visitCnt || 0 : 0) + "회\n" +
        buildPetHomeVisitBadgeMessage(activityData, sender);
    return out.trim();
}

// 현재 보관된 펫홈 활동 알림을 모두 읽음 처리하는 함수
function markPetHomeAlertsRead(activityData, user) {
    var alerts = getPetHomeAlertList(activityData, user);
    for (var i = 0; i < alerts.length; i++) {
        if (alerts[i]) alerts[i].read = true;
    }
}

// 모든 일반 댓글을 삭제하고 댓글핀 보존 수량을 집계하는 함수
function clearPetHomeCommentsPreservingPins(commentsData) {
    commentsData = initPetHomeCommentsData(commentsData);
    var result = { removedCommentCount: 0, preservedPinnedCount: 0, removedUsers: [] };
    for (var commentUser in commentsData.comments) {
        if (!commentsData.comments.hasOwnProperty(commentUser)) continue;
        if (!(commentsData.comments[commentUser] instanceof Array)) continue;
        var commentCount = commentsData.comments[commentUser].length;
        result.removedCommentCount += commentCount;
        if (commentCount > 0) result.removedUsers.push({ user: commentUser, count: commentCount });
    }
    for (var pinnedUser in commentsData.pinnedComments) {
        if (!commentsData.pinnedComments.hasOwnProperty(pinnedUser)) continue;
        if (commentsData.pinnedComments[pinnedUser] instanceof Array) result.preservedPinnedCount += commentsData.pinnedComments[pinnedUser].length;
    }
    commentsData.comments = {};
    return result;
}

// 패스 혜택 개편을 위해 일반 댓글과 좋아홈 수치를 한 번 정리하는 함수
function cleanupPetHomePassBenefitData(homeData, commentsData) {
    commentsData = initPetHomeCommentsData(commentsData);
    if (!commentsData.migrations || typeof commentsData.migrations !== "object") commentsData.migrations = {};
    var result = { changed: false, alreadyApplied: false, removedCommentCount: 0, preservedPinnedCount: 0, resetLikeUserCount: 0, resetLikeCount: 0 };
    if (commentsData.migrations.passBenefits20260726 === true) {
        result.alreadyApplied = true;
        return result;
    }

    var commentCleanupResult = clearPetHomeCommentsPreservingPins(commentsData);
    result.removedCommentCount = commentCleanupResult.removedCommentCount;
    result.preservedPinnedCount = commentCleanupResult.preservedPinnedCount;

    if (homeData && typeof homeData === "object") {
        for (var homeUser in homeData) {
            if (!homeData.hasOwnProperty(homeUser)) continue;
            if (!homeData[homeUser] || homeData[homeUser].likeCnt === undefined) continue;
            result.resetLikeUserCount++;
            result.resetLikeCount += parseInt(homeData[homeUser].likeCnt, 10) || 0;
            delete homeData[homeUser].likeCnt;
        }
    }

    commentsData.migrations.passBenefits20260726 = true;
    result.changed = true;
    return result;
}

// 펫홈 소셜 유저 데이터를 롤백용으로 복사하는 함수
function snapshotPetHomeSocialUser(activityData, user) {
    activityData = requirePetHomeActivityData(activityData);
    return {
        existed: activityData.petHomeSocial.hasOwnProperty(user),
        value: activityData.petHomeSocial.hasOwnProperty(user) ? JSON.parse(JSON.stringify(activityData.petHomeSocial[user])) : null
    };
}

// 롤백용 복사본으로 펫홈 소셜 유저 데이터를 복원하는 함수
function restorePetHomeSocialUser(activityData, user, snapshot) {
    if (snapshot.existed) activityData.petHomeSocial[user] = snapshot.value;
    else delete activityData.petHomeSocial[user];
}

// 기존 펫홈 마음표현 누적 합계를 계산하는 함수
function getPetHomeReactionTotal(userHome) {
    var counts = ensurePetHomeHeartExpressions(userHome);
    return (counts.cute || 0) + (counts.cheer || 0) + (counts.cool || 0) + (counts.love || 0);
}

// 기존 펫홈 데이터에서 소셜 뱃지 누적값을 한 번 초기화하는 함수
function migratePetHomeSocialBadges(data, homeData, commentsData, activityData) {
    activityData = requirePetHomeActivityData(activityData);
    commentsData = initPetHomeCommentsData(commentsData);
    var result = { alreadyApplied: false, userCount: 0, badgeCount: 0 };
    if (activityData.migrations.petHomeSocialBadges20260727 === true) {
        result.alreadyApplied = true;
        return result;
    }
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user) || !data.member || !data.member[user]) continue;
        var userHome = homeData[user] || {};
        var comments = getPetHomeCommentList(commentsData, user);
        raisePetHomeBadgeStat(activityData, user, "receivedComments", comments.length);
        raisePetHomeBadgeStat(activityData, user, "receivedHomeLikes", parseInt(userHome.likeCnt, 10) || 0);
        raisePetHomeBadgeStat(activityData, user, "receivedReactions", getPetHomeReactionTotal(userHome));
        raisePetHomeBadgeStat(activityData, user, "totalVisits", parseInt(userHome.visitCnt, 10) || 0);
        result.badgeCount += awardPetHomeAchievementBadges(activityData, user).length;
        result.userCount++;
    }
    activityData.migrations.petHomeSocialBadges20260727 = true;
    return result;
}

// 계정 삭제 시 펫홈 소셜 관계와 활동 흔적을 정리하는 함수
function removePetHomeActivityUserOnAccountDelete(activityData, user) {
    activityData = requirePetHomeActivityData(activityData);
    delete activityData.petHomeSocial[user];
    delete activityData.alerts[user];
    delete activityData.recentVisitors[user];
    for (var owner in activityData.petHomeSocial) {
        if (!activityData.petHomeSocial.hasOwnProperty(owner)) continue;
        var social = activityData.petHomeSocial[owner];
        removePetHomeStringListValue(social.followers, user);
        removePetHomeStringListValue(social.following, user);
    }
    for (var alertOwner in activityData.alerts) {
        if (!activityData.alerts.hasOwnProperty(alertOwner)) continue;
        var alerts = activityData.alerts[alertOwner];
        for (var alertIndex = alerts.length - 1; alertIndex >= 0; alertIndex--) {
            if (alerts[alertIndex] && alerts[alertIndex].actorId === user) alerts.splice(alertIndex, 1);
        }
    }
    for (var visitorOwner in activityData.recentVisitors) {
        if (!activityData.recentVisitors.hasOwnProperty(visitorOwner)) continue;
        var visitors = activityData.recentVisitors[visitorOwner];
        for (var visitorIndex = visitors.length - 1; visitorIndex >= 0; visitorIndex--) {
            if (visitors[visitorIndex] && visitors[visitorIndex].visitorId === user) visitors.splice(visitorIndex, 1);
        }
    }
    return activityData;
}

// 복수 마음표현을 대상 펫홈 누적값에 반영하고 유형별 수량을 반환하는 함수
function applyPetHomeHeartExpressions(userHome, commandName, count) {
    var counts = ensurePetHomeHeartExpressions(userHome);
    var allocations = {};
    var heartTypes = GLOBAL_CONFIG.petHomeActivity.heartTypes;
    for (var i = 0; i < count; i++) {
        var heartType = commandName === "마음" ? heartTypes[Math.floor(Math.random() * heartTypes.length)] : getPetHomeHeartTypeByCommand(commandName);
        counts[heartType.key] += 1;
        allocations[heartType.key] = (allocations[heartType.key] || 0) + 1;
    }
    return allocations;
}

// 유형별 마음표현 수량을 펫홈 활동 알림으로 기록하는 함수
function addPetHomeHeartAllocationAlerts(activityData, targetUser, actorId, allocations) {
    for (var key in allocations) {
        if (!allocations.hasOwnProperty(key)) continue;
        var heartType = getPetHomeHeartTypeByKey(key);
        if (!heartType) continue;
        var alert = addPetHomeActivityAlert(activityData, targetUser, heartType.alertType, actorId, "");
        alert.count = allocations[key];
    }
}

// 유형별 마음표현 결과를 사용자 안내 문구로 변환하는 함수
function buildPetHomeHeartAllocationText(allocations) {
    var parts = [];
    var heartTypes = GLOBAL_CONFIG.petHomeActivity.heartTypes;
    for (var i = 0; i < heartTypes.length; i++) {
        var count = allocations[heartTypes[i].key] || 0;
        if (count > 0) parts.push(heartTypes[i].label + heartTypes[i].emoji + " x" + count);
    }
    return parts.join(" | ");
}

// 특정 유저의 펫홈 댓글 목록을 반환하는 함수
function getPetHomeCommentList(commentsData, user) {
    commentsData = initPetHomeCommentsData(commentsData);
    if (!(commentsData.comments[user] instanceof Array)) commentsData.comments[user] = [];
    return commentsData.comments[user];
}

// 특정 유저의 펫홈 핀 댓글 목록을 반환하는 함수
function getPetHomePinnedCommentList(commentsData, user) {
    commentsData = initPetHomeCommentsData(commentsData);
    if (!(commentsData.pinnedComments[user] instanceof Array)) commentsData.pinnedComments[user] = [];
    return commentsData.pinnedComments[user];
}

// 펫홈 댓글 동일 여부를 판정하는 함수
function isSamePetHomeComment(a, b) {
    if (!a || !b) return false;
    return a.from === b.from && a.text === b.text && a.time === b.time;
}

// 펫홈 댓글이 핀 목록에 포함되어 있는지 확인하는 함수
function isPinnedPetHomeComment(comment, pinnedComments) {
    if (!(pinnedComments instanceof Array)) return false;
    for (var i = 0; i < pinnedComments.length; i++) {
        if (isSamePetHomeComment(comment, pinnedComments[i])) return true;
    }
    return false;
}

// 별채별 현재 성장 상태와 다음 면적 안내를 생성하는 함수
function buildPetHomeVillageStatus(homeData, petSkillData, user, detail, charm) {
    var home = homeData[user];
    if (!charm) charm = getPetHomeFurnitureCharm(homeData, petSkillData, user);
    var limit = getPetHomeVillageLevelLimit(home), config = GLOBAL_CONFIG.petHomeVillage;
    var out = "🏛️ 루미에르 빌리지\n📐 " + (Number(home.floor) || 0) + "평 · 각 별채 Lv." + limit + "까지\n💞 빌리지 종매 버프 +" + charm.percent + "% 적용 중\n";
    var keys = ["grand", "royal", "arcana"], labels = ["🏠 그랑 별채", "🏰 로열 별채", "👑 아르카나 별채"];
    for (var i = 0; i < keys.length; i++) {
        var state = charm.state[keys[i]], locked = state.level >= limit;
        out += labels[i] + " · Lv." + state.level + " · [📦" + state.progress + "/" + config.materialsPerLevel + "]" + (locked ? " · 🔒 집 확장 필요" : "") + "\n";
        if (detail) out += "└ 레벨당 +" + config[keys[i] + "Percent"] + "%p · 현재 +" + state.level * config[keys[i] + "Percent"] + "%\n";
        if (locked && detail) out += "└ 집 " + ((state.level + 1) * config.areaPerLevel) + "평부터 Lv." + (state.level + 1) + " 성장 가능\n";
    }
    return out.trim();
}

// 가구 원래 수치와 등급 태그를 공통 매력 이모지로 표시하는 함수
function formatPetHomeFurniture(item, includeGrade) {
    return item.name + "(+" + numberWithCommas(Number(item.exp) || 0) + "💞)" + (includeGrade && item.grade ? "[" + item.grade + "]" : "");
}

// 장착 순서를 건드리지 않고 종류별 가장 매력이 높은 가구 세 개를 표시하는 함수
function buildPetHomeVillageMessage(data, petData, petSkillData, guildData, homeData, user, placed, maxSlots) {
    var home = homeData[user], charm = getPetHomeFurnitureCharm(homeData, petSkillData, user);
    var out = "🏡 [" + checkRank(data, petData, guildData, user) + "] 님의 펫홈\n━━━━━━ ✦ ━━━━━━\n🏡 " + (home.houseName || "서울역 4번출구🚉") + " [+" + (home.floor || 0) + "평]\n💞 가구 종합매력 +" + numberWithCommas(charm.total) + "\n────── ✧ ──────\n";
    out += buildPetHomeVillageStatus(homeData, petSkillData, user, false, charm) + "\n━━━━━━ ✦ ━━━━━━\n✨ 우리 집 자랑 가구 TOP " + GLOBAL_CONFIG.petHomeDisplay.furniturePreviewCount + "(🪑" + placed.length + "/" + maxSlots + ")\n\n";
    var sorted = sortFurnitureList(placed.slice(0)), seen = {}, count = 0;
    for (var i = 0; i < sorted.length && count < GLOBAL_CONFIG.petHomeDisplay.furniturePreviewCount; i++) {
        var key = "$" + sorted[i].name;
        if (Object.prototype.hasOwnProperty.call(seen, key)) continue;
        seen[key] = true;
        out += (++count) + ". " + formatPetHomeFurniture(sorted[i], false) + "\n";
    }
    if (count === 0) out += "🪑 아직 장착한 가구가 없어요.\n";
    return out + "🔎 가구·별채 상세: /가구정보 " + user;
}

// 발동 중인 가구스킬만 기존 판정과 동일한 기준으로 설명하는 함수
function buildPetHomeFurnitureSkillMessage(petSkillData, homeData, user, charm) {
    var lines = [];
    if (charm.royal) lines.push("로열 하우스📙 · 종매 +" + numberWithCommas(charm.royal * 2) + "💞\n└ 로열 가구 10개 이상 장착 시 적용");
    if (charm.arcana) lines.push("아르카나 하우스📙 · 종매 +" + numberWithCommas(charm.arcana * 2) + "💞\n└ 아르카나 가구 5개 이상 보유 시 적용");
    if (hasPetSkill(petSkillData, user, "인테리어 장인")) lines.push("인테리어 장인📙 · 기존 10% 효과 유지\n└ 추가 종매 +" + numberWithCommas(charm.interior * 2) + "💞 · 별채 버프 제외");
    if (hasPetSkill(petSkillData, user, GLOBAL_CONFIG.petHomeVillage.dreamSkillName)) lines.push("느그 집 마련의 꿈📙 · 별채 합산 버프 +10%p\n└ 빌리지 버프에 포함 · 해제 시 10%p 제거");
    if (hasPetSkill(petSkillData, user, "건물주")) lines.push("건물주📙 · 장착 +10칸");
    else if (hasPetSkill(petSkillData, user, "하느님 위에 갓물주")) lines.push("하느님 위에 갓물주📙 · 장착 +15칸");
    if (hasPetSkill(petSkillData, user, "베란다 확장")) lines.push("베란다 확장📙[한정판] · 장착 +" + GLOBAL_CONFIG.petSkill.verandaFurnitureSlotBonus + "칸\n└ 해제 시 추가 장착 칸 회수");
    if (hasPetSkill(petSkillData, user, GLOBAL_CONFIG.petSkill.largeVerandaSkillName)) lines.push("베란다 대확장📙[한정판] · 장착 +" + GLOBAL_CONFIG.petSkill.largeVerandaFurnitureSlotBonus + "칸\n└ 소멸 시 초과한 하단 가구는 가방으로 반환");
    return lines.length ? "📙 적용 중인 가구스킬\n" + lines.join("\n\n") + "\n\n※ 매력은 빌리지 버프 적용 전 수치입니다.\n━━━━━━ ✦ ━━━━━━\n" : "";
}

// 대상 유저의 최종 매력·계산·스킬 다음에 원래 번호의 장착 목록을 표시하는 함수
function buildPetHomeFurnitureInfoMessage(data, petData, petSkillData, guildData, homeData, user, viewer, placed) {
    var home = homeData[user], charm = getPetHomeFurnitureCharm(homeData, petSkillData, user);
    var limit = getFurnitureMaxSlots(data, petData, user, home.floor || 0, petSkillData);
    var out = "🪑 [" + checkRank(data, petData, guildData, user) + "] 님의 가구정보\n━━━━━━ ✦ ━━━━━━\n🏡 " + (home.houseName || "서울역 4번출구🚉") + " [+" + (home.floor || 0) + "평]\n🪑 가구 장착 " + placed.length + "/" + limit + "\n\n";
    out += "💞 가구 종합매력 +" + numberWithCommas(charm.total) + "\n⚔️ 캐슬매력 +" + numberWithCommas(charm.castle) + "\n└ 평수 보너스 +" + numberWithCommas(charm.floorApplied) + "\n👾 레이드매력 +" + numberWithCommas(charm.raid) + "\n└ 평수 보너스 +" + numberWithCommas(charm.floorApplied) + "\n────── ✧ ──────\n";
    out += buildPetHomeVillageStatus(homeData, petSkillData, user, true, charm) + "\n━━━━━━ ✦ ━━━━━━\n📖 계산·스킬·장착 상세\n" + allsee + "\n📊 종매 계산\n💡 가구 매력은 캐슬·레이드에 각각 적용돼요.\n예) 가구 매력 10만\n⚔️ 캐슬 +10만 · 👾 레이드 +10만\n└ 💞 가구 종매 +20만\n\n";
    out += "🪑 장착 가구 종매 +" + numberWithCommas(charm.furniture * 2) + "💞\n📙 가구스킬 종매 +" + numberWithCommas((charm.royal + charm.arcana) * 2) + "💞\n└ 기본 합계 " + numberWithCommas(charm.base * 2) + "💞\n🏛️ 기본 합계의 " + charm.percent + "% 추가 → +" + numberWithCommas(charm.villageBonus * 2) + "💞\n";
    if (charm.interior) out += "📙 인테리어 장인 추가 +" + numberWithCommas(charm.interior * 2) + "💞 · 별채 버프 제외\n";
    out += "📐 펫홈 평수 보너스\n보유 평수: " + (home.floor || 0) + "평\n⚔️ 캐슬매력: " + (home.floor || 0) + " × " + numberWithCommas(GLOBAL_CONFIG.petHomeFloor.perMode) + " = +" + numberWithCommas(charm.floor) + " → +" + numberWithCommas(charm.floorApplied) + "\n👾 레이드매력: " + (home.floor || 0) + " × " + numberWithCommas(GLOBAL_CONFIG.petHomeFloor.perMode) + " = +" + numberWithCommas(charm.floor) + " → +" + numberWithCommas(charm.floorApplied) + "\n💞 평수 보너스 합계: +" + numberWithCommas(charm.floorApplied * 2) + "\n";
    out += "💞 최종 가구 종합매력 +" + numberWithCommas(charm.total) + "\n━━━━━━ ✦ ━━━━━━\n";
    out += buildPetHomeFurnitureSkillMessage(petSkillData, homeData, user, charm);
    var villageConfig = GLOBAL_CONFIG.petHomeVillage;
    out += "📦 별채 성장 안내\n🏠 그랑 가구 " + villageConfig.materialsPerLevel + "개 → Lv.+1 · 버프 +" + villageConfig.grandPercent + "%p\n🏰 로열 가구 " + villageConfig.materialsPerLevel + "개 → Lv.+1 · 버프 +" + villageConfig.royalPercent + "%p\n👑 아르카나 가구 " + villageConfig.materialsPerLevel + "개 → Lv.+1 · 버프 +" + villageConfig.arcanaPercent + "%p\n📐 집 " + villageConfig.areaPerLevel + "평당 성장 가능 레벨 +1\n\n※ 버프는 평수·장착 가구·가구스킬 종매의 합계에 적용됩니다.\n※ 인테리어 장인 추가분은 별채 버프에서 제외됩니다.\n※ 별채 레벨·%는 유지되며, 추가 매력은 현재 가구·스킬에 따라 달라집니다.\n";
    if (viewer === user) out += "────── ✧ ──────\n🎒 가구 확인: /가구가방\n📥 /별채등록 [가구가방번호] …\n미장착 그랑·로열·아르카나 가구 최대 10개\n";
    out += "━━━━━━ ✦ ━━━━━━\n🪑 전체 장착 가구 (" + placed.length + "/" + limit + ")\n💞 기본 수치 · 캐슬·레이드에 각각 적용\n※ 빌리지 버프 적용 전 가구 자체 수치입니다.\n────── ✧ ──────\n";
    if (placed.length === 0) out += "🪑 아직 장착한 가구가 없어요.\n";
    for (var i = 0; i < placed.length; i++) out += (i + 1) + ". " + formatPetHomeFurniture(placed[i], true) + "\n";
    return out.trim();
}

// 가방 번호와 관리 안내를 유지하고 별채 등록 안내를 추가하는 함수
function buildPetHomeFurnitureBagMessage(data, petData, petSkillData, guildData, homeData, user) {
    var home = homeData[user], bag = home.furnitureBag;
    var out = getHoiPassPremiumHeader(data, user) + "[" + checkRank(data, petData, guildData, user) + "] 가구 가방🛌 [" + bag.length + "/" + getFurnitureBagLimit(data, user) + "]\n";
    out += "📥 /별채등록 [가구가방번호] …\n미장착 그랑·로열·아르카나 가구 최대 10개\n━━━━━━ ✦ ━━━━━━\n※ 가구 장착: /가구장착 [번호]\n※ 1번 장착 예시: /가구장착 1\n※ 적용 매력 확인: /가구정보\n※ 가구 판매: /가구판매 [번호]\n※ 장착 가구판매: /집청소 [번호]\n※ 장착 귀속해제: /가구해제 [번호]\n━━━━━━ ✦ ━━━━━━\n✧━인벤토리 가구 목록🪑━✧\n";
    if (bag.length === 0) out += "[가방에 보유 중인 가구 없음]\n";
    for (var i = 0; i < bag.length; i++) {
        if (i === 3) out += allsee + "\n";
        out += (i + 1) + ". " + formatPetHomeFurniture(bag[i], true) + "\n";
    }
    return out + "━━━━━━ ✦ ━━━━━━" + (bag.length <= 3 ? allsee : "");
}

// 방문 누적을 이용하는 기존 방문 뱃지의 획득·진행 정보를 표시하는 함수
function buildPetHomeVisitBadgeMessage(activityData, user) {
    var social = getPetHomeSocialUser(activityData, user), badges = GLOBAL_CONFIG.petHomeActivity.achievementBadges, lines = [];
    for (var i = 0; i < badges.length; i++) {
        var badge = badges[i];
        if (badge.stat !== "totalVisits" && !(badge.requirements && badge.requirements.totalVisits)) continue;
        var owned = petHomeStringListContains(social.badges, badge.id);
        lines.push(badge.emoji + " " + badge.name + " [" + badge.id + "] · " + (owned ? "획득" : "누적 방문 " + numberWithCommas(social.badgeStats.totalVisits) + "/" + numberWithCommas(badge.threshold || badge.requirements.totalVisits) + "회"));
    }
    return "🏅 방문 뱃지\n" + lines.join("\n");
}

// 확인 요청의 가방 개체와 예상 효과를 재검증하고 등록 후 상태를 계산하는 함수
function preparePetHomeVillageRegistration(homeData, petSkillData, user, numbers, placed) {
    var config = GLOBAL_CONFIG.petHomeVillage, home = homeData[user], selected = [], counts = { grand: 0, royal: 0, arcana: 0 }, used = {};
    if (numbers.length < 1 || numbers.length > config.maxRegister) return { error: "한 번에 가구가방 번호를 1~" + config.maxRegister + "개 입력해주세요." };
    var bag = home.furnitureBag, state = getPetHomeVillageState(home), limit = getPetHomeVillageLevelLimit(home);
    for (var i = 0; i < numbers.length; i++) {
        var number = numbers[i], item = bag[number - 1];
        if (!isFinite(number) || number < 1 || Math.floor(number) !== number || !item) return { error: "가방 " + number + "번을 확인해주세요. 미장착 그랑·로열·아르카나만 등록할 수 있어요." };
        if (used[number]) return { error: "같은 가구가방 번호를 중복 입력했어요." };
        used[number] = true;
        var key = item.grade === "그랑 루미에르" ? "grand" : item.grade === "로열 루미에르" ? "royal" : item.grade === "아르카나 루미에르" ? "arcana" : null;
        if (!key) return { error: "가방 " + number + "번은 등록할 수 없어요. 미장착 그랑·로열·아르카나만 가능해요." };
        for (var p = 0; p < placed.length; p++) if (item.id !== undefined && String(item.id) === String(placed[p].id)) return { error: "가방 " + number + "번의 장착 상태를 확인해주세요." };
        counts[key]++;
        selected.push({ number: number, key: key, item: item });
    }
    var keys = ["grand", "royal", "arcana"], labels = ["그랑", "로열", "아르카나"];
    for (var j = 0; j < keys.length; j++) {
        var key = keys[j], remaining = Math.max(0, (limit - state[key].level) * config.materialsPerLevel - state[key].progress);
        if (counts[key] > remaining) return { error: labels[j] + " 가구는 현재 " + remaining + "개까지 추가 등록할 수 있어요. 집을 확장하면 더 성장할 수 있어요.\n모든 가구는 소모되지 않았어요." };
    }
    var afterHome = JSON.parse(JSON.stringify(home)), afterData = {};
    afterData[user] = afterHome;
    afterHome.lumiereVillage = getPetHomeVillageState(home);
    var descending = numbers.slice(0).sort(function (a, b) { return b - a; });
    for (var d = 0; d < descending.length; d++) afterHome.furnitureBag.splice(descending[d] - 1, 1);
    for (var k = 0; k < keys.length; k++) {
        var key = keys[k], value = afterHome.lumiereVillage[key], total = value.progress + counts[key];
        value.level += Math.floor(total / config.materialsPerLevel);
        value.progress = total % config.materialsPerLevel;
    }
    var before = getPetHomeFurnitureCharm(homeData, petSkillData, user), after = getPetHomeFurnitureCharm(afterData, petSkillData, user);
    return { selected: selected, counts: counts, before: before, after: after, home: afterHome,
        bagFingerprint: JSON.stringify(bag), effectFingerprint: JSON.stringify({ floor: home.floor, before: before, after: after, skills: getEquippedPetSkillNames(petSkillData, user) }) };
}

// 가구 소모로 발동 조건이 해제되는 스킬을 안내하는 함수
function buildPetHomeVillageLostSkillMessage(result) {
    var lines = [];
    if (result.before.royal && !result.after.royal) lines.push("로열 하우스📙");
    if (result.before.arcana && !result.after.arcana) lines.push("아르카나 하우스📙");
    return lines.length ? "\n⚠️ 가구 소모 시 " + lines.join("·") + "의 조건이 해제됩니다.\n예상·최종 매력에 스킬 효과 해제를 반영했습니다.\n" : "";
}

// 별채 등록 확인과 저장 완료 후 실제 순변동 메시지를 생성하는 함수
function buildPetHomeVillageRegistrationMessage(header, result, completed) {
    var out = header + "\n" + (completed ? "✅ 별채 등록 완료 · 📦" : "📦 별채 등록 확인 · 총 ") + result.selected.length + "개\n━━━━━━ ✦ ━━━━━━\n";
    if (!completed) {
        for (var i = 0; i < result.selected.length; i++) {
            var row = result.selected[i];
            out += (row.key === "grand" ? "🏠" : row.key === "royal" ? "🏰" : "👑") + " 가방 " + row.number + "번 · " + formatPetHomeFurniture(row.item, false) + "\n";
        }
    } else {
        var keys = ["grand", "royal", "arcana"], labels = ["🏠 그랑 별채", "🏰 로열 별채", "👑 아르카나 별채"];
        for (var j = 0; j < keys.length; j++) {
            var key = keys[j];
            if (!result.counts[key]) continue;
            var before = result.before.state[key], after = result.after.state[key];
            out += labels[j] + " · Lv." + after.level + " · " + (after.level >= getPetHomeVillageLevelLimit(result.home) ? "🔒 집 확장 필요" : "[📦" + after.progress + "/10]") + "\n";
            var rate = GLOBAL_CONFIG.petHomeVillage[key + "Percent"];
            if (after.level > before.level) out += "🎉 레벨업! 누적 +" + before.level * rate + "% → +" + after.level * rate + "%\n";
        }
    }
    out += "────── ✧ ──────\n✨ 빌리지 버프 +" + result.before.percent + "% → +" + result.after.percent + "%\n";
    out += completed ? "💞 가구 종합매력 +" + numberWithCommas(result.after.total) + "\n" : "💞 예상 종합매력 " + numberWithCommas(result.before.total) + " → " + numberWithCommas(result.after.total) + "\n";
    out += buildPetHomeVillageLostSkillMessage(result);
    if (!completed) return out + "\n⚠️ 등록한 가구는 소모되며 복구할 수 없어요.\n등록한다 / 등록안한다\n60초 안에 입력해주세요.";
    var delta = result.after.total - result.before.total;
    if (delta !== 0) out += (delta < 0 ? "📉 이번 감소 " : "📈 이번 증가 +") + numberWithCommas(delta) + "💞\n";
    if (result.before.percent === result.after.percent) out += "📦 같은 등급 가구 10개를 모으면 레벨업해요.\n";
    return out + "\n🔎 상세 확인: /가구정보";
}

// 펫홈 댓글을 핀 댓글 보호 후 최대 보관 개수에 맞춰 정리하는 함수
function trimPetHomeComments(comments, pinnedComments) {
    var excess = comments.length - GLOBAL_CONFIG.petHomeComments.maxStored;
    if (excess > 0) comments.splice(0, excess);
}

// 펫홈 댓글 확인 메시지를 생성하는 함수
function buildPetHomeCommentsMessage(data, petData, guildData, targetName, comments, pinnedComments, embedded) {
    var out = (embedded ? "" : "[" + checkRank(data, petData, guildData, targetName) + "] 님의 방명록\n") + "✍️ 방명록 · 댓글 " + comments.length + "개\n";
    if (comments.length === 0 && pinnedComments.length === 0) return out + "아직 작성된 댓글이 없어요.";
    if (pinnedComments.length > 0) {
        out += "❤️ 집주인이 좋아하는 댓글\n";
        for (var i = 0; i < pinnedComments.length; i++) {
            var pin = pinnedComments[i];
            out += (i + 1) + ". 📌 [" + checkRank(data, petData, guildData, pin.from) + "]: " + pin.text + "\n";
            if (i === 0) out += allsee + "\n";
        }
    } else out += allsee + "\n";
    if (comments.length > 0) out += "────── ✧ ──────\n💬 최근 방명록 댓글\n";
    for (var j = comments.length - 1; j >= 0; j--) {
        var comment = comments[j];
        out += (comments.length - j) + ". [" + checkRank(data, petData, guildData, comment.from) + "]: " + comment.text + "\n";
    }
    return out.trim();
}

// 펫스윗홈
function initSweetHomeUser(homeData, user) {
    if (!homeData || typeof homeData !== "object") homeData = {};
    if (!homeData[user]) {
        homeData[user] = {
            floor: 0,
            houseName: "서울역 4번출구🚉",
            exp: 0,
            placedFurnitureSummary: {
                count: 0,
                totalExp: 0,
                royalLumiereCount: 0,
                gradeCounts: {}
            },
            furnitureBag: [],
            visitCnt: 0,
            likeCnt: 0
        };
    }
    if (!homeData[user].placedFurnitureSummary || typeof homeData[user].placedFurnitureSummary !== "object") {
        homeData[user].placedFurnitureSummary = buildPlacedFurnitureSummary(homeData[user].placedFurniture || []);
    }
    return homeData;
}
// 다음 업그레이드 정보 찾기 (현재 floor → +1 floor)
function getNextHomeInfoByFloor(homeInfo, currentFloor) {
    currentFloor = parseInt(currentFloor, 10);
    var target = currentFloor + 1;
    for (var i = 0; i < homeInfo.homeInfo.length; i++) {
        if (homeInfo.homeInfo[i].floor == target) return homeInfo.homeInfo[i];
    }
    return null;
}
// 필요 재료 텍스트 생성
function formatRequired(required) {
    if (!required || !required.length) return "없음";
    var parts = [];
    for (var i = 0; i < required.length; i++) {
        parts.push(required[i].item + " " + required[i].count + "개");
    }
    return parts.join(" ");
}
// 재료 부족 계산 (inventory에서 수량 조회)
function diffRequired(inventoryGetter, user, required) {
    var lacking = [];
    for (var i = 0; i < required.length; i++) {
        var need = required[i];
        var have = inventoryGetter(user, need.item) || 0;
        if (have < need.count) {
            lacking.push({
                item: need.item,
                need: need.count,
                lack: need.count - have
            });
        }
    }
    return lacking;
}
// floor로 집정보 찾기
function findHomeInfoByFloor(homeInfo, floor) {
    for (var i = 0; i < homeInfo.homeInfo.length; i++) {
        if (homeInfo.homeInfo[i].floor == floor) return homeInfo.homeInfo[i];
    }
    return null;
}
function getPetSweetHomeRanking(homeData, data, petData, guildData) {
    let ranking = [];
    for (let user in homeData) {
        let floor = homeData[user].floor;
        ranking.push({
            user: user,
            exp: homeData[user].exp,
            houseName: homeData[user].houseName,
            floor: floor
        });
    }
    ranking.sort(function (a, b) {
        if (b.floor !== a.floor) return b.floor - a.floor;
        return a.user.localeCompare(b.user, "ko");
    });
    let message = "🏡 펫스윗홈 순위 🏡\n따라 따라 다~🎵 따라 라리 라라~🎵\n(펫스윗 홈의 평수 순위입니다)\n\n";
    for (let i = 0; i < ranking.length; i++) {
        if (i === 10 && typeof allsee !== "undefined") {
            message += allsee;
        }
        let r = ranking[i];
        let rankName = checkRank(data, petData, guildData, r.user);
        message += i + 1 + "위 [" + rankName + "] : 🏡 " + r.houseName + "(+" + r.exp + "💕)[+" + r.floor + "평] \n";
        ranking[i].rank = i + 1;
        ranking[i].rankName = rankName;
    }
    return {
        message: message.trim(),
        ranking: ranking
    };
}
//
// 베란다 확장 스킬별 가구 슬롯 보너스를 반환하는 함수
function getVerandaFurnitureSlotBonus(skillName) {
    skillName = normalizePetSkillName(skillName);
    if (skillName === "베란다 확장") return GLOBAL_CONFIG.petSkill.verandaFurnitureSlotBonus;
    if (skillName === GLOBAL_CONFIG.petSkill.largeVerandaSkillName) return GLOBAL_CONFIG.petSkill.largeVerandaFurnitureSlotBonus;
    return 0;
}

// 평수와 장착 효과를 합산해 가구 배치 가능 수를 계산하는 함수
function getFurnitureMaxSlots(data, petData, userName, floor, petSkillData) {
    floor = parseInt(floor, 10);
    if (isNaN(floor) || floor < 0) floor = 0;

    var slotSize;

    if (floor < GLOBAL_CONFIG.sweetHome.furniture.baseFloor) {
        // 0~99평: 5평마다 1개 추가
        slotSize = Math.floor(floor / GLOBAL_CONFIG.sweetHome.furniture.initialFloorStep) + 1;
    } else {
        // 100평 이상: 5평마다 1개 추가
        var baseAt100 = Math.floor(GLOBAL_CONFIG.sweetHome.furniture.baseFloor / GLOBAL_CONFIG.sweetHome.furniture.initialFloorStep) + 1; // 100평 기준 장착 수
        var extra = Math.floor((floor - GLOBAL_CONFIG.sweetHome.furniture.baseFloor) / GLOBAL_CONFIG.sweetHome.furniture.additionalFloorStep); // 기준 평수 초과분의 추가 장착 수
        slotSize = baseAt100 + extra;
    }

    // 펫 특성 보너스
    if (petData[userName]) {
        if (hasPetSkill(petSkillData, userName, "건물주")) slotSize += 10;
        else if (hasPetSkill(petSkillData, userName, "하느님 위에 갓물주")) slotSize += 15;
    }
    if (hasPetSkill(petSkillData, userName, "베란다 확장")) slotSize += GLOBAL_CONFIG.petSkill.verandaFurnitureSlotBonus;
    if (hasPetSkill(petSkillData, userName, GLOBAL_CONFIG.petSkill.largeVerandaSkillName)) slotSize += GLOBAL_CONFIG.petSkill.largeVerandaFurnitureSlotBonus;
    if (isHoiPassPremiumActive(data, userName)) slotSize += GLOBAL_CONFIG.supportPass.premium.furnitureSlotBonusCount;

    return slotSize;
}

// 베란다 확장 해제 후 초과한 하단 가구를 가구가방으로 회수하는 함수
function releaseVerandaExpansionFurniture(homeData, placedFurnitureData, userName, releaseCount) {
    homeData = initSweetHomeUser(homeData, userName);
    var userHome = homeData[userName];
    if (!Array.isArray(userHome.furnitureBag)) userHome.furnitureBag = [];
    var placedFurnitureList = placedFurnitureData ? ensurePlacedFurnitureUser(placedFurnitureData, userName) : getPlacedFurnitureList(homeData, null, userName);
    var releasedItems = [];
    sortFurnitureList(placedFurnitureList);
    while (releaseCount > 0 && placedFurnitureList.length > 0) {
        var releasedItem = placedFurnitureList.pop();
        if (releasedItem && releasedItem.placedAt !== undefined) delete releasedItem.placedAt;
        userHome.furnitureBag.push(releasedItem);
        releasedItems.push(releasedItem);
        releaseCount--;
    }
    userHome.furnitureBag = sortFurnitureList(userHome.furnitureBag);
    sortFurnitureList(placedFurnitureList);
    refreshPlacedFurnitureSummary(homeData, userName, placedFurnitureList);
    if (placedFurnitureData && userHome.placedFurniture !== undefined) delete userHome.placedFurniture;
    return releasedItems;
}

// 프리미엄 종료 후 추가 장착 한도를 넘긴 최저 매력 가구를 가구가방으로 회수하는 함수
function releaseHoiPassPremiumExtraFurniture(data, petData, petSkillData, homeData, placedFurnitureData, userName) {
    homeData = initSweetHomeUser(homeData, userName);
    var userHome = homeData[userName];
    var placedFurnitureList = placedFurnitureData ? ensurePlacedFurnitureUser(placedFurnitureData, userName) : getPlacedFurnitureList(homeData, null, userName);
    var maxSlots = getFurnitureMaxSlots(data, petData, userName, userHome.floor || 0, petSkillData);
    var releasedCount = 0;
    while (placedFurnitureList.length > maxSlots) {
        var lowestIndex = 0; // 현재 장착 가구 중 회수할 최저 매력 위치
        var lowestExp = Number(placedFurnitureList[lowestIndex] && placedFurnitureList[lowestIndex].exp) || 0;
        for (var i = 1; i < placedFurnitureList.length; i++) {
            var furnitureExp = Number(placedFurnitureList[i] && placedFurnitureList[i].exp) || 0;
            if (furnitureExp < lowestExp) {
                lowestIndex = i;
                lowestExp = furnitureExp;
            }
        }
        var releasedItem = placedFurnitureList.splice(lowestIndex, 1)[0];
        if (releasedItem && releasedItem.placedAt !== undefined) delete releasedItem.placedAt;
        userHome.furnitureBag.push(releasedItem);
        releasedCount++;
    }
    userHome.furnitureBag = sortFurnitureList(userHome.furnitureBag);
    sortFurnitureList(placedFurnitureList);
    refreshPlacedFurnitureSummary(homeData, userName, placedFurnitureList);
    if (placedFurnitureData && userHome.placedFurniture !== undefined) delete userHome.placedFurniture;
    return releasedCount;
}

// 장착 가구 목록에서 계산용 최소 요약값 생성
function buildPlacedFurnitureSummary(placedFurniture) {
    var list = Array.isArray(placedFurniture) ? placedFurniture : [];
    var totalExp = 0; // 장착 가구 매력 합계
    var royalLumiereCount = 0; // 로열 하우스 스킬 조건용 가구 개수
    var gradeCounts = {}; // 등급별 배치 가구 개수
    for (var i = 0; i < list.length; i++) {
        var item = list[i];
        if (!item) continue;
        totalExp += Number(item.exp) || 0;
        var itemGrade = String(item.grade || "").trim();
        if (itemGrade) gradeCounts[itemGrade] = (gradeCounts[itemGrade] || 0) + 1;
        if (itemGrade === "로열 루미에르") royalLumiereCount++;
    }
    return {
        count: list.length,
        totalExp: totalExp,
        royalLumiereCount: royalLumiereCount,
        gradeCounts: gradeCounts
    };
}

// 저장된 요약값을 정수 기준으로 정규화
function normalizePlacedFurnitureSummary(summary) {
    summary = summary && typeof summary === "object" ? summary : {};
    var sourceGradeCounts = summary.gradeCounts && typeof summary.gradeCounts === "object" ? summary.gradeCounts : {};
    var gradeCounts = {};
    for (var grade in sourceGradeCounts) {
        if (!sourceGradeCounts.hasOwnProperty(grade)) continue;
        var gradeCount = Math.max(0, parseInt(sourceGradeCounts[grade], 10) || 0);
        if (gradeCount > 0) gradeCounts[grade] = gradeCount;
    }
    return {
        count: Math.max(0, parseInt(summary.count, 10) || 0),
        totalExp: Number(summary.totalExp) || 0,
        royalLumiereCount: Math.max(0, parseInt(summary.royalLumiereCount, 10) || 0),
        gradeCounts: gradeCounts
    };
}

// 숫자 맵 두 개의 키와 값을 비교
function isSameNumberMap(a, b) {
    var left = a && typeof a === "object" ? a : {};
    var right = b && typeof b === "object" ? b : {};
    var leftKeys = Object.keys(left);
    var rightKeys = Object.keys(right);
    if (leftKeys.length !== rightKeys.length) return false;
    for (var i = 0; i < leftKeys.length; i++) {
        var key = leftKeys[i];
        if (!right.hasOwnProperty(key) || Number(left[key]) !== Number(right[key])) return false;
    }
    return true;
}

// 장착 가구 요약값 두 개가 같은지 확인
function isSamePlacedFurnitureSummary(a, b) {
    var left = normalizePlacedFurnitureSummary(a);
    var right = normalizePlacedFurnitureSummary(b);
    return left.count === right.count && left.totalExp === right.totalExp && left.royalLumiereCount === right.royalLumiereCount && isSameNumberMap(left.gradeCounts, right.gradeCounts);
}

// 분리 상세 파일을 우선 사용하고 이관 전에는 기존 펫홈 목록을 반환
function getPlacedFurnitureList(homeData, placedFurnitureData, username) {
    if (placedFurnitureData && Array.isArray(placedFurnitureData[username])) return placedFurnitureData[username];
    if (homeData && homeData[username] && Array.isArray(homeData[username].placedFurniture)) return homeData[username].placedFurniture;
    return [];
}

// 장착 가구 상세 데이터가 사용자별 목록 객체인지 확인
function requirePlacedFurnitureDataMap(placedFurnitureData) {
    if (!placedFurnitureData || typeof placedFurnitureData !== "object" || Array.isArray(placedFurnitureData)) {
        throw new Error("Invalid placed furniture data map: " + petHomePlacedFurniturePath);
    }
    for (var user in placedFurnitureData) {
        if (!placedFurnitureData.hasOwnProperty(user)) continue;
        if (!Array.isArray(placedFurnitureData[user])) {
            throw new Error("Invalid placed furniture user list: " + user);
        }
    }
    return placedFurnitureData;
}

// 장착 가구 상세 파일의 사용자 목록을 배열로 보장
function ensurePlacedFurnitureUser(placedFurnitureData, username) {
    if (!Array.isArray(placedFurnitureData[username])) placedFurnitureData[username] = [];
    return placedFurnitureData[username];
}

// 장착 상세 목록을 기준으로 해당 사용자의 펫홈 요약값 갱신
function refreshPlacedFurnitureSummary(homeData, username, placedFurniture) {
    homeData = initSweetHomeUser(homeData, username);
    homeData[username].placedFurnitureSummary = buildPlacedFurnitureSummary(placedFurniture);
    return homeData[username].placedFurnitureSummary;
}

// 분리 파일과 기존 장착 목록을 가구 ID 기준으로 병합
function mergePlacedFurnitureLists(targetList, legacyList) {
    var target = Array.isArray(targetList) ? targetList : [];
    var legacy = Array.isArray(legacyList) ? legacyList : [];
    var knownIds = {};
    var mergedCount = 0;
    for (var i = 0; i < target.length; i++) {
        if (target[i] && target[i].id) knownIds[String(target[i].id)] = true;
    }
    for (var j = 0; j < legacy.length; j++) {
        var item = legacy[j];
        if (!item) continue;
        var itemId = item.id ? String(item.id) : "";
        if (itemId && knownIds[itemId]) continue;
        target.push(item);
        if (itemId) knownIds[itemId] = true;
        mergedCount++;
    }
    sortFurnitureList(target);
    return { list: target, mergedCount: mergedCount };
}

// 장착 상세와 같은 ID가 가구 가방에도 있으면 장착 상태를 우선해 중복 제거
function removePlacedFurnitureDuplicatesFromBag(furnitureBag, placedFurniture) {
    if (!Array.isArray(furnitureBag) || !Array.isArray(placedFurniture)) return 0;
    var placedIds = {};
    for (var i = 0; i < placedFurniture.length; i++) {
        if (placedFurniture[i] && placedFurniture[i].id) placedIds[String(placedFurniture[i].id)] = true;
    }
    var nextBag = [];
    var removedCount = 0;
    for (var j = 0; j < furnitureBag.length; j++) {
        var item = furnitureBag[j];
        var itemId = item && item.id ? String(item.id) : "";
        if (itemId && placedIds[itemId]) {
            removedCount++;
        } else {
            nextBag.push(item);
        }
    }
    furnitureBag.splice(0, furnitureBag.length);
    for (var k = 0; k < nextBag.length; k++) furnitureBag.push(nextBag[k]);
    sortFurnitureList(furnitureBag);
    return removedCount;
}

// 신규 장착 상세 파일을 기존 데이터에서 안전하게 만들 수 있는지 확인
function canCreatePlacedFurnitureData(homeData) {
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user) || !homeData[user]) continue;
        var legacyList = homeData[user].placedFurniture;
        if (legacyList !== undefined && !Array.isArray(legacyList)) return false;
        var summary = normalizePlacedFurnitureSummary(homeData[user].placedFurnitureSummary);
        var hasSummaryFurniture = summary.count > 0 || summary.totalExp > 0 || summary.royalLumiereCount > 0;
        if (hasSummaryFurniture && !Array.isArray(legacyList)) return false;
    }
    return true;
}

// 상세 목록을 원본으로 펫홈 요약값을 초기 생성하거나 다시 동기화
function synchronizePlacedFurnitureData(homeData, placedFurnitureData) {
    var userCount = 0;
    var furnitureCount = 0;
    var mergedCount = 0;
    var summaryChangedCount = 0;
    var bagDuplicateRemovedCount = 0;
    var orphanUserCount = 0;
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user) || !homeData[user]) continue;
        var legacyList = Array.isArray(homeData[user].placedFurniture) ? homeData[user].placedFurniture : [];
        var currentList = Array.isArray(placedFurnitureData[user]) ? placedFurnitureData[user] : [];
        var mergeResult = mergePlacedFurnitureLists(currentList, legacyList);
        var nextSummary = buildPlacedFurnitureSummary(mergeResult.list);
        if (!isSamePlacedFurnitureSummary(homeData[user].placedFurnitureSummary, nextSummary)) summaryChangedCount++;
        placedFurnitureData[user] = mergeResult.list;
        homeData[user].placedFurnitureSummary = nextSummary;
        bagDuplicateRemovedCount += removePlacedFurnitureDuplicatesFromBag(homeData[user].furnitureBag, mergeResult.list);
        if (homeData[user].placedFurniture !== undefined) delete homeData[user].placedFurniture;
        userCount++;
        furnitureCount += mergeResult.list.length;
        mergedCount += mergeResult.mergedCount;
    }
    for (var placedUser in placedFurnitureData) {
        if (!placedFurnitureData.hasOwnProperty(placedUser)) continue;
        if (!homeData[placedUser]) orphanUserCount++;
    }
    return {
        userCount: userCount,
        furnitureCount: furnitureCount,
        mergedCount: mergedCount,
        summaryChangedCount: summaryChangedCount,
        bagDuplicateRemovedCount: bagDuplicateRemovedCount,
        orphanUserCount: orphanUserCount
    };
}

// 펫홈 요약값과 장착 상세 목록이 모두 일치하는지 검증
function validatePlacedFurnitureSync(homeData, placedFurnitureData) {
    var mismatchUserCount = 0;
    for (var user in homeData) {
        if (!homeData.hasOwnProperty(user) || !homeData[user]) continue;
        var list = placedFurnitureData && Array.isArray(placedFurnitureData[user]) ? placedFurnitureData[user] : [];
        var hasMismatch = !isSamePlacedFurnitureSummary(homeData[user].placedFurnitureSummary, buildPlacedFurnitureSummary(list));
        if (homeData[user].placedFurniture !== undefined) hasMismatch = true;
        if (hasMismatch) mismatchUserCount++;
    }
    return { ok: mismatchUserCount === 0, mismatchUserCount: mismatchUserCount };
}

// 현재 배치된 가구로 얻는 총 매력💕
function getFurnitureExp(userData) {
    if (userData && userData.placedFurnitureSummary && userData.placedFurnitureSummary.totalExp !== undefined) {
        return Number(userData.placedFurnitureSummary.totalExp) || 0;
    }
    if (!userData || !userData.placedFurniture || userData.placedFurniture.length === 0) {
        return 0;
    }
    var total = 0;
    for (var i = 0; i < userData.placedFurniture.length; i++) {
        var item = userData.placedFurniture[i];
        var expValue = Number(item.exp) || 0;
        total += expValue;
    }
    return total;
}
function createCuId() {
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    var id = "";
    for (var i = 0; i < 6; i++) {
        id += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return id;
}
// 가구 리스트 정렬: 매력 높은 순 → 이름 가나다 순 → id 순
function sortFurnitureList(list) {
    list.sort(function (a, b) {
        // 1 매력 높은 순
        if (b.exp !== a.exp) return b.exp - a.exp;
        let nameA = a.name || "";
        let nameB = b.name || "";
        let nameCompare = nameA.localeCompare(nameB, "ko");
        if (nameCompare !== 0) return nameCompare;
        let idA = a.id || "";
        let idB = b.id || "";
        return idA.localeCompare(idB);
    });
    return list;
}
// 특정 아이템의 개수 조회
function getItemCount(data, user, itemName) {
    if (!data.member[user]) return 0;
    if (!data.member[user].bag) return 0;
    return data.member[user].bag[itemName] || 0;
}
// 문자열 시작 부분에서 멤버 이름 찾기
function findTargetAtStart(content, memberMap, allowCommaDelimiter) {
    let names = Object.keys(memberMap || {}); // 모든 멤버 닉네임 목록 가져오기
    names.sort(function (a, b) {
        return b.length - a.length;
    });
    // 긴 닉네임을 먼저 비교
    for (let i = 0; i < names.length; i++) {
        let name = names[i];
        // 메시지가 해당 닉네임으로 시작하고 뒤가 끝, 공백 또는 허용된 쉼표인 경우
        var nextChar = content.charAt(name.length);
        if (content.indexOf(name) === 0 && (content.length === name.length || nextChar === " " || (allowCommaDelimiter && nextChar === ","))) {
            var rest = content.substring(name.length).trim();
            if (allowCommaDelimiter && rest.indexOf(",") === 0) rest = rest.substring(1).trim();
            // target : 닉네임, rest : 나머지
            return {
                target: name,
                rest: rest
            };
        }
    }
    return {
        target: null,
        rest: content
    };
}
// 기존 유저는 0부터 시작하고 저장된 별채 성장 값의 형식을 검증하는 함수
function getPetHomeVillageState(userHome) {
    var stored = userHome && userHome.lumiereVillage;
    if (stored === undefined) return { grand: { level: 0, progress: 0 }, royal: { level: 0, progress: 0 }, arcana: { level: 0, progress: 0 } };
    if (!stored || typeof stored !== "object" || Array.isArray(stored)) throw new Error("별채 데이터 형식 오류");
    var result = {};
    var keys = ["grand", "royal", "arcana"];
    for (var i = 0; i < keys.length; i++) {
        var value = keys[i] === "grand" && stored.grand === undefined ? { level: 0, progress: 0 } : stored[keys[i]];
        if (!value || typeof value.level !== "number" || typeof value.progress !== "number" ||
            !isFinite(value.level) || value.level < 0 || Math.floor(value.level) !== value.level || value.level > 9007199254740991 ||
            !isFinite(value.progress) || value.progress < 0 || Math.floor(value.progress) !== value.progress || value.progress >= GLOBAL_CONFIG.petHomeVillage.materialsPerLevel) throw new Error("별채 성장 값 오류");
        result[keys[i]] = { level: value.level, progress: value.progress };
    }
    return result;
}

// 현재 집 면적에서 각 별채가 성장할 수 있는 레벨을 계산하는 함수
function getPetHomeVillageLevelLimit(userHome) {
    return Math.floor(Math.max(0, Number(userHome && userHome.floor) || 0) / GLOBAL_CONFIG.petHomeVillage.areaPerLevel);
}

// 평수·가구·하우스 스킬의 별채 버프와 인테리어 추가분을 계산하는 함수
function getPetHomeFurnitureCharm(homeData, petSkillData, user, equippedSkillNames) {
    var home = homeData && homeData[user] ? homeData[user] : {};
    var state = getPetHomeVillageState(home);
    var furniture = getFurnitureExp(home); // 한 모드에 적용되는 가구 기본 매력
    var equipped = equippedSkillNames || getEquippedPetSkillNames(petSkillData, user); // 같은 계산에서 스킬 목록은 한 번만 정규화
    var royal = equipped.indexOf("로열 하우스") !== -1 && getPlacedFurnitureCountByGrade(homeData, user, "로열 루미에르") >= 10 ? GLOBAL_CONFIG.petHomeVillage.royalSkillPerMode : 0;
    var arcana = equipped.indexOf("아르카나 하우스") !== -1 && getOwnedFurnitureCountByGrade(homeData, user, "아르카나 루미에르") >= 5 ? GLOBAL_CONFIG.petHomeVillage.arcanaSkillPerMode : 0;
    var floorCharm = getPetHomeFloorCharm(home); // 평수 기본 매력도 빌리지·인테리어 계산에 포함
    var base = furniture + royal + arcana + floorCharm; // 별채 버프 대상인 한 모드의 기본 합계
    var percent = state.grand.level * GLOBAL_CONFIG.petHomeVillage.grandPercent + state.royal.level * GLOBAL_CONFIG.petHomeVillage.royalPercent + state.arcana.level * GLOBAL_CONFIG.petHomeVillage.arcanaPercent;
    if (equipped.indexOf(GLOBAL_CONFIG.petHomeVillage.dreamSkillName) !== -1) percent += GLOBAL_CONFIG.petHomeVillage.dreamPercent; // 스킬 10%p를 레벨 버프에 합산
    var bonus = Math.floor(base * percent / 100); // 캐슬·레이드에 각각 한 번 적용할 추가 매력
    var oldHome = Number(home.exp || 0) + furniture + floorCharm;
    var interior = equipped.indexOf("인테리어 장인") !== -1 ? Math.floor(oldHome * 1.1) - oldHome : 0; // 기존 집·가구 10% 효과 유지
    var floorApplied = floorCharm + bonus - Math.floor((base - floorCharm) * percent / 100); // 평수가 늘린 기본·별채 매력
    if (equipped.indexOf("인테리어 장인") !== -1) floorApplied += interior - (Math.floor((oldHome - floorCharm) * 1.1) - (oldHome - floorCharm)); // 평수가 늘린 인테리어 매력
    return { state: state, furniture: furniture, royal: royal, arcana: arcana, interior: interior, floor: floorCharm, floorApplied: floorApplied, base: base, percent: percent, villageBonus: bonus, bonus: bonus,
        castle: base + bonus + interior, raid: base + bonus + interior, total: (base + bonus + interior) * 2 };
}

// 범용 포맷터
function getHomeTotalExp(homeData, username) {
    if (!homeData || !homeData[username]) return 0;
    var userHome = homeData[username];
    var exp = userHome.exp || 0;
    var furnitureExp = getFurnitureExp(userHome) || 0;
    return parseInt(exp) + parseInt(furnitureExp);
}

// 특정 가구가 배치된 개수 조회
function getPlacedFurnitureCountByName(homeData, username, furnitureName) {
    if (!homeData || !homeData[username] || !homeData[username].placedFurniture) return 0;
    var placed = homeData[username].placedFurniture;
    var target = String(furnitureName || "").trim();
    if (!target) return 0;
    var count = 0;
    for (var i = 0; i < placed.length; i++) {
        var itemName = String((placed[i] && placed[i].name) || "").trim();
        if (itemName === target) count++;
    }
    return count;
}

// 특정 등급의 가구가 배치된 개수 조회
function getPlacedFurnitureCountByGrade(homeData, username, furnitureGrade) {
    var target = String(furnitureGrade || "").trim();
    if (!target) return 0;
    if (!homeData || !homeData[username]) return 0;
    if (homeData[username].placedFurnitureSummary) {
        var summary = normalizePlacedFurnitureSummary(homeData[username].placedFurnitureSummary);
        if (summary.gradeCounts.hasOwnProperty(target)) return summary.gradeCounts[target];
        if (target === "로열 루미에르" && summary.royalLumiereCount > 0) return summary.royalLumiereCount;
    }
    if (!homeData[username].placedFurniture) return 0;
    var placed = homeData[username].placedFurniture;
    var count = 0;
    for (var i = 0; i < placed.length; i++) {
        var itemGrade = String((placed[i] && placed[i].grade) || "").trim();
        if (itemGrade === target) count++;
    }
    return count;
}

// 가구가방과 배치 가구를 합쳐 특정 등급의 총 보유 수를 반환
function getOwnedFurnitureCountByGrade(homeData, username, furnitureGrade) {
    if (!homeData || !homeData[username]) return 0;
    var target = String(furnitureGrade || "").trim();
    if (!target) return 0;
    var count = getPlacedFurnitureCountByGrade(homeData, username, target);
    var furnitureBag = Array.isArray(homeData[username].furnitureBag) ? homeData[username].furnitureBag : [];
    for (var i = 0; i < furnitureBag.length; i++) {
        var itemGrade = String((furnitureBag[i] && furnitureBag[i].grade) || "").trim();
        if (itemGrade === target) count++;
    }
    return count;
}
//샵오픈 관련
// 0~1 비율을 소수점 최대 여섯 자리의 백분율로 표시하는 함수
function formatGachaProbability(probability) {
    return (probability * 100).toFixed(6).replace(/\.?0+$/, "") + "%";
}

// 등급별 확률 테이블 만들기 (grade, rate)
function buildGradeRates(furnitureList) {
    var map = {};
    var arr = [];
    for (var i = 0; i < furnitureList.length; i++) {
        var item = furnitureList[i];
        var g = item.grade;
        if (!g) continue;
        if (!map[g]) {
            map[g] = Number(item.rate) || 0;
            arr.push({
                grade: g,
                rate: map[g]
            });
        }
    }
    return arr;
}
// 등급 하나 뽑기
function pickGrade(gradeRates) {
    var total = 0;
    for (var i = 0; i < gradeRates.length; i++) {
        total += Number(gradeRates[i].rate);
    }
    var r = Math.random() * total;
    var acc = 0;
    for (var j = 0; j < gradeRates.length; j++) {
        acc += Number(gradeRates[j].rate);
        if (r <= acc) return gradeRates[j].grade;
    }
    return gradeRates[gradeRates.length - 1].grade;
}
// 한 명령에서 재사용할 등급별 가구 후보를 원래 목록 순서로 구성
function buildFurnitureGradePools(furnitureList, gradeRates) {
    var pools = [];
    for (var i = 0; i < gradeRates.length; i++) {
        var candidates = null;
        // 확률이 0인 등급의 중복 행도 기존대로 두되 후보 배열은 함께 사용한다.
        for (var known = 0; known < i; known++) {
            if (gradeRates[known].grade === gradeRates[i].grade) { candidates = pools[known]; break; }
        }
        if (!candidates) {
            candidates = [];
            for (var j = 0; j < furnitureList.length; j++) {
                if (furnitureList[j].grade === gradeRates[i].grade) candidates.push(furnitureList[j]);
            }
        }
        pools.push(candidates);
    }
    return pools;
}
// 등급 먼저 뽑고, 미리 구성한 해당 등급의 가구 중 하나 선택
function getRandomFurnitureByGrade(furnitureList, gradeRates, gradePools) {
    var targetGrade = pickGrade(gradeRates);
    var candidates = null;
    for (var i = 0; i < gradeRates.length; i++) {
        if (gradeRates[i].grade === targetGrade) {
            candidates = gradePools[i];
            break;
        }
    }
    // 해당 등급이 하나도 없으면 전체에서 랜덤
    var pool = candidates && candidates.length > 0 ? candidates : furnitureList;
    var idx = Math.floor(Math.random() * pool.length);
    return pool[idx];
}
/**
 * 펫스윗홈 가구를 유저의 homeData[targetName].furnitureBag 에 추가하는 함수
 *
 * ✨ 이 함수는 "뽑기", "패키지", "어드민 지급", "이벤트 지급" 등
 *    모든 경우에서 공통적으로 사용될 수 있도록 설계됨.
 *
 * @param {Object} homeData - 전체 펫스윗홈 데이터 JSON (homeDataFile 불러온 값)
 * @param {String} targetName - 가구를 받을 유저 닉네임
 *
 * @param {String} name - 가구 이름
 *    예: "샤넬 컬렉션🎩"
 *
 * @param {Number|String} exp - 가구 매력 수치
 *    - 문자열 또는 숫자 모두 가능 (내부에서 Number() 처리)
 *    - 예: 56050
 *
 * @param {Number|String} rate - 등장 확률
 *    - 뽑기 시 사용하는 확률 (패키지·어드민 지급 시 보통 0 사용)
 *    - 예: 0.00002
 *
 * @param {String} grade - 가구 등급
 *    예: "시그니엘", "레어", "스페셜", "일반"
 *
 * @param {String} display - 출력용으로 사용되는 표시 문자열
 *    일반적으로 다음 형식으로 자동 생성됨:
 *      `${name}(+${exp}💕)[${grade}]`
 *    예:
 *      "샤넬 컬렉션🎩(+56050💕)[시그니엘]"
 *
 * 📦 최종적으로 homeData[targetName].furnitureBag 에 들어가는 newItem 구조:
 * {
 *   id: "CU_...",                      // createCuId() 로 생성되는 고유 ID
 *   name: "샤넬 컬렉션🎩",             // 가구 이름
 *   exp: 56050,                       // Number 변환된 매력 수치
 *   rate: 0.00002,                    // Number 변환된 확률 (패키지에서는 0)
 *   grade: "시그니엘",                 // 가구 등급
 *   display: "샤넬 컬렉션🎩(+56050💕)[시그니엘]"   // 표시용 문자열
 * }
 *
 * ✔ 가구 정렬 기준 (sortFurnitureList):
 *   1) exp(매력) 높은 순
 *   2) name 가나다 순
 *   3) id 순
 *
 * @return {Object} newItem - 방금 추가된 가구 객체 (메시지 출력용)
 */
function addFurniture(homeData, targetName, name, exp, rate, grade, display) {
    // display 기본값 처리
    if (!display || display.trim() === "") {
        display = name + "(+" + exp + "💕)[" + grade + "]";
    }
    if (!homeData[targetName]) {
        homeData[targetName] = {
            furniture: [],
            exp: 0,
            likeCnt: 0,
            comment: "",
            floor: 1
        };
    }
    if (!homeData[targetName].furnitureBag) {
        homeData[targetName].furnitureBag = [];
    }
    var newItem = {
        id: createCuId(),
        name: name,
        exp: Number(exp),
        rate: Number(rate),
        grade: grade,
        display: display
    };
    homeData[targetName].furnitureBag.push(newItem);
    homeData[targetName].furnitureBag = sortFurnitureList(homeData[targetName].furnitureBag);
    return homeData;
}
/**
 * 미니펫을 유저의 miniPetBag 배열에 추가하는 함수
 *
 * @param {Object} petData - 전체 petData(JSON)
 * @param {String} receiver - 미니펫을 받을 사용자 닉네임
 * @param {String} name - 미니펫 이름
 * @param {String} emoji - 미니펫 이모지
 * @param {String} grade - 미니펫 등급 (일반/고급/희귀/영웅/전설 등)
 * @param {Number} price - 미니펫 판매 가격(또는 획득 가격)
 * @param {Number} exp - battleExp / castleExp / raidExp 에 동일하게 들어가는 매력 수치
 *
 * 미니펫 기본 구조 설명:
 * {
 *    name: "이름",
 *    emoji: "🐹",             // 미니펫 대표 이모지
 *    grade: "희귀",           // 미니펫 등급
 *    price: 30000000,        // 판매 or 가치 포인트
 *    battleExp: 500,         // 전투 매력 (대전 / 배틀)
 *    castleExp: 500,         // 공성 매력
 *    raidExp: 500            // 레이드 매력
 * }
 *
 * 이 함수는 패키지지급 / 이벤트지급 / 어드민지급 등 어디서든 재사용 가능
 */
function addMiniPetToUserBag(petData, receiver, name, emoji, grade, price, exp) {
    // 유저 petData 구조가 없을 때 생성
    if (!petData[receiver]) {
        petData[receiver] = {};
    }
    if (!petData[receiver].miniPetBag) {
        petData[receiver].miniPetBag = [];
    }
    var miniPetObj = {
        name: name,
        emoji: emoji,
        grade: grade,
        price: price,
        battleExp: exp,
        castleExp: exp,
        raidExp: exp
    };
    // 유저의 miniPetBag 배열에 push
    petData[receiver].miniPetBag.push(miniPetObj);
    return miniPetObj;
}

// 펫강화 치명타 배수(계수)
// 0~300강: 1.70 고정
// 301강부터: 1.70 + (강화-300)*0.01  => 301=1.71, 302=1.72 ...
function getMiniPetCombinationConfig(commandName) {
    if (commandName === "태초") return { commandLabel: "태초", inputGrade: "초월+", outputGrade: "태초", successRate: 0.5 };
    if (commandName === "태초+") return { commandLabel: "태초+", inputGrade: "태초", outputGrade: "태초+", successRate: 0.5 };
    if (commandName === "창세") return { commandLabel: "창세", inputGrade: "태초+", outputGrade: "창세", successRate: 0.3 };
    if (commandName === "창조") return { commandLabel: "창조", inputGrade: "창세", outputGrade: "창조", successRate: 1.0 };
    return null;
}
// 조합 풀에서 랜덤으로 미니펫 하나 생성
function getMiniPetCombinationConfigByGrades(firstGrade, secondGrade) {
    if (!firstGrade || !secondGrade) return null;
    if (firstGrade !== secondGrade) return null;

    var firstConfig = getMiniPetCombinationConfig("태초");
    var secondConfig = getMiniPetCombinationConfig("태초+");
    var thirdConfig = getMiniPetCombinationConfig("창세");
    var fourthConfig = getMiniPetCombinationConfig("창조");

    if (firstConfig && firstGrade === firstConfig.inputGrade) return firstConfig;
    if (secondConfig && firstGrade === secondConfig.inputGrade) return secondConfig;
    if (thirdConfig && firstGrade === thirdConfig.inputGrade) return thirdConfig;
    if (fourthConfig && firstGrade === "창세") {
        return {
            commandLabel: fourthConfig.commandLabel,
            inputGrade: "창세",
            outputGrade: fourthConfig.outputGrade,
            successRate: fourthConfig.successRate
        };
    }

    return null;
}

function createMiniPetFromCombination(grade) {
    var pool = MINI_PET_COMBINATION_REWARDS[grade] || [];
    if (!pool.length && miniPetData && miniPetData.miniPet instanceof Array) {
        for (var mp = 0; mp < miniPetData.miniPet.length; mp++) {
            if (miniPetData.miniPet[mp] && miniPetData.miniPet[mp].grade === grade) {
                pool.push([miniPetData.miniPet[mp].name, miniPetData.miniPet[mp].emoji, miniPetData.miniPet[mp].battleExp || miniPetData.miniPet[mp].price || 0]);
            }
        }
    }
    if (!pool.length) return null;
    var picked = pool[Math.floor(Math.random() * pool.length)];
    return { name: picked[0], emoji: picked[1], grade: grade, price: picked[2], battleExp: picked[2], castleExp: picked[2], raidExp: picked[2] };
}

function isEliteMiniPetCombinationMaterial(pet) {
    if (!pet) return false;
    if ((pet.name || "") === "컬렉션창조 미니펫") return false;
    if ((pet.grade || "") !== "창조") return false;
    return parseInt(pet.upgrade || 0, 10) >= 300;
}

