// 펜던트 유저 데이터 구조 보장
function ensurePendantUser(petData, user) {
    if (!petData[user]) petData[user] = {};
    if (!Array.isArray(petData[user].pendantBag)) petData[user].pendantBag = [];
    return petData[user];
}

// 펜던트 객체를 추적하기 위한 고유 ID를 생성하는 함수
function createPendantId() {
    return "PND-" + new Date().getTime().toString(36).toUpperCase() + "-" + Math.floor(Math.random() * 1679616).toString(36).toUpperCase();
}

// 펜던트 승급 단계를 안전한 0 이상의 정수로 정규화하는 함수
function normalizePendantPromotionLevel(pendant) {
    var level = pendant ? Number(pendant.promotionLevel) : 0;
    if (!isFinite(level) || level < 0 || Math.floor(level) !== level) level = 0;
    if (pendant) pendant.promotionLevel = level;
    return level;
}

// 유저의 장착·가방 펜던트에 중복 없는 고유 ID와 승급 단계를 보장하는 함수
function ensurePendantIdsForUser(petData, user) {
    var pet = ensurePendantUser(petData, user);
    var seen = {};
    var changed = false;
    var pendants = [];
    if (pet.pendant) pendants.push(pet.pendant);
    for (var i = 0; i < pet.pendantBag.length; i++) pendants.push(pet.pendantBag[i]);
    for (var j = 0; j < pendants.length; j++) {
        var pendant = pendants[j];
        if (!pendant || typeof pendant !== "object") continue;
        var id = typeof pendant.pendantId === "string" ? pendant.pendantId : "";
        if (!id || seen[id]) {
            do { id = createPendantId(); } while (seen[id]);
            pendant.pendantId = id;
            changed = true;
        }
        seen[id] = true;
        var previousLevel = pendant.promotionLevel;
        normalizePendantPromotionLevel(pendant);
        if (previousLevel !== pendant.promotionLevel) changed = true;
    }
    return changed;
}

// 고유 ID로 장착 또는 가방의 펜던트를 찾는 함수
function getPendantById(petData, user, pendantId) {
    var pet = ensurePendantUser(petData, user);
    if (pet.pendant && pet.pendant.pendantId === pendantId) return { pendant: pet.pendant, source: "equipped", arrayIndex: -1 };
    for (var i = 0; i < pet.pendantBag.length; i++) {
        if (pet.pendantBag[i] && pet.pendantBag[i].pendantId === pendantId) return { pendant: pet.pendantBag[i], source: "bag", arrayIndex: i };
    }
    return { pendant: null, source: "", arrayIndex: -1 };
}

// 다음 창조 펜던트 승급 단계의 비용을 계산하는 함수
function getPendantPromotionCosts(nextLevel) {
    var level = Number(nextLevel);
    if (!isFinite(level) || level < 1 || Math.floor(level) !== level) return null;
    var stones = level * GLOBAL_CONFIG.pendant.promotionStonePerLevel;
    var points = level * GLOBAL_CONFIG.pendant.promotionPointPerLevel;
    var charm = level * GLOBAL_CONFIG.pendant.promotionCharmPerLevel;
    if (!isSafePointValue(points) || !isSafePointValue(charm) || !isSafePointValue(stones)) return null;
    return { level: level, stones: stones, points: points, charm: charm };
}

// 고액 포인트에서도 승급 비용이 정확히 차감되는지 계산하는 함수
function calculatePendantPromotionPointDeduction(currentValue, costValue) {
    var currentPoint = Number(currentValue);
    var costPoint = Number(costValue);
    if (!isFinite(currentPoint) || currentPoint < 0 || Math.floor(currentPoint) !== currentPoint) return { ok: false, reason: "invalid" };
    if (!isSafePointValue(costPoint) || costPoint <= 0) return { ok: false, reason: "invalid" };
    if (currentPoint < costPoint) return { ok: false, reason: "insufficient" };
    var nextPoint = currentPoint - costPoint; // 승급 비용 차감 후 잔액
    if (!isFinite(nextPoint) || nextPoint < 0 || Math.floor(nextPoint) !== nextPoint || currentPoint - nextPoint !== costPoint) {
        return { ok: false, reason: "inexact" };
    }
    return { ok: true, nextPoint: nextPoint };
}

// 승급 재료로 사용할 다른 창조 펜던트를 우선순위에 따라 선택하는 함수
function selectPendantPromotionMaterial(petData, user, targetId) {
    var bag = getPendantBag(petData, user);
    var candidates = [];
    for (var i = 0; i < bag.length; i++) {
        var pendant = bag[i];
        if (!pendant || pendant.pendantId === targetId || pendant.grade !== GLOBAL_CONFIG.pendant.promotionGrade) continue;
        candidates.push({ pendant: pendant, arrayIndex: i });
    }
    candidates.sort(function(a, b) {
        var levelDiff = normalizePendantPromotionLevel(a.pendant) - normalizePendantPromotionLevel(b.pendant);
        if (levelDiff !== 0) return levelDiff;
        var upgradeDiff = (parseInt(a.pendant.upgrade, 10) || 0) - (parseInt(b.pendant.upgrade, 10) || 0);
        if (upgradeDiff !== 0) return upgradeDiff;
        var durabilityDiff = (parseInt(a.pendant.durability, 10) || 0) - (parseInt(b.pendant.durability, 10) || 0);
        if (durabilityDiff !== 0) return durabilityDiff;
        return a.arrayIndex - b.arrayIndex;
    });
    return candidates.length ? candidates[0] : null;
}

// 창조 펜던트 승급 확인 상태를 저장하는 함수
function setPendantPromotionState(sender, state) {
    if (!userState[sender]) userState[sender] = {};
    state.createdAt = new Date().getTime();
    state.processing = false;
    userState[sender].pendantPromotion = state;
}

// 만료되지 않은 창조 펜던트 승급 확인 상태를 반환하는 함수
function getPendantPromotionState(sender) {
    var state = userState[sender] && userState[sender].pendantPromotion ? userState[sender].pendantPromotion : null;
    if (!state) return null;
    if (!state.createdAt || new Date().getTime() - state.createdAt > GLOBAL_CONFIG.pendant.promotionConfirmStaleMs) {
        clearPendantPromotionState(sender);
        return null;
    }
    return state;
}

// 창조 펜던트 승급 확인 상태를 삭제하는 함수
function clearPendantPromotionState(sender) {
    if (userState[sender] && userState[sender].pendantPromotion) delete userState[sender].pendantPromotion;
}

// 펜던트 가방 최대 칸 수 반환
function getPendantBagLimit() {
    return 50;
}

// 펜던트 가방 배열 반환
function getPendantBag(petData, user) {
    return ensurePendantUser(petData, user).pendantBag;
}

// 펜던트 등급 설정 조회
function getPendantGradeInfo(grade) {
    for (var i = 0; i < PENDANT_GRADE_TABLE.length; i++) {
        if (PENDANT_GRADE_TABLE[i].grade === grade) return PENDANT_GRADE_TABLE[i];
    }
    return PENDANT_GRADE_TABLE[0];
}

// 펜던트 객체 생성
function createPendantByGradeInfo(info) {
    return {
        pendantId: createPendantId(),
        name: info.name,
        icon: info.icon,
        grade: info.grade,
        promotionLevel: 0,
        upgrade: 0,
        durability: 5,
        maxDurability: 5,
        bound: false
    };
}

// 펜던트 이름과 이모지를 중복 없이 결합
function formatPendantNameWithIcon(pendant) {
    if (!pendant) return "";
    var name = pendant.name || "";
    var icon = pendant.icon || "";
    if (icon && name.substring(name.length - icon.length) === icon) return name;
    return name + icon;
}

// 펜던트 뽑기 결과 선택
function pickRandomPendant() {
    var r = Math.random() * 100;
    var acc = 0;
    for (var i = 0; i < PENDANT_GRADE_TABLE.length; i++) {
        acc += PENDANT_GRADE_TABLE[i].rate;
        if (r < acc) return createPendantByGradeInfo(PENDANT_GRADE_TABLE[i]);
    }
    return createPendantByGradeInfo(PENDANT_GRADE_TABLE[0]);
}

// 펜던트 표시 문자열 생성
function formatPendantDisplay(pendant) {
    if (!pendant) return "없음";
    var maxDurability = pendant.maxDurability !== undefined ? pendant.maxDurability : 5;
    var durability = pendant.durability !== undefined ? pendant.durability : maxDurability;
    var upgrade = pendant.upgrade !== undefined ? pendant.upgrade : 0;
    var promotionLevel = normalizePendantPromotionLevel(pendant);
    var gradeText = pendant.grade + (promotionLevel > 0 ? "★" + promotionLevel : "");
    return formatPendantNameWithIcon(pendant) + "[" + gradeText + "][⚒️" + durability + "/" + maxDurability + "](+" + upgrade + ")";
}

// 순위표용 등수 접두어를 반환하는 함수
function formatSimpleRankPrefix(rank) {
    if (rank === 1) return "🥇";
    if (rank === 2) return "🥈";
    if (rank === 3) return "🥉";
    return addsingle(rank) + ".";
}

// 펜던트 오픈 결과용 표시 문자열 생성
function formatPendantOpenResultDisplay(pendant) {
    if (!pendant) return "없음";
    var maxDurability = pendant.maxDurability !== undefined ? pendant.maxDurability : 5;
    var durability = pendant.durability !== undefined ? pendant.durability : maxDurability;
    var gradeInfo = getPendantGradeInfo(pendant.grade);
    var promotionLevel = normalizePendantPromotionLevel(pendant);
    var gradeText = pendant.grade + (promotionLevel > 0 ? "★" + promotionLevel : "");
    return formatPendantNameWithIcon(pendant) + "[" + gradeText + "][⚒️" + durability + "/" + maxDurability + "] (확률:" + formatPendantPercent(gradeInfo.rate) + "%)";
}

// 펜던트 확률 표시용 소수 정리
function formatPendantPercent(value) {
    var n = parseFloat(value || 0);
    var decimalPlaces = Math.abs(n) < 1 ? 2 : 1;
    var text = n.toFixed(decimalPlaces);
    return text.replace(/\.?0+$/, "");
}

// 펜던트 등급 정렬 우선순위 반환
function getPendantGradeSortRank(grade) {
    var order = ["창조", "창세", "초월", "신화", "최상급+", "최상급", "상급+", "상급", "중급+", "중급", "하급+", "하급", "최하급"];
    for (var i = 0; i < order.length; i++) {
        if (order[i] === grade) return i;
    }
    return order.length;
}

// 펜던트 가방을 등급 순서대로 정렬
function sortPendantBagByGrade(bag) {
    if (!Array.isArray(bag)) return bag;
    var decorated = [];
    for (var i = 0; i < bag.length; i++) {
        decorated.push({ item: bag[i], index: i });
    }
    decorated.sort(function(a, b) {
        var ar = getPendantGradeSortRank(a.item ? a.item.grade : "");
        var br = getPendantGradeSortRank(b.item ? b.item.grade : "");
        if (ar !== br) return ar - br;
        var an = a.item && a.item.name ? String(a.item.name) : "";
        var bn = b.item && b.item.name ? String(b.item.name) : "";
        if (an < bn) return -1;
        if (an > bn) return 1;
        return a.index - b.index;
    });
    for (var j = 0; j < decorated.length; j++) {
        bag[j] = decorated[j].item;
    }
    return bag;
}

// 펜던트 기본/강화 능력치 계산
function calculatePendantStats(pendant) {
    var result = { charm: 0, explore: 0, baseCharm: 0, upgradeCharm: 0, promotionCharm: 0, baseExplore: 0, upgradeExplore: 0 };
    if (!pendant) return result;
    var gradeInfo = getPendantGradeInfo(pendant.grade);
    result.baseCharm = gradeInfo.charm || 0;
    result.baseExplore = gradeInfo.explore || 0;
    var upgrade = Math.max(0, Math.min(30, parseInt(pendant.upgrade || 0, 10)));
    for (var i = 1; i <= upgrade; i++) {
        if (!PENDANT_UPGRADE_TABLE[i]) continue;
        result.upgradeCharm += PENDANT_UPGRADE_TABLE[i].charm || 0;
        result.upgradeExplore = PENDANT_UPGRADE_TABLE[i].explore || result.upgradeExplore;
    }
    result.promotionCharm = normalizePendantPromotionLevel(pendant) * GLOBAL_CONFIG.pendant.promotionCharmPerLevel;
    result.charm = result.baseCharm + result.upgradeCharm + result.promotionCharm;
    result.explore = result.baseExplore + result.upgradeExplore;
    return result;
}

// 장착 펜던트 기준 순위 행을 생성하는 함수
function buildPendantRankingRows(data, petData) {
    var rows = [];
    if (!data || !data.member || !petData) return rows;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        if (!petData[user] || !petData[user].pendant) continue;
        var pendant = petData[user].pendant;
        var upgrade = parseInt(pendant.upgrade || 0, 10);
        if (isNaN(upgrade)) upgrade = 0;
        rows.push({
            user: user,
            pendant: pendant,
            gradeRank: getPendantGradeSortRank(pendant.grade),
            upgrade: upgrade
        });
    }
    rows.sort(function(a, b) {
        if (a.gradeRank !== b.gradeRank) return a.gradeRank - b.gradeRank;
        if (b.upgrade !== a.upgrade) return b.upgrade - a.upgrade;
        return String(a.user).localeCompare(String(b.user), "ko");
    });
    return rows;
}

// 장착 펜던트 순위 메시지를 생성하는 함수
function buildPendantRankingMessage(data, petData) {
    var rows = buildPendantRankingRows(data, petData);
    var out = "💎 펜던트 순위 💎\n[등급 → 강화수치 → 닉네임 가나다]\n\n";
    if (rows.length === 0) return out + "장착 중인 펜던트가 없습니다.";
    var limit = Math.min(rows.length, 100);
    for (var i = 0; i < limit; i++) {
        if (i === 10 && typeof allsee !== "undefined") out += allsee + "\n";
        out += formatSimpleRankPrefix(i + 1) + " " + rows[i].user + " - " + formatPendantDisplay(rows[i].pendant) + "\n";
    }
    return out.replace(/\n$/, "");
}

// 장착 펜던트의 펫탐험 성공률 보너스 반환
function getPendantExploreBonusPercent(petData, user) {
    if (!petData || !petData[user] || !petData[user].pendant) return 0;
    return calculatePendantStats(petData[user].pendant).explore || 0;
}

// 종합매력 계산용 펜던트 능력치 반환
function calculatePendantItemInfo(pendant) {
    var stats = calculatePendantStats(pendant);
    var half = Math.floor(stats.charm / 2);
    return {
        battleExp: 0,
        raidExp: half,
        castleExp: stats.charm - half
    };
}

// 펜던트 뽑기 확률 안내 생성
function buildPendantRateMessage() {
    var out = "💎 펜던트 확률\n━━━━━━━━━━━━\n";
    for (var i = 0; i < PENDANT_GRADE_TABLE.length; i++) {
        var p = PENDANT_GRADE_TABLE[i];
        out += p.name + p.icon + "[" + p.grade + "] " + p.rate + "%\n";
    }
    return out.trim();
}

// 펜던트 가방 출력 생성
function buildPendantBagMessage(data, petData, guildData, user) {
    if (!petData[user]) return "펫 데이터가 없습니다.";
    var bag = getPendantBag(petData, user);
    sortPendantBagByGrade(bag);
    var out = "[" + checkRank(data, petData, guildData, user) + "] 보유 펜던트가방💎[" + bag.length + "/" + getPendantBagLimit() + "]\n";
    out += "━━━━━━━━━━━━━\n";
    out += "※ 펜던트 장착: /펜던트장착 [펜던트가방번호]\n";
    out += "※ 펜던트 판매: /펜던트판매 [번호]\n";
    out += "※ 펜던트 정보: /펜던트정보 [번호]\n";
    out += "※ 펜던트 강화: /펜던트강화 [펜던트가방번호] (장착 펜던트는 0)\n";
    out += "※ 창조 승급: /펜던트승급 [펜던트가방번호] (장착 펜던트는 0)\n";
    out += "※ 창세 조합: /펜던트조합창세 [번호] [번호] [번호] [번호] [번호] [번호]\n";
    out += "※ 창조 조합: /펜던트조합창조 [번호] [번호] [번호]\n";
    out += "※ 펜던트 정리: /펜던트가방정리 [번호~번호]\n";
    out += "※ 펜던트 해제: /펜던트해제 (귀속권 필요)\n";
    out += "━━━━━━━━━━━━━\n";
    if (bag.length === 0) return out + "보유한 펜던트가 없습니다.";
    for (var i = 0; i < bag.length; i++) {
        if (i === 5 && typeof allsee !== "undefined") out += allsee + "\n";
        out += (i + 1) + ". " + formatPendantDisplay(bag[i]) + "\n";
    }
    return out.trim();
}

// 펜던트 창조조합 사용법을 만드는 함수
function buildPendantCreationCombinationGuide() {
    return "📿 펜던트 창조조합\n" +
        "━━━━━━━━━━━━━━━\n" +
        "창세의 펜던트🌠[창세] ×3\n" +
        "             ↓\n" +
        "창조의 펜던트🪬[창조] ×1\n" +
        "━━━━━━━━━━━━━━━\n" +
        "✅ 성공률: 100%\n" +
        "💰 포인트 소모: 없음\n\n" +
        "사용법:\n" +
        "/펜던트조합창조 [펜던트가방번호] [펜던트가방번호] [펜던트가방번호]\n\n" +
        "예시: /펜던트조합창조 3 7 9\n\n" +
        "※ 서로 다른 가방 번호 3개를 입력해주세요.\n" +
        "※ 강화된 창세 펜던트도 재료로 사용할 수 있습니다.\n" +
        "※ 조합 시 선택한 창세의 펜던트 3개가 소모됩니다.";
}

// 최근 성공한 동일 펜던트 조합 요청인지 확인하는 함수
function isDuplicatePendantCombination(sender, msg) {
    var state = userState[sender] && userState[sender].pendantCombination;
    return !!(state && state.command === msg && Date.now() - state.completedAt < GLOBAL_CONFIG.pendant.creationCombinationDuplicateMs);
}

// 성공한 펜던트 조합 요청을 잠시 기록하는 함수
function markPendantCombination(sender, msg) {
    if (!userState[sender]) userState[sender] = {};
    userState[sender].pendantCombination = { command: msg, completedAt: Date.now() };
}

// 선택한 초월 펜던트 6개를 창세 펜던트 1개로 조합하는 함수
function combineGenesisPendant(data, petData, guildData, sender, indexTexts) {
    var indexes = [];
    var seenIndexes = {};
    for (var i = 0; i < indexTexts.length; i++) {
        var index = parseInt(indexTexts[i], 10);
        if (isNaN(index) || index < 1) return { ok: false, message: "❌ 가방 번호는 양의 정수로 입력해주세요.\n재료는 소모되지 않았습니다." };
        if (seenIndexes[index]) return { ok: false, message: "❌ 서로 다른 가방 번호 6개를 입력해주세요.\n재료는 소모되지 않았습니다." };
        seenIndexes[index] = true;
        indexes.push(index);
    }
    if (indexes.length !== 6) return { ok: false, message: "❌ 천공의 펜던트 6개를 선택해주세요.\n재료는 소모되지 않았습니다." };

    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    var selected = []; // 검증을 통과한 재료의 원본 가방 위치
    for (var j = 0; j < indexes.length; j++) {
        if (indexes[j] > bag.length) return { ok: false, message: "❌ 가방 " + indexes[j] + "번 펜던트가 존재하지 않습니다.\n펜던트가방에서 번호를 확인해주세요.\n재료는 소모되지 않았습니다." };
        var pendant = bag[indexes[j] - 1];
        if (!pendant || pendant.grade !== "초월") {
            return { ok: false, message: "❌ 가방 " + indexes[j] + "번은 천공의 펜던트🪽[초월]가 아닙니다.\n재료는 소모되지 않았습니다." };
        }
        selected.push({ arrayIndex: indexes[j] - 1, pendant: pendant });
    }

    selected.sort(function(a, b) { return b.arrayIndex - a.arrayIndex; });
    for (var k = 0; k < selected.length; k++) bag.splice(selected[k].arrayIndex, 1);
    var genesisInfo = getPendantGradeInfo("창세");
    bag.push(createPendantByGradeInfo(genesisInfo));
    sortPendantBagByGrade(bag);

    var displayIndexes = indexes.slice(0).sort(function(a, b) { return a - b; }); // 성공 메시지용 조합 전 가방 번호
    return {
        ok: true,
        message: "📿 펜던트 창세조합 완료!\n[" + checkRank(data, petData, guildData, sender) + "]\n" +
            "━━━━━━━━━━━━━━━\n" +
            "소모한 재료\n" +
            "가방 " + displayIndexes.join("번 · ") + "번\n" +
            "천공의 펜던트🪽[초월] ×6\n\n" +
            "🎉 획득 아이템\n" +
            "창세의 펜던트🌠[창세] ×1\n" +
            "━━━━━━━━━━━━━━━\n" +
            "💰 소모 포인트: 0\n" +
            "펜던트가방을 확인해주세요."
    };
}

// 펜던트 창세조합 사용법을 만드는 함수
function buildPendantGenesisCombinationGuide() {
    return "📿 펜던트 창세조합\n" +
        "━━━━━━━━━━━━━━━\n" +
        "천공의 펜던트🪽[초월] ×6\n" +
        "             ↓\n" +
        "창세의 펜던트🌠[창세] ×1\n" +
        "━━━━━━━━━━━━━━━\n" +
        "✅ 성공률: 100%\n" +
        "💰 포인트 소모: 없음\n\n" +
        "사용법:\n" +
        "/펜던트조합창세 [번호] [번호] [번호] [번호] [번호] [번호]\n\n" +
        "예시: /펜던트조합창세 1 2 3 4 5 6\n\n" +
        "※ 서로 다른 가방 번호 6개를 입력해주세요.\n" +
        "※ 강화된 초월 펜던트도 재료로 사용할 수 있습니다.\n" +
        "※ 조합 시 선택한 천공의 펜던트 6개가 소모됩니다.";
}

// 선택한 창세 펜던트 3개를 창조 펜던트 1개로 조합하는 함수
function combineCreationPendant(data, petData, guildData, sender, indexTexts) {
    var indexes = [];
    var seenIndexes = {};
    for (var i = 0; i < indexTexts.length; i++) {
        var index = parseInt(indexTexts[i], 10);
        if (isNaN(index) || index < 1) return { ok: false, message: "❌ 가방 번호는 양의 정수로 입력해주세요.\n재료는 소모되지 않았습니다." };
        if (seenIndexes[index]) return { ok: false, message: "❌ 서로 다른 가방 번호 3개를 입력해주세요.\n재료는 소모되지 않았습니다." };
        seenIndexes[index] = true;
        indexes.push(index);
    }
    if (indexes.length !== 3) return { ok: false, message: "❌ 창세의 펜던트 3개를 선택해주세요.\n재료는 소모되지 않았습니다." };

    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    var selected = [];
    for (var j = 0; j < indexes.length; j++) {
        if (indexes[j] > bag.length) return { ok: false, message: "❌ 가방 " + indexes[j] + "번 펜던트가 존재하지 않습니다.\n펜던트가방에서 번호를 확인해주세요.\n재료는 소모되지 않았습니다." };
        var pendant = bag[indexes[j] - 1];
        if (!pendant || pendant.grade !== "창세") {
            return { ok: false, message: "❌ 가방 " + indexes[j] + "번은 창세의 펜던트🌠[창세]가 아닙니다.\n재료는 소모되지 않았습니다." };
        }
        selected.push({ arrayIndex: indexes[j] - 1, pendant: pendant });
    }

    selected.sort(function(a, b) { return b.arrayIndex - a.arrayIndex; });
    for (var k = 0; k < selected.length; k++) bag.splice(selected[k].arrayIndex, 1);
    var creationInfo = getPendantGradeInfo("창조");
    bag.push(createPendantByGradeInfo(creationInfo));
    sortPendantBagByGrade(bag);

    var displayIndexes = indexes.slice(0).sort(function(a, b) { return a - b; });
    return {
        ok: true,
        message: "📿 펜던트 창조조합 완료!\n[" + checkRank(data, petData, guildData, sender) + "]\n" +
            "━━━━━━━━━━━━━━━\n" +
            "소모한 재료\n" +
            "가방 " + displayIndexes.join("번 · ") + "번\n" +
            "창세의 펜던트🌠[창세] ×3\n\n" +
            "🎉 획득 아이템\n" +
            "창조의 펜던트🪬[창조] ×1\n" +
            "━━━━━━━━━━━━━━━\n" +
            "💰 소모 포인트: 0\n" +
            "펜던트가방을 확인해주세요."
    };
}

// 펜던트 번호로 장착/가방 펜던트 조회
function getPendantByIndex(petData, user, index) {
    var pet = ensurePendantUser(petData, user);
    if (index === 0) return { pendant: pet.pendant || null, source: "equipped", arrayIndex: -1 };
    var bag = getPendantBag(petData, user);
    sortPendantBagByGrade(bag);
    if (index < 1 || index > bag.length) return { pendant: null, source: "bag", arrayIndex: -1 };
    return { pendant: bag[index - 1], source: "bag", arrayIndex: index - 1 };
}

// 창조 펜던트 승급 미리보기와 확인 상태를 생성하는 함수
function buildPendantPromotionPreview(data, petData, guildData, sender, index) {
    var targetInfo = getPendantByIndex(petData, sender, index);
    if (!targetInfo.pendant) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다.\n장착 펜던트는 0, 가방 펜던트는 가방 번호를 입력해 주세요." };
    var target = targetInfo.pendant;
    if (target.grade !== GLOBAL_CONFIG.pendant.promotionGrade) return { ok: false, message: "❌ 창조 등급 펜던트만 승급할 수 있습니다." };
    var currentLevel = normalizePendantPromotionLevel(target);
    var costs = getPendantPromotionCosts(currentLevel + 1);
    if (!costs) return { ok: false, message: "❌ 다음 승급 단계가 안전한 계산 범위를 초과하여 진행할 수 없습니다." };
    var materialInfo = selectPendantPromotionMaterial(petData, sender, target.pendantId);
    var pointHave = Number(data.member[sender].point) || 0;
    var pointDeduction = calculatePendantPromotionPointDeduction(pointHave, costs.points); // 현재 잔액에서 승급 비용을 정확히 차감할 수 있는지 확인
    var stoneName = GLOBAL_CONFIG.items.pendantEnhanceStoneName;
    var stoneHave = data.member[sender].bag && data.member[sender].bag[stoneName] ? parseInt(data.member[sender].bag[stoneName], 10) || 0 : 0;
    var shortageLines = [];
    if (!materialInfo) shortageLines.push("창조의 펜던트🪬: 필요 1개 / 보유 0개");
    if (!pointDeduction.ok && pointDeduction.reason === "insufficient") shortageLines.push("포인트💸: 필요 🅟" + numberWithCommas(costs.points) + " / 보유 🅟" + numberWithCommas(pointHave));
    if (!pointDeduction.ok && pointDeduction.reason !== "insufficient") shortageLines.push("포인트💸: 현재 잔액에서 승급 비용을 정확히 차감할 수 없습니다.");
    if (stoneHave < costs.stones) shortageLines.push(stoneName + ": 필요 " + numberWithCommas(costs.stones) + "개 / 보유 " + numberWithCommas(stoneHave) + "개");
    if (shortageLines.length) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n❌ 펜던트 승급 조건을 충족하지 못했습니다.\n━━━━━━━━━━━━━\n" + shortageLines.join("\n") };
    var beforeStats = calculatePendantStats(target);
    var afterTarget = cloneFreeMarketObject(target);
    afterTarget.promotionLevel = costs.level;
    var afterStats = calculatePendantStats(afterTarget);
    setPendantPromotionState(sender, { targetPendantId: target.pendantId, materialPendantId: materialInfo.pendant.pendantId, expectedLevel: currentLevel });
    var out = "[" + checkRank(data, petData, guildData, sender) + "] 님\n💎 창조 펜던트 승급\n━━━━━━━━━━━━━\n";
    out += "대상: " + formatPendantDisplay(target) + "\n";
    out += "재료: " + formatPendantDisplay(materialInfo.pendant) + "\n\n";
    out += "승급: ★" + currentLevel + " → ★" + costs.level + "\n";
    out += "종합매력👑: " + numberWithCommas(beforeStats.charm) + " → " + numberWithCommas(afterStats.charm) + "💞\n";
    out += "펫탐험성공확률⛰️: +" + formatPendantPercent(beforeStats.explore) + "% (변화 없음)\n\n";
    out += "필요 포인트💸: 🅟" + numberWithCommas(costs.points) + "\n";
    out += "필요 " + stoneName + ": " + numberWithCommas(costs.stones) + "개\n";
    out += "성공 확률: 100%\n━━━━━━━━━━━━━\n👉 [승급할거임] / [쫄아뜸]\n※ 30초 안에 선택해 주세요.";
    return { ok: true, message: out };
}

// 저장된 확인 상태를 재검증해 창조 펜던트 승급을 실행하는 함수
function runPendantPromotionFromState(sender, data, petData, guildData) {
    var state = getPendantPromotionState(sender);
    if (!state) return { ok: false, message: "펜던트 승급 확인 시간이 만료되었습니다." };
    if (state.processing) return { ok: false, message: "펜던트 승급을 처리 중입니다." };
    state.processing = true;
    var targetInfo = getPendantById(petData, sender, state.targetPendantId);
    var materialInfo = getPendantById(petData, sender, state.materialPendantId);
    if (!targetInfo.pendant || !materialInfo.pendant || materialInfo.source !== "bag") return { ok: false, message: "대상 또는 재료 펜던트 상태가 변경되어 승급을 취소했습니다." };
    if (targetInfo.pendant.grade !== GLOBAL_CONFIG.pendant.promotionGrade || materialInfo.pendant.grade !== GLOBAL_CONFIG.pendant.promotionGrade) return { ok: false, message: "창조 등급 펜던트만 대상과 재료로 사용할 수 있습니다." };
    var currentLevel = normalizePendantPromotionLevel(targetInfo.pendant);
    if (currentLevel !== state.expectedLevel) return { ok: false, message: "대상 펜던트의 승급 단계가 변경되어 요청을 취소했습니다." };
    var costs = getPendantPromotionCosts(currentLevel + 1);
    if (!costs) return { ok: false, message: "다음 승급 단계가 안전한 계산 범위를 초과했습니다." };
    var currentPoint = Number(data.member[sender].point) || 0;
    var pointDeduction = calculatePendantPromotionPointDeduction(currentPoint, costs.points); // 확정 시점의 포인트 차감 가능 여부 재검증
    if (!pointDeduction.ok && pointDeduction.reason === "insufficient") return { ok: false, message: "포인트가 부족합니다." };
    if (!pointDeduction.ok) return { ok: false, message: "현재 포인트에서 승급 비용을 정확히 차감할 수 없어 승급을 취소했습니다." };
    var stoneName = GLOBAL_CONFIG.items.pendantEnhanceStoneName;
    if (!hasItem(data, sender, stoneName, costs.stones)) return { ok: false, message: stoneName + "이 부족합니다." };
    data.member[sender].point = pointDeduction.nextPoint;
    removeItem(data, sender, stoneName, costs.stones);
    getPendantBag(petData, sender).splice(materialInfo.arrayIndex, 1);
    targetInfo.pendant.promotionLevel = costs.level;
    targetInfo.pendant.promotionUpdatedAt = formatDateTime(new Date());
    var stats = calculatePendantStats(targetInfo.pendant);
    return {
        ok: true,
        message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n✅ 창조 펜던트 승급 성공!\n━━━━━━━━━━━━━\n" + formatPendantDisplay(targetInfo.pendant) + "\n종합매력👑: " + numberWithCommas(stats.charm) + "💞\n펫탐험성공확률⛰️: +" + formatPendantPercent(stats.explore) + "%\n\n사용 포인트💸: 🅟" + numberWithCommas(costs.points) + "\n사용 " + stoneName + ": " + numberWithCommas(costs.stones) + "개",
        noticeMessage: "[💎 펜던트 승급 전체 알림]\n[" + checkRank(data, petData, guildData, sender) + "] 님이 창조의 펜던트를 [창조★" + costs.level + "] 등급으로 승급했습니다!"
    };
}

// 펜던트 정보 메시지 생성
function buildPendantInfoMessage(data, petData, guildData, user, index) {
    var info = getPendantByIndex(petData, user, index);
    if (!info.pendant) return "[" + checkRank(data, petData, guildData, user) + "] 님\n해당 번호의 펜던트가 존재하지 않습니다.";
    return buildPendantInfoDetailMessage("펜던트 정보:", info.pendant);
}

// 펜던트 상세 정보 출력 문자열 생성
function buildPendantInfoDetailMessage(title, pendant) {
    var stats = calculatePendantStats(pendant);
    var next = Math.min(30, (parseInt(pendant.upgrade || 0, 10) + 1));
    var nextInfo = PENDANT_UPGRADE_TABLE[next];
    var out = title + "\n";
    out += formatPendantDisplay(pendant) + "\n";
    out += "━━━━━━━━━━━━━\n";
    out += "기본 종합매력👑: " + numberWithCommas(stats.baseCharm) + "💞\n";
    out += "강화 종합매력👑: +" + numberWithCommas(stats.upgradeCharm) + "💞\n";
    out += "승급 종합매력👑: +" + numberWithCommas(stats.promotionCharm) + "💞\n";
    out += allsee + "\n";
    out += "총 종합매력👑: " + numberWithCommas(stats.charm) + "💞\n\n";
    out += "기본 펫탐험성공확률⛰️: +" + formatPendantPercent(stats.baseExplore) + "%\n";
    out += "강화 펫탐험성공확률⛰️: +" + formatPendantPercent(stats.upgradeExplore) + "%\n";
    out += "총 펫탐험성공확률⛰️: +" + formatPendantPercent(stats.explore) + "%\n\n";
    out += "남은 내구도⚒️: " + (pendant.durability || 0) + "회\n";
    if (parseInt(pendant.upgrade || 0, 10) >= 30) {
        out += "이미 최대 강화 단계입니다.";
    } else {
        out += "다음 강화성공 확률🎲: " + nextInfo.rate + "%\n";
        out += "다음 강화비용💸: 🅟" + numberWithCommas(nextInfo.point) + "\n";
        out += "필요 강화석📿: " + nextInfo.stone + "개";
    }
    if (pendant.grade === GLOBAL_CONFIG.pendant.promotionGrade) {
        var promotionCosts = getPendantPromotionCosts(normalizePendantPromotionLevel(pendant) + 1);
        out += "\n━━━━━━━━━━━━━\n🌟 창조 펜던트 승급\n";
        out += "현재 단계: ★" + normalizePendantPromotionLevel(pendant) + "\n";
        if (promotionCosts) {
            out += "다음 단계: ★" + promotionCosts.level + "\n";
            out += "필요 포인트💸: 🅟" + numberWithCommas(promotionCosts.points) + "\n";
            out += "필요 " + GLOBAL_CONFIG.items.pendantEnhanceStoneName + ": " + numberWithCommas(promotionCosts.stones) + "개\n";
            out += "필요 재료: 다른 창조의 펜던트 1개";
        } else {
            out += "다음 승급 단계가 안전한 계산 범위를 초과했습니다.";
        }
    }
    return out;
}

// 펜던트 오픈 처리
function runPendantOpen(sender, data, petData, guildData, msg) {
    if (!data.member[sender] || !petData[sender]) return { ok: false, message: "펫을 먼저 생성해주세요." };
    var count = 1;
    var m = msg.match(/^\/펜던트오픈\s+(\d+)$/);
    if (m) count = parseInt(m[1], 10);
    if (!count || count < 1) return { ok: false, message: "사용법: /펜던트오픈 [갯수]" };
    var ticketName = GLOBAL_CONFIG.items.pendantOpenTicketName;
    var have = data.member[sender].bag && data.member[sender].bag[ticketName] ? data.member[sender].bag[ticketName] : 0;
    if (have <= 0) return { ok: false, message: "펜던트뽑기💎가 부족합니다." };
    var bag = getPendantBag(petData, sender);
    var remain = getPendantBagLimit() - bag.length;
    if (remain <= 0) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n펜던트 가방이 가득 차서 펜던트뽑기를 진행할 수 없습니다.\n━━━━━━━━━━━━━\n펜던트가방💎: " + bag.length + "/" + getPendantBagLimit() + "\n불필요한 펜던트를 판매하거나 정리해주세요." };
    var openCount = Math.min(count, have);
    var noticeLines = [];
    var openedPendants = [];
    var out = "💎[" + checkRank(data, petData, guildData, sender) + "] 님이 펜던트를 오픈합니다!\n";
    out += "확률정보: 채팅창에 '/펜던트확률'를 적어보세요\n";
    out += "━━━━━━━━━━━━━━━\n";
    out += "✅️ 사용: " + openCount + "개\n";
    removeItem(data, sender, ticketName, openCount);
    for (var i = 0; i < openCount; i++) {
        var pendant = pickRandomPendant();
        bag.push(pendant);
        openedPendants.push(pendant);
        if (getPendantGradeInfo(pendant.grade).notice) {
            var pendantNoticeGradeInfo = getPendantGradeInfo(pendant.grade);
            noticeLines.push("[전체알림💎]\n[" + checkRank(data, petData, guildData, sender) + "] 님이 펜던트💎\n" + pendant.name + pendant.icon + "[" + pendant.grade + "](확률 " + formatPendantPercent(pendantNoticeGradeInfo.rate) + "%)을(를) 획득했습니다!");
        }
    }
    out += "💎 남은 펜던트뽑기: " + numberWithCommas(data.member[sender].bag[ticketName] || 0) + "개\n";
    out += "🎒 펜던트 가방: " + bag.length + "/" + getPendantBagLimit() + "\n";
    out += "━━━━━━━━━━━━━━━\n";
    sortPendantBagByGrade(openedPendants);
    for (var j = 0; j < openedPendants.length; j++) {
        if (j === 4) out += allsee;
        out += (j + 1) + ". " + formatPendantOpenResultDisplay(openedPendants[j]) + "\n";
    }
    out = out.replace(/\n$/, "");
    return { ok: true, message: out, noticeMessages: noticeLines, noticeMessage: "" };
}

// 펜던트 장착 확인 상태 저장
function setPendantEquipState(sender, index) {
    if (!userState[sender]) userState[sender] = {};
    userState[sender].pendantEquip = { index: index, createdAt: new Date().getTime() };
}

// 펜던트 장착 확인 상태 반환
function getPendantEquipState(sender) {
    if (!userState[sender] || !userState[sender].pendantEquip) return null;
    var state = userState[sender].pendantEquip;
    var staleMs = GLOBAL_CONFIG.pendant.equipConfirmStaleMs;
    if (new Date().getTime() - state.createdAt > staleMs) {
        delete userState[sender].pendantEquip;
        return null;
    }
    return state;
}

// 펜던트 장착 확인 상태 삭제
function clearPendantEquipState(sender) {
    if (userState[sender] && userState[sender].pendantEquip) delete userState[sender].pendantEquip;
}

// 펜던트 교체 확인 메시지 생성
function buildPendantEquipConfirmMessage(data, petData, guildData, sender, pendant) {
    return "[" + formatPendantDisplay(pendant) + "]\n\n" +
        "펜던트는 한 번 장착하면 귀속됩니다.\n" +
        "장착 후에는 가방으로 되돌릴 수 없고\n" +
        "기존 장착 펜던트는 소멸됩니다.\n\n" +
        "그래도 장착하시겠습니까?\n\n" +
        "👉 [장착할래] / [생각해볼게]\n\n" +
        "*펜던트를 펜던트가방으로 이동시키려면\n" +
        "펜던트귀속해제💎(/펜던트해제) 가 필요합니다.";
}

// 펜던트 장착 처리
function equipPendantFromBag(data, petData, guildData, sender, index, forceReplace) {
    var pet = ensurePendantUser(petData, sender);
    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    if (index < 1 || index > bag.length) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    var selectedPendant = bag[index - 1];
    if (!selectedPendant || !selectedPendant.name || !selectedPendant.grade) return { ok: false, message: "해당 아이템은 펜던트가 아닙니다." };
    if (pet.pendant && !forceReplace) return { ok: false, pending: true, message: buildPendantEquipConfirmMessage(data, petData, guildData, sender, selectedPendant) };
    var pendant = bag.splice(index - 1, 1)[0];
    pendant.bound = true;
    pet.pendant = pendant;
    var stats = calculatePendantStats(pendant);
    if (forceReplace) return { ok: true, message: "[" + checkRank(data, petData, guildData, sender) + "]님이\n" + formatPendantDisplay(pendant) + "\n펜던트를 새롭게 장착하였습니다." };
    return { ok: true, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n펜던트를 장착 하였습니다.\n━━━━━━━━━━━━━\n" + formatPendantDisplay(pendant) + "\n\n종합매력👑: " + numberWithCommas(stats.charm) + "💞\n펫탐험성공확률⛰️ +" + formatPendantPercent(stats.explore) + "%\n남은 내구도⚒️: " + pendant.durability + "회" };
}

// 펜던트 해제 처리
function unequipPendantToBag(data, petData, guildData, sender) {
    var pet = ensurePendantUser(petData, sender);
    if (!pet.pendant) return { ok: false, message: "장착 중인 펜던트가 없습니다." };
    var bag = getPendantBag(petData, sender);
    if (bag.length >= getPendantBagLimit()) return { ok: false, message: "펜던트가방에 빈칸이 없습니다." };
    var itemName = GLOBAL_CONFIG.items.pendantUnbindItemName;
    var unbindItemCount = data.member[sender].bag && data.member[sender].bag[itemName] ? data.member[sender].bag[itemName] : 0;
    if (unbindItemCount < 1) return { ok: false, message: "펜던트귀속해제💎(/펜던트해제)가 부족합니다.\n귀속권 보유: ❌ 없음" };
    removeItem(data, sender, itemName, 1);
    var remainUnbindItemCount = data.member[sender].bag && data.member[sender].bag[itemName] ? data.member[sender].bag[itemName] : 0;
    var pendant = pet.pendant;
    pendant.bound = false;
    bag.push(pendant);
    delete pet.pendant;
    return { ok: true, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n━━━━━━━━━━━━━\n" + formatPendantDisplay(pendant) + " 을(를)\n펜던트 가방💎으로 이동시켰습니다.\n귀속권 사용: 1개\n남은 귀속권: " + remainUnbindItemCount + "개" };
}

// 펜던트 복원 처리
function restorePendantDurability(data, petData, guildData, sender, index) {
    var info = getPendantByIndex(petData, sender, index);
    if (!info.pendant) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    var maxDurability = info.pendant.maxDurability || 5;
    if ((info.pendant.durability || 0) >= maxDurability) return { ok: false, message: "이미 내구도가 최대치입니다." };
    var itemName = GLOBAL_CONFIG.items.pendantRestoreStoneName;
    if (!hasItem(data, sender, itemName, 1)) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n펜던트 복원석🔷이 부족합니다.\n━━━━━━━━━━━━━\n펜던트 복원석🔷은 미궁 콘텐츠에서 획득할 수 있습니다." };
    var before = info.pendant.durability || 0;
    removeItem(data, sender, itemName, 1);
    info.pendant.durability = maxDurability;
    return { ok: true, message: "펜던트 복원🔷\n━━━━━━━━━━━━━\n[" + checkRank(data, petData, guildData, sender) + "] 님\n" + formatPendantDisplay(info.pendant) + "\n의 내구도를 복원하였습니다.\n━━━━━━━━━━━━━\n기존 내구도: " + before + "회\n복원된 내구도: " + maxDurability + "회" };
}

// 펜던트 강화 확인 상태 저장
function setPendantUpgradeState(sender, index) {
    if (!userState[sender]) userState[sender] = {};
    userState[sender].pendantUpgrade = { index: index, createdAt: new Date().getTime() };
}

// 펜던트 강화 확인 상태 반환
function getPendantUpgradeState(sender) {
    if (!userState[sender] || !userState[sender].pendantUpgrade) return null;
    var state = userState[sender].pendantUpgrade;
    if (!state.createdAt || new Date().getTime() - state.createdAt > 30000) {
        delete userState[sender].pendantUpgrade;
        return null;
    }
    return state;
}

// 펜던트 강화 확인 상태 삭제
function clearPendantUpgradeState(sender) {
    if (userState[sender] && userState[sender].pendantUpgrade) delete userState[sender].pendantUpgrade;
}

// 펜던트 강화에 적용되는 펫스킬북 보너스 확률 반환
function getPendantUpgradePetSkillBonusRate(petSkillData, sender) {
    return hasPetSkill(petSkillData, sender, "결혼못한 대장장이") ? 1 : 0;
}

// 펜던트 강화 성공 확률 표시 문구 생성
function formatPendantUpgradeRateLine(baseRate, bonusRate) {
    var finalRate = Math.min(100, baseRate + bonusRate); // 펫스킬북 적용 후 최종 성공 확률
    if (bonusRate > 0) {
        return "강화성공 확률🎲: " + formatPendantPercent(baseRate) + "%+" + formatPendantPercent(bonusRate) + "% = " + formatPendantPercent(finalRate) + "%\n결혼못한 대장장이📙 " + formatPendantPercent(bonusRate) + "% 적용";
    }
    return "강화성공 확률🎲: " + formatPendantPercent(baseRate) + "%";
}

// 펜던트 강화 미리보기 생성
function buildPendantUpgradePreview(data, petData, guildData, petSkillData, sender, index) {
    var info = getPendantByIndex(petData, sender, index);
    if (!info.pendant) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다.\n━━━━━━━━━━━━━\n예) /펜던트강화 [펜던트가방번호]\n혹은 장착 펜던트는 숫자 0을 입력해주세요." };
    var upgrade = parseInt(info.pendant.upgrade || 0, 10);
    if (upgrade >= 30) return { ok: false, message: "이미 펜던트 최대 강화 단계에 도달했습니다.\n━━━━━━━━━━━━━\n현재 강화수치: +30\n최대 강화수치: +30" };
    if ((info.pendant.durability || 0) <= 0) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n해당 펜던트는 내구도가 0이라 강화할 수 없습니다.\n━━━━━━━━━━━━━\n/펜던트복원 [번호] 명령어로 복원 후 다시 시도해주세요." };
    var next = upgrade + 1;
    var nextInfo = PENDANT_UPGRADE_TABLE[next];
    var pointHave = data.member[sender].point || 0;
    var stoneHave = data.member[sender].bag && data.member[sender].bag[GLOBAL_CONFIG.items.pendantEnhanceStoneName] ? data.member[sender].bag[GLOBAL_CONFIG.items.pendantEnhanceStoneName] : 0;
    if (pointHave < nextInfo.point) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n포인트가 부족하여 펜던트 강화를 진행할 수 없습니다.\n━━━━━━━━━━━━━\n필요 포인트💸: 🅟" + numberWithCommas(nextInfo.point) + "\n보유 포인트💸: 🅟" + numberWithCommas(pointHave) };
    if (stoneHave < nextInfo.stone) return { ok: false, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n펜던트 강화석📿이 부족합니다.\n━━━━━━━━━━━━━\n필요 강화석📿: " + nextInfo.stone + "개\n보유 강화석📿: " + stoneHave + "개" };
    var beforeStats = calculatePendantStats(info.pendant);
    var afterClone = cloneFreeMarketObject(info.pendant);
    afterClone.upgrade = next;
    var afterStats = calculatePendantStats(afterClone);
    var out = "[" + checkRank(data, petData, guildData, sender) + "] 펜던트 강화 시도💎\n━━━━━━━━━━━━━\n";
    out += formatPendantDisplay(info.pendant) + "\n\n";
    out += "강화 성공시:\n";
    out += "종합매력👑: " + numberWithCommas(beforeStats.charm) + "+" + numberWithCommas(afterStats.charm - beforeStats.charm) + "(⬆️)=" + numberWithCommas(afterStats.charm) + "💞\n";
    out += "펫탐험성공확률⛰️:" + formatPendantPercent(beforeStats.explore) + "%+" + formatPendantPercent(afterStats.explore - beforeStats.explore) + "%(⬆️)=" + formatPendantPercent(afterStats.explore) + "%\n\n";
    var skillBonusRate = getPendantUpgradePetSkillBonusRate(petSkillData, sender);
    out += "강화비용💸: 🅟" + numberWithCommas(nextInfo.point) + "\n필요 강화석📿: " + nextInfo.stone + "개\n" + formatPendantUpgradeRateLine(nextInfo.rate, skillBonusRate) + "\n남은 내구도⚒️: " + info.pendant.durability + "회\n━━━━━━━━━━━━━\n펜던트 강화할거임?\n[진행시켜] / [쫄았음]";
    return { ok: true, message: out };
}

// 저장된 확인 상태로 펜던트 강화 실행
function runPendantUpgradeFromState(sender, data, petData, guildData, petSkillData) {
    var state = getPendantUpgradeState(sender);
    if (!state) return { ok: false, message: "펜던트 강화 확인 시간이 만료되었습니다." };
    var info = getPendantByIndex(petData, sender, parseInt(state.index, 10));
    if (!info.pendant) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    var upgrade = parseInt(info.pendant.upgrade || 0, 10);
    var next = upgrade + 1;
    var nextInfo = PENDANT_UPGRADE_TABLE[next];
    if (!nextInfo) return { ok: false, message: "이미 펜던트 최대 강화 단계에 도달했습니다." };
    if ((info.pendant.durability || 0) <= 0) return { ok: false, message: "해당 펜던트는 내구도가 0이라 강화할 수 없습니다." };
    if ((data.member[sender].point || 0) < nextInfo.point) return { ok: false, message: "포인트가 부족합니다." };
    if (!hasItem(data, sender, GLOBAL_CONFIG.items.pendantEnhanceStoneName, nextInfo.stone)) return { ok: false, message: "펜던트 강화석📿이 부족합니다." };
    data.member[sender].point -= nextInfo.point;
    removeItem(data, sender, GLOBAL_CONFIG.items.pendantEnhanceStoneName, nextInfo.stone);
    var skillBonusRate = getPendantUpgradePetSkillBonusRate(petSkillData, sender);
    var successRate = Math.min(100, nextInfo.rate + skillBonusRate); // 실제 강화 판정에 사용하는 최종 성공 확률
    var success = Math.random() * 100 < successRate;
    if (success) {
        info.pendant.upgrade = next;
        var successStats = calculatePendantStats(info.pendant);
        return { ok: true, message: "[✅][" + checkRank(data, petData, guildData, sender) + "] 님! 영롱하군요🤩🤩\n\n펜던트 강화 성공!\n━━━━━━━━━━━━━\n" + formatPendantDisplay(info.pendant) + "\n종합매력👑: " + numberWithCommas(successStats.charm) + "💞\n펫탐험성공확률⛰️:" + formatPendantPercent(successStats.explore) + "%\n━━━━━━━━━━━━━\n남은 포인트💸: 🅟" + numberWithCommas(data.member[sender].point || 0) + "\n남은 내구도⚒️: " + info.pendant.durability + "회" };
    }
    info.pendant.durability = Math.max(0, (info.pendant.durability || 0) - 1);
    var failMsg = "[❌][" + checkRank(data, petData, guildData, sender) + "] 야야 [😵]실패네? ㅋㅋ\n━━━━━━━━━━━━━\n" + formatPendantDisplay(info.pendant) + "\n\n남은 포인트💸: 🅟" + numberWithCommas(data.member[sender].point || 0) + "\n남은 내구도⚒️: " + info.pendant.durability + "회";
    if (info.pendant.durability <= 0) failMsg += "\n*복원석으로 수리해보세요.";
    return { ok: true, message: failMsg };
}

// 펜던트 단일 판매 처리
function sellPendantFromBag(data, petData, guildData, sender, index) {
    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    if (index < 1 || index > bag.length) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    var pendant = bag.splice(index - 1, 1)[0];
    var price = 20000000;
    data.member[sender].point = (data.member[sender].point || 0) + price;
    return { ok: true, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n" + formatPendantDisplay(pendant) + " 을(를) 판매했습니다.\n━━━━━━━━━━━━━\n획득 포인트💸: 🅟" + numberWithCommas(price) + "\n현재 포인트💸: 🅟" + numberWithCommas(data.member[sender].point || 0) };
}

// 펜던트 가방 범위 판매 처리
function cleanPendantBagRange(data, petData, guildData, sender, msg) {
    var m = msg.match(/^\/펜던트가방정리\s+(\d+)~(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트가방정리 번호~번호" };
    var start = parseInt(m[1], 10);
    var end = parseInt(m[2], 10);
    if (start > end) {
        var tmp = start;
        start = end;
        end = tmp;
    }
    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    if (start < 1 || end > bag.length) return { ok: false, message: "정리 범위가 올바르지 않습니다." };
    var count = end - start + 1;
    bag.splice(start - 1, count);
    var point = count * 20000000;
    data.member[sender].point = (data.member[sender].point || 0) + point;
    return { ok: true, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n펜던트 " + count + "개를 정리했습니다.\n획득 포인트💸: 🅟" + numberWithCommas(point) };
}

// 전체 유저의 미니펫 가방 보유 수량을 합산하는 함수
function countAllMiniPetBagItems(petData) {
    var totalCount = 0;
    for (var name in petData) {
        if (!petData.hasOwnProperty(name)) continue;
        var bag = petData[name] && Array.isArray(petData[name].miniPetBag) ? petData[name].miniPetBag : [];
        totalCount += bag.length;
    }
    return totalCount;
}

// 전체 유저의 가구 가방 보유 수량을 합산하는 함수
function countAllFurnitureBagItems(homeData) {
    var totalCount = 0;
    for (var name in homeData) {
        if (!homeData.hasOwnProperty(name)) continue;
        var bag = homeData[name] && Array.isArray(homeData[name].furnitureBag) ? homeData[name].furnitureBag : [];
        totalCount += bag.length;
    }
    return totalCount;
}

// 전체 미니펫 가방 초과분 정리
function cleanAllMiniPetBags(data, petData, guildData, miniPetData) {
    if (!petData) return { ok: false, totalUserCount: 0, totalRemovedCount: 0, userLogLines: [], message: "❌ 미니펫 데이터가 없습니다." };
    var totalUserCount = 0;
    var totalRemovedCount = 0;
    var userLogLines = [];
    for (var name in petData) {
        if (!petData.hasOwnProperty(name)) continue;
        var userPet = petData[name];
        if (!userPet.miniPetBag || !userPet.miniPetBag.length) continue;
        refreshMiniPetSortIndex(petData, name, miniPetData.gradeTable);
        var bag = userPet.miniPetBag;
        var count = bag.length;
        var keepCount = getMiniPetBagLimit(data, name);
        if (count <= keepCount) continue;
        var removedCount = count - keepCount;
        userPet.miniPetBag = bag.slice(0, keepCount);
        refreshMiniPetSortIndex(petData, name, miniPetData.gradeTable);
        totalUserCount++;
        totalRemovedCount += removedCount;
        userLogLines.push("[" + checkRank(data, petData, guildData, name) + "] " + count + "마리 → " + keepCount + "마리 (삭제: " + removedCount + "마리)");
    }
    if (totalUserCount === 0) {
        return { ok: false, totalUserCount: 0, totalRemovedCount: 0, userLogLines: [], message: "✅ 정리 대상 유저가 없습니다.\n(각 이용자의 가방 한도를 초과한 미니펫이 없습니다.)" };
    }
    var msgText = "🧹 [관리자 전용] 미니펫 가방 전체 정리 완료\n";
    msgText += "━━━━━━━━━━━━━━━\n";
    msgText += "정리 대상 유저 수 : " + totalUserCount + "명\n";
    msgText += "전체 삭제된 미니펫 : " + totalRemovedCount + "마리\n";
    msgText += "※ 각 유저별 현재 가방 한도만 남기고 나머지는 영구 삭제되었습니다.\n";
    msgText += "━━━━━━━━━━━━━━━\n";
    msgText += allsee + userLogLines.join("\n");
    return { ok: true, totalUserCount: totalUserCount, totalRemovedCount: totalRemovedCount, userLogLines: userLogLines, message: msgText };
}

// 전체 가구 가방 초과분 정리
function cleanAllFurnitureBags(data, petData, guildData, homeData) {
    if (!homeData) return { ok: false, totalUserCount: 0, totalRemovedCount: 0, userLogLines: [], message: "❌ 가구 데이터가 없습니다." };
    var totalUserCount = 0;
    var totalRemovedCount = 0;
    var userLogLines = [];
    for (var name in homeData) {
        if (!homeData.hasOwnProperty(name)) continue;
        homeData = initSweetHomeUser(homeData, name);
        var userHome = homeData[name];
        if (!userHome.furnitureBag) userHome.furnitureBag = [];
        var bagArr = userHome.furnitureBag;
        var count = bagArr.length;
        var keepCount = getFurnitureBagLimit(data, name);
        if (count <= keepCount) continue;
        bagArr = sortFurnitureList(bagArr);
        userHome.furnitureBag = bagArr;
        var removedCount = count - keepCount;
        userHome.furnitureBag = sortFurnitureList(bagArr.slice(0, keepCount));
        totalUserCount++;
        totalRemovedCount += removedCount;
        userLogLines.push("[" + checkRank(data, petData, guildData, name) + "] " + count + "개 → " + keepCount + "개 (삭제: " + removedCount + "개)");
    }
    if (totalUserCount === 0) {
        return { ok: false, totalUserCount: 0, totalRemovedCount: 0, userLogLines: [], message: "✅ 정리 대상 유저가 없습니다.\n(각 이용자의 가구 가방 한도를 초과한 데이터가 없습니다.)" };
    }
    var msgText = "🧹 [관리자 전용] 가구 가방 전체 정리 완료\n";
    msgText += "━━━━━━━━━━━━━━━\n";
    msgText += "정리 대상 유저 수 : " + totalUserCount + "명\n";
    msgText += "전체 삭제된 가구 : " + totalRemovedCount + "개\n";
    msgText += "※ 각 유저별 현재 가방 한도만 남기고 나머지는 영구 삭제되었습니다.\n";
    msgText += "━━━━━━━━━━━━━━━\n";
    msgText += allsee + userLogLines.join("\n");
    return { ok: true, totalUserCount: totalUserCount, totalRemovedCount: totalRemovedCount, userLogLines: userLogLines, message: msgText };
}

// 전체 유저 펜던트가방 초과분 정리
function cleanAllPendantBags(data, petData, guildData) {
    var totalUserCount = 0;
    var totalRemovedCount = 0;
    var userLogLines = [];
    for (var name in petData) {
        if (!petData.hasOwnProperty(name)) continue;
        var pet = petData[name];
        if (!pet || !Array.isArray(pet.pendantBag)) continue;
        var bag = pet.pendantBag;
        if (bag.length <= getPendantBagLimit()) continue;
        sortPendantBagByGrade(bag);
        var removedCount = bag.length - getPendantBagLimit();
        pet.pendantBag = bag.slice(0, getPendantBagLimit());
        totalUserCount++;
        totalRemovedCount += removedCount;
        userLogLines.push("- [" + checkRank(data, petData, guildData, name) + "] " + removedCount + "개 삭제");
    }
    var msg = "💎 펜던트 전체정리 완료\n";
    msg += "━━━━━━━━━━━━━\n";
    msg += "정리 기준: 펜던트가방 51개 이상\n";
    msg += "정리 유저: " + numberWithCommas(totalUserCount) + "명\n";
    msg += "삭제 펜던트: " + numberWithCommas(totalRemovedCount) + "개";
    if (userLogLines.length) {
        msg += "\n━━━━━━━━━━━━━\n정리 목록\n" + userLogLines.join("\n");
    }
    return { ok: totalRemovedCount > 0, totalUserCount: totalUserCount, totalRemovedCount: totalRemovedCount, userLogLines: userLogLines, message: msg };
}

// 글자수 전체 정리 결과 메시지 생성
function buildTextLengthCleanupMessage(miniResult, furnitureResult, pendantResult) {
    var msg = "[관리자 정리 시스템🧹]\n글자수 전체 정리가 완료되었습니다.\n\n";
    msg += "정리 결과\n";
    msg += "- 미니펫 정리: " + numberWithCommas(miniResult.totalRemovedCount || 0) + "마리 삭제\n";
    msg += "- 가구 정리: " + numberWithCommas(furnitureResult.totalRemovedCount || 0) + "개 삭제\n";
    msg += "- 펜던트 정리: " + numberWithCommas(pendantResult.totalRemovedCount || 0) + "개 삭제\n";
    if (!miniResult.ok && !furnitureResult.ok && !pendantResult.ok) {
        msg += "\n정리할 초과 데이터가 없습니다.";
        return msg;
    }
    msg += "\n데이터 저장이 완료되었습니다.";
    msg += "\n\n상세 결과" + allsee + "\n";
    msg += "[미니펫]\n" + (miniResult.userLogLines && miniResult.userLogLines.length ? miniResult.userLogLines.join("\n") : "정리 대상 없음") + "\n\n";
    msg += "[가구]\n" + (furnitureResult.userLogLines && furnitureResult.userLogLines.length ? furnitureResult.userLogLines.join("\n") : "정리 대상 없음") + "\n\n";
    msg += "[펜던트]\n" + (pendantResult.userLogLines && pendantResult.userLogLines.length ? pendantResult.userLogLines.join("\n") : "정리 대상 없음");
    return msg;
}

// 펜던트 당근 개인거래 처리
function tradePendantByCarrot(data, petData, guildData, sender, msg) {
    var m = msg.match(/^\/펜던트당근(?:거래)?\s+(.+)\s+(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트당근 거래대상닉네임 펜던트가방번호" };
    var target = m[1].trim();
    var index = parseInt(m[2], 10);
    if (!data.member[target] || !petData[target]) return { ok: false, message: "거래 대상 유저를 찾을 수 없습니다." };
    if (!isMemberTierKing(data, sender)) return { ok: false, message: "❌[" + checkRank(data, petData, guildData, sender) + "]님 펜던트 거래는 티어 👑킹 이상부터 가능합니다." };
    if (!isMemberTierKing(data, target)) return { ok: false, message: "❌[" + checkRank(data, petData, guildData, target) + "]님은 티어 👑킹 미만이라 당근 거래 물품을 받을 수 없습니다." };
    if (!hasItem(data, sender, GLOBAL_CONFIG.items.carrotName, GLOBAL_CONFIG.carrotTrade.costs.pendant)) return { ok: false, message: "펜던트 거래 수수료 당근🥕 " + numberWithCommas(GLOBAL_CONFIG.carrotTrade.costs.pendant) + "개가 부족합니다." };
    var senderBag = getPendantBag(petData, sender);
    sortPendantBagByGrade(senderBag);
    var targetBag = getPendantBag(petData, target);
    if (targetBag.length >= getPendantBagLimit()) return { ok: false, message: "상대 펜던트가방 공간이 부족합니다." };
    if (index < 1 || index > senderBag.length) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    var pendant = senderBag.splice(index - 1, 1)[0];
    removeItem(data, sender, GLOBAL_CONFIG.items.carrotName, GLOBAL_CONFIG.carrotTrade.costs.pendant);
    targetBag.push(pendant);
    return { ok: true, message: "펜던트 당근거래 완료\n━━━━━━━━━━━━━\n보낸 유저: " + sender + "\n받은 유저: " + target + "\n" + formatPendantDisplay(pendant) + "\n수수료: 당근🥕 " + numberWithCommas(GLOBAL_CONFIG.carrotTrade.costs.pendant) + "개" };
}

// 펜던트 자유시장 등록 처리
function registerPendantFreeMarket(data, petData, petSkillData, guildData, sender, msg, isConfirmed, freeMarketData) {
    if (!canRegisterFreeMarketByTier(data, sender)) return { ok: false, message: "❌ [" + checkRank(data, petData, guildData, sender) + "]님 거래등록은 티어 \"킹\" 이상만 가능합니다." };
    var m = msg.match(/^\/펜던트거래등록\s+(\d+)\s+(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트거래등록 [펜던트가방번호] [판매금액]" };
    var index = parseInt(m[1], 10);
    var price = parseInt(m[2], 10);
    if (!isPointShopSafeCount(price) || price < GLOBAL_CONFIG.freeMarket.minPrice) return { ok: false, message: "판매금액은 10다이아 이상의 안전한 정수여야 합니다." };
    var activeCount = countFreeMarketActiveListingsBySeller(freeMarketData, sender);
    var limit = getFreeMarketRegisterLimit(data, petSkillData, sender);
    if (activeCount + 1 > limit) return { ok: false, message: "❌ 자유시장 등록 가능 건수를 초과했습니다.\n현재: " + activeCount + "/" + limit + "건\n요청: +1건" };
    var bag = getPendantBag(petData, sender);
    sortPendantBagByGrade(bag);
    if (index < 1 || index > bag.length) return { ok: false, message: "해당 번호의 펜던트가 존재하지 않습니다." };
    if (!isConfirmed) {
        return {
            ok: true,
            pending: true,
            message: buildFreeMarketRegisterConfirmMessage(data, petData, guildData, sender, formatPendantDisplay(bag[index - 1]), 1, price, 0, "")
        };
    }
    var pendant = bag.splice(index - 1, 1)[0];
    addFreeMarketListing(freeMarketData, "pendant", sender, formatPendantDisplay(pendant), 1, price, { pendants: [cloneFreeMarketObject(pendant)] }, 0);
    return { ok: true, freeMarketData: freeMarketData, message: "[" + checkRank(data, petData, guildData, sender) + "] 님\n🏪 자유시장 등록 완료\n━━━━━━━━━━━━\n[" + formatPendantDisplay(pendant) + "]\n💎" + numberWithCommas(price) + "에 등록되었습니다.\n\n※ 등록비 무료\n" + buildFreeMarketTradeFeeNotice(data, sender) };
}

// 관리자 펜던트 지급 처리
function addPendantByAdmin(petData, msg) {
    var body = msg.substring("/펜던트추가".length).trim();
    var comma = body.indexOf(",");
    if (comma < 0) return { ok: false, message: "사용법: /펜던트추가 아이디, 이름 등급 내구도 강화수치" };
    var user = body.substring(0, comma).trim();
    var parts = body.substring(comma + 1).trim().split(/\s+/);
    if (parts.length < 4) return { ok: false, message: "사용법: /펜던트추가 아이디, 이름 등급 내구도 강화수치" };
    var upgrade = parseInt(parts[parts.length - 1], 10);
    var durability = parseInt(parts[parts.length - 2], 10);
    var grade = parts[parts.length - 3];
    var name = parts.slice(0, parts.length - 3).join(" ");
    if (!petData[user]) return { ok: false, message: "대상 펫 데이터가 없습니다." };
    var info = getPendantGradeInfo(grade);
    var pendant = createPendantByGradeInfo(info);
    pendant.name = name || info.name;
    pendant.grade = grade;
    pendant.durability = Math.max(0, Math.min(5, durability));
    pendant.maxDurability = 5;
    pendant.upgrade = Math.max(0, Math.min(30, upgrade));
    getPendantBag(petData, user).push(pendant);
    return { ok: true, message: "[MASTER]\n" + user + " 님에게 펜던트를 지급했습니다.\n━━━━━━━━━━━━━\n" + formatPendantDisplay(pendant) };
}

// 관리자 펜던트 삭제 처리
function deletePendantByAdmin(petData, msg) {
    var m = msg.match(/^\/펜던트삭제\s+(.+),\s*(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트삭제 아이디, 펜던트가방번호" };
    var user = m[1].trim();
    var index = parseInt(m[2], 10);
    if (!petData[user]) return { ok: false, message: "대상 펫 데이터가 없습니다." };
    var bag = getPendantBag(petData, user);
    if (index < 1 || index > bag.length) return { ok: false, message: "해당 번호의 펜던트가 없습니다." };
    var removed = bag.splice(index - 1, 1)[0];
    return { ok: true, message: "펜던트 삭제 완료\n대상: " + user + "\n" + formatPendantDisplay(removed) };
}

// 관리자 펜던트 강화수정 처리
function editPendantUpgradeByAdmin(petData, msg) {
    var m = msg.match(/^\/펜던트강화수정\s+(.+),\s*(\d+),\s*(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트강화수정 아이디, 펜던트가방번호, 강화수치" };
    var user = m[1].trim();
    if (!petData[user]) return { ok: false, message: "대상 펫 데이터가 없습니다." };
    var info = getPendantByIndex(petData, user, parseInt(m[2], 10));
    if (!info.pendant) return { ok: false, message: "해당 번호의 펜던트가 없습니다." };
    info.pendant.upgrade = Math.max(0, Math.min(30, parseInt(m[3], 10)));
    return { ok: true, message: "펜던트 강화수정 완료\n" + formatPendantDisplay(info.pendant) };
}

// 관리자 펜던트 내구도수정 처리
function editPendantDurabilityByAdmin(petData, msg) {
    var m = msg.match(/^\/펜던트내구도수정\s+(.+),\s*(\d+),\s*(\d+)$/);
    if (!m) return { ok: false, message: "사용법: /펜던트내구도수정 아이디, 펜던트가방번호, 내구" };
    var user = m[1].trim();
    if (!petData[user]) return { ok: false, message: "대상 펫 데이터가 없습니다." };
    var info = getPendantByIndex(petData, user, parseInt(m[2], 10));
    if (!info.pendant) return { ok: false, message: "해당 번호의 펜던트가 없습니다." };
    info.pendant.durability = Math.max(0, Math.min(info.pendant.maxDurability || 5, parseInt(m[3], 10)));
    return { ok: true, message: "펜던트 내구도수정 완료\n" + formatPendantDisplay(info.pendant) };
}

// 펜던트 미궁 박스 보상 테이블
function rollPendantMazeBox() {
    var gain = {};
    var minCount = GLOBAL_CONFIG.petExplore.maze.pendantEnhanceMinCount;
    var maxCount = GLOBAL_CONFIG.petExplore.maze.pendantEnhanceMaxCount;
    gain[GLOBAL_CONFIG.items.pendantEnhanceStoneName] = Math.floor(Math.random() * (maxCount - minCount + 1)) + minCount;
    if (Math.random() < GLOBAL_CONFIG.petExplore.maze.rareRewardRate) gain[GLOBAL_CONFIG.items.pendantRestoreStoneName] = 1;
    return {
        gainItems: gain,
        gainTextLines: []
    };
}

// 펜던트 미궁 박스를 오픈하는 함수
function runPendantMazeBoxOpen(sender, data, petData, guildData, msg, replier) {
    runExploreBoxOpen(sender, data, petData, guildData, replier, "/펜던트미궁박스오픈", GLOBAL_CONFIG.petExplore.maze.rewardItem, msg, rollPendantMazeBox);
}

// 대마법사의 유적 박스 보상 테이블
function rollArchmageMazeBox() {
    var gain = {};
    var minCount = GLOBAL_CONFIG.petExplore.maze.archmageFragmentMinCount;
    var maxCount = GLOBAL_CONFIG.petExplore.maze.archmageFragmentMaxCount;
    gain[GLOBAL_CONFIG.petExplore.tierReward.fragmentItemName] = Math.floor(Math.random() * (maxCount - minCount + 1)) + minCount;
    if (Math.random() < GLOBAL_CONFIG.petExplore.maze.rareRewardRate) gain[GLOBAL_CONFIG.petSkill.bookItemName] = 1;
    return {
        gainItems: gain,
        gainTextLines: []
    };
}

// 대마법사의 유적 박스를 오픈하는 함수
function runArchmageMazeBoxOpen(sender, data, petData, guildData, msg, replier) {
    runExploreBoxOpen(sender, data, petData, guildData, replier, "/대마법박스오픈", GLOBAL_CONFIG.petExplore.maze.archmageRewardItem, msg, rollArchmageMazeBox);
}

// 보상 아이템 묶음을 가방에 반영하는 함수
function applyRewardGainItems(data, user, gainItems) {
    for (var itemName in gainItems) {
        if (!gainItems.hasOwnProperty(itemName)) continue;
        addItem(data, user, itemName, gainItems[itemName]);
    }
}

// 봉인금고 관련 명령어를 현재 응답에서 처리할지 확인하는 함수
function isSealedVaultCommandMessage(msg) {
    var command = String(msg || "");
    if (command === "해방열쇠조합" || command === "/해방열쇠조합" || /^\/해방열쇠조합\s+\d+$/.test(command)) return true;
    return command === "/봉인금고" || command === "/봉인금고확률" || command === "/봉인금고기록" || command === "/봉인금고기록전체" ||
        /^\/봉인금고오픈(?:\s+.*)?$/.test(command) || /^\/해방열쇠지급(?:\s+.*)?$/.test(command) ||
        /^\/해방열쇠회수(?:\s+.*)?$/.test(command) || /^\/봉인금고상태(?:\s+.*)?$/.test(command) ||
        /^\/봉인금고부스터설정(?:\s+.*)?$/.test(command) || /^\/봉인금고천장설정(?:\s+.*)?$/.test(command) ||
        /^\/봉인금고보상설정(?:\s+.*)?$/.test(command);
}

// 봉인금고 데이터가 바뀌는 명령어인지 확인하는 함수
function isSealedVaultMutationCommandMessage(msg) {
    var command = String(msg || "");
    if (/^\/해방열쇠조합\s+\d+$/.test(command)) return true;
    return /^\/봉인금고오픈\s+\d+$/.test(command) || /^\/해방열쇠지급\s+.+\s+\d+$/.test(command) ||
        /^\/해방열쇠회수\s+.+\s+\d+$/.test(command) || /^\/봉인금고부스터설정\s+.+\s+\d+$/.test(command) ||
        /^\/봉인금고천장설정\s+.+\s+\d+$/.test(command) ||
        /^\/봉인금고보상설정\s+\d{4}-(?:0[1-9]|1[0-2])\s+\d+\s+\d+\s+\d+$/.test(command);
}

// 봉인금고 공통 반환 객체를 생성하는 함수
function createSealedVaultCommandResult(message, changed, noticeMessages) {
    return {
        message: String(message || ""),
        changed: changed === true,
        noticeMessages: noticeMessages instanceof Array ? noticeMessages : []
    };
}

// 음수가 아닌 봉인금고 누적값을 안전한 정수로 정리하는 함수
function normalizeSealedVaultCount(value, maxValue) {
    var count = parseInt(value, 10);
    if (isNaN(count) || count < 0) count = 0;
    if (typeof maxValue === "number" && count > maxValue) count = maxValue;
    return count;
}

// 회원의 봉인금고 누적 상태를 준비하는 함수
function ensureSealedVaultUserState(data, user) {
    if (!data || !data.member || !data.member[user]) return null;
    var member = data.member[user];
    if (!member.sealedVault || typeof member.sealedVault !== "object" || member.sealedVault instanceof Array) member.sealedVault = {};
    var state = member.sealedVault;
    state.totalOpenCount = normalizeSealedVaultCount(state.totalOpenCount);
    state.boosterCount = normalizeSealedVaultCount(state.boosterCount, GLOBAL_CONFIG.sealedVault.boosterCycle - 1);
    state.platinumMissCount = normalizeSealedVaultCount(state.platinumMissCount, GLOBAL_CONFIG.sealedVault.platinumPityCount - 1);
    if (!(state.rareRecords instanceof Array)) state.rareRecords = [];
    if (state.rareRecords.length > GLOBAL_CONFIG.sealedVault.userRareLogMax) state.rareRecords = state.rareRecords.slice(0, GLOBAL_CONFIG.sealedVault.userRareLogMax);
    return state;
}

// 봉인금고 공용 설정·기록 저장 영역을 준비하는 함수
function ensureSealedVaultRootData(data) {
    if (!data.sealedVault || typeof data.sealedVault !== "object" || data.sealedVault instanceof Array) data.sealedVault = {};
    if (!data.sealedVault.monthlyRewards || typeof data.sealedVault.monthlyRewards !== "object" || data.sealedVault.monthlyRewards instanceof Array) data.sealedVault.monthlyRewards = {};
    if (!(data.sealedVault.rareRecords instanceof Array)) data.sealedVault.rareRecords = [];
    if (!(data.sealedVault.adminLogs instanceof Array)) data.sealedVault.adminLogs = [];
    return data.sealedVault;
}

// KST 기준 봉인금고 월 키를 반환하는 함수
function getSealedVaultMonthKey(inputDate) {
    var date = inputDate instanceof Date ? inputDate : new Date();
    if (typeof java !== "undefined" && java.text && java.util) {
        var formatter = new java.text.SimpleDateFormat("yyyy-MM");
        formatter.setTimeZone(java.util.TimeZone.getTimeZone("Asia/Seoul"));
        return String(formatter.format(date));
    }
    var year = date.getFullYear();
    var month = date.getMonth() + 1;
    return year + "-" + (month < 10 ? "0" + month : String(month));
}

// 월 키를 사용자용 월 표시로 변환하는 함수
function getSealedVaultMonthLabel(monthKey) {
    var match = String(monthKey || "").match(/^\d{4}-(\d{2})$/);
    return match ? parseInt(match[1], 10) + "월" : String(monthKey || "이번 달");
}

// 현재 월에 적용할 초대형 보상 구성을 반환하는 함수
function getSealedVaultMonthlyRewards(data, monthKey) {
    var stored = data && data.sealedVault && data.sealedVault.monthlyRewards ? data.sealedVault.monthlyRewards[monthKey] : null;
    if (stored instanceof Array && stored.length > 0) return stored;
    var defaults = GLOBAL_CONFIG.sealedVault.monthlyRewards[monthKey];
    return defaults instanceof Array && defaults.length > 0 ? defaults : null;
}

// 봉인금고 부스터 진행률을 정수 백분율로 반환하는 함수
function getSealedVaultBoosterPercent(state) {
    return Math.floor((state.boosterCount * 100) / GLOBAL_CONFIG.sealedVault.boosterCycle);
}

// 현재값과 최대값으로 봉인금고 공용 진행 막대를 생성하는 함수
function buildSealedVaultProgressBar(currentCount, maxCount) {
    var current = normalizeSealedVaultCount(currentCount, maxCount);
    var max = normalizeSealedVaultCount(maxCount);
    var percent = max > 0 ? Math.floor((current * 100) / max) : 0;
    var filled = Math.floor(percent / 10);
    var bar = "[";
    for (var i = 0; i < 10; i++) bar += i < filled ? "■" : "□";
    return bar + "] " + percent + "% (" + current + "/" + max + ")";
}

// 보상 목록을 줄 단위 사용자 문구로 변환하는 함수
function formatSealedVaultRewardLines(rewards, doubled) {
    var lines = [];
    for (var i = 0; rewards && i < rewards.length; i++) {
        lines.push(rewards[i].itemName + " ×" + numberWithCommas(rewards[i].count) + (doubled ? " 🔥2배" : ""));
    }
    return lines.join("\n");
}

// 봉인금고 가중치 목록에서 보상 하나를 추첨하는 함수
function drawSealedVaultWeightedReward(rewards, randomFn) {
    var totalWeight = 0;
    for (var i = 0; i < rewards.length; i++) totalWeight += rewards[i].weight;
    if (totalWeight <= 0) throw new Error("봉인금고 보상 가중치 합계 오류");
    var roll = Math.floor(randomFn() * totalWeight);
    if (roll < 0) roll = 0;
    if (roll >= totalWeight) roll = totalWeight - 1;
    var cumulative = 0;
    for (var j = 0; j < rewards.length; j++) {
        cumulative += rewards[j].weight;
        if (roll < cumulative) return rewards[j];
    }
    throw new Error("봉인금고 보상 추첨 오류");
}

// 봉인금고 합산 보상에 아이템 수량을 추가하는 함수
function addSealedVaultGain(gainMap, gainOrder, itemName, count, doubled, rewardType) {
    if (!gainMap.hasOwnProperty(itemName)) {
        gainMap[itemName] = { normal: 0, doubled: 0, platinum: 0, platinumDoubled: 0 };
        gainOrder.push(itemName);
    }
    if (rewardType === "platinum" && doubled) gainMap[itemName].platinumDoubled += count;
    else if (rewardType === "platinum") gainMap[itemName].platinum += count;
    else if (doubled) gainMap[itemName].doubled += count;
    else gainMap[itemName].normal += count;
}

// 봉인금고 희귀 보상 기록을 회원과 전체 기록에 함께 남기는 함수
function appendSealedVaultRareRecord(data, user, rareEvent) {
    var state = ensureSealedVaultUserState(data, user);
    var root = ensureSealedVaultRootData(data);
    var record = {
        at: formatDateTime(new Date()),
        user: user,
        type: rareEvent.type,
        doubled: rareEvent.doubled === true,
        guaranteed: rareEvent.guaranteed === true,
        rewardText: formatSealedVaultRewardLines(rareEvent.rewards).replace(/\n/g, " / ")
    };
    state.rareRecords.unshift(record);
    root.rareRecords.unshift(record);
    if (state.rareRecords.length > GLOBAL_CONFIG.sealedVault.userRareLogMax) state.rareRecords.length = GLOBAL_CONFIG.sealedVault.userRareLogMax;
    if (root.rareRecords.length > GLOBAL_CONFIG.sealedVault.globalRareLogMax) root.rareRecords.length = GLOBAL_CONFIG.sealedVault.globalRareLogMax;
}

// 봉인금고 관리자 변경 이력을 남기는 함수
function appendSealedVaultAdminLog(data, operator, action, target, beforeValue, afterValue) {
    var root = ensureSealedVaultRootData(data);
    root.adminLogs.unshift({
        at: formatDateTime(new Date()),
        operator: operator,
        action: action,
        target: target,
        beforeValue: beforeValue,
        afterValue: afterValue
    });
    if (root.adminLogs.length > GLOBAL_CONFIG.sealedVault.adminLogMax) root.adminLogs.length = GLOBAL_CONFIG.sealedVault.adminLogMax;
}

// 봉인금고 현재 상태 UI를 생성하는 함수
